CREATE OR REPLACE FUNCTION public.accept_research_cloud_result_v1(p_reservation uuid, p_owner text, p_work_key text, p_work_hash text, p_source_commit text, p_outcome text, p_result_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_reservation public.research_model_reservations_v1;
  v_prior public.research_cloud_acceptances_v1;
BEGIN
  IF p_owner IS NULL OR p_work_key IS NULL OR p_work_hash IS NULL OR p_source_commit IS NULL
    OR p_outcome IS NULL OR p_result_hash IS NULL
    OR p_work_key !~ '^cloud:v1:[0-9a-f]{64}$' OR p_work_hash !~ '^[0-9a-f]{64}$'
    OR p_source_commit !~ '^[0-9a-f]{40}$' OR p_result_hash !~ '^[0-9a-f]{64}$'
    OR p_outcome NOT IN ('completed','failed') THEN RAISE EXCEPTION 'cloud_acceptance_input_invalid'; END IF;
  -- Same lock as all role reservations/completions, so a generic finish cannot
  -- race past the provenance check or leave a partial acceptance.
  PERFORM pg_advisory_xact_lock(2409,6002);
  SELECT * INTO v_reservation FROM public.research_model_reservations_v1 WHERE reservation_id=p_reservation;
  IF NOT FOUND OR v_reservation.role<>'independent_test' OR v_reservation.owner<>p_owner
    OR v_reservation.work_key<>p_work_key THEN RAISE EXCEPTION 'cloud_acceptance_reservation_mismatch'; END IF;
  SELECT * INTO v_prior FROM public.research_cloud_acceptances_v1 WHERE reservation_id=p_reservation;
  IF FOUND THEN
    IF v_prior.owner<>p_owner OR v_prior.work_key<>p_work_key OR v_prior.work_hash<>p_work_hash
      OR v_prior.source_commit<>p_source_commit OR v_prior.outcome<>p_outcome OR v_prior.result_hash<>p_result_hash
      THEN RAISE EXCEPTION 'cloud_acceptance_replay_mismatch'; END IF;
    RETURN true;
  END IF;
  IF EXISTS(SELECT 1 FROM public.research_model_completions_v1 WHERE reservation_id=p_reservation)
    THEN RAISE EXCEPTION 'cloud_generic_completion_not_acceptance'; END IF;
  IF v_reservation.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'cloud_acceptance_lease_lost'; END IF;
  PERFORM public.finish_research_model_v1(p_reservation,p_owner,p_outcome,p_result_hash);
  INSERT INTO public.research_cloud_acceptances_v1(reservation_id,owner,work_key,work_hash,source_commit,result_hash,outcome)
    VALUES(p_reservation,p_owner,p_work_key,p_work_hash,p_source_commit,p_result_hash,p_outcome);
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.acquire_legacy_producer_lease_v3_11(p_owner text, p_commit text, p_worker text, p_config bytea, p_config_hash text, p_token uuid, p_lease integer)
 RETURNS legacy_producer_lease_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz:=date_trunc('second',clock_timestamp());v_occ public.legacy_scheduled_occurrence_v3_11;v_run uuid;v_job uuid;v_authority bytea;v_authority_json jsonb;v_authority_hash text;v_payload bytea;v_payload_json jsonb;v_payload_hash text;v_page public.legacy_discovery_authority_page_v3_11;v_pages jsonb:='[]'::jsonb;v_selected jsonb;v_selected_ordinal bigint;v_selected_bytes bytea;v_logical_key text;v_attempt smallint;v_uuid_hash text;v_token_hash text;
BEGIN
  IF p_owner<>'com.stockinsider.auth-source-worker' OR p_commit!~'^[0-9a-f]{40}$' OR p_worker!~'^[0-9a-f]{64}$' OR p_lease<>120 OR octet_length(p_config)<>1226
    OR p_config_hash<>'1ead338d6a56194a51c64ac2adbf36551a410c327ce08ba18f9224e34471c3c2' OR encode(extensions.digest(p_config,'sha256'),'hex')<>p_config_hash THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  v_token_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT run_id INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE status='running' ORDER BY started_at,run_id LIMIT 1 FOR UPDATE;
  IF v_run IS NOT NULL THEN
    IF (SELECT lease_expires_at>=v_now FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run) THEN
      RETURN ROW(NULL,NULL,'owner_already_leased',NULL,NULL)::public.legacy_producer_lease_v3_11;
    END IF;
    IF EXISTS(SELECT 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run
      AND (producer_commit_sha<>p_commit OR worker_sha256<>p_worker OR scheduler_config_sha256<>p_config_hash)) THEN
      UPDATE public.legacy_producer_jobs_v3_11 SET status='cancelled',terminal_at=v_now,failure_code='cancelled',
        owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
        WHERE run_id=v_run AND status IN ('queued','leased','retryable');
      UPDATE public.legacy_producer_runs_v3_11 SET status='cancelled',terminal_at=v_now,failure_code='cancelled',
        heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=v_run;
      v_run:=NULL;
    ELSE
      UPDATE public.legacy_producer_jobs_v3_11 SET status='retryable',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
        WHERE run_id=v_run AND status='leased' AND lease_expires_at<v_now;
      UPDATE public.legacy_producer_runs_v3_11 SET owner_token_hash=v_token_hash,heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=v_run;
      SELECT job_id INTO v_job FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND status IN ('queued','retryable') ORDER BY execution_ordinal LIMIT 1;
      RETURN ROW(v_run,v_job,'resumed',
        (SELECT source_cutoff FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run),
        (SELECT authority_hash FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run))::public.legacy_producer_lease_v3_11;
    END IF;
  END IF;
  v_occ:=public.resolve_legacy_scheduled_occurrence_v3_11(p_owner,p_config_hash);
  v_logical_key:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'legacy-producer-run-v3',v_occ.scheduled_occurrence_id,to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    v_occ.trading_date,v_occ.trading_session_authority_hash,p_commit,p_worker,p_config_hash,
    'e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743'
  )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
  v_authority_json:=jsonb_build_object('schema','legacy-discovery-authority-v1','scheduledOccurrenceId',v_occ.scheduled_occurrence_id,'sourceCutoff',to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  v_authority:=convert_to(v_authority_json::text,'utf8');v_authority_hash:=encode(extensions.digest(v_authority,'sha256'),'hex');
  SELECT run_id INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE logical_run_key=v_logical_key AND status='success' ORDER BY attempt DESC LIMIT 1;
  IF v_run IS NOT NULL THEN RETURN ROW(v_run,NULL,'retained_success',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11; END IF;
  SELECT coalesce(max(attempt),0)+1 INTO v_attempt FROM public.legacy_producer_runs_v3_11 WHERE logical_run_key=v_logical_key;
  IF v_attempt>5 THEN RETURN ROW(NULL,NULL,'attempts_exhausted',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11;END IF;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-run:'||v_logical_key||':'||v_attempt,'utf8'),'sha256'),'hex');
  v_run:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-job:'||v_run::text||':0','utf8'),'sha256'),'hex');
  v_job:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  INSERT INTO public.legacy_producer_runs_v3_11 VALUES(v_run,p_owner,encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex'),p_commit,p_worker,p_config,p_config_hash,
    ARRAY['2301','2303','2308','2330','2337','2344','2345','2356','2379','2382','2408','2421','2449','2454','3008','3017','3034','3037','3189','3231','3324','3533','3711','4958','5347','5388','6230','6285','6415','6669'],
    'e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',v_occ.scheduled_occurrence_id,v_occ.source_cutoff,v_occ.trading_date,v_occ.trading_session_authority_hash,
    v_authority,v_authority_json,v_authority_hash,'running',v_now,v_now,v_now+interval '120 seconds',NULL,NULL,v_logical_key,v_attempt,v_now);
  FOR v_page IN SELECT * FROM public.read_legacy_discovery_authority_v3_11(v_run,p_commit,p_config_hash) LOOP
    INSERT INTO public.legacy_producer_authority_pages_v3_11 VALUES(v_run,v_page.page_kind,v_page.page_ordinal,v_page.first_row_ordinal,v_page.row_count,v_page.page_canonical,v_page.page_json,v_page.page_hash,v_now);
    v_pages:=v_pages||jsonb_build_array(jsonb_build_array(v_page.page_kind,v_page.page_ordinal,v_page.row_count,v_page.page_hash,v_page.kind_row_count,v_page.kind_page_count,v_page.kind_root_hash));
    IF v_page.page_kind='selected_revision' THEN
      FOR v_selected,v_selected_ordinal IN SELECT value,ordinality FROM jsonb_array_elements(v_page.page_json) WITH ORDINALITY AS selected(value,ordinality) LOOP
        IF jsonb_typeof(v_selected)<>'array' OR jsonb_array_length(v_selected)<>11 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
        v_selected_bytes:=convert_to(v_selected::text,'utf8');
        INSERT INTO public.legacy_frozen_source_revisions_v3_11(run_id,selection_ordinal,source_key,revision_id,selected_revision_row_canonical,selected_revision_row_json,selected_revision_row_hash,raw_field_payload_algorithm_version,ingestion_content_revision_sha256,canonical_content_algorithm_version,canonical_content_sha256,recorded_at)
        VALUES(v_run,v_page.first_row_ordinal+v_selected_ordinal-1,(v_selected->>0)::public.source_key_v3,(v_selected->>1)::uuid,v_selected_bytes,v_selected,encode(extensions.digest(v_selected_bytes,'sha256'),'hex'),v_selected->>7,v_selected->>8,v_selected->>9,v_selected->>10,v_now);
      END LOOP;
    END IF;
  END LOOP;
  IF (SELECT count(DISTINCT page_kind) FROM public.legacy_producer_authority_pages_v3_11 WHERE run_id=v_run)<>4 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  v_authority_json:=jsonb_build_object('schema','legacy-discovery-authority-v1','scheduledOccurrenceId',v_occ.scheduled_occurrence_id,'sourceCutoff',to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'pages',v_pages);
  v_authority:=convert_to(v_authority_json::text,'utf8');v_authority_hash:=encode(extensions.digest(v_authority,'sha256'),'hex');
  UPDATE public.legacy_producer_runs_v3_11 SET authority_canonical=v_authority,authority_json=v_authority_json,authority_hash=v_authority_hash WHERE run_id=v_run;
  v_payload_json:=jsonb_build_array('e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',v_run,v_occ.scheduled_occurrence_id,to_char(v_occ.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),v_occ.trading_date,v_occ.trading_session_authority_hash,v_authority_hash);
  v_payload:=convert_to(v_payload_json::text,'utf8');v_payload_hash:=encode(extensions.digest(v_payload,'sha256'),'hex');
  INSERT INTO public.legacy_producer_jobs_v3_11 VALUES(v_job,v_run,'source_sync','stage_barrier',0,NULL,0,NULL,NULL,v_payload_hash,v_payload_hash,'queued',0,5,NULL,NULL,NULL,NULL,NULL,NULL,v_now);
  INSERT INTO public.legacy_producer_job_payloads_v3_11 VALUES(v_job,v_payload,v_payload_json,v_payload_hash,v_now);
  RETURN ROW(v_run,v_job,'created',v_occ.source_cutoff,v_authority_hash)::public.legacy_producer_lease_v3_11;
END $function$

CREATE OR REPLACE FUNCTION public.activate_stockinsider_backend_release_v1(p_release_id text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE headers jsonb; claims jsonb; supplied_backend uuid; supplied_principal uuid;
BEGIN
  IF p_release_id !~ '^[0-9a-f]{40}$' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='stockinsider_release_invalid';
  END IF;
  BEGIN
    headers:=COALESCE(NULLIF(current_setting('request.headers',true),''),'{}')::jsonb;
    claims:=COALESCE(NULLIF(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
    supplied_backend:=(headers->>'x-stockinsider-backend-id')::uuid;
    supplied_principal:=(headers->>'x-stockinsider-runner-principal')::uuid;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='stockinsider_backend_identity_rejected';
  END;
  IF claims->>'role' IS DISTINCT FROM 'service_role'
    OR NOT public.internal_principal_role_is_exact_v3_internal(
      supplied_principal,'opportunity_runner',clock_timestamp())
    OR NOT EXISTS(SELECT 1 FROM public.stockinsider_backend_identities_v1
      WHERE backend_id=supplied_backend AND principal_id=supplied_principal AND status='active'
        AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp())) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='stockinsider_release_activation_rejected';
  END IF;
  PERFORM public.register_production_writer_release(p_release_id,
    COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('activated_at',clock_timestamp()));
  UPDATE public.stockinsider_backend_identities_v1 SET release_id=p_release_id,
    metadata=metadata||jsonb_build_object('release_rotated_at',clock_timestamp())
    WHERE backend_id=supplied_backend AND principal_id=supplied_principal AND status='active';
  RETURN FOUND;
END
$function$

CREATE OR REPLACE FUNCTION public.admit_insider_snapshot_v1(p_run uuid, p_dataset integer, p_token uuid, p_raw_base64 text, p_hash text, p_rows integer, p_attempted timestamp with time zone, p_observed timestamp with time zone, p_parser text, p_rights text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE raw_bytes bytea; rows jsonb; row_value jsonb; binding public.insider_run_members_v1; acquisition public.insider_acquisitions_v1; v_snapshot_id uuid;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  THEN RAISE EXCEPTION 'insider_write_read_committed_required'; END IF;
 IF p_run IS NULL OR public.insider_dataset_v1(p_dataset) IS NULL THEN RAISE EXCEPTION 'insider_admission_identity'; END IF;
 PERFORM pg_advisory_xact_lock(2410,8001); PERFORM pg_advisory_xact_lock(2411,p_dataset);
 IF NOT EXISTS(SELECT 1 FROM public.insider_acquisition_runs_v1 WHERE id=p_run) THEN RAISE EXCEPTION 'insider_run_before_fetch_required'; END IF;
 SELECT * INTO binding FROM public.insider_run_members_v1 m WHERE m.run_id=p_run AND m.dataset=p_dataset;
 IF NOT FOUND OR p_token IS NULL OR binding.acquisition_token<>p_token THEN RAISE EXCEPTION 'insider_acquisition_token_mismatch'; END IF;
 SELECT * INTO STRICT acquisition FROM public.insider_acquisitions_v1 WHERE id=p_token;
 IF acquisition.dataset<>p_dataset THEN RAISE EXCEPTION 'insider_acquisition_token_mismatch'; END IF;
 IF binding.snapshot_id IS NOT NULL THEN
  IF binding.snapshot_id IS DISTINCT FROM acquisition.snapshot_id THEN RAISE EXCEPTION 'insider_acquisition_binding_corrupt'; END IF;
  RETURN public.insider_snapshot_run_v1(p_run);
 END IF;
 IF acquisition.snapshot_id IS NOT NULL THEN RAISE EXCEPTION 'insider_acquisition_binding_corrupt'; END IF;
 IF p_parser IS DISTINCT FROM 'insider-db-projection-v1' OR p_rights IS DISTINCT FROM 'official-insider-private-research-retain-v1' THEN RAISE EXCEPTION 'insider_admission_parser_or_rights'; END IF;
 IF p_raw_base64 IS NULL OR octet_length(p_raw_base64)>16777216 OR p_raw_base64 !~ '^[A-Za-z0-9+/]*={0,2}$' OR length(p_raw_base64)%4<>0 THEN RAISE EXCEPTION 'insider_raw_transport_bound'; END IF;
 IF p_attempted IS NULL OR p_observed IS NULL OR NOT isfinite(p_attempted) OR NOT isfinite(p_observed) OR p_attempted>p_observed OR p_observed>clock_timestamp() OR p_observed-p_attempted>interval '30 seconds' THEN RAISE EXCEPTION 'insider_source_clock_invalid'; END IF;
 raw_bytes:=decode(p_raw_base64,'base64');
 IF octet_length(raw_bytes) NOT BETWEEN 2 AND 12582912 OR p_hash IS NULL OR encode(extensions.digest(raw_bytes,'sha256'),'hex')<>p_hash THEN RAISE EXCEPTION 'insider_raw_identity'; END IF;
 rows:=convert_from(raw_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(rows) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'insider_schema_not_array'; END IF;
 IF p_rows IS NULL OR jsonb_array_length(rows)<>p_rows OR p_rows NOT BETWEEN 0 AND 50000 THEN RAISE EXCEPTION 'insider_row_bound'; END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(rows) LOOP PERFORM public.insider_row_v1(row_value,p_dataset); END LOOP;
 INSERT INTO public.insider_snapshots_v1(dataset,raw,raw_sha256,row_count,attempted_at,observed_at,parser_identity,rights_identity)
  VALUES(p_dataset,raw_bytes,p_hash,p_rows,p_attempted,p_observed,p_parser,p_rights) RETURNING id INTO v_snapshot_id;
 -- Provisional row is transaction-private. Reject oversized derived pages before
 -- creating active progress or binding any member; exception rolls back the raw.
 PERFORM public.insider_snapshot_projection_bound_v1(v_snapshot_id);
 -- Empty snapshots still require the frozen-run commit, ensuring a replay receipt.
 INSERT INTO public.insider_snapshot_progress_v1(snapshot_id,dataset) VALUES(v_snapshot_id,p_dataset);
 UPDATE public.insider_acquisitions_v1 SET snapshot_id=v_snapshot_id,resolved_at=clock_timestamp() WHERE id=p_token;
 UPDATE public.insider_run_members_v1 SET snapshot_id=v_snapshot_id WHERE acquisition_token=p_token AND insider_run_members_v1.snapshot_id IS NULL;
 UPDATE public.insider_acquisition_runs_v1 r SET frozen_at=clock_timestamp() WHERE r.frozen_at IS NULL
  AND EXISTS(SELECT 1 FROM public.insider_run_members_v1 m WHERE m.run_id=r.id AND m.acquisition_token=p_token)
  AND (SELECT count(*) FROM public.insider_run_members_v1 m WHERE m.run_id=r.id AND m.snapshot_id IS NOT NULL)=5;
 RETURN public.insider_snapshot_run_v1(p_run);
END $function$

CREATE OR REPLACE FUNCTION public.admit_research_observed_roster_v1(p_snapshot_hash text, p_canonical_packet text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE packet jsonb; payload jsonb; request jsonb; member jsonb; source jsonb;
 existing public.research_observed_roster_snapshots_v1%ROWTYPE;
 company public.research_observed_companies_v1%ROWTYPE;
 now_clock timestamptz; latest timestamptz; mappings jsonb:='[]'; mapping_hash text;
 n integer; excluded_n integer; matching_n integer; legacy jsonb; scope jsonb; expected_members jsonb; expected_excluded jsonb; source_attempted timestamptz; source_observed timestamptz; scope_recorded timestamptz; legacy_recorded timestamptz;
BEGIN
 IF p_snapshot_hash IS NULL OR p_snapshot_hash !~ '^[a-f0-9]{64}$' OR p_canonical_packet IS NULL OR octet_length(p_canonical_packet)>2000000 THEN RAISE EXCEPTION 'observed_admission_shape_invalid'; END IF;
 packet:=p_canonical_packet::jsonb; payload:=packet->'payload';request:=packet->'request';legacy:=request->'legacyClassification';scope:=request->'securityScope';
 IF EXISTS(WITH RECURSIVE nodes(value,key,depth) AS (
   SELECT packet,''::text,0 UNION ALL
   SELECT child.value,child.key,n.depth+1 FROM nodes n CROSS JOIN LATERAL (
    SELECT e.value,e.key FROM jsonb_each(CASE WHEN jsonb_typeof(n.value)='object' THEN n.value ELSE '{}'::jsonb END)e
    UNION ALL SELECT a.value,''::text FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.value)='array' THEN n.value ELSE '[]'::jsonb END)a
   )child WHERE n.depth<=16
  ) SELECT 1 FROM nodes WHERE depth>16 OR key ~* '^(authorization|headers|cookies?|password|secret|api[_-]?key|access[_-]?token|refresh[_-]?token|__proto__|constructor|prototype|rawHtml|rawText|fullText)$'
   OR (jsonb_typeof(value)='string' AND (length(value#>>'{}')>4096 OR value#>>'{}' ~* '(Bearer[[:space:]]+[^[:space:]]{12,}|-----BEGIN .*PRIVATE KEY-----|eyJ[A-Za-z0-9_-]{12,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+|(password|api[_-]?key|access[_-]?token|cookie)[[:space:]]*[:=][[:space:]]*[^[:space:]]+)'))
 ) THEN RAISE EXCEPTION 'observed_packet_boundary_invalid'; END IF;

 IF p_canonical_packet<>public.research_observed_canonical_json_v1(packet) THEN RAISE EXCEPTION 'observed_packet_canonical_mismatch'; END IF;
 IF encode(extensions.digest(convert_to(p_canonical_packet,'UTF8'),'sha256'),'hex')<>p_snapshot_hash THEN RAISE EXCEPTION 'observed_packet_hash_mismatch'; END IF;
 IF payload->>'schemaVersion' IS DISTINCT FROM 'research-observed-roster-admission-v1' OR payload->>'classifierHash' IS DISTINCT FROM '9eb59b03bd3b89cbe9813a93f49dc2247e5d7e12a6e31e145d042fef493f8f63'
  OR payload->>'classifierVersion' IS DISTINCT FROM 'source-cohort-consumer-v1'
  OR payload->'researchQualified' IS DISTINCT FROM 'false'::jsonb OR payload->'strategyApproved' IS DISTINCT FROM 'false'::jsonb OR payload->'entryEligible' IS DISTINCT FROM 'false'::jsonb
  OR payload->'trustedAuthorityActivated' IS DISTINCT FROM 'false'::jsonb OR payload->'historicalPITEligible' IS DISTINCT FROM 'false'::jsonb OR payload->'rawSourceHashesVerifiedByVm' IS DISTINCT FROM 'false'::jsonb
  OR jsonb_typeof(payload->'members') IS DISTINCT FROM 'array' OR jsonb_typeof(payload->'excluded') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'observed_admission_policy_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(packet) key WHERE key NOT IN('request','payload'))
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(request) key WHERE key NOT IN('legacyClassification','securityScope'))
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(payload) key WHERE key NOT IN('schemaVersion','classifierVersion','classifierHash','classificationHash','legacySnapshotHash','members','excluded','sourceReferences','rawSourceHashesVerifiedByVm','researchQualified','strategyApproved','entryEligible','trustedAuthorityActivated','historicalPITEligible'))
  OR legacy->>'schemaVersion' IS DISTINCT FROM 'stockinsider-observed-security-classification-relay-v1'
  OR scope->>'schemaVersion' IS DISTINCT FROM 'stockinsider-observed-official-security-scope-reconciliation-v1'
  OR legacy->'trustedAuthorityActivated' IS DISTINCT FROM 'false'::jsonb OR scope->'trustedAuthorityActivated' IS DISTINCT FROM 'false'::jsonb
  OR legacy->'historicalPITEligible' IS DISTINCT FROM 'false'::jsonb OR scope->'historicalPITEligible' IS DISTINCT FROM 'false'::jsonb
  OR legacy->'currentTradingEligibilityVerified' IS DISTINCT FROM 'false'::jsonb OR scope->'currentTradingEligibilityVerified' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'observed_raw_boundary_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(legacy) k WHERE k NOT IN('schemaVersion','recordedAt','sources','scope','historicalPITEligible','currentTradingEligibilityVerified','trustedAuthorityActivated','members'))
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(scope) k WHERE k NOT IN('schemaVersion','recordedAt','sources','companyMasterReferenceCommit','legacyClassificationReferenceCommit','encoding','parseDiagnostic','counts','newlyClassifiedOrdinarySymbols','rows','trustedAuthorityActivated','currentTradingEligibilityVerified','historicalPITEligible','limits'))
  OR jsonb_typeof(legacy->'members') IS DISTINCT FROM 'array' OR jsonb_typeof(legacy->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(legacy->'sources') IS DISTINCT FROM 2
  OR jsonb_typeof(scope->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(scope->'rows')>5000 OR jsonb_typeof(scope->'newlyClassifiedOrdinarySymbols') IS DISTINCT FROM 'array'
  OR jsonb_typeof(payload->'sourceReferences') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'observed_raw_shape_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows')r CROSS JOIN unnest(ARRAY['symbol','name','isin','listingDateText','marketText','sectorText','cfi','note','sourceSection','classification'])k WHERE jsonb_typeof(r->k) IS DISTINCT FROM 'string')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows')r WHERE jsonb_typeof(r->'legacyStrictCfiMatched') IS DISTINCT FROM 'boolean' OR EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('symbol','name','isin','listingDateText','marketText','sectorText','cfi','note','sourceSection','classification','legacyStrictCfiMatched')))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')r CROSS JOIN unnest(ARRAY['symbol','name','exchange','cfi','isin','listingDate','sector'])k WHERE jsonb_typeof(r->k) IS DISTINCT FROM 'string')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')r WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('symbol','name','exchange','cfi','isin','listingDate','sector')))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'members')r WHERE btrim(r->>'name')='' OR r->>'isin' !~ '^[A-Z0-9]{12}$') THEN RAISE EXCEPTION 'observed_raw_row_schema_invalid'; END IF;
 IF jsonb_typeof(legacy->'scope') IS DISTINCT FROM 'string' OR scope->>'companyMasterReferenceCommit' IS NULL OR scope->>'companyMasterReferenceCommit' !~ '^[a-f0-9]{40}$' OR scope->>'legacyClassificationReferenceCommit' IS NULL OR scope->>'legacyClassificationReferenceCommit' !~ '^[a-f0-9]{40}$'
  OR jsonb_typeof(scope->'limits') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'limits')v WHERE jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'observed_raw_metadata_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'sources') WITH ORDINALITY AS sources(r,ord) WHERE
  EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('url','observedAt','responseBytes','responseSha256','selectedCount'))
  OR r->>'url' IS DISTINCT FROM CASE WHEN ord=1 THEN 'https://isin.twse.com.tw/isin/class_main.jsp?Page=&issuetype=1&market=1' ELSE 'https://isin.twse.com.tw/isin/C_public.jsp?strMode=4' END
  OR r->>'responseSha256' IS NULL OR r->>'responseSha256' !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(r->'responseBytes') IS DISTINCT FROM 'number' OR r->>'responseBytes' !~ '^[0-9]+$' OR (r->>'responseBytes')::bigint NOT BETWEEN 1 AND 4000000
  OR r->'selectedCount' IS DISTINCT FROM to_jsonb((SELECT count(*) FROM jsonb_array_elements(legacy->'members')m WHERE m->>'exchange'=CASE WHEN ord=1 THEN 'TWSE' ELSE 'TPEX' END))) THEN RAISE EXCEPTION 'observed_legacy_receipt_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'sources')r WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('label','url','attemptedAt','observedAt','httpStatus','status','resolvedUrl','bytes','sha256')) OR jsonb_typeof(r->'bytes') IS DISTINCT FROM 'number' OR r->>'bytes' !~ '^[0-9]+$' OR jsonb_typeof(r->'httpStatus') IS DISTINCT FROM 'number') THEN RAISE EXCEPTION 'observed_scope_receipt_shape_invalid'; END IF;
 IF payload->'sourceReferences' IS DISTINCT FROM jsonb_build_array(
  jsonb_build_object('url',scope#>'{sources,0,url}','observedAt',scope#>'{sources,0,observedAt}','responseBytes',scope#>'{sources,0,bytes}','responseSha256',scope#>'{sources,0,sha256}'),
  jsonb_build_object('url',legacy#>'{sources,1,url}','observedAt',legacy#>'{sources,1,observedAt}','responseBytes',legacy#>'{sources,1,responseBytes}','responseSha256',legacy#>'{sources,1,responseSha256}')) THEN RAISE EXCEPTION 'observed_source_projection_mismatch'; END IF;
 n:=jsonb_array_length(payload->'members');excluded_n:=jsonb_array_length(payload->'excluded');
 IF n<1 OR n>5000 OR excluded_n>5000 OR jsonb_array_length(payload->'sourceReferences')<>2 THEN RAISE EXCEPTION 'observed_admission_count_invalid'; END IF;
 IF payload->>'classificationHash'<>encode(extensions.digest(convert_to(public.research_observed_canonical_json_v1(jsonb_build_object('members',payload->'members','excluded',payload->'excluded')),'UTF8'),'sha256'),'hex')
  OR payload->>'legacySnapshotHash'<>encode(extensions.digest(convert_to(public.research_observed_canonical_json_v1(legacy),'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION 'observed_classification_hash_mismatch'; END IF;
 -- Serialize identity/snapshot admissions; all DB clocks are captured after this lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('research_observed_admission_v1',0));now_clock:=clock_timestamp();
 SELECT * INTO existing FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=p_snapshot_hash;
 scope_recorded:=public.research_observed_instant_v1(scope->>'recordedAt');legacy_recorded:=public.research_observed_instant_v1(legacy->>'recordedAt');
 source_attempted:=public.research_observed_instant_v1(scope#>>'{sources,0,attemptedAt}');source_observed:=public.research_observed_instant_v1(scope#>>'{sources,0,observedAt}');
 IF source_attempted>source_observed OR source_observed>scope_recorded OR scope_recorded>now_clock OR legacy_recorded>now_clock THEN RAISE EXCEPTION 'observed_source_clock_chain_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'sources') r WHERE public.research_observed_instant_v1(r->>'observedAt')>legacy_recorded) THEN RAISE EXCEPTION 'observed_legacy_source_clock_chain_invalid'; END IF;
 IF scope->>'encoding' IS DISTINCT FROM 'cp950_strict' OR jsonb_array_length(scope->'sources') IS DISTINCT FROM 1 OR jsonb_typeof(scope->'counts') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'observed_raw_scope_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')r WHERE r->>'exchange' NOT IN('TWSE','TPEX') OR r->>'cfi' IS DISTINCT FROM 'ESVUFR' OR r->>'symbol' !~ '^[1-9][0-9]{3}$') OR (SELECT count(DISTINCT r->>'symbol')FROM jsonb_array_elements(legacy->'members')r) IS DISTINCT FROM jsonb_array_length(legacy->'members') THEN RAISE EXCEPTION 'observed_legacy_member_invalid'; END IF;
 IF (SELECT count(DISTINCT r->>'symbol')FROM jsonb_array_elements(scope->'rows')r) IS DISTINCT FROM jsonb_array_length(scope->'rows') THEN RAISE EXCEPTION 'observed_raw_symbol_duplicate'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows')r WHERE r->'legacyStrictCfiMatched' IS DISTINCT FROM to_jsonb(EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')l WHERE l->>'exchange'='TWSE' AND l->>'symbol'=r->>'symbol'))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')l WHERE l->>'exchange'='TWSE' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows')r WHERE r->>'symbol'=l->>'symbol' AND r->>'cfi'=l->>'cfi' AND r->>'isin'=l->>'isin' AND r->>'name'=l->>'name')) THEN RAISE EXCEPTION 'observed_legacy_crosscheck_invalid'; END IF;
 -- Reconstruct all derived columns and exclusions from the original request. A self-consistent caller hash is not a classifier receipt.
 SELECT coalesce(jsonb_agg(projection.member ORDER BY projection.member->>'symbol'),'[]') INTO expected_members FROM (
  SELECT jsonb_build_object('symbol',r->'symbol','name',r->'name','exchange','TWSE','isin',r->'isin','cfi',r->'cfi','listingDate',r->'listingDateText','sector',r->'sectorText','observedAt',scope#>'{sources,0,observedAt}','sourceSection',r->'sourceSection') member FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection' IN('股票','創新板') AND r->>'cfi' ~ '^ES[A-Z]{4}$' AND r->>'symbol' ~ '^[1-9][0-9]{3}$'
  UNION ALL
  SELECT r||jsonb_build_object('observedAt',legacy#>'{sources,1,observedAt}','sourceSection','legacy TPEX stock observation') FROM jsonb_array_elements(legacy->'members')r WHERE r->>'exchange'='TPEX'
 )projection;
 SELECT coalesce(jsonb_agg(jsonb_build_object('symbol',r->'symbol','cfi',r->'cfi','sourceSection',r->'sourceSection','reason','non_ordinary_tdr') ORDER BY r->>'symbol'),'[]') INTO expected_excluded FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection'='臺灣存託憑證(TDR)' AND r->>'cfi' ~ '^ED[A-Z]{4}$';
 IF expected_members IS DISTINCT FROM payload->'members' OR expected_excluded IS DISTINCT FROM payload->'excluded' THEN RAISE EXCEPTION 'observed_classifier_output_mismatch'; END IF;
 IF scope->'counts' IS DISTINCT FROM jsonb_build_object(
  'twseMasterMatched',jsonb_array_length(scope->'rows'),'twseOrdinaryResearchCandidates',jsonb_array_length(expected_members)-(SELECT count(*)FROM jsonb_array_elements(legacy->'members')r WHERE r->>'exchange'='TPEX'),
  'twseInnovationBoard',(SELECT count(*)FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection'='創新板'),
  'twseOrdinaryAdditionalTransferRestrictionCfi',(SELECT count(*)FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection' IN('股票','創新板') AND r->>'cfi'<>'ESVUFR'),
  'twseTdrExcludedFromOrdinaryScope',jsonb_array_length(expected_excluded),'unchangedObservedTpexOrdinary',(SELECT count(*)FROM jsonb_array_elements(legacy->'members')r WHERE r->>'exchange'='TPEX'),
  'reconciledObservedOrdinaryResearchCohort',jsonb_array_length(expected_members),'legacyStrictObservedCohort',jsonb_array_length(legacy->'members')) THEN RAISE EXCEPTION 'observed_derived_counts_mismatch'; END IF;
 IF jsonb_array_length(scope->'newlyClassifiedOrdinarySymbols') IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection' IN('股票','創新板') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')l WHERE l->>'exchange'='TWSE' AND l->>'symbol'=r->>'symbol')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows')r WHERE r->>'sourceSection' IN('股票','創新板') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(legacy->'members')l WHERE l->>'exchange'='TWSE' AND l->>'symbol'=r->>'symbol') AND NOT (scope->'newlyClassifiedOrdinarySymbols' @> jsonb_build_array(r->'symbol'))) THEN RAISE EXCEPTION 'observed_derived_additions_mismatch'; END IF;

 IF EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'rows') r WHERE (
   (r->>'sourceSection' IN('股票','創新板') AND r->>'cfi' ~ '^ES[A-Z]{4}$' AND r->>'symbol' ~ '^[1-9][0-9]{3}$' AND r->>'classification'='ordinary_equity_research_candidate') OR
   (r->>'sourceSection'='臺灣存託憑證(TDR)' AND r->>'cfi' ~ '^ED[A-Z]{4}$' AND r->>'classification'='non_ordinary_tdr' AND r->'legacyStrictCfiMatched'='false'::jsonb)) IS NOT TRUE) THEN RAISE EXCEPTION 'observed_raw_classification_invalid'; END IF;
 latest:='-infinity';
 FOR source IN SELECT value FROM jsonb_array_elements(payload->'sourceReferences') LOOP
  IF source->>'url' IS NULL OR source->>'responseSha256' IS NULL OR source->>'responseBytes' IS NULL OR source->>'url' NOT IN('https://isin.twse.com.tw/isin/C_public.jsp?strMode=2','https://isin.twse.com.tw/isin/C_public.jsp?strMode=4') OR source->>'responseSha256' !~ '^[a-f0-9]{64}$'
   OR (source->>'responseBytes')::bigint<1 OR (source->>'responseBytes')::bigint>(CASE WHEN source->>'url' LIKE '%strMode=2' THEN 12000000 ELSE 4000000 END)
   OR public.research_observed_instant_v1(source->>'observedAt')>now_clock THEN RAISE EXCEPTION 'observed_source_receipt_invalid'; END IF;
  IF source->>'url'='https://isin.twse.com.tw/isin/C_public.jsp?strMode=2' THEN
   IF source->>'responseSha256' IS DISTINCT FROM scope#>>'{sources,0,sha256}' OR source->>'responseBytes' IS DISTINCT FROM scope#>>'{sources,0,bytes}' OR source->>'observedAt' IS DISTINCT FROM scope#>>'{sources,0,observedAt}'
    OR scope#>>'{sources,0,url}' IS DISTINCT FROM source->>'url' OR scope#>>'{sources,0,resolvedUrl}' IS DISTINCT FROM source->>'url' OR scope#>>'{sources,0,status}' IS DISTINCT FROM 'read_success' OR scope#>>'{sources,0,httpStatus}' IS DISTINCT FROM '200'
    OR public.research_observed_instant_v1(scope#>>'{sources,0,attemptedAt}')>public.research_observed_instant_v1(source->>'observedAt') THEN RAISE EXCEPTION 'observed_source_binding_invalid'; END IF;
  ELSE
   IF source->>'responseSha256' IS DISTINCT FROM legacy#>>'{sources,1,responseSha256}' OR source->>'responseBytes' IS DISTINCT FROM legacy#>>'{sources,1,responseBytes}' OR source->>'observedAt' IS DISTINCT FROM legacy#>>'{sources,1,observedAt}' OR legacy#>>'{sources,1,url}' IS DISTINCT FROM source->>'url' THEN RAISE EXCEPTION 'observed_source_binding_invalid'; END IF;
  END IF;
  latest:=greatest(latest,public.research_observed_instant_v1(source->>'observedAt'));
 END LOOP;
 IF public.research_observed_instant_v1(legacy->>'recordedAt')>now_clock OR public.research_observed_instant_v1(scope->>'recordedAt')>now_clock THEN RAISE EXCEPTION 'observed_roster_future'; END IF;
 -- Recompute inclusion from the supplied official classification rows, not caller membership flags.
 SELECT count(*) INTO matching_n FROM jsonb_array_elements(scope->'rows') r WHERE r->>'sourceSection' IN('股票','創新板') AND r->>'cfi' ~ '^ES[A-Z]{4}$' AND r->>'symbol' ~ '^[1-9][0-9]{3}$';
 matching_n:=matching_n+(SELECT count(*) FROM jsonb_array_elements(legacy->'members') r WHERE r->>'exchange'='TPEX' AND r->>'cfi'='ESVUFR');
 IF matching_n<>n OR excluded_n<>(SELECT count(*) FROM jsonb_array_elements(scope->'rows') r WHERE r->>'sourceSection'='臺灣存託憑證(TDR)' AND r->>'cfi' ~ '^ED[A-Z]{4}$') THEN RAISE EXCEPTION 'observed_membership_count_mismatch'; END IF;
 IF existing.snapshot_hash IS NOT NULL THEN
  IF existing.canonical_packet<>p_canonical_packet THEN RAISE EXCEPTION 'observed_replay_bytes_mismatch'; END IF;
  RETURN jsonb_build_object('snapshotHash',existing.snapshot_hash,'mappingDigest',existing.mapping_digest,'includedCount',existing.included_count,'excludedCount',existing.excluded_count,'receivedAt',existing.received_at,'latestObservedAt',existing.latest_observed_at,'idempotentReplay',true,'researchQualified',false,'strategyApproved',false,'entryEligible',false);
 END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
  IF member->>'exchange'='TWSE' THEN
   SELECT count(*) INTO matching_n FROM jsonb_array_elements(scope->'rows') r WHERE r->>'symbol'=member->>'symbol' AND r->>'name'=member->>'name' AND r->>'isin'=member->>'isin' AND r->>'cfi'=member->>'cfi' AND r->>'sourceSection'=member->>'sourceSection' AND r->>'sourceSection' IN('股票','創新板');
  ELSIF member->>'exchange'='TPEX' THEN
   SELECT count(*) INTO matching_n FROM jsonb_array_elements(legacy->'members') r WHERE r->>'exchange'='TPEX' AND r->>'symbol'=member->>'symbol' AND r->>'name'=member->>'name' AND r->>'isin'=member->>'isin' AND r->>'cfi'=member->>'cfi';
  ELSE RAISE EXCEPTION 'observed_exchange_invalid'; END IF;
  IF public.research_observed_instant_v1(member->>'observedAt') IS DISTINCT FROM (SELECT (r->>'observedAt')::timestamptz FROM jsonb_array_elements(payload->'sourceReferences')r WHERE r->>'url'=CASE WHEN member->>'exchange'='TWSE' THEN 'https://isin.twse.com.tw/isin/C_public.jsp?strMode=2' ELSE 'https://isin.twse.com.tw/isin/C_public.jsp?strMode=4' END) THEN RAISE EXCEPTION 'observed_member_clock_binding_invalid'; END IF;
  IF matching_n<>1 OR member->>'cfi' !~ '^ES[A-Z]{4}$' OR public.research_observed_instant_v1(member->>'observedAt')>now_clock THEN RAISE EXCEPTION 'observed_member_binding_invalid'; END IF;
  SELECT * INTO company FROM public.research_observed_companies_v1 WHERE market='TW' AND symbol=member->>'symbol';
  IF FOUND THEN
   IF company.exchange<>member->>'exchange' OR company.isin<>member->>'isin' OR company.issuer_name<>member->>'name' THEN RAISE EXCEPTION 'observed_issuer_conflict'; END IF;
  ELSE
   INSERT INTO public.research_observed_companies_v1(symbol,exchange,issuer_name,isin) VALUES(member->>'symbol',member->>'exchange',member->>'name',member->>'isin') RETURNING * INTO company;
  END IF;
  mappings:=mappings||jsonb_build_array(jsonb_build_object('researchCompanyId',company.research_company_id,'symbol',company.symbol,'stockId',null));
 END LOOP;
 mapping_hash:=encode(extensions.digest(convert_to(public.research_observed_canonical_json_v1(mappings),'UTF8'),'sha256'),'hex');
 INSERT INTO public.research_observed_roster_snapshots_v1(snapshot_hash,canonical_packet,schema_version,classifier_hash,classification_hash,legacy_snapshot_hash,source_references,included_count,excluded_count,mapping_digest,latest_observed_at,received_at)
  VALUES(p_snapshot_hash,p_canonical_packet,payload->>'schemaVersion',payload->>'classifierHash',payload->>'classificationHash',payload->>'legacySnapshotHash',payload->'sourceReferences',n,excluded_n,mapping_hash,latest,now_clock);
 INSERT INTO public.research_observed_roster_members_v1(snapshot_hash,research_company_id,symbol,exchange,isin,observed_name,observed_sector,cfi,source_section,observed_at)
  SELECT p_snapshot_hash,c.research_company_id,r->>'symbol',r->>'exchange',r->>'isin',r->>'name',r->>'sector',r->>'cfi',r->>'sourceSection',(r->>'observedAt')::timestamptz
  FROM jsonb_array_elements(payload->'members')r JOIN public.research_observed_companies_v1 c ON c.market='TW' AND c.symbol=r->>'symbol';
 RETURN jsonb_build_object('snapshotHash',p_snapshot_hash,'mappingDigest',mapping_hash,'includedCount',n,'excludedCount',excluded_n,'receivedAt',now_clock,'latestObservedAt',latest,'idempotentReplay',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false);
END $function$

CREATE OR REPLACE FUNCTION public.append_candidate_enterprise_multiple_snapshot_v6(p_stock_id uuid, p_session_date date, p_model_version text, p_payload jsonb, p_fact_ids uuid[], p_available_at timestamp with time zone, p_caller_principal uuid)
 RETURNS TABLE(idempotent_replay boolean, calculation_input_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_hash text; v_existing text; v_inserted boolean:=false; v_enterprise numeric; v_ev_ebitda numeric; v_ev_sales numeric; v_fact_ids uuid[];
BEGIN
  IF p_stock_id IS NULL OR p_available_at IS NULL
    OR NOT public.internal_principal_role_is_exact_v3_internal(p_caller_principal,'opportunity_runner',clock_timestamp())
    OR p_session_date IS NULL OR p_session_date>p_available_at::date OR p_available_at>clock_timestamp()
    OR COALESCE(p_model_version,'') !~ '^enterprise-multiple-v[0-9]+$'
    OR jsonb_typeof(COALESCE(p_payload,'null'::jsonb))<>'object'
    OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_payload) key)
       IS DISTINCT FROM ARRAY['cash_and_equivalents','current_price','diluted_shares','total_debt','ttm_ebitda','ttm_revenue']::text[]
    OR p_fact_ids IS NULL OR cardinality(p_fact_ids) NOT BETWEEN 1 AND 128
  THEN RAISE EXCEPTION 'invalid_enterprise_multiple_snapshot'; END IF;
  SELECT array_agg(DISTINCT fact_id ORDER BY fact_id) INTO v_fact_ids FROM unnest(p_fact_ids) fact_id;
  v_enterprise:=(p_payload->>'current_price')::numeric*(p_payload->>'diluted_shares')::numeric
    +(p_payload->>'total_debt')::numeric-(p_payload->>'cash_and_equivalents')::numeric;
  IF v_enterprise<=0 OR (p_payload->>'current_price')::numeric<=0 OR (p_payload->>'diluted_shares')::numeric<=0
    OR (p_payload->>'total_debt')::numeric<0 OR (p_payload->>'cash_and_equivalents')::numeric<0
  THEN RAISE EXCEPTION 'invalid_enterprise_multiple_snapshot_values'; END IF;
  v_ev_ebitda:=CASE WHEN NULLIF(p_payload->>'ttm_ebitda','')::numeric>0
    THEN v_enterprise/(p_payload->>'ttm_ebitda')::numeric END;
  v_ev_sales:=CASE WHEN NULLIF(p_payload->>'ttm_revenue','')::numeric>0
    THEN v_enterprise/(p_payload->>'ttm_revenue')::numeric END;
  IF (v_ev_ebitda IS NULL OR v_ev_ebitda>=1000) AND (v_ev_sales IS NULL OR v_ev_sales>=1000)
  THEN RAISE EXCEPTION 'enterprise_multiple_not_defensible'; END IF;
  v_hash:=encode(digest(convert_to(p_payload::text||'|'||array_to_string(v_fact_ids,','),'utf8'),'sha256'),'hex');
  INSERT INTO public.candidate_enterprise_multiple_snapshots_v6(
    stock_id,session_date,model_version,current_price,diluted_shares,total_debt,cash_and_equivalents,
    enterprise_value,ttm_ebitda,ttm_revenue,ev_ebitda_multiple,ev_sales_multiple,fact_ids,calculation_input_hash,available_at
  ) VALUES (
    p_stock_id,p_session_date,p_model_version,(p_payload->>'current_price')::numeric,(p_payload->>'diluted_shares')::numeric,
    (p_payload->>'total_debt')::numeric,(p_payload->>'cash_and_equivalents')::numeric,v_enterprise,
    NULLIF(p_payload->>'ttm_ebitda','')::numeric,NULLIF(p_payload->>'ttm_revenue','')::numeric,
    CASE WHEN v_ev_ebitda>0 AND v_ev_ebitda<1000 THEN v_ev_ebitda END,
    CASE WHEN v_ev_sales>0 AND v_ev_sales<1000 THEN v_ev_sales END,v_fact_ids,v_hash,p_available_at
  ) ON CONFLICT DO NOTHING RETURNING candidate_enterprise_multiple_snapshots_v6.calculation_input_hash INTO v_existing;
  v_inserted:=FOUND;
  IF NOT v_inserted THEN
    SELECT snapshot.calculation_input_hash INTO v_existing
    FROM public.candidate_enterprise_multiple_snapshots_v6 snapshot
    WHERE snapshot.stock_id=p_stock_id AND snapshot.session_date=p_session_date AND snapshot.model_version=p_model_version
      AND snapshot.calculation_input_hash=v_hash;
  END IF;
  IF v_existing IS DISTINCT FROM v_hash THEN RAISE EXCEPTION 'enterprise_multiple_snapshot_replay_missing'; END IF;
  idempotent_replay:=NOT v_inserted;calculation_input_hash:=v_hash;RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.append_instrument_roster_authority_v3(input instrument_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(instrument_authority_id uuid, official_alias_authority_ids uuid[], recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_aliases uuid[]:='{}'::uuid[]; v_alias uuid; v_existing uuid;
  v_existing_recorded timestamptz; v_registry_count integer; v_revision_count integer;
  v_stream_canonical bytea; v_stream_hash text; v_alias_canonical bytea;
  v_alias_hash text; v_alias_text text; v_alias_status public.authority_status_v3;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).roster_version<>'tw-instrument-roster-v3.0'
    OR (($1).exchange='TWSE') IS DISTINCT FROM (($1).provider='twse')
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'instrument_roster',($1).stock_id
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|instrument_roster',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='instrument_roster'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='instrument_roster'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 20001
    ) bounded;
    IF v_registry_count>=20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('instrument_roster',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.instrument_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_instruments_v3 retained
  WHERE retained.stock_id=($1).stock_id
    AND retained.symbol=($1).symbol
    AND retained.exchange=($1).exchange
    AND retained.instrument_type=($1).instrument_type
    AND retained.listing_status=($1).listing_status
    AND retained.official_legal_name=($1).official_legal_name
    AND retained.official_short_name IS NOT DISTINCT FROM ($1).official_short_name
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.roster_version=($1).roster_version
  ORDER BY retained.instrument_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_instrument_roster_authority_v3',$2,'instrument',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).stock_id,($1).source_timestamp,($1).roster_version
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_aliases,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.instrument_authority_id
    FROM public.stock_instruments_v3 retained
    WHERE retained.stock_id=($1).stock_id
    ORDER BY retained.recorded_at DESC,retained.instrument_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_instruments_v3(
    instrument_authority_id,stock_id,symbol,exchange,instrument_type,listing_status,
    official_legal_name,official_short_name,provider,source_timestamp,valid_from,valid_to,roster_version,recorded_at
  ) VALUES(v_id,($1).stock_id,($1).symbol,($1).exchange,($1).instrument_type,($1).listing_status,
    ($1).official_legal_name,($1).official_short_name,($1).provider,($1).source_timestamp,
    ($1).valid_from,($1).valid_to,($1).roster_version,v_now);
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|stock_alias',0));
  FOR v_alias_text,v_alias_status IN
    WITH normalized(alias,status) AS (
      SELECT btrim(regexp_replace(
          translate(
            regexp_replace(btrim(normalize(($1).official_legal_name,NFKC)),
              '[[:space:]]+',' ','g'),
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'
          ),
          '(股份有限公司|有限公司|公司)$',''
        )),
        CASE WHEN ($1).listing_status='active'
          THEN 'active'::public.authority_status_v3 ELSE 'inactive'::public.authority_status_v3 END
      UNION
      SELECT btrim(regexp_replace(
          translate(
            regexp_replace(btrim(normalize(($1).official_short_name,NFKC)),
              '[[:space:]]+',' ','g'),
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'
          ),
          '(股份有限公司|有限公司|公司)$',''
        )),
        CASE WHEN ($1).listing_status='active'
          THEN 'active'::public.authority_status_v3 ELSE 'inactive'::public.authority_status_v3 END
      WHERE ($1).official_short_name IS NOT NULL
    ), requested(alias,status) AS (
      SELECT alias,status FROM normalized
      WHERE char_length(alias) BETWEEN 2 AND 40
    ), latest_alias AS (
      SELECT DISTINCT ON (alias.normalized_alias)
        alias.normalized_alias,alias.status
      FROM public.stock_aliases_v3 alias
      WHERE alias.stock_id=($1).stock_id
        AND alias.source='official_roster_seed'
      ORDER BY alias.normalized_alias,alias.recorded_at DESC,alias.alias_authority_id
    ), revoked(alias,status) AS (
      SELECT latest_alias.normalized_alias,'inactive'::public.authority_status_v3
      FROM latest_alias
      WHERE latest_alias.status='active'
        AND NOT EXISTS (
          SELECT 1 FROM requested
          WHERE requested.alias=latest_alias.normalized_alias
            AND requested.status='active'
        )
    )
    SELECT alias,status FROM requested
    UNION
    SELECT alias,status FROM revoked
    ORDER BY alias,status
  LOOP
    v_alias_canonical:=convert_to(regexp_replace(jsonb_build_array(
      'stock_alias',($1).stock_id,v_alias_text,'official_roster_seed'
    )::text,', ', ',', 'g'),'utf8');
    v_alias_hash:=encode(extensions.digest(v_alias_canonical,'sha256'),'hex');
    PERFORM pg_advisory_xact_lock(hashtextextended(v_alias_hash,0));
    IF NOT EXISTS (
      SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='stock_alias'
        AND registry.stream_key_hash=v_alias_hash
        AND registry.stream_key_canonical=v_alias_canonical
    ) THEN
      SELECT count(*) INTO v_registry_count FROM (
        SELECT registry.stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3 registry
        WHERE registry.family='stock_alias'
        ORDER BY registry.stream_key_hash,registry.stream_key_canonical
        LIMIT 100001
      ) bounded;
      IF v_registry_count>=100000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
      END IF;
      INSERT INTO public.opportunity_authority_stream_registry_v3(
        family,stream_key_hash,stream_key_canonical,registered_at
      ) VALUES('stock_alias',v_alias_hash,v_alias_canonical,v_now);
    END IF;
    SELECT count(*) INTO v_revision_count FROM (
      SELECT alias.alias_authority_id
      FROM public.stock_aliases_v3 alias
      WHERE alias.stock_id=($1).stock_id
        AND alias.normalized_alias=v_alias_text
        AND alias.source='official_roster_seed'
      ORDER BY alias.recorded_at DESC,alias.alias_authority_id
      LIMIT 65
    ) bounded;
    IF v_revision_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    v_alias:=extensions.gen_random_uuid();
    INSERT INTO public.stock_aliases_v3(alias_authority_id,stock_id,normalized_alias,source,source_timestamp,
      approved_by_principal_id,approved_at,valid_from,valid_to,status,normalization_version,recorded_at)
    VALUES(v_alias,($1).stock_id,v_alias_text,'official_roster_seed',($1).source_timestamp,
      $2,v_now,($1).valid_from,($1).valid_to,v_alias_status,
      'entity-link-v3.1',v_now);
    v_aliases:=array_append(v_aliases,v_alias);
  END LOOP;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_instrument_roster_authority_v3',$2,'instrument',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).stock_id,($1).source_timestamp,($1).roster_version
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_aliases,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_legacy_analysis_evaluation_v3_11(p_input analysis_evaluation_input_v3_11, p_job uuid, p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_run uuid;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT run_id INTO v_run FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND job_id=p_job AND stage='analysis_revision' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  SELECT evaluation_id INTO v_id FROM public.legacy_analysis_evaluations_v3_11 WHERE producer_run_id=v_run AND symbol=(p_input).symbol;IF v_id IS NOT NULL THEN RETURN v_id;END IF;v_id:=extensions.gen_random_uuid();
  INSERT INTO public.legacy_analysis_evaluations_v3_11 VALUES(v_id,(p_input).symbol,(p_input).revision_id,(p_input).evaluated_material_change_hash,(p_input).disposition,(p_input).evaluated_at,(p_input).evaluated_source_cutoff,(p_input).evaluated_price_session,(p_input).evaluated_adjusted_close,(p_input).trigger,v_run,clock_timestamp());RETURN v_id;
END $function$

