CREATE OR REPLACE FUNCTION public.append_legacy_candidate_discovery_v3_11(p_input candidate_discovery_input_v3_11, p_job uuid, p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_seed public.opportunity_candidate_seed_membership_v3_11;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE run_id=(p_input).source_run_id AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run.run_id AND job_id=p_job AND stage='candidate_funnel' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND OR (p_input).material_evidence_hash!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  IF (p_input).stock_id IS NOT NULL THEN v_seed:=CASE WHEN (p_input).symbol=ANY(v_run.legacy_seed_symbols) THEN 'in_seed' ELSE 'out_of_seed' END;END IF;
  SELECT discovery_id INTO v_id FROM public.legacy_candidate_discovery_ledger_v3_11 WHERE source_run_id=(p_input).source_run_id AND source_key=(p_input).source_key AND document_revision_id IS NOT DISTINCT FROM (p_input).document_revision_id AND claim_id IS NOT DISTINCT FROM (p_input).claim_id AND mention_id IS NOT DISTINCT FROM (p_input).mention_id AND stock_id IS NOT DISTINCT FROM (p_input).stock_id AND reason=(p_input).reason;
  IF v_id IS NOT NULL THEN RETURN v_id;END IF;v_id:=extensions.gen_random_uuid();
  INSERT INTO public.legacy_candidate_discovery_ledger_v3_11 VALUES(v_id,(p_input).source_run_id,(p_input).source_key,(p_input).document_revision_id,(p_input).claim_id,(p_input).mention_id,(p_input).stock_id,(p_input).symbol,(p_input).disposition,(p_input).reason,(p_input).research_disposition,(p_input).research_reason,v_seed,CASE WHEN v_seed IS NULL THEN NULL ELSE v_run.legacy_seed_set_hash END,(p_input).material_evidence_hash,clock_timestamp());RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.append_legacy_radar_projection_v3_11(p_input legacy_radar_projection_input_v3_11, p_job uuid, p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_run uuid;v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT run_id INTO v_run FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_run AND status='running' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now AND producer_commit_sha=(p_input).producer_commit_sha AND worker_sha256=(p_input).worker_sha256 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_run AND job_id=p_job AND stage='compact_radar_projection' AND status='leased' AND owner_token_hash=v_token_hash AND lease_expires_at>=v_now FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  IF (p_input)."window" NOT IN ('daily','three_day','weekly','home') OR (p_input).payload_sha256<>encode(extensions.digest((p_input).payload_canonical,'sha256'),'hex') OR convert_from((p_input).payload_canonical,'utf8')::jsonb<>(p_input).payload_json OR (p_input).projection_key<>'legacy-radar-v3.11:'||(p_input)."window"||':'||to_char((p_input).as_of AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')||':'||(p_input).payload_sha256 THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended((p_input)."window",0));SELECT projection_id INTO v_id FROM public.legacy_radar_projections_v3_11 WHERE projection_key=(p_input).projection_key;
  IF v_id IS NULL THEN v_id:=extensions.gen_random_uuid();INSERT INTO public.legacy_radar_projections_v3_11(projection_id,projection_key,"window",as_of,producer_commit_sha,worker_sha256,material_change_root,payload_canonical,payload_json,payload_sha256) VALUES(v_id,(p_input).projection_key,(p_input)."window",(p_input).as_of,(p_input).producer_commit_sha,(p_input).worker_sha256,(p_input).material_change_root,(p_input).payload_canonical,(p_input).payload_json,(p_input).payload_sha256);END IF;
  PERFORM set_config('stockinsider.legacy_projection_retention','on',true);DELETE FROM public.legacy_radar_projections_v3_11 WHERE projection_id IN (SELECT projection_id FROM public.legacy_radar_projections_v3_11 WHERE "window"=(p_input)."window" ORDER BY as_of DESC,created_at DESC,projection_id ASC OFFSET 1500);RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.append_legacy_source_shard_v3_19(p_run uuid, p_completed_source_job uuid, p_source_result_hash text, p_selected_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_initial_count integer;v_next_ordinal integer;v_first_ordinal integer:=NULL;
  v_first_revision uuid:=NULL;v_appended integer:=0;v_item jsonb;v_source_key public.source_key_v3;
  v_revision uuid;v_selected_bytes bytea;v_selected_hash text;v_inserted integer;
BEGIN
  IF p_source_result_hash !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof(p_selected_rows)<>'array' OR jsonb_array_length(p_selected_rows)>272 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_source_shard_shape_invalid';
  END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 job
  JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=job.job_id
  WHERE job.run_id=p_run AND job.job_id=p_completed_source_job
    AND job.stage='source_sync' AND job.status='succeeded' AND result.result_hash=p_source_result_hash;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_source_shard_predecessor_conflict';
  END IF;
  SELECT count(*),coalesce(max(frozen.selection_ordinal),-1)+1
  INTO v_initial_count,v_next_ordinal
  FROM public.legacy_frozen_source_revisions_v3_11 frozen WHERE frozen.run_id=p_run;
  FOR v_item IN SELECT item.value FROM jsonb_array_elements(p_selected_rows) item
  LOOP
    IF jsonb_typeof(v_item)<>'array' OR jsonb_array_length(v_item)<>11
      OR nullif(v_item->>0,'') IS NULL OR nullif(v_item->>1,'') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_source_shard_row_invalid';
    END IF;
    v_source_key:=(v_item->>0)::public.source_key_v3;
    v_revision:=(v_item->>1)::uuid;
    v_selected_bytes:=convert_to(v_item::text,'utf8');
    v_selected_hash:=encode(extensions.digest(v_selected_bytes,'sha256'),'hex');
    INSERT INTO public.legacy_frozen_source_revisions_v3_11(
      run_id,selection_ordinal,source_key,revision_id,selected_revision_row_canonical,
      selected_revision_row_json,selected_revision_row_hash,raw_field_payload_algorithm_version,
      ingestion_content_revision_sha256,canonical_content_algorithm_version,canonical_content_sha256
    ) VALUES(
      p_run,v_next_ordinal,v_source_key,v_revision,v_selected_bytes,v_item,v_selected_hash,
      v_item->>7,v_item->>8,v_item->>9,v_item->>10
    ) ON CONFLICT(run_id,revision_id) DO NOTHING;
    GET DIAGNOSTICS v_inserted=ROW_COUNT;
    IF v_inserted=1 THEN
      IF v_first_ordinal IS NULL THEN
        v_first_ordinal:=v_next_ordinal;v_first_revision:=v_revision;
      END IF;
      v_next_ordinal:=v_next_ordinal+1;v_appended:=v_appended+1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('initialCount',v_initial_count,'firstOrdinal',v_first_ordinal,
    'firstRevision',v_first_revision,'appended',v_appended);
END $function$

CREATE OR REPLACE FUNCTION public.append_manual_stock_alias_authority_v3(input manual_alias_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(alias_authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_normalized_alias text; v_existing uuid; v_existing_recorded timestamptz;
  v_registry_count integer; v_revision_count integer;
  v_stream_canonical bytea; v_stream_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'identity_reviewer',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  v_normalized_alias:=btrim(regexp_replace(
    translate(
      regexp_replace(btrim(normalize(($1).proposed_alias,NFKC)),'[[:space:]]+',' ','g'),
      'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'
    ),
    '(股份有限公司|有限公司|公司)$',''
  ));
  IF char_length(v_normalized_alias) NOT BETWEEN 2 AND 40 THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'stock_alias',($1).stock_id,v_normalized_alias,'manual_review'
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|stock_alias',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='stock_alias'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='stock_alias'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 100001
    ) bounded;
    IF v_registry_count>=100000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('stock_alias',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.alias_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_aliases_v3 retained
  WHERE retained.stock_id=($1).stock_id
    AND retained.normalized_alias=v_normalized_alias
    AND retained.source='manual_review'
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.approved_by_principal_id=$2
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.status=($1).status
  ORDER BY retained.alias_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_manual_stock_alias_authority_v3',$2,'alias',v_existing,
      v_stream_hash,'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.alias_authority_id
    FROM public.stock_aliases_v3 retained
    WHERE retained.stock_id=($1).stock_id
      AND retained.normalized_alias=v_normalized_alias
      AND retained.source='manual_review'
    ORDER BY retained.recorded_at DESC,retained.alias_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_aliases_v3(alias_authority_id,stock_id,normalized_alias,source,source_timestamp,
    approved_by_principal_id,approved_at,valid_from,valid_to,status,normalization_version,recorded_at)
  VALUES(v_id,($1).stock_id,v_normalized_alias,'manual_review',($1).source_timestamp,
    $2,v_now,($1).valid_from,($1).valid_to,($1).status,'entity-link-v3.1',v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_manual_stock_alias_authority_v3',$2,'alias',v_id,
    v_stream_hash,'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_opportunity_manifest_page_v3(job_id uuid, owner_token text, requested_manifest_id uuid, section_key opportunity_manifest_section_key_v3, page_ordinal integer, first_row_ordinal bigint, page_canonical bytea, page_json jsonb, requested_page_hash text, rows opportunity_manifest_row_input_v3[])
 RETURNS TABLE(status opportunity_manifest_page_status_v3, page_id uuid, row_count integer, page_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_manifest public.opportunity_manifests_v3%ROWTYPE;
  v_now timestamptz:=clock_timestamp(); v_page uuid; v_descriptor jsonb; v_row public.opportunity_manifest_row_input_v3;
  v_count integer:=COALESCE(cardinality($10),0); v_expected bigint:=$6;
  v_payload jsonb; v_read jsonb; v_index integer:=0; v_expected_identity text;
  v_next_native jsonb; v_next_hash text; v_next_identity text; v_next_terminal text;
  v_candidate_page jsonb; v_first_identity text; v_last_identity text;
  v_lookup_symbol text; v_lookup_session date; v_entry_session date;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased' AND j.lease_expires_at>=v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  SELECT * INTO v_manifest FROM public.opportunity_manifests_v3 m
  WHERE m.manifest_id=$3 AND m.status='building' FOR UPDATE;
  SELECT p.payload_json->5 INTO v_payload
  FROM public.opportunity_job_payloads_v3 p
  WHERE p.job_id=$1 AND p.run_id=v_job.run_id AND p.payload_kind='manifest_page';
  SELECT u.read_json->5 INTO v_read
  FROM public.opportunity_worker_read_units_v3 u
  WHERE u.job_id=$1 AND u.input_hash=v_job.input_hash;
  IF v_job.job_id IS NULL OR v_manifest.manifest_id IS NULL OR v_count<1 OR v_count>2000
    OR octet_length($7)>786432 OR $9!~'^[0-9a-f]{64}$'
    OR encode(extensions.digest($7,'sha256'),'hex')<>$9
    OR $7<>convert_to(regexp_replace($8::text, ', ', ',', 'g'),'utf8')
    OR v_payload IS NULL OR v_read IS NULL
    OR (v_payload->>1)::uuid<>$3
    OR (v_payload->>5)::public.opportunity_manifest_section_key_v3<>$4
    OR (v_payload->>6)::integer<>$5 OR (v_payload->>7)::bigint<>$6
    OR jsonb_typeof(v_read->1)<>'array'
    OR jsonb_array_length(v_read->1) NOT BETWEEN v_count AND v_count+1
    OR v_count>least(2000,jsonb_array_length(v_read->1))
    OR jsonb_typeof($8)<>'array' OR jsonb_array_length($8)<>8
    OR $8->>0<>'opportunity-manifest-page-v3.3'
    OR $8->>1<>v_manifest.manifest_kind::text OR $8->>2<>v_manifest.contract_version
    OR ($8->>3)::timestamptz IS DISTINCT FROM v_manifest.source_cutoff
    OR ($8->>4)::public.opportunity_manifest_section_key_v3<>$4
    OR ($8->>5)::integer<>$5 OR ($8->>6)::bigint<>$6
    OR jsonb_typeof($8->7)<>'array' OR jsonb_array_length($8->7)<>v_count
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  IF v_count<least(2000,jsonb_array_length(v_read->1)) THEN
    v_next_native:=v_read->1->v_count;
    v_next_hash:=encode(extensions.digest(
      convert_to(regexp_replace(v_next_native::text, ', ', ',', 'g'),'utf8'),'sha256'
    ),'hex');
    v_next_identity:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'opportunity-manifest-row-identity-v3.3',v_manifest.manifest_kind,$4,$6+v_count,v_next_hash
    )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex');
    v_next_terminal:=CASE
      WHEN v_next_native @> '["active"]'::jsonb THEN 'effective_active'
      WHEN v_next_native @> '["inactive"]'::jsonb OR v_next_native @> '["delisted"]'::jsonb
        THEN 'revoked_or_expired'
      ELSE NULL
    END;
    v_candidate_page:=jsonb_set(
      $8,
      '{7}',
      ($8->7)||jsonb_build_array(jsonb_build_array(
        $6+v_count,v_next_identity,v_next_terminal,v_next_native
      )),
      false
    );
    IF octet_length(convert_to(
      regexp_replace(v_candidate_page::text, ', ', ',', 'g'),'utf8'
    ))<=786432 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
  END IF;
  IF $5=0 THEN
    IF v_payload->8<>'null'::jsonb OR v_payload->9<>'null'::jsonb OR v_payload->10<>'null'::jsonb
      OR v_read->0<>'null'::jsonb
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1
      FROM public.opportunity_manifest_pages_v3 prior
      WHERE prior.manifest_id=$3 AND prior.section_key=$4 AND prior.page_ordinal=$5-1
        AND prior.page_id=(v_payload->>8)::uuid
        AND prior.page_hash=v_payload->>9
        AND prior.last_identity=v_payload->>10
    ) OR v_read->0->>0<>v_payload->>8 OR v_read->0->>1<>v_payload->>9
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  END IF;
  v_descriptor:=public.derive_manifest_page_descriptor_v3_internal($3,$4,$5,$6);
  v_page:=(v_descriptor->>0)::uuid;
  v_first_identity:=($10[1]).identity_key;
  v_last_identity:=($10[v_count]).identity_key;
  IF v_manifest.manifest_kind='sector_benchmark' THEN
    SELECT (pair->>1)::date INTO v_entry_session
    FROM jsonb_array_elements(v_manifest.header_json) pair
    WHERE pair->>0='entrySession';
  END IF;
  INSERT INTO public.opportunity_manifest_pages_v3(
    page_id,manifest_id,section_key,page_ordinal,first_row_ordinal,row_count,
    first_identity,last_identity,page_canonical,page_json,page_hash,recorded_at
  ) VALUES(
    v_page,$3,$4,$5,$6,v_count,v_first_identity,v_last_identity,$7,$8,$9,v_now
  );
  FOREACH v_row IN ARRAY $10 LOOP
    v_expected_identity:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'opportunity-manifest-row-identity-v3.3',v_manifest.manifest_kind,$4,v_expected,v_row.payload_hash
    )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex');
    IF v_row.row_ordinal<>v_expected OR v_row.payload_hash!~'^[0-9a-f]{64}$'
      OR encode(extensions.digest(v_row.payload_canonical,'sha256'),'hex')<>v_row.payload_hash
      OR v_row.payload_canonical<>convert_to(regexp_replace(v_row.payload_json::text, ', ', ',', 'g'),'utf8')
      OR v_row.payload_json IS DISTINCT FROM v_read->1->v_index
      OR v_row.identity_key<>v_expected_identity
      OR $8->7->v_index IS DISTINCT FROM jsonb_build_array(
        v_row.row_ordinal,v_row.identity_key,v_row.terminal_code,v_row.payload_json
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
    v_lookup_symbol:=NULL;
    v_lookup_session:=NULL;
    IF v_manifest.manifest_kind='sector_benchmark' AND $4='entry_rows' THEN
      v_lookup_symbol:=v_row.payload_json->>0;
      v_lookup_session:=v_entry_session;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND $4='evaluation_rows' THEN
      v_lookup_session:=(v_row.payload_json->>0)::date;
      v_lookup_symbol:=v_row.payload_json->>3;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND $4='session_conservation' THEN
      v_lookup_session:=(v_row.payload_json->>0)::date;
    END IF;
    INSERT INTO public.opportunity_manifest_rows_v3(
      manifest_id,page_id,section_key,row_ordinal,identity_key,terminal_code,
      lookup_symbol,lookup_session,payload_json,payload_canonical,payload_hash,recorded_at
    ) VALUES(
      $3,v_page,$4,v_row.row_ordinal,v_row.identity_key,v_row.terminal_code,
      v_lookup_symbol,v_lookup_session,v_row.payload_json,v_row.payload_canonical,
      v_row.payload_hash,v_now
    );
    v_expected:=v_expected+1;
    v_index:=v_index+1;
  END LOOP;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_kind='manifest_page',
    output_manifest_id=$3,output_hash=$9,terminal_at=v_now,
    owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'stored'::public.opportunity_manifest_page_status_v3,v_page,v_count,$9;
END
$function$

CREATE OR REPLACE FUNCTION public.append_peer_relationship_authority_v3(input peer_relationship_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(relationship_authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_supplier uuid; v_customer uuid; v_existing uuid; v_existing_recorded timestamptz;
  v_registry_count integer; v_revision_count integer;
  v_stream_canonical bytea; v_stream_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'peer_reviewer',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  SELECT stock_id INTO v_supplier FROM public.stock_instruments_v3 WHERE instrument_authority_id=($1).supplier_instrument_authority_id AND instrument_type='common_stock' FOR SHARE;
  SELECT stock_id INTO v_customer FROM public.stock_instruments_v3 WHERE instrument_authority_id=($1).customer_instrument_authority_id AND instrument_type='common_stock' FOR SHARE;
  IF v_supplier IS NULL OR v_customer IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='authority_reference_unavailable'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'peer_relationship',v_supplier,v_customer,'supply_chain'
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|peer_relationship',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='peer_relationship'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='peer_relationship'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 100001
    ) bounded;
    IF v_registry_count>=100000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('peer_relationship',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.relationship_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_peer_relationships_v3 retained
  WHERE retained.supplier_stock_id=v_supplier
    AND retained.customer_stock_id=v_customer
    AND retained.relationship_kind='supply_chain'
    AND retained.supplier_instrument_authority_id=($1).supplier_instrument_authority_id
    AND retained.customer_instrument_authority_id=($1).customer_instrument_authority_id
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.status=($1).status
    AND retained.evidence_ref=($1).evidence_ref
    AND retained.reviewer_principal_id=$2
  ORDER BY retained.relationship_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_peer_relationship_authority_v3',$2,'peer_relationship',v_existing,
      v_stream_hash,'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.relationship_authority_id
    FROM public.stock_peer_relationships_v3 retained
    WHERE retained.supplier_stock_id=v_supplier
      AND retained.customer_stock_id=v_customer
      AND retained.relationship_kind='supply_chain'
    ORDER BY retained.recorded_at DESC,retained.relationship_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_peer_relationships_v3(relationship_authority_id,supplier_instrument_authority_id,
    supplier_stock_id,customer_instrument_authority_id,customer_stock_id,relationship_kind,source_timestamp,
    approved_at,valid_from,valid_to,status,evidence_ref,reviewer_principal_id,recorded_at)
  VALUES(v_id,($1).supplier_instrument_authority_id,v_supplier,($1).customer_instrument_authority_id,v_customer,
    'supply_chain',($1).source_timestamp,v_now,($1).valid_from,($1).valid_to,($1).status,($1).evidence_ref,$2,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_peer_relationship_authority_v3',$2,'peer_relationship',v_id,
    v_stream_hash,'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

