CREATE OR REPLACE FUNCTION public.append_price_authority_v3(input price_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(kind price_authority_kind_v3, observation_id uuid, snapshot_id uuid, reported_pe_id uuid, dataset_hash text, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_observation uuid;
  v_snapshot uuid;
  v_reported_pe uuid;
  v_hash text;
  v_feed public.corporate_action_feed_evidence_input_v3;
  v_event public.corporate_action_event_input_v3;
  v_i integer:=0;
  v_count integer;
  v_expected_provider text;
  v_expected_feeds text[];
  v_expected_event_feed text;
  v_feed_rows jsonb;
  v_event_rows jsonb;
  v_source_row_preimage jsonb;
  v_snapshot_preimage jsonb;
  v_input_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).kind='raw_price' THEN
    IF ($1).raw_price IS NULL OR ($1).corporate_action_snapshot IS NOT NULL OR ($1).exchange_reported_pe IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    v_expected_provider:=CASE (($1).raw_price).exchange
      WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    IF (($1).raw_price).provider::text NOT IN (v_expected_provider,'finmind')
      OR (($1).raw_price).source_timestamp>(($1).raw_price).collected_at
      OR (($1).raw_price).collected_at>v_now
      OR NOT EXISTS (
        SELECT 1
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_authority_id=(($1).raw_price).session_authority_id
          AND session.session_id=(($1).raw_price).session_id
          AND session.market::text=(($1).raw_price).exchange::text
          AND session.status='completed'
          AND session.provider::text=v_expected_provider
      )
    THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_price_authority'; END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).raw_price).stock_id::text||'|'||(($1).raw_price).exchange::text||'|'||
      (($1).raw_price).session_id::text||'|'||(($1).raw_price).session_authority_id::text||'|'||
      (($1).raw_price).provider::text,0
    ));
    SELECT observation.observation_id INTO v_observation
    FROM public.opportunity_price_observations_v3 observation
    WHERE observation.stock_id=(($1).raw_price).stock_id
      AND observation.exchange=(($1).raw_price).exchange
      AND observation.session_id=(($1).raw_price).session_id
      AND observation.session_authority_id=(($1).raw_price).session_authority_id
      AND observation.provider=(($1).raw_price).provider
      AND observation.raw_open=(($1).raw_price).raw_open
      AND observation.raw_high=(($1).raw_price).raw_high
      AND observation.raw_low=(($1).raw_price).raw_low
      AND observation.raw_close=(($1).raw_price).raw_close
      AND observation.volume=(($1).raw_price).volume
      AND observation.turnover_twd=(($1).raw_price).turnover_twd
      AND observation.source_timestamp=(($1).raw_price).source_timestamp
      AND observation.collected_at=(($1).raw_price).collected_at
      AND observation.source_ref=(($1).raw_price).source_ref
    ORDER BY observation.observation_id
    LIMIT 1;
    IF v_observation IS NOT NULL THEN
      RETURN QUERY SELECT ($1).kind,v_observation,NULL::uuid,NULL::uuid,NULL::text,v_now;
      RETURN;
    END IF;
    SELECT count(*) INTO v_count FROM (
      SELECT 1
      FROM public.opportunity_price_observations_v3 observation
      WHERE observation.stock_id=(($1).raw_price).stock_id
        AND observation.exchange=(($1).raw_price).exchange
        AND observation.session_id=(($1).raw_price).session_id
        AND observation.session_authority_id=(($1).raw_price).session_authority_id
        AND observation.provider=(($1).raw_price).provider
      ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
        observation.recorded_at DESC,observation.source_ref,observation.observation_id
      LIMIT 65
    ) bounded_revisions;
    IF v_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
    v_observation:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_price_observations_v3(
      observation_id,stock_id,exchange,session_id,session_authority_id,raw_open,raw_high,raw_low,raw_close,
      volume,turnover_twd,provider,source_timestamp,collected_at,source_ref,recorded_at
    ) VALUES(v_observation,(($1).raw_price).stock_id,(($1).raw_price).exchange,(($1).raw_price).session_id,
      (($1).raw_price).session_authority_id,(($1).raw_price).raw_open,(($1).raw_price).raw_high,
      (($1).raw_price).raw_low,(($1).raw_price).raw_close,(($1).raw_price).volume,
      (($1).raw_price).turnover_twd,(($1).raw_price).provider,(($1).raw_price).source_timestamp,
      (($1).raw_price).collected_at,(($1).raw_price).source_ref,v_now);
    v_input_hash:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
      'raw-price-authority-v3.1',(($1).raw_price).stock_id,(($1).raw_price).exchange,
      (($1).raw_price).session_id,(($1).raw_price).session_authority_id,
      (($1).raw_price).raw_open,(($1).raw_price).raw_high,(($1).raw_price).raw_low,
      (($1).raw_price).raw_close,(($1).raw_price).volume,(($1).raw_price).turnover_twd,
      (($1).raw_price).provider,(($1).raw_price).source_timestamp,
      (($1).raw_price).collected_at,(($1).raw_price).source_ref
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_price_authority_v3',$2,'price_observation',v_observation,v_input_hash,'appended',v_now
    );
  ELSIF ($1).kind='corporate_action_snapshot' THEN
    IF ($1).corporate_action_snapshot IS NULL OR ($1).raw_price IS NOT NULL OR ($1).exchange_reported_pe IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    v_expected_provider:=CASE (($1).corporate_action_snapshot).exchange
      WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    v_expected_feeds:=CASE (($1).corporate_action_snapshot).exchange
      WHEN 'TWSE' THEN ARRAY[
        'twse:twt49u:v1','twse:twtauu:v1','twse:twtb8u:v1'
      ] ELSE ARRAY[
        'tpex:exright-cal:v1','tpex:reduction-reference:v1','tpex:change-reference:v1'
      ] END;
    IF (($1).corporate_action_snapshot).corporate_action_version<>'tw-corporate-action-v3.1'
      OR (($1).corporate_action_snapshot).provider::text<>v_expected_provider
      OR (($1).corporate_action_snapshot).collected_at>v_now
      OR cardinality((($1).corporate_action_snapshot).feed_evidence)<>3
      OR cardinality((($1).corporate_action_snapshot).events)
        <> (($1).corporate_action_snapshot).declared_event_count
      OR NOT EXISTS (
        SELECT 1
        FROM public.tw_trading_sessions_v3 session
        WHERE session.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
          AND session.session_id=(($1).corporate_action_snapshot).session_id
          AND session.market::text=(($1).corporate_action_snapshot).exchange::text
          AND session.status='completed'
          AND session.provider::text=v_expected_provider
      )
    THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_authority'; END IF;
    FOR v_i IN 1..3 LOOP
      v_feed:=(($1).corporate_action_snapshot).feed_evidence[v_i];
      IF v_feed.feed_identity<>v_expected_feeds[v_i] THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_feed'; END IF;
    END LOOP;
    IF (
      SELECT coalesce(sum(feed.parsed_row_count),0)
      FROM unnest((($1).corporate_action_snapshot).feed_evidence)
        feed(feed_identity,response_byte_count,response_sha256,parsed_row_count)
    ) <> (($1).corporate_action_snapshot).declared_event_count THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_corporate_action_feed';
    END IF;
    v_i:=0;
    FOREACH v_event IN ARRAY (($1).corporate_action_snapshot).events LOOP
      v_i:=v_i+1;
      v_expected_event_feed:=CASE v_event.event_kind
        WHEN 'ex_right_dividend' THEN (v_expected_feeds)[1]
        WHEN 'capital_reduction' THEN (v_expected_feeds)[2]
        ELSE (v_expected_feeds)[3] END;
      IF v_event.feed_identity<>v_expected_event_feed
        OR (v_i>1 AND v_event.symbol<=
          ((($1).corporate_action_snapshot).events[v_i-1]).symbol)
      THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_conflict'; END IF;
      v_source_row_preimage:=jsonb_build_array(
        'corporate-action-source-row-v3.1',
        (($1).corporate_action_snapshot).exchange,
        (($1).corporate_action_snapshot).session_id,
        v_event.symbol,v_event.event_kind,v_event.pre_action_reference_price,
        v_event.post_action_reference_price,v_event.feed_identity
      );
      IF v_event.source_row_ref<>encode(extensions.digest(convert_to(
        regexp_replace(v_source_row_preimage::text,', ', ',', 'g'),'utf8'
      ),'sha256'),'hex') THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_source_row_ref'; END IF;
    END LOOP;
    SELECT jsonb_agg(jsonb_build_array(
      feed.feed_identity,feed.response_byte_count,feed.response_sha256,feed.parsed_row_count
    ) ORDER BY feed.ordinality)
    INTO v_feed_rows
    FROM unnest((($1).corporate_action_snapshot).feed_evidence)
      WITH ORDINALITY feed(feed_identity,response_byte_count,response_sha256,parsed_row_count,ordinality);
    SELECT coalesce(jsonb_agg(jsonb_build_array(
      event.symbol,event.event_kind,event.pre_action_reference_price,
      event.post_action_reference_price,event.feed_identity,event.source_row_ref
    ) ORDER BY event.ordinality),'[]'::jsonb)
    INTO v_event_rows
    FROM unnest((($1).corporate_action_snapshot).events)
      WITH ORDINALITY event(symbol,event_kind,pre_action_reference_price,
        post_action_reference_price,feed_identity,source_row_ref,ordinality);
    v_snapshot_preimage:=jsonb_build_array(
      'corporate-action-snapshot-v3.1',
      (($1).corporate_action_snapshot).exchange,
      (($1).corporate_action_snapshot).session_id,
      (($1).corporate_action_snapshot).session_authority_id,
      (($1).corporate_action_snapshot).corporate_action_version,
      (($1).corporate_action_snapshot).provider,
      (($1).corporate_action_snapshot).collected_at,
      v_feed_rows,v_event_rows
    );
    v_hash:=encode(extensions.digest(convert_to(
      regexp_replace(v_snapshot_preimage::text,', ', ',', 'g'),'utf8'
    ),'sha256'),'hex');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).corporate_action_snapshot).exchange::text||'|'||
      (($1).corporate_action_snapshot).session_id::text||'|'||
      (($1).corporate_action_snapshot).session_authority_id::text||'|'||
      (($1).corporate_action_snapshot).corporate_action_version,0
    ));
    SELECT snapshot.snapshot_id INTO v_snapshot
    FROM public.opportunity_corporate_action_snapshots_v3 snapshot
    WHERE snapshot.exchange=(($1).corporate_action_snapshot).exchange
      AND snapshot.session_id=(($1).corporate_action_snapshot).session_id
      AND snapshot.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
      AND snapshot.corporate_action_version=(($1).corporate_action_snapshot).corporate_action_version
      AND snapshot.dataset_hash=v_hash
    ORDER BY snapshot.snapshot_id
    LIMIT 1;
    IF v_snapshot IS NOT NULL THEN
      RETURN QUERY SELECT ($1).kind,NULL::uuid,v_snapshot,NULL::uuid,v_hash,v_now;
      RETURN;
    END IF;
    SELECT count(*) INTO v_count FROM (
      SELECT 1
      FROM public.opportunity_corporate_action_snapshots_v3 snapshot
      WHERE snapshot.exchange=(($1).corporate_action_snapshot).exchange
        AND snapshot.session_id=(($1).corporate_action_snapshot).session_id
        AND snapshot.session_authority_id=(($1).corporate_action_snapshot).session_authority_id
        AND snapshot.corporate_action_version=(($1).corporate_action_snapshot).corporate_action_version
      ORDER BY snapshot.collected_at DESC,snapshot.recorded_at DESC,snapshot.snapshot_id
      LIMIT 65
    ) bounded_revisions;
    IF v_count>=64 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
    v_snapshot:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_corporate_action_snapshots_v3(
      snapshot_id,exchange,session_id,session_authority_id,corporate_action_version,provider,
      collected_at,declared_event_count,dataset_hash,recorded_at
    ) VALUES(v_snapshot,(($1).corporate_action_snapshot).exchange,(($1).corporate_action_snapshot).session_id,
      (($1).corporate_action_snapshot).session_authority_id,(($1).corporate_action_snapshot).corporate_action_version,
      (($1).corporate_action_snapshot).provider,(($1).corporate_action_snapshot).collected_at,
      (($1).corporate_action_snapshot).declared_event_count,v_hash,v_now);
    v_i:=0;
    FOREACH v_feed IN ARRAY (($1).corporate_action_snapshot).feed_evidence LOOP
      INSERT INTO public.opportunity_corporate_action_feed_evidence_v3(
        snapshot_id,feed_ordinal,feed_identity,response_byte_count,response_sha256,parsed_row_count,recorded_at
      ) VALUES(v_snapshot,v_i,v_feed.feed_identity,v_feed.response_byte_count,v_feed.response_sha256,v_feed.parsed_row_count,v_now);
      v_i:=v_i+1;
    END LOOP;
    v_i:=0;
    FOREACH v_event IN ARRAY (($1).corporate_action_snapshot).events LOOP
      INSERT INTO public.opportunity_corporate_action_events_v3(
        snapshot_id,event_ordinal,symbol,event_kind,pre_action_reference_price,post_action_reference_price,
        feed_identity,source_row_ref,recorded_at
      ) VALUES(v_snapshot,v_i,v_event.symbol,v_event.event_kind,v_event.pre_action_reference_price,
        v_event.post_action_reference_price,v_event.feed_identity,v_event.source_row_ref,v_now);
      v_i:=v_i+1;
    END LOOP;
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_price_authority_v3',$2,'price_observation',v_snapshot,v_hash,'appended',v_now
    );
  ELSE
    IF ($1).exchange_reported_pe IS NULL OR ($1).raw_price IS NOT NULL OR ($1).corporate_action_snapshot IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';END IF;
    v_expected_provider:=CASE (($1).exchange_reported_pe).exchange WHEN 'TWSE' THEN 'twse' ELSE 'tpex' END;
    IF (($1).exchange_reported_pe).close<=0
      OR (($1).exchange_reported_pe).close='Infinity'::double precision
      OR (($1).exchange_reported_pe).reported_pe IN ('Infinity'::double precision,'-Infinity'::double precision)
      OR (($1).exchange_reported_pe).source_ref NOT LIKE v_expected_provider||':%'
      OR (($1).exchange_reported_pe).published_at>(($1).exchange_reported_pe).source_timestamp
      OR (($1).exchange_reported_pe).source_timestamp>(($1).exchange_reported_pe).collected_at
      OR (($1).exchange_reported_pe).collected_at>v_now
      OR NOT EXISTS (
        SELECT 1 FROM public.tw_trading_sessions_v3 session
        WHERE session.session_id=(($1).exchange_reported_pe).session_date
          AND session.market::text=(($1).exchange_reported_pe).exchange::text
          AND session.provider::text=v_expected_provider AND session.status='completed'
      ) THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_price_authority';END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      (($1).exchange_reported_pe).stock_id::text||'|'||(($1).exchange_reported_pe).exchange::text||'|'||
      (($1).exchange_reported_pe).session_date::text,0));
    SELECT reported.reported_pe_id INTO v_reported_pe FROM public.opportunity_exchange_reported_pe_v3 reported
    WHERE reported.stock_id=(($1).exchange_reported_pe).stock_id AND reported.exchange=(($1).exchange_reported_pe).exchange
      AND reported.session_date=(($1).exchange_reported_pe).session_date AND reported.close=(($1).exchange_reported_pe).close
      AND reported.reported_pe=(($1).exchange_reported_pe).reported_pe AND reported.published_at=(($1).exchange_reported_pe).published_at
      AND reported.source_timestamp=(($1).exchange_reported_pe).source_timestamp AND reported.collected_at=(($1).exchange_reported_pe).collected_at
      AND reported.source_ref=(($1).exchange_reported_pe).source_ref ORDER BY reported.reported_pe_id LIMIT 1;
    IF v_reported_pe IS NOT NULL THEN RETURN QUERY SELECT ($1).kind,NULL::uuid,NULL::uuid,v_reported_pe,NULL::text,v_now;RETURN;END IF;
    v_reported_pe:=extensions.gen_random_uuid();
    INSERT INTO public.opportunity_exchange_reported_pe_v3(reported_pe_id,stock_id,exchange,session_date,close,reported_pe,published_at,source_timestamp,collected_at,source_ref,recorded_at)
    VALUES(v_reported_pe,(($1).exchange_reported_pe).stock_id,(($1).exchange_reported_pe).exchange,(($1).exchange_reported_pe).session_date,
      (($1).exchange_reported_pe).close,(($1).exchange_reported_pe).reported_pe,(($1).exchange_reported_pe).published_at,
      (($1).exchange_reported_pe).source_timestamp,(($1).exchange_reported_pe).collected_at,(($1).exchange_reported_pe).source_ref,v_now);
    v_input_hash:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array('exchange-reported-pe-v3.1',
      (($1).exchange_reported_pe).stock_id,(($1).exchange_reported_pe).exchange,(($1).exchange_reported_pe).session_date,
      (($1).exchange_reported_pe).close,(($1).exchange_reported_pe).reported_pe,(($1).exchange_reported_pe).published_at,
      (($1).exchange_reported_pe).source_timestamp,(($1).exchange_reported_pe).collected_at,(($1).exchange_reported_pe).source_ref
    )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
    INSERT INTO public.opportunity_rpc_audit_v3(function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at)
    VALUES('append_price_authority_v3',$2,'exchange_reported_pe',v_reported_pe,v_input_hash,'appended',v_now);
  END IF;
  RETURN QUERY SELECT ($1).kind,v_observation,v_snapshot,v_reported_pe,v_hash,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_publisher_verification_authority_v3(input publisher_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_registry_count integer;
  v_revision_count integer; v_stream_canonical bytea; v_stream_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'publisher_reviewer',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'publisher_verification',($1).publisher_identity_id
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|publisher_verification',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='publisher_verification'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='publisher_verification'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 10001
    ) bounded;
    IF v_registry_count>=10000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('publisher_verification',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.publisher_verification_authorities_v3 retained
  WHERE retained.publisher_identity_id=($1).publisher_identity_id
    AND retained.source_class=($1).source_class
    AND retained.domains=($1).domains
    AND retained.feed_identity IS NOT DISTINCT FROM ($1).feed_identity
    AND retained.institution_identity IS NOT DISTINCT FROM ($1).institution_identity
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.status=($1).status
    AND retained.approving_principal_id=$2
  ORDER BY retained.authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_publisher_verification_authority_v3',$2,'publisher',v_existing,
      v_stream_hash,'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.authority_id
    FROM public.publisher_verification_authorities_v3 retained
    WHERE retained.publisher_identity_id=($1).publisher_identity_id
    ORDER BY retained.recorded_at DESC,retained.authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.publisher_verification_authorities_v3(authority_id,publisher_identity_id,source_class,
    domains,feed_identity,institution_identity,valid_from,valid_to,approved_at,approving_principal_id,status,recorded_at)
  VALUES(v_id,($1).publisher_identity_id,($1).source_class,($1).domains,($1).feed_identity,
    ($1).institution_identity,($1).valid_from,($1).valid_to,v_now,$2,($1).status,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_publisher_verification_authority_v3',$2,'publisher',v_id,
    v_stream_hash,'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_source_document_revision_v3(input source_document_revision_input_v3, caller_principal uuid)
 RETURNS TABLE(revision_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp(); v_authority public.source_identity_authorities_v3%ROWTYPE;
  v_authority_cutoff timestamptz := v_now;
  v_supplied_authority public.source_identity_authorities_v3%ROWTYPE;
  v_latest_recorded_at timestamptz; v_semantic_count integer;
  v_family text; v_revision uuid := extensions.gen_random_uuid(); v_registered_count bigint;
  v_existing uuid; v_existing_recorded timestamptz; v_field jsonb; v_segment jsonb;
  v_field_text text; v_field_key text; v_normalized text; v_segments jsonb;
  v_canonical_fields jsonb := '[]'::jsonb; v_measured_count integer := 0;
  v_expected_raw_hash text; v_expected_canonical_hash text;
  v_json_text text; v_compact_json text; v_character text;
  v_json_index integer; v_json_ordinal integer := 0;
  v_inside_string boolean; v_escaped boolean;
BEGIN
  IF to_regclass('public.legacy_source_append_context_v3_13') IS NOT NULL THEN
    EXECUTE $context$
      SELECT context.authority_cutoff
      FROM public.legacy_source_append_context_v3_13 context
      WHERE context.source_identity_authority_id=$1
        AND context.stable_connector_document_id=$2
        AND context.backend_pid=pg_backend_pid()
        AND context.transaction_id=txid_current()
        AND NOT EXISTS (
          SELECT 1 FROM public.legacy_source_document_persistence_v3_13 persisted
          WHERE persisted.source_run_id=context.source_run_id
            AND persisted.profile_id=context.profile_id
            AND persisted.source_key=context.source_key
            AND persisted.stable_connector_document_id=context.stable_connector_document_id
        )
      ORDER BY context.recorded_at DESC LIMIT 1
    $context$ INTO v_authority_cutoff
    USING ($1).source_identity_authority_id,($1).stable_connector_document_id;
    v_authority_cutoff:=coalesce(v_authority_cutoff,v_now);
  END IF;
  SELECT * INTO v_supplied_authority FROM public.source_identity_authorities_v3 a
  WHERE a.authority_id=($1).source_identity_authority_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='authority_reference_unavailable'; END IF;
  -- Append and every cutoff reader share the contractual discovery-identity stream.
  -- The registry-first guard proves the family/stream bounds and equal-time conflict
  -- sentinel before status or expiry can revive an older event.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'discovery_identity:'||v_supplied_authority.source_identity_id::text,0));
  PERFORM public.opportunity_authority_selected_stream_count_v3_internal('discovery_identity',v_authority_cutoff);
  SELECT max(a.recorded_at) INTO v_latest_recorded_at
  FROM public.source_identity_authorities_v3 a
  WHERE a.source_identity_id=v_supplied_authority.source_identity_id
    AND a.recorded_at<=v_authority_cutoff AND a.approved_at<=v_authority_cutoff AND a.valid_from<=v_authority_cutoff;
  SELECT count(DISTINCT jsonb_build_array(a.source_identity_id,a.source_key,a.source_class,
      a.distribution_identity,a.valid_from,a.valid_to,a.status,a.approved_at,a.approving_principal_id))
    INTO v_semantic_count
  FROM public.source_identity_authorities_v3 a
  WHERE a.source_identity_id=v_supplied_authority.source_identity_id
    AND a.recorded_at=v_latest_recorded_at AND a.approved_at<=v_authority_cutoff AND a.valid_from<=v_authority_cutoff;
  IF v_semantic_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='authority_revision_conflict';
  END IF;
  SELECT * INTO v_authority FROM public.source_identity_authorities_v3 a
  WHERE a.source_identity_id=v_supplied_authority.source_identity_id
    AND a.recorded_at=v_latest_recorded_at AND a.approved_at<=v_authority_cutoff AND a.valid_from<=v_authority_cutoff
  ORDER BY a.authority_id LIMIT 1 FOR SHARE;
  IF v_authority.authority_id IS DISTINCT FROM ($1).source_identity_authority_id
    OR v_authority.status<>'active' OR v_authority.valid_from>v_authority_cutoff
    OR (v_authority.valid_to IS NOT NULL AND v_authority_cutoff>=v_authority.valid_to)
  THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='authority_reference_unavailable'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF ($1).adapter_version<>'source-adapter-v3.3'
    OR ($1).raw_field_payload_algorithm_version<>'raw-field-payload-v3.0'
    OR ($1).canonical_content_algorithm_version<>'canonical-content-v3.0'
    OR (
      ($1).acquisition_status='content_overflow'
      AND ($1).raw_code_point_count<>100001
    )
    OR (
      ($1).acquisition_status<>'content_overflow'
      AND ($1).raw_code_point_count>100000
    )
    OR ($1).collected_at>v_now
    OR (($1).published_at IS NOT NULL AND ($1).published_at>($1).collected_at)
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  IF ($1).acquisition_status='complete' THEN
    IF ($1).raw_field_payload IS NULL
      OR jsonb_typeof(($1).raw_field_payload)<>'array'
      OR jsonb_array_length(($1).raw_field_payload)<>3
      OR ($1).ingestion_content_revision_sha256 IS NULL
      OR ($1).ingestion_canonical_content_hash_v3 IS NULL
    THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
    FOR v_field,v_field_key IN
      SELECT field.value,
        CASE field.ordinality
          WHEN 1 THEN 'title'
          WHEN 2 THEN 'summary'
          WHEN 3 THEN CASE WHEN v_authority.source_key IN ('earnings_call','podcast','youtube')
            THEN 'transcript' ELSE 'body' END
        END
      FROM jsonb_array_elements(($1).raw_field_payload)
        WITH ORDINALITY AS field(value,ordinality)
      ORDER BY field.ordinality
    LOOP
      IF v_field_key='transcript' THEN
        IF jsonb_typeof(v_field)<>'array' THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        FOR v_segment IN SELECT value FROM jsonb_array_elements(v_field)
        LOOP
          IF jsonb_typeof(v_segment)<>'array'
            OR jsonb_array_length(v_segment)<>3
            OR jsonb_typeof(v_segment->0)<>'number'
            OR (v_segment->>0)!~'^-?[0-9]+$'
            OR jsonb_typeof(v_segment->1)<>'string'
            OR jsonb_typeof(v_segment->2)<>'string'
          THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
          v_normalized:=normalize(replace(replace(
            CASE WHEN left(v_segment->>2,1)=chr(65279)
              THEN substr(v_segment->>2,2) ELSE v_segment->>2 END,
            E'\r\n',E'\n'),E'\r',E'\n'),NFKC);
          v_measured_count:=v_measured_count+char_length(v_normalized);
          IF v_measured_count>100000 THEN
            RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
          END IF;
        END LOOP;
        SELECT coalesce(jsonb_agg(jsonb_build_array(
          (segment.value->>0)::bigint,
          normalize(replace(replace(
            CASE WHEN left(segment.value->>2,1)=chr(65279)
              THEN substr(segment.value->>2,2) ELSE segment.value->>2 END,
            E'\r\n',E'\n'),E'\r',E'\n'),NFKC)
        ) ORDER BY (segment.value->>0)::bigint,segment.value->>1),'[]'::jsonb)
        INTO v_segments
        FROM jsonb_array_elements(v_field) AS segment(value);
        v_canonical_fields:=v_canonical_fields||
          jsonb_build_array(jsonb_build_array(v_field_key,v_segments));
      ELSE
        IF jsonb_typeof(v_field)<>'string' THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        v_field_text:=v_field#>>'{}';
        v_normalized:=normalize(replace(replace(
          CASE WHEN left(v_field_text,1)=chr(65279)
            THEN substr(v_field_text,2) ELSE v_field_text END,
          E'\r\n',E'\n'),E'\r',E'\n'),NFKC);
        v_measured_count:=v_measured_count+char_length(v_normalized);
        IF v_measured_count>100000 THEN
          RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
        END IF;
        v_canonical_fields:=v_canonical_fields||
          jsonb_build_array(jsonb_build_array(v_field_key,v_normalized));
      END IF;
    END LOOP;
    FOREACH v_json_text IN ARRAY ARRAY[
      '{"adapterVersion":'||to_jsonb(($1).adapter_version)::text||
        ',"fields":'||($1).raw_field_payload::text||
        ',"version":"raw-field-payload-v3.0"}',
      v_canonical_fields::text
    ] LOOP
      v_json_ordinal:=v_json_ordinal+1;
      v_compact_json:=''; v_json_index:=1; v_inside_string:=false; v_escaped:=false;
      WHILE v_json_index<=char_length(v_json_text) LOOP
        v_character:=substr(v_json_text,v_json_index,1);
        IF v_inside_string THEN
          v_compact_json:=v_compact_json||v_character;
          IF v_escaped THEN v_escaped:=false;
          ELSIF v_character=chr(92) THEN v_escaped:=true;
          ELSIF v_character='"' THEN v_inside_string:=false;
          END IF;
        ELSIF v_character='"' THEN
          v_inside_string:=true; v_compact_json:=v_compact_json||v_character;
        ELSIF v_character=',' AND substr(v_json_text,v_json_index+1,1)=' ' THEN
          v_compact_json:=v_compact_json||','; v_json_index:=v_json_index+1;
        ELSE
          v_compact_json:=v_compact_json||v_character;
        END IF;
        v_json_index:=v_json_index+1;
      END LOOP;
      IF v_inside_string OR v_escaped THEN
        RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
      END IF;
      IF v_json_ordinal=1 THEN
        v_expected_raw_hash:=encode(extensions.digest(convert_to(v_compact_json,'utf8'),'sha256'),'hex');
      ELSE
        v_expected_canonical_hash:=encode(extensions.digest(convert_to(v_compact_json,'utf8'),'sha256'),'hex');
      END IF;
    END LOOP;
    IF v_measured_count<>($1).raw_code_point_count
      OR v_expected_raw_hash<>($1).ingestion_content_revision_sha256
      OR v_expected_canonical_hash<>($1).ingestion_canonical_content_hash_v3
    THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  ELSIF ($1).raw_field_payload IS NOT NULL
    OR ($1).ingestion_content_revision_sha256 IS NOT NULL
    OR ($1).ingestion_canonical_content_hash_v3 IS NOT NULL
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_family := encode(extensions.digest(convert_to(jsonb_build_array(
    'source-revision-family-v3.3',v_authority.source_key,v_authority.source_identity_id,
    ($1).stable_connector_document_id
  )::text,'utf8'),'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(v_authority.source_key::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family,0));
  IF NOT EXISTS (
    SELECT 1
    FROM public.source_revision_family_registry_v3 registry
    WHERE registry.source_key=v_authority.source_key
      AND registry.revision_family_key=v_family
  ) THEN
    SELECT count(*) INTO v_registered_count
    FROM (
      SELECT registry.revision_family_key
      FROM public.source_revision_family_registry_v3 registry
      WHERE registry.source_key=v_authority.source_key
      ORDER BY registry.revision_family_key
      LIMIT 1000001
    ) bounded_registry;
    IF v_registered_count>=1000000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
  END IF;
  INSERT INTO public.source_revision_family_registry_v3(
    source_key,revision_family_key,approved_source_identity_id,stable_connector_document_id,registered_at
  ) VALUES(v_authority.source_key,v_family,v_authority.source_identity_id,($1).stable_connector_document_id,v_now)
  ON CONFLICT(source_key,revision_family_key) DO NOTHING;
  IF ($1).supersedes_revision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.source_document_revisions_v3 prior
    WHERE prior.revision_id=($1).supersedes_revision_id
      AND prior.source_key=v_authority.source_key
      AND prior.revision_family_key=v_family
      AND prior.recorded_at<v_now
  ) THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  SELECT retained.revision_id,retained.recorded_at INTO v_existing,v_existing_recorded
  FROM public.source_document_revisions_v3 retained
  WHERE retained.source_key=v_authority.source_key
    AND retained.revision_family_key=v_family
    AND retained.source_identity_authority_id=($1).source_identity_authority_id
    AND retained.canonical_url_candidate IS NOT DISTINCT FROM ($1).canonical_url_candidate
    AND retained.published_at IS NOT DISTINCT FROM ($1).published_at
    AND retained.collected_at=($1).collected_at
    AND retained.adapter_version=($1).adapter_version
    AND retained.acquisition_status=($1).acquisition_status
    AND retained.raw_field_payload IS NOT DISTINCT FROM ($1).raw_field_payload
    AND retained.raw_code_point_count=($1).raw_code_point_count
    AND retained.raw_field_payload_algorithm_version=($1).raw_field_payload_algorithm_version
    AND retained.ingestion_content_revision_sha256 IS NOT DISTINCT FROM ($1).ingestion_content_revision_sha256
    AND retained.canonical_content_algorithm_version=($1).canonical_content_algorithm_version
    AND retained.ingestion_canonical_content_hash_v3 IS NOT DISTINCT FROM ($1).ingestion_canonical_content_hash_v3
    AND retained.supersedes_revision_id IS NOT DISTINCT FROM ($1).supersedes_revision_id
  ORDER BY retained.revision_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_source_document_revision_v3',$2,'source_revision',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        v_family,($1).ingestion_content_revision_sha256
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  IF (SELECT count(*) FROM (
    SELECT 1 FROM public.source_document_revisions_v3 r
    WHERE r.source_key=v_authority.source_key AND r.revision_family_key=v_family
    ORDER BY r.recorded_at DESC,r.revision_id LIMIT 65
  ) bounded) >= 64 THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  INSERT INTO public.source_document_revisions_v3(
    revision_id,revision_family_key,source_key,source_identity_authority_id,approved_source_identity_id,
    stable_connector_document_id,canonical_url_candidate,published_at,collected_at,adapter_version,
    acquisition_status,raw_field_payload,raw_code_point_count,raw_field_payload_algorithm_version,
    ingestion_content_revision_sha256,canonical_content_algorithm_version,
    ingestion_canonical_content_hash_v3,supersedes_revision_id,recorded_at
  ) VALUES(
    v_revision,v_family,v_authority.source_key,($1).source_identity_authority_id,v_authority.source_identity_id,
    ($1).stable_connector_document_id,($1).canonical_url_candidate,($1).published_at,($1).collected_at,
    ($1).adapter_version,($1).acquisition_status,($1).raw_field_payload,($1).raw_code_point_count,
    ($1).raw_field_payload_algorithm_version,($1).ingestion_content_revision_sha256,
    ($1).canonical_content_algorithm_version,($1).ingestion_canonical_content_hash_v3,
    ($1).supersedes_revision_id,v_now
  );
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_source_document_revision_v3',$2,'source_revision',v_revision,
    encode(extensions.digest(convert_to(jsonb_build_array(v_family,($1).ingestion_content_revision_sha256)::text,'utf8'),'sha256'),'hex'),
    'appended',v_now
  );
  RETURN QUERY SELECT v_revision,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_source_identity_authority_v3(input source_identity_authority_input_v3, caller_principal uuid)
 RETURNS TABLE(authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_registry_count integer;
  v_revision_count integer; v_stream_canonical bytea; v_stream_hash text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'source_reviewer',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'discovery_identity',($1).source_identity_id
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|discovery_identity',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='discovery_identity'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='discovery_identity'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 10001
    ) bounded;
    IF v_registry_count>=10000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('discovery_identity',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.source_identity_authorities_v3 retained
  WHERE retained.source_identity_id=($1).source_identity_id
    AND retained.source_key=($1).source_key
    AND retained.source_class=($1).source_class
    AND retained.distribution_identity=($1).distribution_identity
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.status=($1).status
    AND retained.approving_principal_id=$2
  ORDER BY retained.authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_source_identity_authority_v3',$2,'source_identity',v_existing,
      v_stream_hash,'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.authority_id
    FROM public.source_identity_authorities_v3 retained
    WHERE retained.source_identity_id=($1).source_identity_id
    ORDER BY retained.recorded_at DESC,retained.authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.source_identity_authorities_v3(authority_id,source_identity_id,source_key,source_class,
    distribution_identity,valid_from,valid_to,status,approved_at,approving_principal_id,recorded_at)
  VALUES(v_id,($1).source_identity_id,($1).source_key,($1).source_class,($1).distribution_identity,
    ($1).valid_from,($1).valid_to,($1).status,v_now,$2,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_source_identity_authority_v3',$2,'source_identity',v_id,
    v_stream_hash,'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_stock_sector_assignment_v3(input sector_assignment_input_v3, caller_principal uuid)
 RETURNS TABLE(assignment_authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_registry_count integer;
  v_revision_count integer; v_stream_canonical bytea; v_stream_hash text;
  v_expected_sector public.canonical_sector_key_v3;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  v_expected_sector:=CASE ($1).official_industry_code
    WHEN '01' THEN 'cement' WHEN '02' THEN 'food' WHEN '03' THEN 'plastics'
    WHEN '04' THEN 'textile' WHEN '05' THEN 'electrical_machinery'
    WHEN '06' THEN 'electrical_cable' WHEN '08' THEN 'glass_ceramic'
    WHEN '09' THEN 'paper_pulp' WHEN '10' THEN 'steel' WHEN '11' THEN 'rubber'
    WHEN '12' THEN 'auto' WHEN '14' THEN 'construction'
    WHEN '15' THEN 'shipping_transport' WHEN '16' THEN 'tourism'
    WHEN '17' THEN 'finance_insurance' WHEN '18' THEN 'department_store'
    WHEN '20' THEN 'other' WHEN '21' THEN 'chemical'
    WHEN '22' THEN 'biotech_medical' WHEN '23' THEN 'oil_gas_electricity'
    WHEN '24' THEN 'semiconductor' WHEN '25' THEN 'computer_peripheral'
    WHEN '26' THEN 'optoelectronics' WHEN '27' THEN 'communications_network'
    WHEN '28' THEN 'electronic_components' WHEN '29' THEN 'electronic_distribution'
    WHEN '30' THEN 'information_service' WHEN '31' THEN 'other_electronics'
    WHEN '32' THEN 'green_energy_environment' WHEN '33' THEN 'digital_cloud'
    WHEN '34' THEN 'sports_leisure' WHEN '35' THEN 'home_living'
    ELSE 'unknown'
  END;
  IF ($1).taxonomy_version<>'tw-sector-taxonomy-v3.0'
    OR (($1).market='TWSE') IS DISTINCT FROM (($1).provider='twse')
    OR ($1).canonical_sector_key<>v_expected_sector
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  v_stream_canonical:=convert_to(regexp_replace(jsonb_build_array(
    'sector_assignment',($1).stock_id,($1).market
  )::text,', ', ',', 'g'),'utf8');
  v_stream_hash:=encode(extensions.digest(v_stream_canonical,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('authority-registry|sector_assignment',0));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_stream_hash,0));
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_authority_stream_registry_v3 registry
    WHERE registry.family='sector_assignment'
      AND registry.stream_key_hash=v_stream_hash
      AND registry.stream_key_canonical=v_stream_canonical
  ) THEN
    SELECT count(*) INTO v_registry_count FROM (
      SELECT registry.stream_key_hash
      FROM public.opportunity_authority_stream_registry_v3 registry
      WHERE registry.family='sector_assignment'
      ORDER BY registry.stream_key_hash,registry.stream_key_canonical
      LIMIT 20001
    ) bounded;
    IF v_registry_count>=20000 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
    END IF;
    INSERT INTO public.opportunity_authority_stream_registry_v3(
      family,stream_key_hash,stream_key_canonical,registered_at
    ) VALUES('sector_assignment',v_stream_hash,v_stream_canonical,v_now);
  END IF;
  SELECT retained.assignment_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.stock_sector_assignments_v3 retained
  WHERE retained.stock_id=($1).stock_id
    AND retained.market=($1).market
    AND retained.official_industry_code=($1).official_industry_code
    AND retained.canonical_sector_key=($1).canonical_sector_key
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.valid_from=($1).valid_from
    AND retained.valid_to IS NOT DISTINCT FROM ($1).valid_to
    AND retained.taxonomy_version=($1).taxonomy_version
    AND retained.status=($1).status
  ORDER BY retained.assignment_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_stock_sector_assignment_v3',$2,'sector_assignment',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).stock_id,($1).market,($1).source_timestamp
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.assignment_authority_id
    FROM public.stock_sector_assignments_v3 retained
    WHERE retained.stock_id=($1).stock_id AND retained.market=($1).market
    ORDER BY retained.recorded_at DESC,retained.assignment_authority_id
    LIMIT 65
  ) bounded;
  IF v_revision_count>=64 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.stock_sector_assignments_v3(
    assignment_authority_id,stock_id,market,official_industry_code,canonical_sector_key,provider,
    source_timestamp,valid_from,valid_to,taxonomy_version,status,recorded_at
  ) VALUES(v_id,($1).stock_id,($1).market,($1).official_industry_code,($1).canonical_sector_key,
    ($1).provider,($1).source_timestamp,($1).valid_from,($1).valid_to,($1).taxonomy_version,($1).status,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_stock_sector_assignment_v3',$2,'sector_assignment',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).stock_id,($1).market,($1).source_timestamp
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.append_trading_session_v3(input trading_session_input_v3, caller_principal uuid)
 RETURNS TABLE(session_authority_id uuid, recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid:=extensions.gen_random_uuid();
  v_existing uuid; v_existing_recorded timestamptz; v_revision_count integer;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  IF (($1).market='TWSE') IS DISTINCT FROM (($1).provider='twse')
    OR (($1).open_at AT TIME ZONE 'Asia/Taipei')::date<>($1).session_id
    OR (($1).close_at AT TIME ZONE 'Asia/Taipei')::date<>($1).session_id
    OR ($1).open_at>=($1).close_at
    OR ($1).source_timestamp>($1).collected_at
    OR ($1).collected_at>v_now
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(
    '|','trading_session',($1).market,($1).session_id
  ),0));
  SELECT retained.session_authority_id,retained.recorded_at
  INTO v_existing,v_existing_recorded
  FROM public.tw_trading_sessions_v3 retained
  WHERE retained.market=($1).market
    AND retained.session_id=($1).session_id
    AND retained.open_at=($1).open_at
    AND retained.close_at=($1).close_at
    AND retained.status=($1).status
    AND retained.provider=($1).provider
    AND retained.source_timestamp=($1).source_timestamp
    AND retained.collected_at=($1).collected_at
    AND retained.source_ref=($1).source_ref
  ORDER BY retained.session_authority_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
    ) VALUES(
      'append_trading_session_v3',$2,'trading_session',v_existing,
      encode(extensions.digest(convert_to(jsonb_build_array(
        ($1).market,($1).session_id,($1).source_timestamp
      )::text,'utf8'),'sha256'),'hex'),'idempotent',v_now
    );
    RETURN QUERY SELECT v_existing,v_existing_recorded;
    RETURN;
  END IF;
  SELECT count(*) INTO v_revision_count FROM (
    SELECT retained.session_authority_id
    FROM public.tw_trading_sessions_v3 retained
    WHERE retained.market=($1).market AND retained.session_id=($1).session_id
    ORDER BY retained.recorded_at DESC,retained.session_authority_id
    LIMIT 1025
  ) bounded;
  IF v_revision_count>=1024 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  INSERT INTO public.tw_trading_sessions_v3(session_authority_id,session_id,market,open_at,close_at,status,
    provider,source_timestamp,collected_at,source_ref,recorded_at)
  VALUES(v_id,($1).session_id,($1).market,($1).open_at,($1).close_at,($1).status,
    ($1).provider,($1).source_timestamp,($1).collected_at,($1).source_ref,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'append_trading_session_v3',$2,'trading_session',v_id,
    encode(extensions.digest(convert_to(jsonb_build_array(
      ($1).market,($1).session_id,($1).source_timestamp
    )::text,'utf8'),'sha256'),'hex'),'appended',v_now
  );
  RETURN QUERY SELECT v_id,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.apply_legacy_official_ingestion_chunk_base_v3_15(p_run_id uuid, p_job_id uuid, p_owner_token uuid, p_kind text, p_ordinal integer, p_items jsonb, p_chunk_hash text, p_producer_sha text, p_source_cutoff timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_item jsonb;v_now timestamptz:=clock_timestamp();v_stock uuid;
  v_exchange public.stock_exchange_v3;v_session date;v_session_authority uuid;
  v_feed_evidence public.corporate_action_feed_evidence_input_v3[];
  v_action_events public.corporate_action_event_input_v3[];v_close double precision;v_expected_hash text;
BEGIN
  IF p_kind NOT IN('trading_sessions','financial_facts','price_observations',
      'corporate_action_snapshots','reported_valuations','terminal') OR p_ordinal<0
    OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)>200 OR p_chunk_hash!~'^[0-9a-f]{64}$'
    OR p_producer_sha!~'^[0-9a-f]{40}$' THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';END IF;
  IF p_kind<>'terminal' THEN
    v_expected_hash:=encode(extensions.digest(convert_to(public.legacy_canonical_json_v3_13(jsonb_build_array(
      'official-ingestion-chunk-v3.14',p_kind,p_ordinal,p_items)),'utf8'),'sha256'),'hex');
    IF v_expected_hash<>p_chunk_hash THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='official_ingestion_chunk_hash';END IF;
  ELSE
    v_expected_hash:=encode(extensions.digest(convert_to(public.legacy_canonical_json_v3_13(jsonb_build_array(
      'official-ingestion-terminal-v3.14',p_items#>>'{0,sourceCutoff}',p_items#>'{0,counts}',p_items#>'{0,chunks}')),'utf8'),'sha256'),'hex');
    IF v_expected_hash<>p_chunk_hash THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='official_ingestion_terminal_hash';END IF;
  END IF;

  -- instrument_roster_chunk_snapshot_v3_16_21: the frozen acquisition has one
  -- truthful fetchedAt, so one complete registry validation authorizes all
  -- bounded indexed symbol lookups in this transaction.
  IF p_kind IN('financial_facts','price_observations','reported_valuations') THEN
    IF (SELECT count(DISTINCT (item.value->>'collectedAt')::timestamptz)
        FROM jsonb_array_elements(p_items) item(value))<>1
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='official_ingestion_mixed_acquisition_time';
    END IF;
    PERFORM public.opportunity_authority_selected_stream_count_v3_internal(
      'instrument_roster',
      (SELECT min((item.value->>'collectedAt')::timestamptz)
       FROM jsonb_array_elements(p_items) item(value))
    );
  END IF;
  IF p_kind='trading_sessions' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) item(value) LOOP
      IF coalesce(v_item->>'market','') NOT IN('TWSE','TPEX') OR coalesce(v_item->>'status','') NOT IN('completed','holiday','scheduled')
        OR coalesce(v_item->>'provider','')<>lower(v_item->>'market')
        OR coalesce(v_item->>'sourceRef','') NOT LIKE lower(v_item->>'market')||'-annual-calendar:%'
        OR (v_item->>'sourceTimestamp')::timestamptz>(v_item->>'collectedAt')::timestamptz
        OR (v_item->>'collectedAt')::timestamptz>v_now THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      IF v_item->>'status'='scheduled' THEN CONTINUE;END IF;
      PERFORM public.append_trading_session_v3(ROW((v_item->>'session')::date,
        (v_item->>'market')::public.tw_market_v3,(v_item->>'openAt')::timestamptz,
        (v_item->>'scheduledCloseAt')::timestamptz,
        CASE WHEN v_item->>'status'='completed' THEN 'completed'::public.trading_session_status_v3
          ELSE 'cancelled'::public.trading_session_status_v3 END,
        (v_item->>'provider')::public.official_roster_provider_v3,(v_item->>'sourceTimestamp')::timestamptz,
        (v_item->>'collectedAt')::timestamptz,v_item->>'sourceRef')::public.trading_session_input_v3,
        'a11d4e67-7d0a-4c44-8a9d-1d5c3b875001'::uuid);
    END LOOP;
  ELSIF p_kind='financial_facts' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) item(value) LOOP
      IF (v_item->>'symbol')!~'^[0-9]{4}$' OR coalesce(v_item->>'provider','') NOT IN('twse','tpex')
        OR NOT(coalesce(v_item->>'sourceRef','') LIKE (v_item->>'provider')||'-openapi:%'
          OR coalesce(v_item->>'sourceRef','') LIKE (v_item->>'provider')||'-mops-inline:%')
        OR (v_item->>'filingPublishedAt')::timestamptz>(v_item->>'sourceTimestamp')::timestamptz
        OR (v_item->>'sourceTimestamp')::timestamptz>(v_item->>'collectedAt')::timestamptz
        OR (v_item->>'collectedAt')::timestamptz>v_now THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      SELECT selected.stock_id INTO v_stock FROM public.resolve_legacy_instrument_symbol_authority_v3_13_internal(
        v_item->>'symbol',(v_item->>'collectedAt')::timestamptz) selected
      WHERE selected.instrument_type='common_stock' AND selected.listing_status='active'
        AND selected.provider::text=v_item->>'provider' AND(selected.valid_to IS NULL OR (v_item->>'collectedAt')::timestamptz<selected.valid_to);
      IF v_stock IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='instrument_dependency_unavailable',
        CONSTRAINT='instrument_dependency_unavailable';END IF;
      PERFORM public.append_financial_fact_v3(ROW(v_stock,(v_item->>'factKey')::public.financial_fact_key_v3,
        NULLIF(v_item->>'periodStart','')::date,(v_item->>'periodEnd')::date,
        (v_item->>'durationKind')::public.financial_duration_kind_v3,(v_item->>'value')::double precision,
        (v_item->>'unit')::public.financial_unit_v3,(v_item->>'provider')::public.financial_provider_v3,
        (v_item->>'authorityTier')::public.financial_authority_tier_v3,(v_item->>'estimateKind')::public.financial_estimate_kind_v3,
        (v_item->>'estimateHorizon')::public.financial_estimate_horizon_v3,(v_item->>'filingPublishedAt')::timestamptz,
        (v_item->>'sourceTimestamp')::timestamptz,(v_item->>'collectedAt')::timestamptz,NULL,
        v_item->>'sourceRef')::public.financial_fact_input_v3,'a11d4e67-7d0a-4c44-8a9d-1d5c3b875001'::uuid);
    END LOOP;
  ELSIF p_kind='price_observations' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) item(value) LOOP
      IF (v_item->>'symbol')!~'^[0-9]{4}$' OR coalesce(v_item->>'exchange','') NOT IN('TWSE','TPEX')
        OR coalesce(v_item->>'provider','')<>lower(v_item->>'exchange')
        OR coalesce(v_item->>'sourceRef','')<>lower(v_item->>'exchange')||'-rwd:'||
          (CASE WHEN v_item->>'exchange'='TWSE' THEN 'STOCK_DAY:' ELSE 'tradingStock:' END)||
          (v_item->>'session')||':'||(v_item->>'symbol')
        OR (v_item->>'sourceTimestamp')::timestamptz>(v_item->>'collectedAt')::timestamptz
        OR (v_item->>'collectedAt')::timestamptz>v_now THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_exchange:=(v_item->>'exchange')::public.stock_exchange_v3;v_session:=(v_item->>'session')::date;
      SELECT selected.stock_id INTO v_stock FROM public.resolve_legacy_instrument_symbol_authority_v3_13_internal(
        v_item->>'symbol',(v_item->>'collectedAt')::timestamptz) selected
      WHERE selected.exchange=v_exchange AND selected.instrument_type='common_stock' AND selected.listing_status='active'
        AND(selected.valid_to IS NULL OR (v_item->>'collectedAt')::timestamptz<selected.valid_to);
      SELECT selected.session_authority_id INTO v_session_authority
      FROM public.resolve_legacy_trading_session_dependency_v3_16_9_internal(v_session,
        v_exchange::text::public.tw_market_v3,(v_item->>'collectedAt')::timestamptz,v_now) selected
      WHERE selected.status='completed' AND selected.close_at<=(v_item->>'collectedAt')::timestamptz;
      IF v_stock IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='instrument_dependency_unavailable',
        CONSTRAINT='instrument_dependency_unavailable';END IF;
      IF v_session_authority IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='calendar_dependency_unavailable',
        CONSTRAINT='calendar_dependency_unavailable';END IF;
      PERFORM public.append_price_authority_v3(ROW('raw_price',ROW(v_stock,v_exchange,v_session,v_session_authority,
        (v_item->>'open')::double precision,(v_item->>'high')::double precision,(v_item->>'low')::double precision,
        (v_item->>'close')::double precision,(v_item->>'volume')::double precision,(v_item->>'turnoverTwd')::double precision,
        (v_item->>'provider')::public.price_provider_v3,(v_item->>'sourceTimestamp')::timestamptz,
        (v_item->>'collectedAt')::timestamptz,v_item->>'sourceRef')::public.price_observation_input_v3,NULL,NULL)
        ::public.price_authority_input_v3,'a11d4e67-7d0a-4c44-8a9d-1d5c3b875001'::uuid);
    END LOOP;
  ELSIF p_kind='corporate_action_snapshots' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) item(value) LOOP
      IF coalesce(v_item->>'exchange','') NOT IN('TWSE','TPEX') OR (v_item->>'corporateActionVersion')<>'tw-corporate-action-v3.1'
        OR jsonb_array_length(coalesce(v_item->'feedEvidence','[]'::jsonb))<>3
        OR jsonb_array_length(coalesce(v_item->'events','[]'::jsonb))<>coalesce((v_item->>'declaredEventCount')::integer,-1)
        OR (v_item->>'collectedAt')::timestamptz>v_now THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_exchange:=(v_item->>'exchange')::public.stock_exchange_v3;v_session:=(v_item->>'session')::date;
      SELECT selected.session_authority_id INTO v_session_authority
      FROM public.resolve_legacy_trading_session_dependency_v3_16_9_internal(v_session,
        v_exchange::text::public.tw_market_v3,(v_item->>'collectedAt')::timestamptz,v_now) selected
      WHERE selected.status='completed' AND selected.close_at<=(v_item->>'collectedAt')::timestamptz;
      IF v_session_authority IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='calendar_dependency_unavailable',
        CONSTRAINT='calendar_dependency_unavailable';END IF;
      SELECT coalesce(array_agg(ROW(value->>'feedIdentity',(value->>'responseByteCount')::integer,
        value->>'responseSha256',(value->>'parsedRowCount')::integer)::public.corporate_action_feed_evidence_input_v3
        ORDER BY ordinality),ARRAY[]::public.corporate_action_feed_evidence_input_v3[]) INTO v_feed_evidence
      FROM jsonb_array_elements(v_item->'feedEvidence') WITH ORDINALITY feed(value,ordinality);
      SELECT coalesce(array_agg(ROW(value->>'symbol',(value->>'eventKind')::public.corporate_action_kind_v3,
        (value->>'preActionReferencePrice')::double precision,(value->>'postActionReferencePrice')::double precision,
        value->>'feedIdentity',value->>'sourceRowRef')::public.corporate_action_event_input_v3 ORDER BY value->>'symbol'),
        ARRAY[]::public.corporate_action_event_input_v3[]) INTO v_action_events FROM jsonb_array_elements(v_item->'events') event(value);
      PERFORM public.append_price_authority_v3(ROW('corporate_action_snapshot',NULL,
        ROW(v_exchange,v_session,v_session_authority,'tw-corporate-action-v3.1',(v_item->>'provider')::public.official_roster_provider_v3,
          (v_item->>'collectedAt')::timestamptz,v_feed_evidence,(v_item->>'declaredEventCount')::integer,v_action_events)
          ::public.corporate_action_snapshot_input_v3,NULL)::public.price_authority_input_v3,
        'a11d4e67-7d0a-4c44-8a9d-1d5c3b875001'::uuid);
    END LOOP;
  ELSIF p_kind='reported_valuations' THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) item(value) LOOP
      IF (v_item->>'symbol')!~'^[0-9]{4}$' OR NOT (coalesce(v_item->>'sourceRef','') LIKE ANY(ARRAY['twse-openapi:%','tpex-openapi:%','twse-rwd:%','tpex-rwd:%']))
        OR (v_item->>'collectedAt')::timestamptz>v_now THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_exchange:=CASE WHEN(v_item->>'sourceRef') LIKE 'twse-%' THEN 'TWSE'::public.stock_exchange_v3 ELSE 'TPEX'::public.stock_exchange_v3 END;
      v_session:=(v_item->>'session')::date;
      SELECT selected.stock_id INTO v_stock FROM public.resolve_legacy_instrument_symbol_authority_v3_13_internal(
        v_item->>'symbol',(v_item->>'collectedAt')::timestamptz) selected
      WHERE selected.exchange=v_exchange AND selected.instrument_type='common_stock' AND selected.listing_status='active';
      v_close:=CASE WHEN coalesce(v_item->>'close','')~'^[0-9]+([.][0-9]+)?$' THEN(v_item->>'close')::double precision ELSE NULL END;
      IF v_close IS NULL THEN SELECT raw_close INTO v_close FROM public.opportunity_price_observations_v3
        WHERE stock_id=v_stock AND exchange=v_exchange AND session_id=v_session
          AND source_timestamp<=(v_item->>'collectedAt')::timestamptz
          AND collected_at<=(v_item->>'collectedAt')::timestamptz AND recorded_at<=v_now
        ORDER BY source_timestamp DESC,collected_at DESC,recorded_at DESC,observation_id LIMIT 1;END IF;
      IF v_stock IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='instrument_dependency_unavailable',
        CONSTRAINT='instrument_dependency_unavailable';END IF;
      IF v_close IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='price_dependency_unavailable',
        CONSTRAINT='price_dependency_unavailable';END IF;
      IF NOT(coalesce(v_item->>'peRatio','')~'^[0-9]+([.][0-9]+)?$' AND(v_item->>'peRatio')::double precision>0)
        AND NOT(coalesce(v_item->>'pbRatio','')~'^[0-9]+([.][0-9]+)?$' AND(v_item->>'pbRatio')::double precision>0)
      THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='valuation_metric_unavailable',
        CONSTRAINT='valuation_metric_unavailable';END IF;
      PERFORM public.append_exchange_reported_valuation_transaction_v3_16_9(ROW(v_stock,v_exchange,v_session,v_close,
        CASE WHEN coalesce(v_item->>'peRatio','')~'^[0-9]+([.][0-9]+)?$' AND(v_item->>'peRatio')::double precision>0 THEN(v_item->>'peRatio')::double precision END,
        CASE WHEN coalesce(v_item->>'pbRatio','')~'^[0-9]+([.][0-9]+)?$' AND(v_item->>'pbRatio')::double precision>0 THEN(v_item->>'pbRatio')::double precision END,
        (v_session::text||' 06:30:00+00')::timestamptz,(v_session::text||' 06:30:00+00')::timestamptz,
        (v_item->>'collectedAt')::timestamptz,v_item->>'sourceRef')::public.exchange_reported_valuation_input_v3_13,
        'a11d4e67-7d0a-4c44-8a9d-1d5c3b875001'::uuid);
    END LOOP;
  ELSE
    IF jsonb_array_length(p_items)<>1 OR p_items#>>'{0,terminalRoot}'<>p_chunk_hash
      OR (p_items#>>'{0,sourceCutoff}')::timestamptz<>p_source_cutoff
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='official_ingestion_terminal_invalid';END IF;
  END IF;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.assert_research_editorial_review_v2(packet jsonb, review jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c jsonb; f jsonb; id jsonb;allowed_paragraphs jsonb;allowed_sources jsonb; seen text[]:=ARRAY[]::text[]; concerns integer:=0;
 -- ECMAScript WhiteSpace + LineTerminator set, identical to String.trim().
 trim_chars text:=chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)||
  chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||
  chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279);
BEGIN
 IF review IS NULL OR jsonb_typeof(review)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(review) key)
  IS DISTINCT FROM ARRAY['articleHash','checks','decision','findings','reviewPackHash','reviewedAt','schemaVersion','strongestCounterEvidence']
  OR jsonb_typeof(review->'decision') IS DISTINCT FROM 'string' OR review->>'decision' NOT IN ('accepted','revision_required','rejected')
  OR jsonb_typeof(review->'checks') IS DISTINCT FROM 'array' OR jsonb_array_length(review->'checks')<>8
  OR jsonb_typeof(review->'findings') IS DISTINCT FROM 'array' OR jsonb_array_length(review->'findings')>30
  OR jsonb_typeof(review->'strongestCounterEvidence') IS DISTINCT FROM 'string' OR length(btrim(review->>'strongestCounterEvidence',trim_chars))<20 OR length(review->>'strongestCounterEvidence')>4000
 THEN RAISE EXCEPTION 'research_editorial_review_shape'; END IF;
 allowed_paragraphs:=jsonb_build_array(packet->'article'->'summary'->>'id')||
  (SELECT coalesce(jsonb_agg(p->>'id'),'[]') FROM jsonb_array_elements(packet->'article'->'sections') s CROSS JOIN LATERAL jsonb_array_elements(s->'paragraphs') p);
 allowed_sources:=(SELECT coalesce(jsonb_agg(s->'descriptor'->>'id'),'[]') FROM jsonb_array_elements(packet->'research'->'sources') s);
 FOR c IN SELECT value FROM jsonb_array_elements(review->'checks') LOOP
  IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(c) key)
   IS DISTINCT FROM ARRAY['category','paragraphIds','rationale','status']
   OR jsonb_typeof(c->'category') IS DISTINCT FROM 'string' OR c->>'category' NOT IN ('source_support','rumor_staging','financial_recalculation','periods_and_dilution','competitive_alternatives','valuation_assumptions','counterevidence','entry_separation')
   OR c->>'category'=ANY(seen) OR jsonb_typeof(c->'status') IS DISTINCT FROM 'string' OR c->>'status' NOT IN ('pass','concern','fail')
   OR jsonb_typeof(c->'rationale') IS DISTINCT FROM 'string' OR length(btrim(c->>'rationale',trim_chars))<20 OR length(c->>'rationale')>2000
   OR jsonb_typeof(c->'paragraphIds') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'paragraphIds')>30
   OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(c->'paragraphIds'))<>jsonb_array_length(c->'paragraphIds')
  THEN RAISE EXCEPTION 'research_editorial_review_check'; END IF;
  seen:=array_append(seen,c->>'category');IF c->>'status'<>'pass' THEN concerns:=concerns+1; END IF;
  FOR id IN SELECT value FROM jsonb_array_elements(c->'paragraphIds') LOOP
   IF jsonb_typeof(id)<>'string' OR NOT allowed_paragraphs @> jsonb_build_array(id) THEN RAISE EXCEPTION 'research_editorial_review_paragraph'; END IF;
  END LOOP;
 END LOOP;
 FOR f IN SELECT value FROM jsonb_array_elements(review->'findings') LOOP
  IF jsonb_typeof(f) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(f) key)
   IS DISTINCT FROM ARRAY['issue','paragraphId','severity','sourceIds']
   OR jsonb_typeof(f->'severity') IS DISTINCT FROM 'string' OR f->>'severity' NOT IN ('blocking','major','minor')
   OR (f->'paragraphId'<>'null'::jsonb AND (jsonb_typeof(f->'paragraphId')<>'string' OR NOT allowed_paragraphs @> jsonb_build_array(f->'paragraphId')))
   OR jsonb_typeof(f->'issue') IS DISTINCT FROM 'string' OR length(btrim(f->>'issue',trim_chars))<20 OR length(f->>'issue')>2000
   OR jsonb_typeof(f->'sourceIds') IS DISTINCT FROM 'array' OR jsonb_array_length(f->'sourceIds')>30
   OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(f->'sourceIds'))<>jsonb_array_length(f->'sourceIds')
  THEN RAISE EXCEPTION 'research_editorial_review_finding'; END IF;
  IF f->>'severity'<>'minor' THEN concerns:=concerns+1; END IF;
  FOR id IN SELECT value FROM jsonb_array_elements(f->'sourceIds') LOOP
   IF jsonb_typeof(id)<>'string' OR NOT allowed_sources @> jsonb_build_array(id) THEN RAISE EXCEPTION 'research_editorial_review_source'; END IF;
  END LOOP;
 END LOOP;
 IF (review->>'decision'='accepted' AND concerns<>0) OR (review->>'decision'<>'accepted' AND concerns=0) THEN RAISE EXCEPTION 'research_editorial_review_decision'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.assert_research_input_preparation_v2(p_request jsonb, p_preparation_id uuid, p_input_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE old public.research_input_preparations_v2; replay jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'input_preparation_read_committed_required'; END IF;
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR octet_length(p_request::text)>8192
  OR p_preparation_id IS NULL OR p_input_hash IS NULL OR p_input_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'input_preparation_assert_shape'; END IF;
 PERFORM pg_advisory_xact_lock(610091002::bigint);
 PERFORM pg_advisory_xact_lock(2409,6002);
 SELECT * INTO old FROM public.research_input_preparations_v2 WHERE preparation_id=p_preparation_id;
 IF NOT FOUND OR old.request IS DISTINCT FROM p_request OR old.input_hash IS DISTINCT FROM p_input_hash THEN RAISE EXCEPTION 'input_preparation_assert_mismatch'; END IF;
 -- Original function rechecks lease, lineage, role, attempt/completion and source
 -- seal even for replay; immutable old row guarantees no admission branch.
 replay:=public.prepare_research_input_v2(p_request);
 IF replay->>'preparation_id' IS DISTINCT FROM p_preparation_id::text OR replay->>'input_hash' IS DISTINCT FROM p_input_hash
  OR replay->'replay' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'input_preparation_assert_mismatch'; END IF;
 RETURN replay;
END $function$

CREATE OR REPLACE FUNCTION public.assert_research_source_seal_v2(p_seal uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result public.research_source_seals_v2; item jsonb; actual_hash text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'source_fence_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(610091002::bigint);
 SELECT * INTO result FROM public.research_source_seals_v2 WHERE seal_id=p_seal;
 IF NOT FOUND OR EXISTS(SELECT FROM public.research_source_seal_invalidations_v2 WHERE seal_id=p_seal) THEN RAISE EXCEPTION 'source_seal_invalidated_or_missing'; END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(result.documents) x LOOP
  SELECT encode(sha256(convert_to(to_jsonb(s)::text,'UTF8')),'hex') INTO actual_hash FROM public.source_raw_documents s WHERE s.id=(item->>'id')::uuid;
  IF actual_hash IS DISTINCT FROM item->>'rowHash' THEN RAISE EXCEPTION 'source_seal_hash_changed'; END IF;
 END LOOP;
 RETURN to_jsonb(result);
END $function$

CREATE OR REPLACE FUNCTION public.assert_stockinsider_backend_request_v1(p_require_lease boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE headers jsonb; claims jsonb; supplied_backend uuid; supplied_principal uuid; supplied_release text; matched uuid;
BEGIN
  IF NOT COALESCE((SELECT identity_fence_enabled FROM public.stockinsider_data_plane_settings_v1 WHERE singleton),false)
  THEN RETURN NULL; END IF;
  BEGIN
    headers:=COALESCE(NULLIF(current_setting('request.headers',true),''),'{}')::jsonb;
    claims:=COALESCE(NULLIF(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
    supplied_backend:=(headers->>'x-stockinsider-backend-id')::uuid;
    supplied_principal:=(headers->>'x-stockinsider-runner-principal')::uuid;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='stockinsider_backend_identity_rejected';
  END;
  supplied_release:=headers->>'x-stockinsider-writer-release';
  IF claims->>'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='stockinsider_backend_role_rejected';
  END IF;
  SELECT backend_id INTO matched FROM public.stockinsider_backend_identities_v1
  WHERE backend_id=supplied_backend AND principal_id=supplied_principal AND release_id=supplied_release
    AND status='active' AND valid_from<=clock_timestamp()
    AND (valid_to IS NULL OR valid_to>clock_timestamp());
  IF matched IS NULL OR NOT public.internal_principal_role_is_exact_v3_internal(
      supplied_principal,'opportunity_runner',clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='stockinsider_backend_identity_rejected';
  END IF;
  IF p_require_lease AND NOT EXISTS(SELECT 1 FROM public.production_write_leases
      WHERE lease_key='production-data-plane' AND expires_at>clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='stockinsider_backend_lease_required';
  END IF;
  RETURN matched;
END
$function$

CREATE OR REPLACE FUNCTION public.assign_research_author_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_principal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE revision jsonb; existing jsonb; saved public.research_author_assignments_v2;
 payload jsonb; n timestamptz;
BEGIN
 -- Exact replay still passes every live original/source fence before returning.
 existing:=public.read_research_author_assignment_v2(p_request,p_revision_id,p_input_hash,p_principal);
 IF existing IS NOT NULL THEN RETURN existing; END IF;
 revision:=public.research_author_assignment_context_v2(p_request,p_revision_id,p_input_hash,p_principal);
 payload:=revision->'canonical_payload';n:=clock_timestamp();
 INSERT INTO public.research_author_assignments_v2(job_id,attempt,reservation_id,input_revision_id,input_hash,
  research_company_id,snapshot_hash,controller_principal,work_owner,canonical_request,assigned_at,
  reservation_started_at,reservation_expires_at,original_job_deadline)
 VALUES((p_request->>'jobId')::uuid,(p_request->>'attempt')::integer,(p_request->>'reservationId')::uuid,
  p_revision_id,p_input_hash,(revision->>'research_company_id')::uuid,revision->>'snapshot_hash',p_principal,
  p_request->>'owner',p_request,n,(payload->'originalReservation'->>'startedAt')::timestamptz,
  (payload->'originalReservation'->>'leaseExpiresAt')::timestamptz,(payload->'originalJob'->>'leaseExpiresAt')::timestamptz)
 RETURNING * INTO saved;
 IF clock_timestamp()>=least(saved.original_job_deadline,saved.reservation_expires_at) THEN
  RAISE EXCEPTION 'research_author_assignment_expired'; END IF;
 RETURN to_jsonb(saved);
END $function$

CREATE OR REPLACE FUNCTION public.assign_research_reviewer_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_author_principal text, p_reviewer_principal text, p_result_id uuid, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context jsonb; a jsonb; existing jsonb; r public.research_model_reservations_v1; saved public.research_reviewer_assignments_v2;n timestamptz;
BEGIN
 context:=public.read_research_reviewer_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_result_id,p_result_hash);
 existing:=context->'reviewerAssignment';
 IF existing<>'null'::jsonb THEN
  IF clock_timestamp()>=least((existing->>'original_job_deadline')::timestamptz,(existing->>'reservation_expires_at')::timestamptz) THEN RAISE EXCEPTION 'research_reviewer_assignment_expired'; END IF;
  RETURN existing;
 END IF;
 a:=context->'authorContext'->'assignment';
 SELECT * INTO r FROM public.reserve_research_model_v1('counter_review',a->>'work_owner',
  'deep-review-v2:'||(a->>'job_id')||':'||(a->>'attempt')||':'||p_result_id);
 IF NOT FOUND THEN RETURN NULL; END IF;
 n:=clock_timestamp();
 IF n>=least((a->>'original_job_deadline')::timestamptz,r.lease_expires_at) THEN RAISE EXCEPTION 'research_reviewer_assignment_expired'; END IF;
 INSERT INTO public.research_reviewer_assignments_v2(author_assignment_id,author_result_id,author_result_hash,job_id,attempt,
  input_revision_id,input_hash,reviewer_principal,work_owner,reservation_id,reservation_started_at,reservation_expires_at,original_job_deadline,assigned_at)
 VALUES((a->>'assignment_id')::uuid,p_result_id,p_result_hash,(a->>'job_id')::uuid,(a->>'attempt')::integer,
  p_revision_id,p_input_hash,p_reviewer_principal,a->>'work_owner',r.reservation_id,r.started_at,r.lease_expires_at,(a->>'original_job_deadline')::timestamptz,n)
 RETURNING * INTO saved;
 context:=public.read_research_reviewer_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_result_id,p_result_hash);
 IF context->'reviewerAssignment' IS DISTINCT FROM to_jsonb(saved) THEN RAISE EXCEPTION 'research_reviewer_assignment_changed'; END IF;
 IF clock_timestamp()>=least(saved.original_job_deadline,saved.reservation_expires_at) THEN RAISE EXCEPTION 'research_reviewer_assignment_expired'; END IF;
 RETURN to_jsonb(saved);
END $function$

CREATE OR REPLACE FUNCTION public.capture_research_first_discoveries_v1(p_run_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_run public.research_priority_runs_v1; v_row jsonb; v_first timestamptz;
  v_price jsonb; v_session date; v_stock uuid; v_count integer:=0; v_added integer;
BEGIN
  SELECT * INTO v_run FROM public.research_priority_runs_v1 WHERE run_id=p_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'research_priority_run_missing'; END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(v_run.rows) LOOP
    IF COALESCE((v_row->>'hasDiscoveryEvidence')::boolean,false) IS NOT TRUE THEN CONTINUE; END IF;
    IF EXISTS(SELECT 1 FROM public.research_first_discoveries_v1 WHERE symbol=v_row->>'symbol') THEN CONTINUE; END IF;
    v_first:=COALESCE((v_row->>'firstSeenAt')::timestamptz,v_run.as_of);
    IF v_first>v_run.as_of THEN RAISE EXCEPTION 'research_discovery_future_observation'; END IF;
    SELECT id INTO v_stock FROM public.stocks WHERE symbol=v_row->>'symbol' AND market='TW';
    -- Calendar close/source/observation clocks must all predate discovery.
    SELECT max(session_id::date) INTO v_session FROM public.tw_trading_sessions_v3
      WHERE status='completed' AND close_at<=v_first AND source_timestamp<=v_first
        AND collected_at<=v_first AND recorded_at<=v_first;
    SELECT jsonb_build_object('session',p.session_date,'close',p.close,'volume',p.volume,
      'sourceUrl',p.source_url,'availableAt',p.available_at,'priceBasis','raw_exchange_quote') INTO v_price
    FROM public.official_price_history p WHERE p.stock_id=v_stock AND p.session_date=v_session
      AND p.available_at<=v_first AND p.as_of<=v_first AND p.close>0
      AND p.source_url ~ '^https://([a-z0-9-]+[.])*(twse[.]com[.]tw|tpex[.]org[.]tw)/'
      AND COALESCE(p.provenance->>'provider','') NOT LIKE '%finmind%'
      AND COALESCE(p.provenance->>'integrityStatus','')<>'conflict'
      AND COALESCE(p.provenance->>'integrity_status','')<>'conflict' LIMIT 1;
    INSERT INTO public.research_first_discoveries_v1(symbol,run_id,first_seen_at,snapshot)
      VALUES(v_row->>'symbol',p_run_id,v_first,jsonb_build_object('price',v_price,
        'priceStatus',CASE WHEN v_price IS NULL THEN 'missing_at_discovery' ELSE 'official_quote' END,
        'pricePhase','unknown','relative5d',NULL,'relative20d',NULL,'relative60d',NULL,
        'gap','Adjusted price history and aligned benchmark are evaluated separately; a raw quote alone is not an early-entry signal.',
        'factors',COALESCE(v_row->'factors','[]'::jsonb))) ON CONFLICT(symbol) DO NOTHING;
    GET DIAGNOSTICS v_added=ROW_COUNT; v_count:=v_count+v_added;
  END LOOP;
  RETURN v_count;
END $function$

CREATE OR REPLACE FUNCTION public.charge_research_deep_admission_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(2409,6001);
 IF (SELECT count(*)FROM public.research_deep_admission_charges_v1 WHERE admission_week=NEW.week_start)>=5 THEN RAISE EXCEPTION 'deep_admission_week_capacity'; END IF;
 INSERT INTO public.research_deep_admission_charges_v1(job_id,issuer_key,admission_at,admission_week) VALUES(NEW.job_id,'TW:'||NEW.symbol,NEW.created_at,NEW.week_start);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.claim_candidate_deep_outbox_v1(p_deep_job_id uuid, p_deep_owner text, p_deep_attempt integer, p_revision_id uuid, p_input_hash text, p_outbox_owner text)
 RETURNS TABLE(job_id uuid, bundle_id uuid, lease_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_job public.research_deep_jobs_v1;
  v_outbox public.candidate_dossier_outbox_v5;
  v_stock UUID;
BEGIN
  SELECT * INTO v_job FROM public.research_deep_jobs_v1
    WHERE research_deep_jobs_v1.job_id=p_deep_job_id AND research_scope='formal_v1' FOR UPDATE;
  IF NOT FOUND OR v_job.status<>'running' OR v_job.lease_owner IS DISTINCT FROM p_deep_owner
    OR v_job.attempts<>p_deep_attempt OR v_job.lease_expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'research_deep_job_lease_lost';
  END IF;
  IF p_outbox_owner IS NULL OR length(trim(p_outbox_owner))<3 OR length(p_outbox_owner)>120 THEN
    RAISE EXCEPTION 'research_deep_outbox_owner_invalid';
  END IF;
  SELECT detail.stock_id INTO v_stock FROM public.candidate_detail_snapshots detail
    WHERE detail.id=p_revision_id;
  IF v_stock IS DISTINCT FROM v_job.stock_id THEN
    RAISE EXCEPTION 'research_deep_stock_revision_mismatch';
  END IF;
  INSERT INTO public.candidate_dossier_outbox_v5(bundle_id,revision_id,input_hash,publication_kind)
    SELECT bundle.bundle_id,bundle.revision_id,bundle.input_hash,'deep' FROM public.candidate_dossier_bundles bundle
    WHERE bundle.revision_id=p_revision_id AND bundle.input_hash=p_input_hash
    ON CONFLICT (revision_id,input_hash,publication_kind) DO NOTHING;
  SELECT * INTO v_outbox FROM public.candidate_dossier_outbox_v5 outbox
    WHERE outbox.revision_id=p_revision_id AND outbox.input_hash=p_input_hash
      AND outbox.publication_kind='deep' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'research_deep_outbox_unavailable';
  END IF;
  IF v_outbox.status='running' AND v_outbox.deep_job_id=p_deep_job_id
    AND v_outbox.deep_attempt=p_deep_attempt
    AND v_outbox.lease_owner=p_outbox_owner AND v_outbox.lease_expires_at>clock_timestamp() THEN
    RETURN QUERY SELECT v_outbox.job_id,v_outbox.bundle_id,v_outbox.lease_expires_at;
    RETURN;
  END IF;
  IF NOT (v_outbox.status IN ('queued','rejected') OR
      (v_outbox.status='running' AND v_outbox.lease_expires_at<=clock_timestamp()
        AND v_outbox.deep_job_id=p_deep_job_id AND v_outbox.deep_attempt<=p_deep_attempt))
    OR v_outbox.attempts>=12
    OR (v_outbox.status='rejected' AND (p_deep_attempt<2 OR v_outbox.deep_job_id IS DISTINCT FROM p_deep_job_id
      OR v_outbox.deep_attempt>=p_deep_attempt))
    OR (v_outbox.next_attempt_at IS NOT NULL AND v_outbox.next_attempt_at>clock_timestamp()) THEN
    RAISE EXCEPTION 'research_deep_outbox_lease_lost';
  END IF;
  UPDATE public.candidate_dossier_outbox_v5 outbox SET
    status='running', attempts=outbox.attempts+1, lease_owner=p_outbox_owner,
    lease_expires_at=LEAST(v_job.lease_expires_at,clock_timestamp()+interval '20 minutes'),
    deep_job_id=p_deep_job_id, deep_attempt=p_deep_attempt,
    next_attempt_at=NULL, updated_at=clock_timestamp()
    WHERE outbox.job_id=v_outbox.job_id RETURNING * INTO v_outbox;
  RETURN QUERY SELECT v_outbox.job_id,v_outbox.bundle_id,v_outbox.lease_expires_at;
END $function$

CREATE OR REPLACE FUNCTION public.claim_legacy_mention_barrier_transport_v3_15(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_job public.legacy_producer_jobs_v3_11%ROWTYPE;
  v_run public.legacy_producer_runs_v3_11%ROWTYPE;
  v_payload public.legacy_producer_job_payloads_v3_11%ROWTYPE;
  v_now timestamptz:=date_trunc('second',clock_timestamp());
  v_owner_hash text;
  v_barrier_json jsonb;
  v_barrier_bytes bytea;
  v_barrier_hash text;
  v_barrier_count integer;
BEGIN
  IF p_lease<>120 THEN RETURN NULL; END IF;
  v_owner_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT run.* INTO v_run FROM public.legacy_producer_runs_v3_11 run
  WHERE run.run_id=p_run AND run.status='running' AND run.owner_token_hash=v_owner_hash
    AND run.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT job.* INTO v_job FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.job_id=p_job AND job.run_id=p_run AND job.status IN ('queued','retryable') FOR UPDATE;
  IF NOT FOUND OR v_job.stage<>'mention_claim_extraction' OR v_job.job_kind<>'stage_barrier' THEN
    RETURN NULL;
  END IF;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='leased',attempt=attempt+1,
    owner_token_hash=v_owner_hash,leased_at=v_now,heartbeat_at=v_now,
    lease_expires_at=v_now+interval '120 seconds'
  WHERE job_id=p_job RETURNING * INTO v_job;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,
    lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  SELECT payload.* INTO STRICT v_payload
  FROM public.legacy_producer_job_payloads_v3_11 payload WHERE payload.job_id=p_job;
  v_barrier_json:=public.read_legacy_mention_barrier_transport_v3_15(p_run);
  v_barrier_count:=jsonb_array_length(v_barrier_json->'candidates');
  v_barrier_bytes:=convert_to(v_barrier_json::text,'utf8');
  v_barrier_hash:=encode(extensions.digest(v_barrier_bytes,'sha256'),'hex');
  RETURN ROW(v_job.run_id,v_job.job_id,v_job.stage,v_job.job_kind,v_job.stage_ordinal,
    v_job.shard_ordinal,v_job.execution_ordinal,v_job.revision_id,v_job.attempt,
    v_payload.payload_canonical,v_payload.payload_json,v_payload.payload_hash,
    NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
    'mention_shard_results',v_barrier_bytes,v_barrier_json,v_barrier_hash,
    v_barrier_count,v_job.lease_expires_at)::public.legacy_producer_claim_v3_11;
END $function$

CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_13(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_payload public.legacy_producer_job_payloads_v3_11%ROWTYPE;v_prior public.legacy_producer_job_results_v3_11%ROWTYPE;v_source_result public.legacy_producer_job_results_v3_11%ROWTYPE;v_frozen public.legacy_frozen_revision_read_v3_11;v_frozen_json jsonb;v_frozen_bytes bytea;v_frozen_hash text;v_now timestamptz:=date_trunc('second',clock_timestamp());v_hash text;v_selected_hash text;v_source_published_at timestamptz;v_source_collected_at timestamptz;v_read_kind text;v_read_json jsonb;v_read_bytes bytea;v_read_hash text;v_read_count integer;v_include_authority boolean:=false;
BEGIN
  IF p_lease<>120 THEN RETURN NULL; END IF;v_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE run_id=p_run AND status='running' AND owner_token_hash=v_hash AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO v_job FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job AND run_id=p_run AND status IN ('queued','retryable') FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='leased',attempt=attempt+1,owner_token_hash=v_hash,leased_at=v_now,heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE job_id=p_job RETURNING * INTO v_job;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  SELECT * INTO v_payload FROM public.legacy_producer_job_payloads_v3_11 WHERE job_id=p_job;
  IF v_job.predecessor_job_id IS NOT NULL THEN SELECT * INTO v_prior FROM public.legacy_producer_job_results_v3_11 WHERE job_id=v_job.predecessor_job_id; END IF;
  IF v_job.job_kind='revision_shard' THEN
    SELECT selected_revision_row_hash,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>5)::timestamptz ELSE NULL END,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>6)::timestamptz ELSE (selected_revision_row_json->>5)::timestamptz END
    INTO v_selected_hash,v_source_published_at,v_source_collected_at FROM public.legacy_frozen_source_revisions_v3_11 WHERE run_id=p_run AND revision_id=v_job.revision_id;
    v_frozen:=public.read_legacy_frozen_revision_v3_11(p_run,p_job,v_hash,v_job.revision_id,v_selected_hash);
    IF v_frozen IS NULL THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    v_frozen_json:=jsonb_build_object('runId',(v_frozen).run_id,'jobId',(v_frozen).job_id,'selectionOrdinal',(v_frozen).selection_ordinal,'sourceKey',(v_frozen).source_key,'revisionId',(v_frozen).revision_id,'sourcePublishedAt',CASE WHEN v_source_published_at IS NULL THEN NULL ELSE to_char(v_source_published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') END,'sourceCollectedAt',to_char(v_source_collected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'selectedRevisionRowHash',(v_frozen).selected_revision_row_hash,'rawFieldPayload',(v_frozen).raw_field_payload,'rawCodePointCount',(v_frozen).raw_code_point_count,'rawFieldPayloadAlgorithmVersion',(v_frozen).raw_field_payload_algorithm_version,'ingestionContentRevisionSha256',(v_frozen).ingestion_content_revision_sha256,'canonicalContentAlgorithmVersion',(v_frozen).canonical_content_algorithm_version,'ingestionCanonicalContentHashV3',(v_frozen).ingestion_canonical_content_hash_v3);
    v_frozen_bytes:=convert_to(v_frozen_json::text,'utf8');v_frozen_hash:=encode(extensions.digest(v_frozen_bytes,'sha256'),'hex');
  END IF;
  IF v_job.stage<>'source_sync' THEN
    IF v_job.job_kind='revision_shard' THEN
      v_read_kind:='frozen_revision_authority';
      v_include_authority:=current_setting('stockinsider.legacy_authority_hash',true) IS DISTINCT FROM v_run.authority_hash;
      IF v_include_authority THEN
        SELECT jsonb_build_object(
          'authorityHash',v_run.authority_hash,
          'authorityPages',coalesce(jsonb_agg(jsonb_build_array(page_kind,page_ordinal,page_hash,page_json)
            ORDER BY page_kind,page_ordinal),'[]'::jsonb),
          'frozenRevision',v_frozen_json
        ),coalesce(sum(row_count),0)::integer
        INTO v_read_json,v_read_count
        FROM public.legacy_producer_authority_pages_v3_11 WHERE run_id=p_run;
      ELSE
        v_read_json:=jsonb_build_object('authorityHash',v_run.authority_hash,'authorityPages','[]'::jsonb,
          'frozenRevision',v_frozen_json);
        v_read_count:=1;
      END IF;
    ELSIF v_job.stage='mention_claim_extraction' THEN
      v_read_kind:='mention_shard_results';
      SELECT jsonb_build_object('results',coalesce(jsonb_agg(result.result_json ORDER BY job.shard_ordinal),'[]'::jsonb)),count(*)::integer
      INTO v_read_json,v_read_count
      FROM public.legacy_producer_jobs_v3_11 job JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=job.job_id
      WHERE job.run_id=p_run AND job.stage='mention_claim_extraction' AND job.job_kind='revision_shard' AND job.status='succeeded';
    ELSIF v_job.stage='candidate_funnel' THEN
      v_read_kind:='candidate_funnel_input';
      v_read_json:=jsonb_build_object(
        'mentionResult',v_prior.result_json,
        'seedSymbols',to_jsonb(v_run.legacy_seed_symbols),
        'priorLedger',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'stockId',prior.stock_id,'symbol',prior.symbol,'materialEvidenceHash',prior.material_evidence_hash,
            'disposition',prior.disposition,'sourceCutoff',prior.source_cutoff
          ) ORDER BY prior.stock_id)
          FROM (
            WITH prior_success AS (
              SELECT prior_run.run_id,prior_run.source_cutoff
              FROM public.legacy_producer_runs_v3_11 prior_run
              WHERE prior_run.status='success' AND prior_run.source_cutoff<v_run.source_cutoff
              ORDER BY prior_run.source_cutoff DESC,prior_run.terminal_at DESC,prior_run.run_id LIMIT 1
            )
            SELECT DISTINCT ON (ledger.stock_id) ledger.stock_id,ledger.symbol,ledger.material_evidence_hash,
              ledger.disposition,prior_success.source_cutoff
            FROM prior_success JOIN public.legacy_candidate_discovery_ledger_v3_11 ledger
              ON ledger.source_run_id=prior_success.run_id
            WHERE ledger.stock_id IS NOT NULL
            ORDER BY ledger.stock_id,ledger.recorded_at DESC,ledger.discovery_id
            LIMIT 60
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='facts_refresh' THEN
      v_read_kind:='candidate_fact_plane';
      v_read_json:=public.read_legacy_candidate_fact_plane_v3_11(v_run.source_cutoff,v_prior.result_json);
      v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='analysis_revision' THEN
      v_read_kind:='analysis_revision_input';
      v_read_json:=jsonb_build_object(
        'factsResult',v_prior.result_json,
        'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'producerCommitSha',v_run.producer_commit_sha,
        'priorRevisions',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'symbol',prior.symbol,'revisionId',prior.revision_id,'materialChangeHash',prior.material_change_hash,
            'analysisGeneratedAt',to_char(prior.analysis_generated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
          ) ORDER BY prior.symbol)
          FROM (
            SELECT DISTINCT ON (revision.symbol) revision.symbol,revision.revision_id,
              revision.material_change_hash,revision.analysis_generated_at,revision.source_cutoff
            FROM public.legacy_analysis_revisions_v3_11 revision
            WHERE revision.symbol IN (
              SELECT decision.value->>'symbol' FROM jsonb_array_elements(coalesce(v_prior.result_json->'decisions','[]'::jsonb)) decision(value)
            ) AND revision.source_cutoff<v_run.source_cutoff
            ORDER BY revision.symbol,revision.source_cutoff DESC,revision.recorded_at DESC,revision.revision_id
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    ELSE
      SELECT result.* INTO STRICT v_source_result
      FROM public.legacy_producer_jobs_v3_11 source_job
      JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=source_job.job_id
      WHERE source_job.run_id=p_run AND source_job.stage='source_sync'
        AND source_job.job_kind='stage_barrier' AND source_job.status='succeeded';
      IF jsonb_typeof(v_source_result.result_json->'legacyPayloads')<>'object'
        OR jsonb_typeof(v_source_result.result_json->'legacyPayloadHashes')<>'object'
      THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_read_kind:='compact_projection_input';v_read_json:=jsonb_build_object('analysisResult',v_prior.result_json,'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'producerCommitSha',v_run.producer_commit_sha,'workerSha256',v_run.worker_sha256,'legacyPayloads',v_source_result.result_json->'legacyPayloads','legacyPayloadHashes',v_source_result.result_json->'legacyPayloadHashes',
        'legacySourceResultHash',v_source_result.result_hash,
        'legacyRadarCompatibility',v_source_result.result_json->'legacyRadarCompatibility');v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    END IF;
    v_read_bytes:=convert_to(v_read_json::text,'utf8');v_read_hash:=encode(extensions.digest(v_read_bytes,'sha256'),'hex');
    IF octet_length(v_read_bytes)>3145728 OR v_read_count>20000 THEN RAISE EXCEPTION 'bound_violation';END IF;
  END IF;
  RETURN ROW(v_job.run_id,v_job.job_id,v_job.stage,v_job.job_kind,v_job.stage_ordinal,v_job.shard_ordinal,v_job.execution_ordinal,v_job.revision_id,v_job.attempt,
    v_payload.payload_canonical,v_payload.payload_json,v_payload.payload_hash,v_prior.result_canonical,v_prior.result_json,v_prior.result_hash,
    CASE WHEN v_job.stage='source_sync' THEN 'legacy-discovery-authority-v1' ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_canonical ELSE NULL END,
    CASE WHEN v_job.stage='source_sync' THEN v_run.authority_json ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_hash ELSE NULL END,v_frozen_bytes,v_frozen_json,v_frozen_hash,
    v_read_kind,v_read_bytes,v_read_json,v_read_hash,v_read_count,v_job.lease_expires_at)::public.legacy_producer_claim_v3_11;
END $function$

CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_15(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_claim public.legacy_producer_claim_v3_11;v_prior jsonb;v_conflict boolean;v_cutoff timestamptz;
BEGIN
  v_claim:=public.claim_legacy_producer_job_authoritative_v3_13(p_run,p_job,p_token,p_lease);
  IF v_claim.run_id IS NULL THEN RETURN v_claim;END IF;
  SELECT run.source_cutoff INTO STRICT v_cutoff FROM public.legacy_producer_runs_v3_11 run
    WHERE run.run_id=v_claim.run_id;
  IF v_claim.read_kind='analysis_revision_input' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'symbol',prior.value->>'symbol','revisionId',prior.value->>'revisionId',
      'materialChangeHash',prior.value->>'materialChangeHash',
      'analysisGeneratedAt',prior.value->>'analysisGeneratedAt','facts',payload.payload_json)
      ORDER BY prior.value->>'symbol'),'[]'::jsonb) INTO v_prior
    FROM jsonb_array_elements(coalesce(v_claim.read_json->'priorRevisions','[]'::jsonb)) prior(value)
    JOIN public.legacy_analysis_revision_payloads_v3_13 payload
      ON payload.revision_id=(prior.value->>'revisionId')::uuid
      AND payload.symbol=prior.value->>'symbol'
      AND payload.material_change_hash=prior.value->>'materialChangeHash';
    v_claim.read_json:=jsonb_set(v_claim.read_json,'{priorRevisions}',v_prior,false);
  ELSIF v_claim.read_kind='compact_projection_input' THEN
    WITH ranked AS MATERIALIZED(
      SELECT projection."window",projection.as_of,projection.created_at,projection.projection_id,
        projection.payload_sha256,projection.payload_json,
        row_number() OVER(PARTITION BY projection."window" ORDER BY projection.as_of DESC,
          projection.created_at DESC,projection.projection_id ASC) AS rank
      FROM public.legacy_radar_projections_v3_11 projection WHERE projection.as_of<v_cutoff
    )
    SELECT EXISTS(SELECT 1 FROM ranked newest JOIN ranked sentinel
      ON sentinel."window"=newest."window" AND sentinel.rank=2
      WHERE newest.rank=1 AND newest.as_of=sentinel.as_of AND newest.created_at=sentinel.created_at
        AND newest.payload_sha256<>sentinel.payload_sha256) INTO v_conflict;
    IF v_conflict THEN RAISE EXCEPTION 'projection_conflict';END IF;
    WITH ranked AS MATERIALIZED(
      SELECT projection."window",projection.payload_json,
        row_number() OVER(PARTITION BY projection."window" ORDER BY projection.as_of DESC,
          projection.created_at DESC,projection.projection_id ASC) AS rank
      FROM public.legacy_radar_projections_v3_11 projection WHERE projection.as_of<v_cutoff
    ) SELECT coalesce(jsonb_object_agg(ranked."window",ranked.payload_json ORDER BY ranked."window"),
        '{}'::jsonb) INTO v_prior FROM ranked WHERE ranked.rank=1;
    v_claim.read_json:=jsonb_set(v_claim.read_json,'{priorProjections}',v_prior,false);
  ELSE
    RETURN v_claim;
  END IF;
  v_claim.read_canonical:=convert_to(v_claim.read_json::text,'utf8');
  v_claim.read_hash:=encode(extensions.digest(v_claim.read_canonical,'sha256'),'hex');
  IF octet_length(v_claim.read_canonical)>3145728 THEN RAISE EXCEPTION 'bound_violation';END IF;
  RETURN v_claim;
END $function$

CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_16(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_claim public.legacy_producer_claim_v3_11;
  v_cutoff timestamptz;
BEGIN
  -- The V3.11 predecessor materializes the complete per-shard result array and
  -- enforces its 3 MiB canonical bound before a wrapper can replace that
  -- value. Claim the mention barrier directly with the same row locks,
  -- owner-token, lease and attempt transitions, then return only the reviewed
  -- candidate projection. All shard evidence remains immutable in storage.
  v_claim:=public.claim_legacy_mention_barrier_transport_v3_15(p_run,p_job,p_token,p_lease);
  IF v_claim.run_id IS NOT NULL THEN RETURN v_claim; END IF;

  v_claim:=public.claim_legacy_producer_job_authoritative_v3_15(p_run,p_job,p_token,p_lease);
  IF v_claim.run_id IS NULL THEN RETURN v_claim; END IF;

  IF v_claim.read_kind='mention_shard_results' THEN
    v_claim.read_json:=public.read_legacy_mention_barrier_transport_v3_15(p_run);
    v_claim.read_row_count:=jsonb_array_length(v_claim.read_json->'candidates');
    v_claim.read_canonical:=convert_to(v_claim.read_json::text,'utf8');
    v_claim.read_hash:=encode(extensions.digest(v_claim.read_canonical,'sha256'),'hex');
    RETURN v_claim;
  END IF;
  IF v_claim.read_kind IS DISTINCT FROM 'candidate_funnel_input' THEN RETURN v_claim; END IF;

  SELECT run.source_cutoff INTO STRICT v_cutoff
  FROM public.legacy_producer_runs_v3_11 run WHERE run.run_id=v_claim.run_id;
  v_claim.read_json:=v_claim.read_json||jsonb_build_object(
    'sourceCutoff',to_char(v_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  v_claim.read_canonical:=convert_to(v_claim.read_json::text,'utf8');
  v_claim.read_hash:=encode(extensions.digest(v_claim.read_canonical,'sha256'),'hex');
  IF octet_length(v_claim.read_canonical)>3145728 OR coalesce(v_claim.read_row_count,0)>20000 THEN
    RAISE EXCEPTION USING ERRCODE='PT413',MESSAGE='bound_violation';
  END IF;
  -- The durable predecessor result remains available by job id.  Do not copy
  -- it twice through the REST claim boundary.
  v_claim.predecessor_result_canonical:=NULL;
  v_claim.predecessor_result_json:=NULL;
  v_claim.predecessor_result_hash:=NULL;
  RETURN v_claim;
END $function$

CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_16_15(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_claim public.legacy_producer_claim_v3_11;
  v_now timestamptz;
  v_owner_hash text;
BEGIN
  IF p_lease<>120 THEN RETURN NULL; END IF;
  v_claim:=public.claim_legacy_producer_job_authoritative_v3_16(
    p_run,p_job,p_token,p_lease);
  IF v_claim.run_id IS NULL THEN RETURN v_claim; END IF;

  -- Use a post-materialization wall-clock value.  Do not require the lease
  -- timestamp written at claim entry to remain live: this transaction still
  -- owns both locked rows, and no competing claim can commit before it.
  v_now:=date_trunc('second',clock_timestamp());
  v_owner_hash:=encode(extensions.digest(
    convert_to(p_token::text,'utf8'),'sha256'),'hex');
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 run
  WHERE run.run_id=v_claim.run_id AND run.status='running'
    AND run.owner_token_hash=v_owner_hash FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.run_id=v_claim.run_id AND job.job_id=v_claim.job_id
    AND job.status='leased' AND job.owner_token_hash=v_owner_hash FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  UPDATE public.legacy_producer_runs_v3_11
    SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds'
  WHERE run_id=v_claim.run_id;
  UPDATE public.legacy_producer_jobs_v3_11
    SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds'
  WHERE run_id=v_claim.run_id AND job_id=v_claim.job_id;
  v_claim.lease_expires_at:=v_now+interval '120 seconds';
  RETURN v_claim;
END $function$

