CREATE OR REPLACE FUNCTION public.commit_insider_snapshot_page_v1(p_run uuid, p_dataset integer, p_snapshot uuid, p_offset integer, p_generation integer, p_next integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.insider_snapshots_v1; p public.insider_snapshot_progress_v1; rows jsonb; doc jsonb; i integer;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  THEN RAISE EXCEPTION 'insider_write_read_committed_required'; END IF;
 IF p_run IS NULL OR p_dataset IS NULL OR p_snapshot IS NULL OR p_offset IS NULL OR p_generation IS NULL OR p_next IS NULL THEN RAISE EXCEPTION 'insider_commit_required'; END IF;
 PERFORM pg_advisory_xact_lock(2410,8001); PERFORM pg_advisory_xact_lock(2411,p_dataset);
 IF NOT EXISTS(SELECT 1 FROM public.insider_acquisition_runs_v1 r JOIN public.insider_run_members_v1 m ON m.run_id=r.id WHERE r.id=p_run AND r.frozen_at IS NOT NULL AND m.dataset=p_dataset AND m.snapshot_id=p_snapshot) THEN RAISE EXCEPTION 'insider_frozen_run_binding_required'; END IF;
 SELECT * INTO STRICT s FROM public.insider_snapshots_v1 WHERE id=p_snapshot AND dataset=p_dataset;
 SELECT * INTO STRICT p FROM public.insider_snapshot_progress_v1 WHERE snapshot_id=p_snapshot;
 rows:=public.insider_snapshot_assert_v1(p_snapshot);
 IF p_offset<0 OR p_offset%500<>0 OR p_generation<>p_offset/500 OR p_next<>least(p_offset+500,s.row_count) OR p_offset>s.row_count THEN RAISE EXCEPTION 'insider_page_span_invalid'; END IF;
 IF p.offset_rows=p_next AND p.generation=p_generation+1 THEN RETURN public.read_insider_snapshot_page_v1(p_run,p_dataset,p_snapshot); END IF;
 IF p.complete OR p.offset_rows<>p_offset OR p.generation<>p_generation THEN RAISE EXCEPTION 'insider_page_cas_conflict'; END IF;
 IF p_next>p_offset THEN FOR i IN p_offset..p_next-1 LOOP
  doc:=public.insider_expected_document_v1(p_snapshot,i,rows->i);
  IF doc IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.source_raw_documents d WHERE d.platform='twse_insider' AND d.document_url=doc->>'documentUrl' AND d.title=doc->>'title' AND d.summary=doc->>'summary' AND d.content_text=doc->>'contentText' AND d.published_at IS NULL AND d.sentiment_label='neutral' AND d.content_semantics='official_chip_evidence' AND d.stance_semantics='neutral' AND d.canonical_content_hash=encode(extensions.digest(convert_to(lower(doc->>'contentText'),'UTF8'),'sha256'),'hex') AND d.symbols=doc->'symbols' AND d.metadata @> (doc->'metadata') AND d.collected_at>=s.observed_at) THEN RAISE EXCEPTION 'insider_page_document_missing_or_mismatch'; END IF;
 END LOOP; END IF;
 UPDATE public.insider_snapshot_progress_v1 SET offset_rows=p_next,generation=generation+1,complete=p_next=s.row_count,completed_at=CASE WHEN p_next=s.row_count THEN clock_timestamp() ELSE NULL END WHERE snapshot_id=p_snapshot;
 RETURN public.read_insider_snapshot_page_v1(p_run,p_dataset,p_snapshot);
END $function$

CREATE OR REPLACE FUNCTION public.commit_research_author_handoff_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_principal text, p_result_id uuid, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context jsonb; a jsonb; receipt public.research_model_completions_v1;
BEGIN
 context:=public.read_research_author_handoff_context_v2(p_request,p_revision_id,p_input_hash,p_principal,p_result_id,p_result_hash);
 a:=context->'assignment';
 IF context->'completion'<>'null'::jsonb THEN
  IF clock_timestamp()>=least((a->>'original_job_deadline')::timestamptz,(a->>'reservation_expires_at')::timestamptz)
   THEN RAISE EXCEPTION 'research_author_handoff_expired'; END IF;
  RETURN context->'completion';
 END IF;
 INSERT INTO public.research_model_completions_v1(reservation_id,owner,outcome,result_hash)
 VALUES((a->>'reservation_id')::uuid,a->>'work_owner','completed',context->'result'->'payload'->'validatedArticle'->>'articleHash')
 RETURNING * INTO receipt;
 IF clock_timestamp()>=least((a->>'original_job_deadline')::timestamptz,(a->>'reservation_expires_at')::timestamptz)
 THEN RAISE EXCEPTION 'research_author_handoff_expired'; END IF;
 RETURN to_jsonb(receipt);
END $function$

CREATE OR REPLACE FUNCTION public.complete_candidate_financial_acquisition_job_v4(p_job_id uuid, p_owner text, p_caller_principal uuid, p_facts jsonb, p_source_sha256 text, p_response_bytes integer, p_collected_at timestamp with time zone)
 RETURNS TABLE(written_facts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_job public.candidate_financial_acquisition_jobs_v4%ROWTYPE;
  v_fact jsonb;
  v_fact_id uuid;
  v_written integer := 0;
  v_provider text;
  v_batch_provider text;
  v_actual_source_url text;
BEGIN
  IF p_facts IS NULL OR jsonb_typeof(p_facts) <> 'array' THEN
    RAISE EXCEPTION 'invalid_candidate_financial_completion';
  END IF;
  IF jsonb_array_length(p_facts) < 1
    OR COALESCE(p_source_sha256,'') !~ '^[0-9a-f]{64}$'
    OR p_response_bytes IS NULL
    OR p_response_bytes < 0 OR p_response_bytes > 67108864
    OR p_collected_at IS NULL OR p_collected_at > clock_timestamp() THEN
    RAISE EXCEPTION 'invalid_candidate_financial_completion';
  END IF;
  SELECT * INTO v_job
  FROM public.candidate_financial_acquisition_jobs_v4
  WHERE job_id = p_job_id AND status = 'running' AND lease_owner = p_owner
  FOR UPDATE;
  IF NOT FOUND OR v_job.lease_expires_at < clock_timestamp() THEN
    RAISE EXCEPTION 'candidate_financial_job_lease_lost';
  END IF;

  FOR v_fact IN SELECT value FROM jsonb_array_elements(p_facts)
  LOOP
    v_provider := v_fact #>> '{input,provider}';
    v_batch_provider := COALESCE(v_batch_provider,v_provider);
    v_actual_source_url := CASE
      WHEN v_provider = 'finmind' THEN 'https://api.finmindtrade.com/api/v4/data'
      ELSE v_job.source_url
    END;
    IF v_provider IS DISTINCT FROM v_batch_provider
      OR v_provider NOT IN ('mops','twse','tpex','finmind')
      OR (v_fact #>> '{input,stock_id}')::uuid IS DISTINCT FROM v_job.stock_id
      OR (v_fact #>> '{input,period_end}')::date IS DISTINCT FROM v_job.period_end
      OR (v_fact #>> '{input,collected_at}')::timestamptz IS DISTINCT FROM p_collected_at
      OR (v_provider = 'finmind' AND COALESCE(v_fact #>> '{input,source_ref}','') !~ '^finmind:')
      OR (v_provider = 'mops' AND COALESCE(v_fact #>> '{input,source_ref}','') !~ '^(twse|tpex)-mops-inline:')
      OR (v_provider IN ('twse','tpex') AND COALESCE(v_fact #>> '{input,source_ref}','') !~ '^(twse|tpex)-openapi:')
      OR v_actual_source_url !~ '^https://' THEN
      RAISE EXCEPTION 'candidate_financial_provenance_invalid';
    END IF;
    SELECT appended.fact_id INTO v_fact_id
    FROM public.append_financial_fact_v3(
      jsonb_populate_record(NULL::public.financial_fact_input_v3, v_fact->'input'),
      p_caller_principal
    ) appended
    LIMIT 1;
    IF v_fact_id IS NULL THEN RAISE EXCEPTION 'candidate_financial_fact_append_empty'; END IF;
    INSERT INTO public.candidate_financial_fact_provenance_v4(
      fact_id,acquisition_job_id,source_url,source_sha256,locator,extracted_at
    ) VALUES(
      v_fact_id,p_job_id,v_actual_source_url,p_source_sha256,
      COALESCE(v_fact->'locator','{}'::jsonb),p_collected_at
    ) ON CONFLICT DO NOTHING;
    v_written := v_written + 1;
  END LOOP;

  UPDATE public.candidate_financial_acquisition_jobs_v4
  SET status='terminal',attempts=LEAST(attempts+1,20),consecutive_failures=0,lease_owner=NULL,lease_expires_at=NULL,
      terminal_reason='complete',terminal_detail=NULL,response_sha256=p_source_sha256,
      response_bytes=p_response_bytes,collected_at=p_collected_at,next_attempt_at=NULL,
      updated_at=p_collected_at
  WHERE job_id=p_job_id;

  INSERT INTO public.candidate_financial_acquisition_cursors_v4(
    stock_id,endpoint_key,cursor_value,last_successful_period_end,last_terminal_reason,
    last_collected_at,updated_at
  ) VALUES(
    v_job.stock_id,v_job.endpoint_key,
    jsonb_build_object(
      'cursor_key',v_job.cursor_key,'job_id',p_job_id,
      'source_sha256',p_source_sha256,
      'provider',v_batch_provider
    ),
    v_job.period_end,'complete',p_collected_at,p_collected_at
  ) ON CONFLICT(stock_id,endpoint_key) DO UPDATE SET
    cursor_value=EXCLUDED.cursor_value,
    last_successful_period_end=GREATEST(public.candidate_financial_acquisition_cursors_v4.last_successful_period_end,EXCLUDED.last_successful_period_end),
    last_terminal_reason=EXCLUDED.last_terminal_reason,
    last_collected_at=EXCLUDED.last_collected_at,
    updated_at=EXCLUDED.updated_at;

  RETURN QUERY SELECT v_written;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_candidate_financial_document_receipt_parser_v10(p_receipt_id uuid, p_owner text, p_caller_principal uuid, p_facts jsonb, p_parser_locators jsonb, p_parser_evidence jsonb, p_missing_requirements jsonb, p_rejection_reasons jsonb, p_completed_at timestamp with time zone)
 RETURNS TABLE(receipt_status text, added_fact_count integer, duplicate_fact_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_receipt public.candidate_financial_document_receipts_v6%ROWTYPE;
  v_fact jsonb; v_locator jsonb; v_fact_id uuid; v_recorded_at timestamptz;
  v_added integer:=0; v_duplicate integer:=0; v_status text; v_evidence_id uuid;
  v_manifest_sha text; v_parser text; v_validation jsonb; v_manifest jsonb;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal(p_caller_principal,'opportunity_runner',clock_timestamp())
  THEN RAISE EXCEPTION 'principal_role_unavailable'; END IF;
  IF jsonb_typeof(p_facts) IS DISTINCT FROM 'array' OR jsonb_array_length(COALESCE(p_facts,'[]'::jsonb))>128
    OR jsonb_typeof(p_parser_locators) IS DISTINCT FROM 'array' OR jsonb_array_length(COALESCE(p_parser_locators,'[]'::jsonb))>200
    OR jsonb_typeof(COALESCE(p_parser_evidence,'null'::jsonb))<>'object'
    OR p_parser_evidence->>'schema' IS DISTINCT FROM 'candidate-financial-parser-evidence-v10'
    OR jsonb_typeof(COALESCE(p_parser_evidence->'validatedFacts','null'::jsonb))<>'array'
    OR jsonb_array_length(p_parser_evidence->'validatedFacts')>200
    OR jsonb_typeof(p_missing_requirements) IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_rejection_reasons) IS DISTINCT FROM 'array'
    OR p_completed_at IS NULL OR p_completed_at>clock_timestamp()
  THEN RAISE EXCEPTION 'invalid_candidate_financial_document_completion'; END IF;

  SELECT * INTO v_receipt FROM public.candidate_financial_document_receipts_v6 receipt
  WHERE receipt.receipt_id=p_receipt_id AND receipt.parser_status='running' AND receipt.parser_owner=p_owner FOR UPDATE;
  IF NOT FOUND OR v_receipt.parser_lease_expires_at<clock_timestamp()
  THEN RAISE EXCEPTION 'candidate_financial_document_lease_lost'; END IF;
  IF p_parser_evidence->>'documentSha256' IS DISTINCT FROM v_receipt.document_sha256
  THEN RAISE EXCEPTION 'candidate_financial_parser_evidence_document_mismatch'; END IF;

  v_parser:=NULLIF(p_parser_evidence->>'parser','');
  v_validation:=p_parser_evidence->'validation';
  v_manifest:=p_parser_evidence->'validatedFacts';
  PERFORM public.validate_candidate_financial_fact_scope_v10(p_parser_evidence,v_receipt.content_type,jsonb_array_length(p_facts)>0);

  FOR v_locator IN SELECT value FROM jsonb_array_elements(p_parser_locators) LOOP
    IF jsonb_typeof(v_locator)<>'object' OR NOT (
      (v_locator ? 'xbrl_context' AND v_locator ? 'xbrl_concept'
        AND jsonb_typeof(v_locator->'xbrl_context')='string' AND jsonb_typeof(v_locator->'xbrl_concept')='string'
        AND char_length(v_locator->>'xbrl_context') BETWEEN 1 AND 256
        AND char_length(v_locator->>'xbrl_concept') BETWEEN 1 AND 256)
      OR (v_locator ? 'page' AND jsonb_typeof(v_locator->'page')='number'
        AND (v_locator->>'page')::integer BETWEEN 1 AND 200
        AND (NOT (v_locator ? 'table') OR (jsonb_typeof(v_locator->'table')='number'
          AND (v_locator->>'table')::integer BETWEEN 1 AND 20)))
    ) THEN RAISE EXCEPTION 'candidate_financial_document_locator_invalid'; END IF;
  END LOOP;

  -- Hash the complete canonical evidence, not only its fact manifest. Two
  -- empty-manifest attempts with different runtime diagnostics must remain
  -- independently auditable.
  v_manifest_sha:=encode(digest(convert_to(p_parser_evidence::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.candidate_financial_parser_evidence_v8(
    receipt_id,document_sha256,parser,parser_version,taxonomy_sha256,validation_summary,
    validated_fact_manifest,manifest_sha256,recorded_at,evidence_schema_version,document_status,fact_acceptance,error_manifest_sha256
  ) VALUES(p_receipt_id,v_receipt.document_sha256,v_parser,NULLIF(p_parser_evidence->>'parserVersion',''),
    NULLIF(p_parser_evidence->>'taxonomySha256',''),v_validation,v_manifest,v_manifest_sha,p_completed_at,10,p_parser_evidence->>'documentStatus',
    p_parser_evidence->'factAcceptance',p_parser_evidence->>'errorManifestSha256')
  ON CONFLICT(receipt_id,manifest_sha256) DO NOTHING RETURNING evidence_id INTO v_evidence_id;
  IF v_evidence_id IS NULL THEN
    SELECT evidence_id INTO v_evidence_id FROM public.candidate_financial_parser_evidence_v8
      WHERE receipt_id=p_receipt_id AND manifest_sha256=v_manifest_sha;
  END IF;

  FOR v_fact IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
    IF (v_fact #>> '{input,stock_id}')::uuid IS DISTINCT FROM v_receipt.stock_id
      OR (v_fact #>> '{input,period_end}')::date IS DISTINCT FROM v_receipt.period_end
      OR (v_fact #>> '{input,provider}') IS DISTINCT FROM 'mops'
      OR (v_fact #>> '{input,authority_tier}') IS DISTINCT FROM 'official_filing'
      OR COALESCE(v_fact #>> '{input,source_ref}','') !~ ('^issuer-document:'||v_receipt.document_sha256||':')
      OR jsonb_typeof(COALESCE(v_fact->'locator','null'::jsonb))<>'object'
      OR NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_manifest) manifest(row)
        JOIN public.stocks stock ON stock.id=v_receipt.stock_id
        WHERE manifest.row->>'factKey'=v_fact #>> '{locator,structural_fact_key}'
          AND manifest.row->>'concept_namespace'=v_fact #>> '{locator,concept_namespace}'
          AND manifest.row->>'xbrl_context'=v_fact #>> '{locator,xbrl_context}'
          AND manifest.row->>'xbrl_concept'=v_fact #>> '{locator,xbrl_concept}'
          AND manifest.row->>'unit'=v_fact #>> '{input,unit}'
          AND (manifest.row->>'value')::numeric=(v_fact #>> '{input,value}')::numeric
          AND manifest.row->>'entity_identifier'=stock.symbol
          AND (manifest.row->>'period_start')::date IS NOT DISTINCT FROM (v_fact #>> '{input,period_start}')::date
          AND (manifest.row->>'period_end')::date=(v_fact #>> '{input,period_end}')::date
          AND manifest.row->>'duration_kind'=v_fact #>> '{input,duration_kind}'
          AND (manifest.row->>'dimension_count')::integer=0
      )
    THEN RAISE EXCEPTION 'candidate_financial_document_fact_invalid'; END IF;

    SELECT fact.fact_id,fact.recorded_at INTO v_fact_id,v_recorded_at
    FROM public.opportunity_financial_facts_v3 fact
    WHERE fact.stock_id=v_receipt.stock_id AND fact.source_ref=v_fact #>> '{input,source_ref}'
      AND fact.collected_at<=(v_fact #>> '{input,collected_at}')::timestamptz
    ORDER BY fact.recorded_at,fact.fact_id LIMIT 1;
    IF v_fact_id IS NULL THEN
      SELECT appended.fact_id,appended.recorded_at INTO v_fact_id,v_recorded_at
      FROM public.append_financial_fact_v3(
        jsonb_populate_record(NULL::public.financial_fact_input_v3,v_fact->'input'),p_caller_principal
      ) appended LIMIT 1;
      v_added:=v_added+1;
    ELSE v_duplicate:=v_duplicate+1; END IF;
    IF v_fact_id IS NULL OR v_recorded_at IS NULL
    THEN RAISE EXCEPTION 'candidate_financial_document_fact_append_empty'; END IF;
    INSERT INTO public.candidate_financial_fact_provenance_v4(
      fact_id,issuer_document_id,source_url,source_sha256,locator,extracted_at
    ) VALUES(v_fact_id,v_receipt.issuer_document_id,v_receipt.source_url,v_receipt.document_sha256,
      (v_fact->'locator')||jsonb_build_object('parser_evidence_id',v_evidence_id,'manifest_sha256',v_manifest_sha),p_completed_at)
    ON CONFLICT DO NOTHING;
    INSERT INTO public.candidate_financial_document_fact_links_v8(receipt_id,fact_id,fact_recorded_at,evidence_id,created_at)
    VALUES(p_receipt_id,v_fact_id,v_recorded_at,v_evidence_id,p_completed_at) ON CONFLICT DO NOTHING;
  END LOOP;

  IF p_parser_evidence->>'documentStatus'='partial' AND NOT (p_missing_requirements ? 'document_structural_validation_incomplete') THEN
    p_missing_requirements:=COALESCE(p_missing_requirements,'[]'::jsonb)||jsonb_build_array('document_structural_validation_incomplete');
  END IF;
  v_status:=CASE WHEN jsonb_array_length(p_rejection_reasons)>0 THEN 'rejected'
    WHEN jsonb_array_length(p_facts)>0 THEN 'validation_pending' ELSE 'partial' END;
  UPDATE public.candidate_financial_document_receipts_v6 SET
    receipt_status=v_status,parser_status='complete',parser_owner=NULL,parser_lease_expires_at=NULL,
    added_fact_count=v_added,duplicate_fact_count=v_duplicate,parser_locators=p_parser_locators,
    parser_evidence_id=v_evidence_id,
    financial_validation_status=CASE WHEN jsonb_array_length(p_facts)>0 THEN 'pending' ELSE 'not_applicable' END,
    financial_validation_attempts=0,
    financial_validation_next_attempt_at=CASE WHEN jsonb_array_length(p_facts)>0 THEN p_completed_at ELSE NULL END,
    financial_validation_terminal_reason=NULL,
    missing_requirements=p_missing_requirements,rejection_reasons=p_rejection_reasons,completed_at=p_completed_at
  WHERE receipt_id=p_receipt_id;
  receipt_status:=v_status; added_fact_count:=v_added; duplicate_fact_count:=v_duplicate; RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.complete_candidate_financial_document_receipt_parser_v7(p_receipt_id uuid, p_owner text, p_caller_principal uuid, p_facts jsonb, p_parser_locators jsonb, p_missing_requirements jsonb, p_rejection_reasons jsonb, p_completed_at timestamp with time zone)
 RETURNS TABLE(receipt_status text, added_fact_count integer, duplicate_fact_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_receipt public.candidate_financial_document_receipts_v6%ROWTYPE; v_fact jsonb; v_locator jsonb; v_fact_id uuid;
  v_added integer:=0; v_duplicate integer:=0; v_status text;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal(p_caller_principal,'opportunity_runner',clock_timestamp())
  THEN RAISE EXCEPTION 'principal_role_unavailable'; END IF;
  IF jsonb_typeof(COALESCE(p_facts,'[]'::jsonb))<>'array' OR jsonb_array_length(COALESCE(p_facts,'[]'::jsonb))>128
    OR jsonb_typeof(COALESCE(p_parser_locators,'[]'::jsonb))<>'array' OR jsonb_array_length(COALESCE(p_parser_locators,'[]'::jsonb))>200
    OR jsonb_typeof(COALESCE(p_missing_requirements,'[]'::jsonb))<>'array'
    OR jsonb_typeof(COALESCE(p_rejection_reasons,'[]'::jsonb))<>'array'
    OR p_completed_at IS NULL OR p_completed_at>clock_timestamp()
  THEN RAISE EXCEPTION 'invalid_candidate_financial_document_completion'; END IF;
  SELECT * INTO v_receipt FROM public.candidate_financial_document_receipts_v6 receipt
  WHERE receipt.receipt_id=p_receipt_id AND receipt.parser_status='running' AND receipt.parser_owner=p_owner FOR UPDATE;
  IF NOT FOUND OR v_receipt.parser_lease_expires_at<clock_timestamp() THEN RAISE EXCEPTION 'candidate_financial_document_lease_lost'; END IF;
  FOR v_locator IN SELECT value FROM jsonb_array_elements(p_parser_locators) LOOP
    IF jsonb_typeof(v_locator)<>'object'
      OR NOT (v_locator ? 'xbrl_context' OR v_locator ? 'page' OR v_locator ? 'table')
      OR (v_locator ? 'page' AND (jsonb_typeof(v_locator->'page')<>'number' OR v_locator->>'page' !~ '^[0-9]+$' OR (v_locator->>'page')::integer NOT BETWEEN 1 AND 200))
      OR (v_locator ? 'table' AND (jsonb_typeof(v_locator->'table')<>'number' OR v_locator->>'table' !~ '^[0-9]+$' OR (v_locator->>'table')::integer NOT BETWEEN 1 AND 20))
      OR (v_locator ? 'xbrl_context' AND (jsonb_typeof(v_locator->'xbrl_context')<>'string' OR char_length(v_locator->>'xbrl_context')>256))
      OR (v_locator ? 'xbrl_concept' AND (jsonb_typeof(v_locator->'xbrl_concept')<>'string' OR char_length(v_locator->>'xbrl_concept')>256))
    THEN RAISE EXCEPTION 'candidate_financial_document_locator_invalid'; END IF;
  END LOOP;
  FOR v_fact IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
    IF (v_fact #>> '{input,stock_id}')::uuid IS DISTINCT FROM v_receipt.stock_id
      OR (v_fact #>> '{input,period_end}')::date IS DISTINCT FROM v_receipt.period_end
      OR (v_fact #>> '{input,provider}')<>'mops'
      OR (v_fact #>> '{input,authority_tier}')<>'official_filing'
      OR COALESCE(v_fact #>> '{input,source_ref}','') !~ ('^issuer-document:'||v_receipt.document_sha256||':')
      OR jsonb_typeof(COALESCE(v_fact->'locator','null'::jsonb))<>'object'
      OR NOT (v_fact->'locator' ? 'xbrl_context' OR v_fact->'locator' ? 'page' OR v_fact->'locator' ? 'table')
      OR NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_parser_locators) parsed(locator)
        WHERE
          (v_fact->'locator' ? 'xbrl_context'
            AND parsed.locator->>'xbrl_context'=v_fact #>> '{locator,xbrl_context}'
            AND parsed.locator->>'xbrl_concept'=v_fact #>> '{locator,xbrl_concept}')
          OR (v_fact->'locator' ? 'page'
            AND parsed.locator->>'page'=v_fact #>> '{locator,page}'
            AND (NOT (v_fact->'locator' ? 'table') OR parsed.locator->>'table'=v_fact #>> '{locator,table}'))
      )
    THEN RAISE EXCEPTION 'candidate_financial_document_fact_invalid'; END IF;
    SELECT fact.fact_id INTO v_fact_id FROM public.opportunity_financial_facts_v3 fact
    WHERE fact.stock_id=v_receipt.stock_id AND fact.source_ref=v_fact #>> '{input,source_ref}'
      AND fact.collected_at<=(v_fact #>> '{input,collected_at}')::timestamptz ORDER BY fact.recorded_at,fact.fact_id LIMIT 1;
    IF v_fact_id IS NULL THEN
      SELECT appended.fact_id INTO v_fact_id FROM public.append_financial_fact_v3(
        jsonb_populate_record(NULL::public.financial_fact_input_v3,v_fact->'input'),p_caller_principal
      ) appended LIMIT 1;
