    missing_requirements=p_missing_requirements,rejection_reasons=p_rejection_reasons,completed_at=p_completed_at
  WHERE receipt_id=p_receipt_id;
  -- A complete structured document can close its linked work in the same
  -- transaction. A partial document deliberately leaves the original gap
  -- open; it cannot become artificial queue progress.
  IF v_status='accepted' AND v_receipt.acquisition_job_id IS NOT NULL THEN
    UPDATE public.candidate_financial_acquisition_jobs_v4 SET status='terminal',terminal_reason='complete',terminal_detail=NULL,
      lease_owner=NULL,lease_expires_at=NULL,collected_at=p_completed_at,next_attempt_at=NULL,updated_at=p_completed_at
    WHERE job_id=v_receipt.acquisition_job_id AND status IN ('queued','running');
  END IF;
  receipt_status:=v_status;added_fact_count:=v_added;duplicate_fact_count:=v_duplicate;RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.complete_candidate_history_month_v1(p_stock_id uuid, p_dataset text, p_month date, p_attempted_at timestamp with time zone, p_latest_session date, p_observed_through date, p_status text, p_terminal_reason text, p_next_attempt_at timestamp with time zone, p_source_url text, p_parser_version text, p_prices jsonb, p_multiples jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row JSONB; v_session DATE; v_sessions JSONB:='[]'::jsonb; v_conflict BOOLEAN:=p_status='conflict';
  v_status TEXT:=p_status; v_reason TEXT:=p_terminal_reason; v_attempt public.candidate_history_backfill_attempts_v1;
  v_available_at TIMESTAMPTZ:=clock_timestamp();
  v_prior_conflict_reason TEXT;
  v_price public.official_price_history; v_multiple public.official_multiple_history; v_fundamental public.fundamental_snapshots;
BEGIN
  IF p_stock_id IS NULL OR p_dataset IS NULL OR p_dataset NOT IN ('price','multiple') OR p_month IS NULL OR extract(day FROM p_month)<>1
    OR p_attempted_at IS NULL OR p_latest_session IS NULL OR p_status IS NULL OR p_status NOT IN ('complete','retry','conflict')
    OR p_terminal_reason IS NULL OR p_parser_version IS NULL OR p_parser_version<>'candidate-history-month-v1'
    OR p_latest_session>(v_available_at AT TIME ZONE 'Asia/Taipei')::date
    OR p_source_url IS NULL OR p_source_url!~'^https://www\.(twse\.com\.tw|tpex\.org\.tw)/'
    OR jsonb_typeof(p_prices) IS DISTINCT FROM 'array' OR jsonb_typeof(p_multiples) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_prices)>31 OR jsonb_array_length(p_multiples)>1
    OR (p_dataset='price' AND jsonb_array_length(p_multiples)>0)
    OR (p_dataset='multiple' AND jsonb_array_length(p_prices)>0)
    OR (p_status='complete' AND jsonb_array_length(p_prices)+jsonb_array_length(p_multiples)=0)
    OR (p_status='retry' AND (p_next_attempt_at IS NULL OR p_next_attempt_at<=p_attempted_at))
    OR (p_status='conflict' AND (p_dataset<>'price' OR p_terminal_reason<>'official_history_provider_conflict'
      OR jsonb_array_length(p_prices)+jsonb_array_length(p_multiples)<>0 OR p_next_attempt_at IS NOT NULL
      OR p_observed_through IS NULL OR date_trunc('month',p_observed_through)::date<>p_month
      OR p_observed_through>p_latest_session))
  THEN RAISE EXCEPTION 'candidate_history_completion_invalid'; END IF;
  -- Serialize per issuer-month and make a retry of the same completion idempotent.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_stock_id::text||':'||p_dataset||':'||p_month::text,0));
  -- A clean later session does not adjudicate an earlier contradictory value.
  -- Keep the month quarantined until an explicit reviewed resolution exists.
  SELECT terminal_reason INTO v_prior_conflict_reason FROM public.candidate_history_backfill_months_v1
    WHERE stock_id=p_stock_id AND dataset=p_dataset AND month=p_month AND status='conflict';
  IF FOUND THEN v_conflict:=true; END IF;
  SELECT * INTO v_attempt FROM public.candidate_history_backfill_attempts_v1
    WHERE stock_id=p_stock_id AND dataset=p_dataset AND month=p_month AND attempted_at=p_attempted_at;
  IF FOUND THEN RETURN CASE WHEN v_prior_conflict_reason IS NOT NULL
    THEN jsonb_build_object('status','conflict','terminal_reason',v_prior_conflict_reason)
    ELSE jsonb_build_object('status',v_attempt.status,'terminal_reason',v_attempt.terminal_reason) END; END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(CASE WHEN p_dataset='price' THEN p_prices ELSE p_multiples END) LOOP
    v_session:=COALESCE(v_row->>'time',v_row->>'date')::date;
    IF v_session IS NULL OR date_trunc('month',v_session)::date<>p_month OR v_session>p_latest_session
      OR v_row->>'authorityTier' IS DISTINCT FROM 'official_primary'
      OR v_row->>'provider' IS DISTINCT FROM 'official_primary'
      OR v_row->>'sourceUrl' IS DISTINCT FROM p_source_url
    THEN RAISE EXCEPTION 'candidate_history_row_provenance_invalid'; END IF;
    IF p_dataset='price' THEN
      IF (v_row->>'open')::numeric IS NULL OR (v_row->>'high')::numeric IS NULL OR (v_row->>'low')::numeric IS NULL OR (v_row->>'close')::numeric IS NULL
        OR (v_row->>'low')::numeric<=0 OR (v_row->>'low')::numeric>least((v_row->>'open')::numeric,(v_row->>'close')::numeric)
        OR (v_row->>'high')::numeric<greatest((v_row->>'open')::numeric,(v_row->>'close')::numeric)
        OR (v_row->>'volume')::numeric<0 THEN RAISE EXCEPTION 'candidate_history_price_invalid'; END IF;
      IF EXISTS(SELECT 1 FROM public.official_price_history WHERE stock_id=p_stock_id AND session_date=v_session
        AND (open IS DISTINCT FROM (v_row->>'open')::numeric OR high IS DISTINCT FROM (v_row->>'high')::numeric
          OR low IS DISTINCT FROM (v_row->>'low')::numeric OR close IS DISTINCT FROM (v_row->>'close')::numeric
          OR volume IS DISTINCT FROM (v_row->>'volume')::numeric)) THEN v_conflict:=true; END IF;
    ELSE
      IF ((v_row->>'peRatio')::numeric IS NULL AND (v_row->>'pbRatio')::numeric IS NULL)
        OR (v_row->>'peRatio')::numeric<=0 OR (v_row->>'pbRatio')::numeric<=0
      THEN RAISE EXCEPTION 'candidate_history_multiple_invalid'; END IF;
      IF EXISTS(SELECT 1 FROM public.official_multiple_history WHERE stock_id=p_stock_id AND month_end=v_session
        AND (pe_ratio IS DISTINCT FROM (v_row->>'peRatio')::numeric OR pb_ratio IS DISTINCT FROM (v_row->>'pbRatio')::numeric)) THEN v_conflict:=true; END IF;
    END IF;
    v_sessions:=v_sessions||jsonb_build_array(v_session::text);
  END LOOP;
  IF v_conflict THEN v_status:='conflict'; v_reason:=COALESCE(v_prior_conflict_reason,
    CASE WHEN p_status='conflict' THEN p_terminal_reason ELSE 'official_history_existing_row_conflict' END);
  ELSE
    FOR v_row IN SELECT value FROM jsonb_array_elements(p_prices) LOOP
      v_session:=(v_row->>'time')::date;
      INSERT INTO public.official_price_history(stock_id,session_date,open,high,low,close,volume,source_url,as_of,available_at,provenance)
        VALUES(p_stock_id,v_session,(v_row->>'open')::numeric,(v_row->>'high')::numeric,(v_row->>'low')::numeric,
          (v_row->>'close')::numeric,(v_row->>'volume')::numeric,p_source_url,
          (v_session::text||'T13:30:00+08:00')::timestamptz,v_available_at,
          jsonb_build_object('provider','official_primary','authorityTier','official_primary','integrityStatus','valid','history_policy',p_parser_version))
        ON CONFLICT(stock_id,session_date) DO NOTHING;
      -- The ordinary research writer does not share our advisory lock. Its
      -- uncommitted INSERT can win the unique key after the preflight SELECT.
      -- Re-read the resolved row and hold its lock through checkpoint commit.
      SELECT * INTO v_price FROM public.official_price_history
        WHERE stock_id=p_stock_id AND session_date=v_session FOR UPDATE;
      IF NOT FOUND OR v_price.open IS DISTINCT FROM (v_row->>'open')::numeric
        OR v_price.high IS DISTINCT FROM (v_row->>'high')::numeric
        OR v_price.low IS DISTINCT FROM (v_row->>'low')::numeric
        OR v_price.close IS DISTINCT FROM (v_row->>'close')::numeric
        OR v_price.volume IS DISTINCT FROM (v_row->>'volume')::numeric
      THEN v_conflict:=true; END IF;
    END LOOP;
    FOR v_row IN SELECT value FROM jsonb_array_elements(p_multiples) LOOP
      v_session:=(v_row->>'date')::date;
      INSERT INTO public.official_multiple_history(stock_id,month_end,close,pe_ratio,pb_ratio,source_url,as_of,available_at,provenance,valuation_parser_version,quality_status)
        VALUES(p_stock_id,v_session,NULL,(v_row->>'peRatio')::numeric,(v_row->>'pbRatio')::numeric,p_source_url,
          (v_session::text||'T13:30:00+08:00')::timestamptz,v_available_at,
          jsonb_build_object('provider','official_primary','official',true,'valuation_parser_version',v_row->>'parserVersion','history_policy',p_parser_version),
          v_row->>'parserVersion','valid') ON CONFLICT(stock_id,month_end) DO NOTHING;
      SELECT * INTO v_multiple FROM public.official_multiple_history
        WHERE stock_id=p_stock_id AND month_end=v_session FOR UPDATE;
      IF NOT FOUND OR v_multiple.pe_ratio IS DISTINCT FROM (v_row->>'peRatio')::numeric
        OR v_multiple.pb_ratio IS DISTINCT FROM (v_row->>'pbRatio')::numeric
      THEN v_conflict:=true; CONTINUE; END IF;
      INSERT INTO public.fundamental_snapshots(stock_id,as_of_date,pe_ratio,pb_ratio,source_url,valuation_parser_version,quality_status)
        VALUES(p_stock_id,v_session,(v_row->>'peRatio')::numeric,(v_row->>'pbRatio')::numeric,p_source_url,v_row->>'parserVersion','valid')
        ON CONFLICT(stock_id,as_of_date) DO NOTHING;
      SELECT * INTO v_fundamental FROM public.fundamental_snapshots
        WHERE stock_id=p_stock_id AND as_of_date=v_session FOR UPDATE;
      IF NOT FOUND OR v_fundamental.pe_ratio IS DISTINCT FROM (v_row->>'peRatio')::numeric
        OR v_fundamental.pb_ratio IS DISTINCT FROM (v_row->>'pbRatio')::numeric
      THEN v_conflict:=true; END IF;
    END LOOP;
  END IF;
  IF v_conflict THEN v_status:='conflict'; v_reason:=COALESCE(v_prior_conflict_reason,
    CASE WHEN p_status='conflict' THEN p_terminal_reason ELSE 'official_history_existing_row_conflict' END); END IF;
  INSERT INTO public.candidate_history_backfill_attempts_v1(stock_id,dataset,month,attempted_at,status,terminal_reason,acquired_rows,source_url,parser_version)
    VALUES(p_stock_id,p_dataset,p_month,p_attempted_at,v_status,v_reason,jsonb_array_length(v_sessions),p_source_url,p_parser_version);
  INSERT INTO public.candidate_history_backfill_months_v1(stock_id,dataset,month,status,attempted_at,next_attempt_at,attempts,observed_through,observed_sessions,terminal_reason,source_url,parser_version)
    VALUES(p_stock_id,p_dataset,p_month,v_status,p_attempted_at,CASE WHEN v_status='retry' THEN p_next_attempt_at END,1,p_observed_through,v_sessions,v_reason,p_source_url,p_parser_version)
    ON CONFLICT(stock_id,dataset,month) DO UPDATE SET status=excluded.status,attempted_at=excluded.attempted_at,
      next_attempt_at=excluded.next_attempt_at,attempts=candidate_history_backfill_months_v1.attempts+1,
      observed_through=excluded.observed_through,observed_sessions=excluded.observed_sessions,
      terminal_reason=excluded.terminal_reason,source_url=excluded.source_url,parser_version=excluded.parser_version;
  RETURN jsonb_build_object('status',v_status,'terminal_reason',v_reason);
END $function$

CREATE OR REPLACE FUNCTION public.complete_legacy_producer_job_authoritative_v3_13(p_run uuid, p_job uuid, p_token uuid, p_result bytea, p_json jsonb, p_hash text)
 RETURNS TABLE(status text, next_job jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_frozen public.legacy_frozen_source_revisions_v3_11%ROWTYPE;v_now timestamptz:=date_trunc('second',clock_timestamp());v_next uuid;v_stage public.opportunity_legacy_producer_stage_v3_11;v_kind public.opportunity_legacy_producer_job_kind_v3_11:='stage_barrier';v_payload bytea;v_payload_json jsonb;v_payload_hash text;v_shard integer;v_revision uuid;v_item jsonb;v_revision_id uuid;v_prior_revision_id uuid;v_revision_created boolean;v_projection jsonb;v_projection_bytes bytea;v_uuid_hash text;v_prior_json jsonb;v_expected_symbols text[];v_actual_symbols text[];v_expected_deep text[];v_actual_deep text[];v_expected_shallow text[];v_actual_shallow text[];v_expected_source text[];v_actual_source text[];
BEGIN
  IF octet_length(p_result)>3145728 OR convert_from(p_result,'utf8')::jsonb<>p_json OR encode(extensions.digest(p_result,'sha256'),'hex')<>p_hash THEN RAISE EXCEPTION 'data_integrity_failure'; END IF;
  SELECT run.* INTO v_run FROM public.legacy_producer_runs_v3_11 run WHERE run.run_id=p_run AND run.status='running'
    AND run.owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND run.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT job.* INTO v_job FROM public.legacy_producer_jobs_v3_11 job WHERE job.run_id=p_run AND job.job_id=p_job AND job.status='leased'
    AND job.owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND job.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_job.predecessor_job_id IS NOT NULL THEN
    SELECT result_json INTO STRICT v_prior_json FROM public.legacy_producer_job_results_v3_11 WHERE job_id=v_job.predecessor_job_id;
  END IF;
  IF (v_job.stage='source_sync' AND p_json->>'schema'<>'legacy-source-sync-result-v3.11')
    OR (v_job.stage='mention_claim_extraction' AND v_job.job_kind='revision_shard' AND p_json->>'schema'<>'legacy-mention-claim-result-v3.11')
    OR (v_job.stage='mention_claim_extraction' AND v_job.job_kind='stage_barrier' AND p_json->>'schema'<>'legacy-mention-barrier-result-v3.11')
    OR (v_job.stage='candidate_funnel' AND p_json->>'schema'<>'legacy-candidate-funnel-result-v3.11')
    OR (v_job.stage='facts_refresh' AND p_json->>'schema'<>'legacy-facts-refresh-result-v3.11')
    OR (v_job.stage='analysis_revision' AND p_json->>'schema'<>'legacy-analysis-revision-result-v3.11')
    OR (v_job.stage='compact_radar_projection' AND p_json->>'schema'<>'legacy-compact-projection-result-v3.11')
  THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  IF v_job.stage='candidate_funnel' THEN
    IF jsonb_array_length(coalesce(p_json->'candidates','[]'::jsonb))>60 THEN RAISE EXCEPTION 'bound_violation';END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_json->'candidates','[]'::jsonb)) item(value) LOOP
      INSERT INTO public.legacy_candidate_discovery_ledger_v3_11(
        discovery_id,source_run_id,source_key,document_revision_id,claim_id,mention_id,stock_id,symbol,
        disposition,reason,research_disposition,research_reason,seed_membership,legacy_seed_set_hash,
        material_evidence_hash,recorded_at
      ) VALUES(extensions.gen_random_uuid(),p_run,(v_item->>'sourceKey')::public.source_key_v3,
        NULLIF(v_item->>'revisionId','')::uuid,NULLIF(v_item->>'claimId','')::uuid,NULLIF(v_item->>'mentionId','')::uuid,(v_item->>'stockId')::uuid,v_item->>'symbol',
        (v_item->>'disposition')::public.opportunity_candidate_discovery_disposition_v3_11,
        (v_item->>'reason')::public.opportunity_candidate_discovery_reason_v3_11,
        (v_item->>'researchDisposition')::public.opportunity_candidate_research_disposition_v3_11,
        NULLIF(v_item->>'researchReason','')::public.opportunity_candidate_research_reason_v3_11,
        (v_item->>'seedMembership')::public.opportunity_candidate_seed_membership_v3_11,
        v_run.legacy_seed_set_hash,v_item->>'materialEvidenceHash',v_now)
      ON CONFLICT(source_run_id,source_key,document_revision_id,claim_id,mention_id,stock_id,reason) DO NOTHING;
    END LOOP;
  ELSIF v_job.stage='facts_refresh' THEN
    IF jsonb_array_length(coalesce(p_json->'decisions','[]'::jsonb))>20
      OR jsonb_array_length(coalesce(p_json->'shallowObservations','[]'::jsonb))>10
      OR jsonb_array_length(coalesce(p_json->'sourceCandidates','[]'::jsonb))>40
    THEN RAISE EXCEPTION 'bound_violation';END IF;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_symbols
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value);
    SELECT array_agg(symbol ORDER BY symbol) INTO v_actual_symbols FROM (
      SELECT value->>'symbol' symbol FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value)
      UNION ALL SELECT value->>'symbol' FROM jsonb_array_elements(coalesce(p_json->'sourceCandidates','[]'::jsonb)) item(value)
    ) actual;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_deep
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_deep FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_shallow
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE (value->>'shallowSelected')::boolean AND NOT (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_shallow FROM jsonb_array_elements(coalesce(p_json->'shallowObservations','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_source
      FROM jsonb_array_elements(coalesce(v_prior_json->'candidates','[]'::jsonb)) item(value) WHERE NOT (value->>'deepSelected')::boolean;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_source FROM jsonb_array_elements(coalesce(p_json->'sourceCandidates','[]'::jsonb)) item(value);
    IF coalesce(v_expected_symbols,ARRAY[]::text[])<>coalesce(v_actual_symbols,ARRAY[]::text[])
      OR cardinality(coalesce(v_actual_symbols,ARRAY[]::text[]))<>cardinality(ARRAY(SELECT DISTINCT unnest(coalesce(v_actual_symbols,ARRAY[]::text[]))))
      OR coalesce(v_expected_deep,ARRAY[]::text[])<>coalesce(v_actual_deep,ARRAY[]::text[])
      OR coalesce(v_expected_shallow,ARRAY[]::text[])<>coalesce(v_actual_shallow,ARRAY[]::text[])
      OR coalesce(v_expected_source,ARRAY[]::text[])<>coalesce(v_actual_source,ARRAY[]::text[])
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
  ELSIF v_job.stage='analysis_revision' THEN
    IF jsonb_array_length(coalesce(p_json->'decisions','[]'::jsonb))>60 THEN RAISE EXCEPTION 'bound_violation';END IF;
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_expected_symbols
      FROM jsonb_array_elements(coalesce(v_prior_json->'decisions','[]'::jsonb)) item(value);
    SELECT array_agg(value->>'symbol' ORDER BY value->>'symbol') INTO v_actual_symbols
      FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value);
    IF coalesce(v_expected_symbols,ARRAY[]::text[])<>coalesce(v_actual_symbols,ARRAY[]::text[])
      OR cardinality(coalesce(v_actual_symbols,ARRAY[]::text[]))<>cardinality(ARRAY(SELECT DISTINCT unnest(coalesce(v_actual_symbols,ARRAY[]::text[]))))
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_json->'decisions','[]'::jsonb)) item(value) LOOP
      v_revision_created:=false;v_prior_revision_id:=NULL;
      SELECT revision_id INTO v_revision_id FROM public.legacy_analysis_revisions_v3_11
      WHERE symbol=v_item->>'symbol' AND material_change_hash=v_item->>'materialChangeHash';
      IF v_revision_id IS NULL THEN
        SELECT revision_id INTO v_prior_revision_id FROM public.legacy_analysis_revisions_v3_11
        WHERE symbol=v_item->>'symbol' AND source_cutoff<v_run.source_cutoff
        ORDER BY source_cutoff DESC,recorded_at DESC,revision_id LIMIT 1;
        v_revision_id:=extensions.gen_random_uuid();
        INSERT INTO public.legacy_analysis_revisions_v3_11 VALUES(
          v_revision_id,v_item->>'symbol',v_run.source_cutoff,v_item->>'materialChangeHash',v_prior_revision_id,
          (v_item->>'researchMaturity')::public.opportunity_research_maturity_v3_11,
          CASE WHEN v_item->'valuation'->>'status'='normal' THEN 'normal' ELSE 'valuation_review' END,
          CASE WHEN v_item->>'action' IN ('avoid','valuation_review','wait_trigger','event_starter','starter_now') THEN v_item->>'action' ELSE 'valuation_review' END,
          encode(extensions.digest(convert_to(coalesce((v_item->'fundamental')::text,'null'),'utf8'),'sha256'),'hex'),
          CASE WHEN v_item->'technical' IS NULL THEN NULL ELSE encode(extensions.digest(convert_to((v_item->'technical')::text,'utf8'),'sha256'),'hex') END,
          CASE WHEN v_item->'valuation' IS NULL THEN NULL ELSE encode(extensions.digest(convert_to((v_item->'valuation')::text,'utf8'),'sha256'),'hex') END,
          jsonb_build_array(v_item->>'claimId'),'legacy-structured-narrative-v3.11',jsonb_build_array(v_item->>'claimId'),
          '來源訊號已重新檢查；估值與技術證據完整前不形成買進建議。',
          encode(extensions.digest(convert_to('來源訊號已重新檢查；估值與技術證據完整前不形成買進建議。','utf8'),'sha256'),'hex'),
          coalesce(NULLIF(v_item->>'analysisGeneratedAt','')::timestamptz,v_run.source_cutoff),v_run.producer_commit_sha,v_now);
        v_revision_created:=true;
      END IF;
      INSERT INTO public.legacy_analysis_evaluations_v3_11 VALUES(
        extensions.gen_random_uuid(),v_item->>'symbol',v_revision_id,v_item->>'materialChangeHash',
        CASE
          WHEN v_revision_created THEN 'material_revision_created'::public.opportunity_analysis_evaluation_disposition_v3_11
          ELSE 'no_material_change'::public.opportunity_analysis_evaluation_disposition_v3_11
        END,
        v_run.source_cutoff,v_run.source_cutoff,NULL,NULL,'scheduled_material_check',p_run,v_now)
      ON CONFLICT(producer_run_id,symbol) DO NOTHING;
    END LOOP;
  ELSIF v_job.stage='compact_radar_projection' THEN
    IF jsonb_array_length(coalesce(p_json->'projections','[]'::jsonb))<>4
      OR (SELECT array_agg(value->>'storageWindow' ORDER BY value->>'storageWindow')
          FROM jsonb_array_elements(p_json->'projections') item(value))
        <>ARRAY['daily','home','three_day','weekly']::text[]
    THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    FOR v_projection IN SELECT value FROM jsonb_array_elements(p_json->'projections') item(value) LOOP
      v_projection_bytes:=convert_to(v_projection#>>'{bundle,canonical}','utf8');
      IF convert_from(v_projection_bytes,'utf8')::jsonb<>v_projection->'payload'
        OR encode(extensions.digest(v_projection_bytes,'sha256'),'hex')<>v_projection->>'payloadChecksum'
      THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      INSERT INTO public.legacy_radar_projections_v3_11(
        projection_key,"window",as_of,producer_commit_sha,worker_sha256,material_change_root,
        payload_canonical,payload_json,payload_sha256
      ) VALUES(v_projection->>'projectionKey',v_projection->>'storageWindow',v_run.source_cutoff,
        v_run.producer_commit_sha,v_run.worker_sha256,
        encode(extensions.digest(convert_to(coalesce((p_json->'projections')::text,'[]'),'utf8'),'sha256'),'hex'),
        v_projection_bytes,v_projection->'payload',v_projection->>'payloadChecksum')
      ON CONFLICT(projection_key) DO NOTHING;
    END LOOP;
  END IF;
  INSERT INTO public.legacy_producer_job_results_v3_11 VALUES(p_job,p_result,p_json,p_hash,v_now) ON CONFLICT(job_id) DO NOTHING;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='succeeded',terminal_at=v_now,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;
  IF v_job.stage_ordinal=5 THEN UPDATE public.legacy_producer_runs_v3_11 SET status='success',terminal_at=v_now,heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=p_run;status:='success';next_job:=NULL;RETURN NEXT;RETURN; END IF;
  IF v_job.stage='source_sync' OR v_job.job_kind='revision_shard' THEN
    SELECT * INTO v_frozen FROM public.legacy_frozen_source_revisions_v3_11 WHERE run_id=p_run AND selection_ordinal>coalesce(v_job.shard_ordinal,-1) ORDER BY selection_ordinal LIMIT 1;
    v_stage:='mention_claim_extraction';
    IF FOUND THEN v_kind:='revision_shard';v_shard:=v_frozen.selection_ordinal;v_revision:=v_frozen.revision_id;
    ELSE v_kind:='stage_barrier';v_shard:=NULL;v_revision:=NULL;END IF;
  ELSE
    v_stage:=(ARRAY['source_sync','mention_claim_extraction','candidate_funnel','facts_refresh','analysis_revision','compact_radar_projection']::public.opportunity_legacy_producer_stage_v3_11[])[v_job.stage_ordinal+2];
  END IF;
  v_uuid_hash:=encode(extensions.digest(convert_to('legacy-job:'||p_run::text||':'||(v_job.execution_ordinal+1)::text,'utf8'),'sha256'),'hex');
  v_next:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  v_payload_json:=jsonb_build_array('e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',p_hash,v_stage::text,v_kind::text,v_shard,v_revision);v_payload:=convert_to(v_payload_json::text,'utf8');v_payload_hash:=encode(extensions.digest(v_payload,'sha256'),'hex');
  INSERT INTO public.legacy_producer_jobs_v3_11 VALUES(v_next,p_run,v_stage,v_kind,CASE WHEN v_stage='mention_claim_extraction' THEN 1 ELSE v_job.stage_ordinal+1 END,v_shard,v_job.execution_ordinal+1,v_revision,p_job,v_payload_hash,v_payload_hash,'queued',0,5,NULL,NULL,NULL,NULL,NULL,NULL,v_now);
  INSERT INTO public.legacy_producer_job_payloads_v3_11 VALUES(v_next,v_payload,v_payload_json,v_payload_hash,v_now);
  status:='running';next_job:=jsonb_build_object('jobId',v_next,'stage',v_stage);RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.complete_legacy_producer_job_v3_11(p_run uuid, p_job uuid, p_token uuid, p_result bytea, p_json jsonb, p_hash text)
 RETURNS TABLE(status text, next_job jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_status text;v_next jsonb;v_stage text;v_initial_count integer;
  v_first_ordinal integer:=NULL;v_first_revision uuid:=NULL;v_row record;v_selected jsonb;
  v_selected_rows jsonb:='[]'::jsonb;v_append jsonb;
BEGIN
  SELECT job.stage::text INTO v_stage
  FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.run_id=p_run AND job.job_id=p_job AND job.status='leased';
  SELECT completed.status,completed.next_job INTO v_status,v_next
  FROM public.complete_legacy_producer_job_authoritative_v3_19(p_run,p_job,p_token,p_result,p_json,p_hash) completed;
  IF v_status IS NULL THEN RETURN;END IF;
  IF v_stage<>'source_sync' OR v_status<>'running' THEN
    status:=v_status;next_job:=v_next;RETURN NEXT;RETURN;
  END IF;

  FOR v_row IN
    SELECT revision.*
    FROM public.legacy_source_document_persistence_v3_13 persisted
    JOIN public.source_document_revisions_v3 revision ON revision.revision_id=persisted.revision_id
    WHERE persisted.source_run_id=p_run AND persisted.disposition='new_revision'
      AND revision.acquisition_status='complete'
    ORDER BY revision.source_key,revision.recorded_at,revision.revision_id
  LOOP
    v_selected:=jsonb_build_array(v_row.source_key,v_row.revision_id,v_row.revision_family_key,
      v_row.approved_source_identity_id,v_row.stable_connector_document_id,
      CASE WHEN v_row.published_at IS NULL THEN NULL ELSE to_char(v_row.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') END,
      to_char(v_row.collected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      v_row.raw_field_payload_algorithm_version,v_row.ingestion_content_revision_sha256,
      v_row.canonical_content_algorithm_version,v_row.ingestion_canonical_content_hash_v3);
    v_selected_rows:=v_selected_rows||jsonb_build_array(v_selected);
  END LOOP;
  v_append:=public.append_legacy_source_shard_v3_19(p_run,p_job,p_hash,v_selected_rows);
  v_initial_count:=(v_append->>'initialCount')::integer;
  v_first_ordinal:=NULLIF(v_append->>'firstOrdinal','')::integer;
  v_first_revision:=NULLIF(v_append->>'firstRevision','')::uuid;

  -- With no cursor-selected document the predecessor created a barrier. Turn
  -- that still-queued successor into the first fresh shard; terminal rows are
  -- never rewritten and the normal shard chain handles remaining revisions.
  IF v_initial_count=0 AND v_first_ordinal IS NOT NULL AND v_next->>'stage'='mention_claim_extraction' THEN
    v_next:=public.schedule_legacy_source_shard_successor_v3_19(
      p_run,p_job,(v_next->>'jobId')::uuid,p_hash,v_first_ordinal,v_first_revision);
  END IF;

  INSERT INTO public.legacy_source_sync_cursors_v3_19(
    source_run_id,source_document_high_water_at,source_document_high_water_revision_id
  )
  SELECT p_run,high_water.recorded_at,high_water.revision_id
  FROM (
    SELECT revision.recorded_at,revision.revision_id
    FROM public.legacy_frozen_source_revisions_v3_11 frozen
    JOIN public.source_document_revisions_v3 revision ON revision.revision_id=frozen.revision_id
    WHERE frozen.run_id=p_run
    ORDER BY revision.recorded_at DESC,revision.revision_id DESC
    LIMIT 1
  ) high_water
  ON CONFLICT(source_run_id) DO NOTHING;
  status:=v_status;next_job:=v_next;RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.complete_taiwan_data_refresh_job_v5(p_job_id uuid, p_owner text, p_result jsonb, p_completed_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_status text; v_attempt jsonb; v_order integer := 0; v_job_attempts integer; v_terminal text;
  v_dataset text; v_symbol text; v_exchange text; v_phase text;
BEGIN
  IF jsonb_typeof(p_result) <> 'object' OR p_result->>'schema' <> 'taiwan-data-provider-result-v1'
    OR p_result->>'terminal' NOT IN ('complete','empty','timeout','usage_limited','auth_failed','http_error','network_error','schema_invalid','not_configured')
    OR jsonb_typeof(p_result->'attempts') <> 'array' OR jsonb_array_length(p_result->'attempts') NOT BETWEEN 1 AND 2 THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid_taiwan_data_terminal_result';
  END IF;
  SELECT status,attempts,dataset,symbol,exchange,refresh_phase
    INTO v_status,v_job_attempts,v_dataset,v_symbol,v_exchange,v_phase
    FROM public.taiwan_data_refresh_queue_v5
    WHERE job_id=p_job_id AND status='running' AND lease_owner=p_owner AND lease_expires_at >= p_completed_at FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'taiwan_data_job_lease_lost'; END IF;
  IF p_result->>'dataset' IS DISTINCT FROM v_dataset
    OR p_result->>'symbol' IS DISTINCT FROM v_symbol
    OR p_result->>'exchange' IS DISTINCT FROM v_exchange
    OR p_result->>'phase' IS DISTINCT FROM v_phase THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'taiwan_data_result_identity_mismatch';
  END IF;
  IF p_result->>'terminal'='complete' AND (
    COALESCE((p_result->>'actionEligible')::boolean,false) IS NOT TRUE
    OR NOT EXISTS(SELECT 1 FROM public.taiwan_data_canonical_results_v5 c WHERE c.job_id=p_job_id)
  ) THEN RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='taiwan_data_canonical_persistence_required'; END IF;
  SELECT COALESCE(max(attempt_order),0) INTO v_order FROM public.taiwan_data_provider_attempts_v5 WHERE job_id=p_job_id;
  FOR v_attempt IN SELECT value FROM jsonb_array_elements(p_result->'attempts') LOOP
    v_order := v_order + 1;
    IF v_attempt->>'provider' NOT IN ('twse','tpex','finmind')
      OR v_attempt->>'authorityTier' NOT IN ('official_primary','finmind_fallback')
      OR v_attempt->>'terminal' NOT IN ('complete','empty','timeout','usage_limited','auth_failed','http_error','network_error','schema_invalid','not_configured')
      OR (v_attempt->>'provider'='finmind') <> (v_attempt->>'authorityTier'='finmind_fallback')
      OR COALESCE((v_attempt->>'responseBytes')::integer, -1) NOT BETWEEN 0 AND 5000001
      OR (v_attempt->>'responseSha256' IS NOT NULL AND v_attempt->>'responseSha256' !~ '^[0-9a-f]{64}$')
      OR (v_attempt->>'httpStatus' IS NOT NULL AND COALESCE((v_attempt->>'httpStatus')::integer,0) NOT BETWEEN 100 AND 599)
    THEN RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid_taiwan_data_attempt'; END IF;
    INSERT INTO public.taiwan_data_provider_attempts_v5(
      job_id,attempt_order,provider,authority_tier,terminal_status,source_url,fetched_at,http_status,response_sha256,response_bytes,api_usage,normalized_payload,detail
    ) VALUES (
      p_job_id,v_order,v_attempt->>'provider',v_attempt->>'authorityTier',v_attempt->>'terminal',
      COALESCE(v_attempt->>'sourceUrl',''),(v_attempt->>'fetchedAt')::timestamptz,
      NULLIF(v_attempt->>'httpStatus','')::integer,v_attempt->>'responseSha256',(v_attempt->>'responseBytes')::integer,
      NULLIF(v_attempt->'apiUsage','null'::jsonb),
      NULLIF(v_attempt->'normalizedPayload','null'::jsonb),
      v_attempt->>'detail'
    );
  END LOOP;
  v_terminal:=p_result->>'terminal';
  IF v_terminal IN ('timeout','usage_limited','http_error','network_error') AND v_job_attempts < 3 THEN
    UPDATE public.taiwan_data_refresh_queue_v5 SET status='queued',terminal_status=NULL,terminal_result=NULL,
      completed_at=NULL,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=p_completed_at + interval '15 minutes',updated_at=p_completed_at
    WHERE job_id=p_job_id;
    RETURN 'retry_scheduled';
  END IF;
  UPDATE public.taiwan_data_refresh_queue_v5 SET status='terminal',terminal_status=v_terminal,terminal_result=p_result,
    completed_at=p_completed_at,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=NULL,updated_at=p_completed_at WHERE job_id=p_job_id;
  RETURN 'terminal';
END $function$

CREATE OR REPLACE FUNCTION public.consume_internal_nonce_v3(principal_id uuid, required_role internal_principal_role_v3, nonce text, request_timestamp timestamp with time zone)
 RETURNS TABLE(recorded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz := clock_timestamp(); v_recorded timestamptz;
BEGIN
  IF $3 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now - $4))) > 300 THEN
    RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='authentication_rejected';
  END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($1,$2,v_now) THEN
    RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='principal_role_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at)
  VALUES($1,$3,$4,v_now) RETURNING internal_principal_nonces_v3.recorded_at INTO v_recorded;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'consume_internal_nonce_v3',$1,'nonce',NULL,
    encode(extensions.digest(convert_to(jsonb_build_array($1,$2,$4)::text,'utf8'),'sha256'),'hex'),
    'consumed',v_now
  );
  RETURN QUERY SELECT v_recorded;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='authentication_rejected';
END
$function$

CREATE OR REPLACE FUNCTION public.create_opportunity_manifest_v3(job_id uuid, owner_token text, requested_manifest_id uuid, manifest_kind opportunity_manifest_kind_v3, contract_version text, source_cutoff timestamp with time zone, header_canonical bytea, header_json jsonb)
 RETURNS TABLE(status opportunity_manifest_status_v3, manifest_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_now timestamptz:=clock_timestamp(); v_hash text; v_logical text;
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased' AND j.stage IN ('authority_manifest','input_manifest_pages')
    AND j.lease_expires_at>=v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  IF octet_length($7)>3145728 THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  v_hash:=encode(extensions.digest($7,'sha256'),'hex');
  v_logical:=encode(extensions.digest(convert_to(jsonb_build_array(
    'opportunity-manifest-logical-v3.8',v_job.run_id,$3,$4,$5,$6,v_hash
  )::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.opportunity_manifests_v3(
    manifest_id,manifest_kind,contract_version,source_cutoff,header_canonical,header_json,
    status,created_at,recorded_at
  ) VALUES($3,$4,$5,$6,$7,$8,'building',v_now,v_now)
  ON CONFLICT ON CONSTRAINT opportunity_manifests_v3_pkey DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_manifests_v3 m
    WHERE m.manifest_id=$3 AND m.manifest_kind=$4 AND m.contract_version=$5
      AND m.source_cutoff IS NOT DISTINCT FROM $6 AND m.header_canonical=$7
      AND m.header_json=$8 AND m.status='building'
  ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_run_jobs_v3 SET output_manifest_id=$3
  WHERE opportunity_run_jobs_v3.job_id=$1;
  UPDATE public.opportunity_run_jobs_v3 SET status='succeeded',output_kind='manifest_header',
    output_hash=v_hash,terminal_at=v_now,owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  PERFORM public.enqueue_next_opportunity_job_v3_internal(v_job.run_id,$1);
  RETURN QUERY SELECT 'building'::public.opportunity_manifest_status_v3,$3;
END
$function$

CREATE OR REPLACE FUNCTION public.derive_manifest_page_descriptor_v3_internal(requested_manifest_id uuid, requested_section_key opportunity_manifest_section_key_v3, requested_page_ordinal integer, requested_first_row_ordinal bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_bytes bytea; v_hex text; v_page_id uuid; v_name text;
BEGIN
  IF requested_page_ordinal<0 OR requested_first_row_ordinal<0 OR NOT EXISTS (
    SELECT 1 FROM public.opportunity_manifests_v3
    WHERE manifest_id=requested_manifest_id AND status='building'
  ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  v_name := format('["%s","%s",%s]',requested_manifest_id,requested_section_key,requested_page_ordinal);
  v_bytes := substring(extensions.digest(
    decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
      || convert_to(v_name,'utf8'),'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_hex := encode(v_bytes,'hex');
  v_page_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
    ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
  RETURN jsonb_build_array(v_page_id,requested_manifest_id,requested_section_key,requested_page_ordinal,requested_first_row_ordinal);
END
$function$

CREATE OR REPLACE FUNCTION public.enforce_candidate_shadow_identity_immutable_v4()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.cohort_key IS DISTINCT FROM OLD.cohort_key
    OR NEW.canonical_input_hashes IS DISTINCT FROM OLD.canonical_input_hashes THEN
    RAISE EXCEPTION 'candidate_shadow_input_identity_immutable_v4' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_opportunity_detail_evidence_v3()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_item jsonb;
  v_count integer;
  v_stock_id uuid;
  v_expected_evidence_count integer;
  v_horizon text;
  v_horizon_ordinal integer := 0;
  v_card_matches integer;
  v_source_run_id uuid;
BEGIN
  SELECT r.upstream_run_id INTO STRICT v_source_run_id
  FROM public.opportunity_runs r WHERE r.run_id=NEW.run_id;
  SELECT c.stock_id INTO STRICT v_stock_id
  FROM public.opportunity_candidate_snapshots c
  WHERE c.run_id=NEW.run_id AND c.symbol=NEW.symbol
    AND c.candidate_origin='direct_candidate' AND c.deep_status='succeeded';
  IF NEW.payload_json->>'runId'<>NEW.run_id::text
    OR NEW.payload_json->>'symbol'<>NEW.symbol
    OR (NEW.payload_json->>'sourceCutoff')::timestamptz<>(
      SELECT r.source_cutoff FROM public.opportunity_runs r WHERE r.run_id=NEW.run_id
    )
    OR jsonb_typeof(NEW.payload_json->'sourceEvidence')<>'array'
    OR jsonb_typeof(NEW.payload_json->'horizonDetails')<>'array'
    OR jsonb_array_length(NEW.payload_json->'horizonDetails')<>3
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  v_count:=jsonb_array_length(NEW.payload_json->'sourceEvidence');
  IF v_count NOT BETWEEN 1 AND 12 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  IF (
    SELECT count(DISTINCT value->>'ref') FROM jsonb_array_elements(NEW.payload_json->'sourceEvidence')
  ) <> v_count THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  SELECT LEAST(12,count(DISTINCT c.source_ref))::integer INTO v_expected_evidence_count
  FROM public.opportunity_source_claims c
  JOIN public.opportunity_source_mentions m
    ON m.run_id=c.run_id AND m.revision_id=c.revision_id AND m.claim_ordinal=c.claim_ordinal
  WHERE c.run_id=v_source_run_id AND m.stock_id=v_stock_id AND m.symbol=NEW.symbol
    AND m.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim');
  IF v_count<>v_expected_evidence_count THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(NEW.payload_json->'sourceEvidence') LOOP
    IF 1 <> (
      SELECT count(*)
      FROM public.opportunity_source_claims c
      JOIN public.source_document_revisions_v3 r ON r.revision_id=c.revision_id
      JOIN public.opportunity_run_manifest_inputs source_identity_binding
        ON source_identity_binding.run_id=NEW.run_id
        AND source_identity_binding.input_role='source_identity_allowlist'
        AND source_identity_binding.ordinal=0
      JOIN public.opportunity_manifest_rows_v3 source_identity_row
        ON source_identity_row.manifest_id=source_identity_binding.manifest_id
        AND source_identity_row.section_key='rows'
        AND (source_identity_row.payload_json->>0)::uuid=r.source_identity_authority_id
        AND (source_identity_row.payload_json->>1)::uuid=r.approved_source_identity_id
        AND source_identity_row.payload_json->>2=r.source_key::text
      JOIN public.opportunity_source_mentions m
        ON m.run_id=c.run_id AND m.revision_id=c.revision_id AND m.claim_ordinal=c.claim_ordinal
      WHERE c.run_id=v_source_run_id
        AND m.stock_id=v_stock_id
        AND m.symbol=NEW.symbol
        AND m.outcome IN ('linked_new','linked_refresh','linked_duplicate_claim')
        AND c.source_ref=v_item->>'ref'
        AND r.source_key::text=v_item->>'sourceKey'
        AND source_identity_row.payload_json->>3=v_item->>'sourceClass'
        AND c.effective_at=(v_item->>'effectiveAt')::timestamptz
        AND m.reason::text=v_item->>'linkReason'
        AND c.verification_tier::text=v_item->>'verificationTier'
        AND c.claim_evidence_stance::text=v_item->>'stance'
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  END LOOP;
  FOR v_item IN SELECT value FROM jsonb_array_elements(NEW.payload_json->'horizonDetails') LOOP
    v_horizon := (ARRAY['momentum_5_20d','swing_20_60d','thesis_120_250d'])[v_horizon_ordinal+1];
    IF v_item->>'horizon'<>v_horizon
      OR jsonb_typeof(v_item->'factors')<>'array'
      OR jsonb_array_length(v_item->'factors')<>6
      OR (SELECT array_agg(value->>'key' ORDER BY ordinal)
          FROM jsonb_array_elements(v_item->'factors') WITH ORDINALITY AS f(value,ordinal))
        <> ARRAY['priceVolume','chip','catalyst','marketSector','fundamental','valuation']
      OR 1 <> (
        SELECT count(*) FROM public.opportunity_score_snapshots s
        WHERE s.run_id=NEW.run_id AND s.stock_id=v_stock_id AND s.symbol=NEW.symbol
          AND s.horizon::text=v_horizon
          AND s.rank=(v_item->>'rank')::integer
          AND s.score=(v_item->>'score')::double precision
          AND s.score_confidence=(v_item->>'scoreConfidence')::double precision
          AND s.available_weight=(v_item->>'availableWeight')::double precision
      )
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
    v_horizon_ordinal := v_horizon_ordinal+1;
  END LOOP;
  SELECT count(*) INTO v_card_matches
  FROM public.opportunity_public_projections_v3 p
  CROSS JOIN LATERAL jsonb_array_elements(
    COALESCE(p.payload_json->'actionableNow','[]'::jsonb)
      || COALESCE(p.payload_json->'waitingForTrigger','[]'::jsonb)
      || COALESCE(p.payload_json->'valuationReview','[]'::jsonb)
  ) AS cards(card)
  WHERE p.run_id=NEW.run_id AND cards.card->>'symbol'=NEW.symbol
    AND cards.card=NEW.payload_json->'card';
  IF v_card_matches<>1 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure';
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR datetime_field_overflow THEN
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
END
$function$

CREATE OR REPLACE FUNCTION public.enforce_production_writer_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE required_release text; supplied_release text; headers jsonb;
BEGIN
  SELECT release_id INTO required_release FROM public.production_writer_releases
    WHERE active ORDER BY activated_at DESC LIMIT 1;
  IF required_release IS NULL THEN RETURN NEW; END IF;
  BEGIN headers:=COALESCE(NULLIF(current_setting('request.headers',true),''),'{}')::jsonb;
  EXCEPTION WHEN OTHERS THEN headers:='{}'::jsonb; END;
  supplied_release:=headers->>'x-stockinsider-writer-release';
  IF supplied_release IS DISTINCT FROM required_release THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='production_writer_release_rejected';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.production_write_leases WHERE lease_key='production-data-plane'
      AND expires_at>clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='production_writer_lease_required';
  END IF;
  PERFORM public.assert_stockinsider_backend_request_v1(true);
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.enqueue_next_opportunity_job_v3_internal(requested_run_id uuid, predecessor_job_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_run public.opportunity_runs%ROWTYPE;
  v_predecessor public.opportunity_run_jobs_v3%ROWTYPE;
  v_predecessor_payload public.opportunity_job_payloads_v3%ROWTYPE;
  v_kind public.opportunity_manifest_kind_v3;
  v_next_kind public.opportunity_manifest_kind_v3;
  v_contract text;
  v_ordinal integer := 0;
  v_next_ordinal integer := 0;
  v_source_ordinal integer;
  v_source_key public.source_key_v3;
  v_dataset_manifest_id uuid;
  v_revision_row jsonb;
  v_revision_id uuid;
  v_revision_selection_ordinal integer;
  v_revision_raw_code_point_count integer;
  v_audited_session date;
  v_audited_session_hash text;
  v_previous_session date;
  v_previous_session_hash text;
  v_recent_session_plan_hash text;
  v_stage public.opportunity_job_stage_v3;
  v_section public.opportunity_manifest_section_key_v3;
  v_next_section public.opportunity_manifest_section_key_v3;
  v_section_count bigint;
  v_payload_kind public.opportunity_job_payload_kind_v3;
  v_shard text;
  v_manifest_id uuid;
  v_body jsonb;
  v_payload jsonb;
  v_payload_text text;
  v_payload_hash text;
  v_input_hash text;
  v_input_text text;
  v_selected_count bigint;
  v_registered_count bigint;
  v_canonical_sector public.canonical_sector_key_v3;
  v_entry_session date;
  v_entry_session_hash text;
  v_benchmark_input_run_id uuid;
  v_roster_manifest_hash text;
  v_taxonomy_manifest_hash text;
  v_bytes bytea;
  v_hex text;
  v_job_id uuid;
  v_predecessor_hashes jsonb := '[]'::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(requested_run_id::text,0));
  SELECT * INTO STRICT v_run FROM public.opportunity_runs WHERE run_id=requested_run_id FOR UPDATE;
  IF predecessor_job_id IS NULL THEN
    IF v_run.status<>'preparing' OR EXISTS (
      SELECT 1 FROM public.opportunity_run_jobs_v3 WHERE run_id=requested_run_id
    ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
    SELECT kind,contract_version INTO v_kind,v_contract FROM (VALUES
      ('source_scan'::public.opportunity_mode_v3,'source_identity_allowlist'::public.opportunity_manifest_kind_v3,'source-identity-allowlist-v3.1'),
      ('enrich_rank'::public.opportunity_mode_v3,'peer_reviewer_allowlist'::public.opportunity_manifest_kind_v3,'peer-reviewer-allowlist-v3.0'),
      ('label_outcomes'::public.opportunity_mode_v3,'outcome_input'::public.opportunity_manifest_kind_v3,'source-led-eval-v3.7'),
      ('shadow_evaluate'::public.opportunity_mode_v3,'evaluation_input'::public.opportunity_manifest_kind_v3,'source-led-eval-v3.7')
    ) AS initial(mode,kind,contract_version) WHERE mode=v_run.mode;
    IF v_run.mode='label_outcomes' AND EXISTS (
      SELECT 1
      FROM public.opportunity_run_inputs binding
      JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
      JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
      JOIN LATERAL (
        SELECT assignment.canonical_sector_key
        FROM public.stock_sector_assignments_v3 assignment
        WHERE assignment.stock_id=score.stock_id
          AND assignment.recorded_at<=v_run.source_cutoff
          AND assignment.source_timestamp<=v_run.source_cutoff
          AND assignment.valid_from<=v_run.source_cutoff
          AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
          AND assignment.status='active'
        ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
        LIMIT 1
      ) sector ON sector.canonical_sector_key<>'unknown'
      JOIN LATERAL (
        SELECT session.session_id
        FROM public.opportunity_effective_taiwan_sessions_v3 session
        WHERE session.session_id>input.trading_date
          AND session.canonical_cutoff<=v_run.source_cutoff
        ORDER BY session.session_id LIMIT 1
      ) entry_session ON true
      WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
    ) THEN
      v_kind:='sector_benchmark';
      v_contract:='sector-benchmark-v3.1';
    END IF;
    IF v_kind='source_identity_allowlist' THEN
      SELECT count(*) INTO v_registered_count FROM (
        SELECT stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3
        WHERE family='discovery_identity'
        ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
      ) bounded_registry;
      IF v_registered_count>10000 OR EXISTS (
        SELECT 1
        FROM public.opportunity_authority_stream_registry_v3 registry
        CROSS JOIN LATERAL (
          SELECT count(*) AS retained_count FROM (
            SELECT authority_id
            FROM public.source_identity_authorities_v3 authority
            WHERE authority.source_identity_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            ORDER BY authority.recorded_at DESC,authority.authority_id LIMIT 65
          ) bounded
        ) stream
        WHERE registry.family='discovery_identity' AND stream.retained_count>64
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
      v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
        'discovery_identity',v_run.source_cutoff
      );
      IF v_selected_count>10000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
    ELSIF v_kind='peer_reviewer_allowlist' THEN
      SELECT count(*) INTO v_registered_count FROM (
        SELECT stream_key_hash
        FROM public.opportunity_authority_stream_registry_v3
        WHERE family='peer_reviewer'
        ORDER BY stream_key_hash,stream_key_canonical LIMIT 1001
      ) bounded_registry;
      IF v_registered_count>1000 OR EXISTS (
        SELECT 1
        FROM public.opportunity_authority_stream_registry_v3 registry
        CROSS JOIN LATERAL (
          SELECT count(*) AS retained_count FROM (
            SELECT reviewer_authority_id
            FROM public.stock_peer_relationship_reviewers_v3 authority
            WHERE authority.reviewer_principal_id=(
              convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
            )::uuid
            ORDER BY authority.recorded_at DESC,authority.reviewer_authority_id LIMIT 65
          ) bounded
        ) stream
        WHERE registry.family='peer_reviewer' AND stream.retained_count>64
      ) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
      v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
        'peer_reviewer',v_run.source_cutoff
      );
      IF v_selected_count>1000 THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
      END IF;
    END IF;
    v_stage := CASE WHEN v_kind IN (
      'source_identity_allowlist','publisher_verification_allowlist','instrument_roster','alias_authority',
      'taxonomy_assignment','peer_reviewer_allowlist','peer_authority'
    ) THEN 'authority_manifest' ELSE 'input_manifest_pages' END;
    v_payload_kind := 'manifest_header';
    v_shard := v_kind::text||':0:header';
    v_input_text := format('["%s","%s",0,"%s"]',requested_run_id,v_kind,v_contract);
    v_bytes := substring(extensions.digest(
      decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
        || convert_to(v_input_text,'utf8'),'sha1') FROM 1 FOR 16);
    v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
    v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
    v_hex := encode(v_bytes,'hex');
    v_manifest_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
      ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
    v_body := jsonb_build_array(
      0,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
      CASE
        WHEN v_kind='source_identity_allowlist' THEN jsonb_build_array(
          jsonb_build_array('rowCount',
            public.opportunity_authority_selected_stream_count_v3_internal(
              'discovery_identity',v_run.source_cutoff
            )),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff)
        )
        WHEN v_kind='peer_reviewer_allowlist' THEN jsonb_build_array(
          jsonb_build_array('rowCount',
            public.opportunity_authority_selected_stream_count_v3_internal(
              'peer_reviewer',v_run.source_cutoff
            )),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff)
        )
        WHEN v_kind='sector_benchmark' THEN (
          WITH benchmark_pairs AS (
            SELECT sector.canonical_sector_key,entry.session_id,
              min(input.run_id::text)::uuid AS input_run_id,
              min(entry.taiwan_session_authority_hash) AS entry_session_authority_hash
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            JOIN LATERAL (
              SELECT assignment.canonical_sector_key
              FROM public.stock_sector_assignments_v3 assignment
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
              ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
              LIMIT 1
            ) sector ON sector.canonical_sector_key<>'unknown'
            JOIN LATERAL (
              SELECT session.session_id,session.taiwan_session_authority_hash
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
            GROUP BY sector.canonical_sector_key,entry.session_id
            ORDER BY sector.canonical_sector_key,entry.session_id
            OFFSET 0 LIMIT 1
          )
          SELECT jsonb_build_array(
            jsonb_build_array('canonicalSector',pair.canonical_sector_key),
            jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
            jsonb_build_array('entrySession',pair.session_id),
            jsonb_build_array('entrySessionAuthorityHash',pair.entry_session_authority_hash),
            jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
            jsonb_build_array('rosterManifestHash',(
              SELECT manifest.manifest_hash
              FROM public.opportunity_run_manifest_inputs manifest_binding
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=manifest_binding.manifest_id
              WHERE manifest_binding.run_id=pair.input_run_id
                AND manifest_binding.input_role='instrument_roster'
                AND manifest_binding.ordinal=0 AND manifest.status='complete'
            )),
            jsonb_build_array('sourceCutoff',v_run.source_cutoff),
            jsonb_build_array('taxonomyAssignmentManifestHash',(
              SELECT manifest.manifest_hash
              FROM public.opportunity_run_manifest_inputs manifest_binding
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=manifest_binding.manifest_id
              WHERE manifest_binding.run_id=pair.input_run_id
                AND manifest_binding.input_role='taxonomy_assignment'
                AND manifest_binding.ordinal=0 AND manifest.status='complete'
            )),
            jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
              convert_to(regexp_replace(jsonb_build_array(
                'sector-benchmark-calendar-window-v3.4',
                coalesce((SELECT jsonb_agg(jsonb_build_array(
                  session.session_id,session.taiwan_session_authority_hash
                ) ORDER BY session.session_id)
                FROM (
                  SELECT session_id,taiwan_session_authority_hash
                  FROM public.opportunity_effective_taiwan_sessions_v3
                  WHERE session_id>=pair.session_id
                    AND canonical_cutoff<=v_run.source_cutoff
                  ORDER BY session_id LIMIT 250
                ) session),'[]'::jsonb)
              )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
          )
          FROM benchmark_pairs pair
        )
        WHEN v_kind='outcome_input' THEN jsonb_build_array(
          jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
          jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
          jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
          jsonb_build_array('runPurpose',v_run.run_purpose),
          jsonb_build_array('sourceCutoff',v_run.source_cutoff),
          jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
            convert_to(regexp_replace(jsonb_build_array(
              'outcome-calendar-window-v3.4',
              coalesce((SELECT jsonb_agg(jsonb_build_array(
                session_id,taiwan_session_authority_hash
              ) ORDER BY session_id)
              FROM (
                SELECT session_id,taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff
                ORDER BY session_id DESC LIMIT 252
              ) sessions),'[]'::jsonb)
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
        )
        WHEN v_kind='evaluation_input' THEN jsonb_build_array(
          jsonb_build_array('backtestCount',(
            SELECT count(*) FROM (
              SELECT input.trading_date
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              WHERE binding.run_id=v_run.run_id AND binding.input_role='evaluation_enrich'
                AND input.run_purpose='backtest_daily_primary'
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_run_inputs outcome_binding
                  JOIN public.opportunity_run_inputs outcome_source
                    ON outcome_source.run_id=outcome_binding.input_run_id
                    AND outcome_source.input_run_id=input.run_id
                    AND outcome_source.input_role='outcome_enrich'
                  WHERE outcome_binding.run_id=v_run.run_id
                    AND outcome_binding.input_role='evaluation_outcome'
                )
                AND (
                  SELECT count(*)
                  FROM public.opportunity_score_snapshots score
                  JOIN public.opportunity_outcomes outcome
                    ON outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon='session_20'
                  WHERE score.run_id=input.run_id
                )>=10
              ORDER BY input.trading_date DESC,input.run_id
              LIMIT 120
            ) qualifying_backtest
          )),
          jsonb_build_array('comparisonContractKey',v_run.comparison_contract_key),
          jsonb_build_array('evaluationCutoff',v_run.source_cutoff),
          jsonb_build_array('evaluationDatasetLockHash',v_run.evaluation_dataset_lock_hash),
          jsonb_build_array('liveCount',(
            SELECT count(*) FROM (
              SELECT input.trading_date
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              WHERE binding.run_id=v_run.run_id AND binding.input_role='evaluation_enrich'
                AND input.run_purpose='production_shadow_daily'
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_run_inputs outcome_binding
                  JOIN public.opportunity_run_inputs outcome_source
                    ON outcome_source.run_id=outcome_binding.input_run_id
                    AND outcome_source.input_run_id=input.run_id
                    AND outcome_source.input_role='outcome_enrich'
                  WHERE outcome_binding.run_id=v_run.run_id
                    AND outcome_binding.input_role='evaluation_outcome'
                )
                AND (
                  SELECT count(*)
                  FROM public.opportunity_score_snapshots score
                  JOIN public.opportunity_outcomes outcome
                    ON outcome.score_snapshot_id=score.score_snapshot_id
                    AND outcome.maturity_horizon='session_20'
                  WHERE score.run_id=input.run_id
                )>=10
              ORDER BY (
                SELECT max(outcome.maturity_session)
                FROM public.opportunity_score_snapshots score
                JOIN public.opportunity_outcomes outcome
                  ON outcome.score_snapshot_id=score.score_snapshot_id
                  AND outcome.maturity_horizon='session_20'
                WHERE score.run_id=input.run_id
              ) DESC,input.trading_date DESC,input.run_id
              LIMIT 20
            ) qualifying_live
          )),
          jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
          jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
            convert_to(regexp_replace(jsonb_build_array(
              'evaluation-calendar-window-v3.4',
              coalesce((SELECT jsonb_agg(jsonb_build_array(
                session_id,taiwan_session_authority_hash
              ) ORDER BY session_id)
              FROM (
                SELECT session_id,taiwan_session_authority_hash
                FROM public.opportunity_effective_taiwan_sessions_v3
                WHERE canonical_cutoff<=v_run.source_cutoff
                ORDER BY session_id DESC LIMIT 252
              ) sessions),'[]'::jsonb)
            )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
        )
        ELSE NULL
      END
    );
    IF v_body->5 IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
  ELSE
    SELECT * INTO v_predecessor FROM public.opportunity_run_jobs_v3
    WHERE job_id=predecessor_job_id AND run_id=requested_run_id AND status='succeeded'
    FOR SHARE;
    SELECT * INTO v_predecessor_payload FROM public.opportunity_job_payloads_v3
    WHERE job_id=predecessor_job_id AND run_id=requested_run_id;
    IF v_predecessor.job_id IS NULL OR v_predecessor_payload.job_id IS NULL
      OR v_predecessor.output_hash IS NULL OR v_run.status IN ('failed','converged','success') THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    v_predecessor_hashes := jsonb_build_array(v_predecessor.output_hash);
    IF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_header' THEN
      v_body := v_predecessor_payload.payload_json->5;
      v_ordinal := (v_body->>0)::integer;
      v_kind := (v_body->>2)::public.opportunity_manifest_kind_v3;
      v_contract := v_body->>3;
      v_manifest_id := (v_body->>1)::uuid;
      v_stage := v_predecessor.stage;
      IF v_kind='source_dataset' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':connector_roots:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'connector_roots',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='peer_authority' THEN
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'selected_rows',0,1
          )
        ) THEN v_next_section:='selected_rows';
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
          )
        ) THEN v_next_section:='excluded_rows';
        ELSE v_next_section:=NULL;
        END IF;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind='candidate_financial' THEN
        IF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'selected_facts',0,1
          )
        ) THEN
          v_next_section:='selected_facts';
        ELSIF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_facts',0,1
          )
        ) THEN
          v_next_section:='excluded_facts';
        ELSE
          v_next_section:='conservation';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN ('bias_reference','technical_history_reference','reported_pe_reference') THEN
        SELECT candidate.section_key INTO v_next_section
        FROM (VALUES
          ('bias_reference'::public.opportunity_manifest_kind_v3,1,'current_rows'::public.opportunity_manifest_section_key_v3),
          ('bias_reference',2,'excluded_rows'),('bias_reference',3,'sector_rows'),
          ('bias_reference',4,'conservation'),
          ('technical_history_reference',1,'market_benchmark_rows'),
          ('technical_history_reference',2,'raw_adjusted_rows'),
          ('technical_history_reference',3,'history_rows'),
          ('technical_history_reference',4,'excluded_rows'),
          ('technical_history_reference',5,'conservation'),
          ('reported_pe_reference',1,'own_history_rows'),
          ('reported_pe_reference',2,'sector_current_rows'),
          ('reported_pe_reference',3,'excluded_rows'),
          ('reported_pe_reference',4,'sector_rows'),
          ('reported_pe_reference',5,'conservation')
        ) candidate(kind,section_ordinal,section_key)
        WHERE candidate.kind=v_kind AND EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
          )
        )
        ORDER BY candidate.section_ordinal LIMIT 1;
        IF v_next_section IS NULL THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN (
        'factor_scoring_reference','sector_valuation_reference','mover_price_reference',
        'market_reference'
      ) THEN
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'included_rows',0,1
          )
        ) THEN v_next_section:='included_rows';
        ELSIF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
          )
        ) THEN v_next_section:='excluded_rows';
        ELSE v_next_section:='conservation';
        END IF;
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          v_next_section,0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_scoring_reference' THEN
        SELECT candidate.section_key INTO v_next_section
        FROM (VALUES
          (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
          (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
          (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
          (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
          (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
          (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
          (7,'conservation'::public.opportunity_manifest_section_key_v3)
        ) candidate(section_ordinal,section_key)
        WHERE EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
          )
        )
        ORDER BY candidate.section_ordinal LIMIT 1;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind IN ('link_audit_sample','link_audit_resolution') THEN
        IF v_kind='link_audit_sample' THEN
          IF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'strata',0,1
            )
          ) THEN v_next_section:='strata';
          ELSIF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'samples',0,1
            )
          ) THEN v_next_section:='samples';
          ELSE v_next_section:=NULL;
          END IF;
        ELSE
          IF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'resolved_rows',0,1
            )
          ) THEN v_next_section:='resolved_rows';
          ELSIF EXISTS (
            SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
              requested_run_id,v_manifest_id,v_kind,'unresolved_rows',0,1
            )
          ) THEN v_next_section:='unresolved_rows';
          ELSE v_next_section:=NULL;
          END IF;
        END IF;
        IF v_next_section IS NULL THEN
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        ELSE
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            v_next_section,0,0,NULL,NULL,NULL
          );
        END IF;
      ELSIF v_kind='evaluation_input' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':attempt_roster:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'attempt_roster',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_benchmark' AND EXISTS (
        SELECT 1
        FROM public.stock_sector_assignments_v3 assignment
        JOIN public.stock_instruments_v3 instrument ON instrument.stock_id=assignment.stock_id
        JOIN public.opportunity_price_observations_v3 observation
          ON observation.stock_id=assignment.stock_id
        WHERE assignment.canonical_sector_key=(
            SELECT (pair->>1)::public.canonical_sector_key_v3
            FROM jsonb_array_elements(v_body->5) pair
            WHERE pair->>0='canonicalSector'
          )
          AND assignment.recorded_at<=v_run.source_cutoff
          AND assignment.source_timestamp<=v_run.source_cutoff
          AND assignment.valid_from<=v_run.source_cutoff
          AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
          AND assignment.status='active'
          AND instrument.recorded_at<=v_run.source_cutoff
          AND instrument.source_timestamp<=v_run.source_cutoff
          AND instrument.valid_from<=v_run.source_cutoff
          AND (instrument.valid_to IS NULL OR v_run.source_cutoff<instrument.valid_to)
          AND instrument.instrument_type='common_stock'
          AND instrument.listing_status='active'
          AND observation.session_id=(
            SELECT (pair->>1)::date
            FROM jsonb_array_elements(v_body->5) pair
            WHERE pair->>0='entrySession'
          )
          AND observation.source_timestamp<=v_run.source_cutoff
          AND observation.collected_at<=v_run.source_cutoff
          AND observation.recorded_at<=v_run.source_cutoff
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':entry_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'entry_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='sector_benchmark' THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':session_conservation:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'session_conservation',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='outcome_input' AND EXISTS (
        SELECT 1
        FROM public.opportunity_run_inputs binding
        JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
        JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
        CROSS JOIN (VALUES (20),(60),(120),(250)) maturity(session_count)
        JOIN LATERAL (
          SELECT session.session_id
          FROM public.opportunity_effective_taiwan_sessions_v3 session
          WHERE session.session_id>input.trading_date
            AND session.canonical_cutoff<=v_run.source_cutoff
          ORDER BY session.session_id
          LIMIT 1
        ) entry_session ON true
        JOIN LATERAL (
          SELECT session.session_id
          FROM public.opportunity_effective_taiwan_sessions_v3 session
          WHERE session.session_id>=entry_session.session_id
            AND session.canonical_cutoff<=v_run.source_cutoff
          ORDER BY session.session_id
          OFFSET maturity.session_count-1
          LIMIT 1
        ) maturity_session ON true
        JOIN LATERAL (
          SELECT observation.source_ref
          FROM public.opportunity_price_observations_v3 observation
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=entry_session.session_id
            AND observation.source_timestamp<=v_run.source_cutoff
            AND observation.collected_at<=v_run.source_cutoff
            AND observation.recorded_at<=v_run.source_cutoff
          ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) entry_price ON true
        JOIN LATERAL (
          SELECT observation.source_ref
          FROM public.opportunity_price_observations_v3 observation
          WHERE observation.stock_id=score.stock_id
            AND observation.session_id=maturity_session.session_id
            AND observation.source_timestamp<=v_run.source_cutoff
            AND observation.collected_at<=v_run.source_cutoff
            AND observation.recorded_at<=v_run.source_cutoff
          ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
            observation.recorded_at DESC,observation.observation_id
          LIMIT 1
        ) maturity_price ON true
        JOIN LATERAL (
          SELECT benchmark.manifest_id
          FROM public.stock_sector_assignments_v3 assignment
          JOIN public.opportunity_run_manifest_inputs benchmark_binding
            ON benchmark_binding.run_id=v_run.run_id
            AND benchmark_binding.input_role='sector_benchmark'
          JOIN public.opportunity_manifests_v3 benchmark
            ON benchmark.manifest_id=benchmark_binding.manifest_id
            AND benchmark.status='complete'
          WHERE assignment.stock_id=score.stock_id
            AND assignment.recorded_at<=v_run.source_cutoff
            AND assignment.source_timestamp<=v_run.source_cutoff
            AND assignment.valid_from<=v_run.source_cutoff
            AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
            AND assignment.status='active'
            AND EXISTS (
              SELECT 1 FROM jsonb_array_elements(benchmark.header_json) pair
              WHERE pair->>0='canonicalSector'
                AND pair->>1=assignment.canonical_sector_key::text
            )
            AND EXISTS (
              SELECT 1 FROM jsonb_array_elements(benchmark.header_json) pair
              WHERE pair->>0='entrySession'
                AND (pair->>1)::date=entry_session.session_id
            )
            AND EXISTS (
              SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
              WHERE conservation.manifest_id=benchmark.manifest_id
                AND conservation.section_key='session_conservation'
                AND conservation.payload_json->>0=maturity_session.session_id::text
                AND conservation.payload_json->>5='available'
            )
          ORDER BY benchmark_binding.ordinal
          LIMIT 1
        ) benchmark ON true
        WHERE binding.run_id=v_run.run_id
          AND binding.input_role='outcome_enrich'
          AND NOT EXISTS (
            SELECT 1 FROM public.opportunity_outcomes outcome
            WHERE outcome.score_snapshot_id=score.score_snapshot_id
          )
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':input_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'input_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind='outcome_input' AND EXISTS (
        SELECT 1
        FROM public.opportunity_run_inputs binding
        JOIN public.opportunity_score_snapshots score ON score.run_id=binding.input_run_id
        WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':excluded_rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'excluded_rows',0,0,NULL,NULL,NULL
        );
      ELSIF v_kind IN (
        'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
        'alias_authority','taxonomy_assignment','peer_reviewer_allowlist','source_eligible'
      ) AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_body->5) pair
        WHERE pair->>0 IN ('rowCount','eligibleCount') AND (pair->>1)::bigint>0
      ) THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':rows:0';
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'rows',0,0,NULL,NULL,NULL
        );
      ELSE
        v_payload_kind := 'manifest_root';
        v_shard := v_kind::text||':'||v_ordinal||':root';
        v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
      END IF;
    ELSIF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_page' THEN
      v_body := v_predecessor_payload.payload_json->5;
      v_ordinal := (v_body->>0)::integer;
      v_kind := (v_body->>2)::public.opportunity_manifest_kind_v3;
      v_contract := v_body->>3;
      v_manifest_id := (v_body->>1)::uuid;
      v_stage := v_predecessor.stage;
      IF v_kind='source_dataset' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'connector_roots' THEN count(*)
          WHEN 'selected_revision_rows' THEN coalesce(sum(least(1000,m.row_count)),0)
          WHEN 'connector_conservation' THEN count(*)
          ELSE 0
        END INTO v_section_count
        FROM public.opportunity_run_manifest_inputs i
        JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
        WHERE i.run_id=requested_run_id AND i.input_role='source_eligible';
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'connector_roots' THEN CASE WHEN (
              SELECT coalesce(sum(least(1000,m.row_count)),0)
              FROM public.opportunity_run_manifest_inputs i
              JOIN public.opportunity_manifests_v3 m ON m.manifest_id=i.manifest_id
              WHERE i.run_id=requested_run_id AND i.input_role='source_eligible'
            )>0 THEN 'selected_revision_rows'::public.opportunity_manifest_section_key_v3
              ELSE 'connector_conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'selected_revision_rows' THEN 'connector_conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NOT NULL THEN
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          ELSE
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
          END IF;
        END IF;
      ELSIF v_kind IN (
        'peer_authority','factor_scoring_reference','sector_valuation_reference',
        'sector_scoring_reference','mover_price_reference','market_reference',
        'bias_reference','technical_history_reference','reported_pe_reference',
        'link_audit_sample','link_audit_resolution'
      ) THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF EXISTS (
          SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,v_section,
            (v_body->>7)::integer+2000,1
          )
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE
            WHEN v_kind='peer_authority' AND v_section='selected_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='factor_scoring_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='factor_scoring_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference'
              AND v_section IN ('included_rows','excluded_rows')
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'aggregate_rows',0,1
                )
              ) THEN 'aggregate_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='sector_valuation_reference'
              AND v_section IN ('included_rows','excluded_rows','aggregate_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='mover_price_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='mover_price_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='market_reference' AND v_section='included_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1
                )
              ) THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='market_reference'
              AND v_section IN ('included_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section='current_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section IN ('current_rows','excluded_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_rows',0,1))
              THEN 'sector_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='bias_reference' AND v_section IN ('current_rows','excluded_rows','sector_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'raw_adjusted_rows',0,1))
              THEN 'raw_adjusted_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='market_benchmark_rows'
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section='raw_adjusted_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'history_rows',0,1))
              THEN 'history_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section IN ('raw_adjusted_rows','history_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='technical_history_reference' AND v_section IN ('raw_adjusted_rows','history_rows','excluded_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section='own_history_rows'
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_current_rows',0,1))
              THEN 'sector_current_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'excluded_rows',0,1))
              THEN 'excluded_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows','excluded_rows')
              AND EXISTS (SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                requested_run_id,v_manifest_id,v_kind,'sector_rows',0,1))
              THEN 'sector_rows'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='reported_pe_reference' AND v_section IN ('own_history_rows','sector_current_rows','excluded_rows','sector_rows')
              THEN 'conservation'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='link_audit_sample' AND v_section='strata'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'samples',0,1
                )
              ) THEN 'samples'::public.opportunity_manifest_section_key_v3
            WHEN v_kind='link_audit_resolution' AND v_section='resolved_rows'
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'unresolved_rows',0,1
                )
              ) THEN 'unresolved_rows'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_kind='sector_scoring_reference' THEN
            SELECT candidate.section_key INTO v_next_section
            FROM (VALUES
              (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
              (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
              (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
              (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
              (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
              (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
              (7,'conservation'::public.opportunity_manifest_section_key_v3)
            ) candidate(section_ordinal,section_key)
            WHERE candidate.section_ordinal>(
              SELECT current.section_ordinal FROM (VALUES
                (1,'market_benchmark_rows'::public.opportunity_manifest_section_key_v3),
                (2,'sector_aggregate_rows'::public.opportunity_manifest_section_key_v3),
                (3,'sector_aggregate_exclusions'::public.opportunity_manifest_section_key_v3),
                (4,'aggregate_evidence_rows'::public.opportunity_manifest_section_key_v3),
                (5,'sector_excess_included_rows'::public.opportunity_manifest_section_key_v3),
                (6,'sector_excess_excluded_rows'::public.opportunity_manifest_section_key_v3),
                (7,'conservation'::public.opportunity_manifest_section_key_v3)
              ) current(section_ordinal,section_key)
              WHERE current.section_key=v_section
            )
              AND EXISTS (
                SELECT 1 FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,candidate.section_key,0,1
                )
              )
            ORDER BY candidate.section_ordinal LIMIT 1;
          END IF;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='candidate_financial' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF EXISTS (
          SELECT 1
          FROM public.opportunity_manifest_native_rows_v3_internal(
            requested_run_id,v_manifest_id,v_kind,v_section,
            (v_body->>7)::integer+2000,1
          )
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'selected_facts' THEN
              CASE WHEN EXISTS (
                SELECT 1
                FROM public.opportunity_manifest_native_rows_v3_internal(
                  requested_run_id,v_manifest_id,v_kind,'excluded_facts',0,1
                )
              ) THEN 'excluded_facts'::public.opportunity_manifest_section_key_v3
              ELSE 'conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'excluded_facts' THEN 'conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='sector_benchmark' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'entry_rows' THEN (
            SELECT count(*)
            FROM (
              SELECT DISTINCT instrument.stock_id
              FROM public.stock_instruments_v3 instrument
              JOIN public.stock_sector_assignments_v3 assignment
                ON assignment.stock_id=instrument.stock_id
              WHERE instrument.recorded_at<=v_run.source_cutoff
                AND instrument.source_timestamp<=v_run.source_cutoff
                AND instrument.valid_from<=v_run.source_cutoff
                AND (instrument.valid_to IS NULL OR v_run.source_cutoff<instrument.valid_to)
                AND instrument.instrument_type='common_stock'
                AND instrument.listing_status='active'
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
                AND assignment.canonical_sector_key=(
                  SELECT (pair->>1)::public.canonical_sector_key_v3
                  FROM public.opportunity_manifests_v3 manifest
                  CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                  WHERE manifest.manifest_id=v_manifest_id AND pair->>0='canonicalSector'
                )
                AND EXISTS (
                  SELECT 1
                  FROM public.opportunity_price_observations_v3 observation
                  WHERE observation.stock_id=instrument.stock_id
                    AND observation.session_id=(
                      SELECT (pair->>1)::date
                      FROM public.opportunity_manifests_v3 manifest
                      CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                      WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
                    )
                    AND observation.source_timestamp<=v_run.source_cutoff
                    AND observation.collected_at<=v_run.source_cutoff
                    AND observation.recorded_at<=v_run.source_cutoff
                )
            ) entry_population
          )
          WHEN 'evaluation_rows' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 entry
            JOIN public.stock_instruments_v3 instrument ON instrument.symbol=entry.payload_json->>0
            JOIN public.opportunity_effective_taiwan_sessions_v3 session
              ON session.session_id>=(
                SELECT (pair->>1)::date
                FROM public.opportunity_manifests_v3 manifest
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
              )
              AND session.canonical_cutoff<=v_run.source_cutoff
            WHERE entry.manifest_id=v_manifest_id AND entry.section_key='entry_rows'
              AND EXISTS (
                SELECT 1
                FROM public.opportunity_price_observations_v3 observation
                WHERE observation.stock_id=instrument.stock_id
                  AND observation.session_id=session.session_id
                  AND observation.source_timestamp<=v_run.source_cutoff
                  AND observation.collected_at<=v_run.source_cutoff
                  AND observation.recorded_at<=v_run.source_cutoff
              )
          )
          WHEN 'session_conservation' THEN (
            SELECT count(*)
            FROM (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>=(
                SELECT (pair->>1)::date
                FROM public.opportunity_manifests_v3 manifest
                CROSS JOIN LATERAL jsonb_array_elements(manifest.header_json) pair
                WHERE manifest.manifest_id=v_manifest_id AND pair->>0='entrySession'
              )
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 250
            ) bounded_sessions
          )
          ELSE 0
        END INTO v_section_count;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind:='manifest_page';
          v_shard:=v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body:=jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          v_next_section:=CASE v_section
            WHEN 'entry_rows' THEN CASE WHEN EXISTS (
              SELECT 1 FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key='entry_rows'
            ) THEN 'evaluation_rows'::public.opportunity_manifest_section_key_v3
              ELSE 'session_conservation'::public.opportunity_manifest_section_key_v3 END
            WHEN 'evaluation_rows' THEN 'session_conservation'::public.opportunity_manifest_section_key_v3
            ELSE NULL
          END;
          IF v_next_section IS NULL THEN
            v_payload_kind:='manifest_root';
            v_shard:=v_kind::text||':'||v_ordinal||':root';
            v_body:=jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind:='manifest_page';
            v_shard:=v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body:=jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind='outcome_input' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        IF v_section='conservation' THEN
          SELECT 4*count(*) INTO v_section_count
          FROM public.opportunity_run_inputs binding
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich';
        ELSE
          WITH planned AS (
            SELECT score.score_snapshot_id,
              entry_price.source_ref AS entry_price_ref,
              maturity_price.source_ref AS maturity_price_ref,
              benchmark.manifest_id AS benchmark_manifest_id
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            CROSS JOIN (VALUES
              ('session_20'::public.opportunity_outcome_maturity_v3,20),
              ('session_60'::public.opportunity_outcome_maturity_v3,60),
              ('session_120'::public.opportunity_outcome_maturity_v3,120),
              ('session_250'::public.opportunity_outcome_maturity_v3,250)
            ) maturity(maturity_horizon,session_count)
            JOIN LATERAL (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry_session ON true
            JOIN LATERAL (
              SELECT session.session_id
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>=entry_session.session_id
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id
              OFFSET maturity.session_count-1 LIMIT 1
            ) maturity_session ON true
            LEFT JOIN LATERAL (
              SELECT observation.source_ref
              FROM public.opportunity_price_observations_v3 observation
              WHERE observation.stock_id=score.stock_id
                AND observation.session_id=entry_session.session_id
                AND observation.source_timestamp<=v_run.source_cutoff
                AND observation.collected_at<=v_run.source_cutoff
                AND observation.recorded_at<=v_run.source_cutoff
              ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                observation.recorded_at DESC,observation.observation_id LIMIT 1
            ) entry_price ON true
            LEFT JOIN LATERAL (
              SELECT observation.source_ref
              FROM public.opportunity_price_observations_v3 observation
              WHERE observation.stock_id=score.stock_id
                AND observation.session_id=maturity_session.session_id
                AND observation.source_timestamp<=v_run.source_cutoff
                AND observation.collected_at<=v_run.source_cutoff
                AND observation.recorded_at<=v_run.source_cutoff
              ORDER BY observation.source_timestamp DESC,observation.collected_at DESC,
                observation.recorded_at DESC,observation.observation_id LIMIT 1
            ) maturity_price ON true
            LEFT JOIN LATERAL (
              SELECT manifest.manifest_id
              FROM public.stock_sector_assignments_v3 assignment
              JOIN public.opportunity_run_manifest_inputs benchmark_binding
                ON benchmark_binding.run_id=v_run.run_id
                AND benchmark_binding.input_role='sector_benchmark'
              JOIN public.opportunity_manifests_v3 manifest
                ON manifest.manifest_id=benchmark_binding.manifest_id
                AND manifest.status='complete'
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
                AND EXISTS (
                  SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                  WHERE pair->>0='canonicalSector'
                    AND pair->>1=assignment.canonical_sector_key::text
                )
                AND EXISTS (
                  SELECT 1 FROM jsonb_array_elements(manifest.header_json) pair
                  WHERE pair->>0='entrySession'
                    AND (pair->>1)::date=entry_session.session_id
                )
                AND EXISTS (
                  SELECT 1 FROM public.opportunity_manifest_rows_v3 conservation
                  WHERE conservation.manifest_id=manifest.manifest_id
                    AND conservation.section_key='session_conservation'
                    AND conservation.payload_json->>0=maturity_session.session_id::text
                    AND conservation.payload_json->>5='available'
                )
              ORDER BY benchmark_binding.ordinal LIMIT 1
            ) benchmark ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
              AND NOT EXISTS (
                SELECT 1 FROM public.opportunity_outcomes outcome
                WHERE outcome.score_snapshot_id=score.score_snapshot_id
                  AND outcome.maturity_horizon=maturity.maturity_horizon
              )
          )
          SELECT CASE v_section
            WHEN 'input_rows' THEN count(*) FILTER (
              WHERE entry_price_ref IS NOT NULL AND maturity_price_ref IS NOT NULL
                AND benchmark_manifest_id IS NOT NULL
            )
            ELSE count(*) FILTER (
              WHERE entry_price_ref IS NULL OR maturity_price_ref IS NULL
                OR benchmark_manifest_id IS NULL
            )
          END INTO v_section_count
          FROM planned;
        END IF;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSIF v_section='input_rows' AND (
          SELECT count(*) FROM public.opportunity_run_inputs binding
          JOIN public.opportunity_score_snapshots score ON score.run_id=binding.input_run_id
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
        )>v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':excluded_rows:0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            'excluded_rows',0,0,NULL,NULL,NULL
          );
        ELSIF v_section IN ('input_rows','excluded_rows') AND EXISTS (
          SELECT 1 FROM public.opportunity_run_inputs binding
          WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
        ) THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':conservation:0';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            'conservation',0,0,NULL,NULL,NULL
          );
        ELSE
          v_payload_kind := 'manifest_root';
          v_shard := v_kind::text||':'||v_ordinal||':root';
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
          );
        END IF;
      ELSIF v_kind='evaluation_input' THEN
        v_section:=(v_body->>5)::public.opportunity_manifest_section_key_v3;
        SELECT CASE v_section
          WHEN 'attempt_roster' THEN 252
          WHEN 'backtest_rows' THEN coalesce((
            SELECT (pair->>1)::bigint
            FROM public.opportunity_manifests_v3 manifest,
              LATERAL jsonb_array_elements(manifest.header_json) pair
            WHERE manifest.manifest_id=v_manifest_id AND pair->>0='backtestCount'
          ),0)
          WHEN 'live_rows' THEN coalesce((
            SELECT (pair->>1)::bigint
            FROM public.opportunity_manifests_v3 manifest,
              LATERAL jsonb_array_elements(manifest.header_json) pair
            WHERE manifest.manifest_id=v_manifest_id AND pair->>0='liveCount'
          ),0)
          WHEN 'cohort_rows' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 selected_date
            JOIN public.opportunity_score_snapshots score
              ON score.run_id=(selected_date.payload_json->>2)::uuid
              AND score.horizon='swing_20_60d'
            JOIN public.opportunity_outcomes outcome
              ON outcome.score_snapshot_id=score.score_snapshot_id
              AND outcome.maturity_horizon='session_20'
            WHERE selected_date.manifest_id=v_manifest_id
              AND selected_date.section_key IN ('backtest_rows','live_rows')
          )
          WHEN 'conservation' THEN (
            SELECT count(*)
            FROM public.opportunity_manifest_rows_v3 selected_date
            WHERE selected_date.manifest_id=v_manifest_id
              AND selected_date.section_key IN ('backtest_rows','live_rows')
          )
          ELSE 0
        END INTO v_section_count;
        IF (v_body->>7)::bigint+2000<v_section_count THEN
          v_payload_kind := 'manifest_page';
          v_shard := v_kind::text||':'||v_ordinal||':'||v_section::text||':'||
            ((v_body->>6)::integer+1);
          v_body := jsonb_build_array(
            v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,v_section,
            (v_body->>6)::integer+1,(v_body->>7)::integer+2000,
            (SELECT page_id FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT page_hash FROM public.opportunity_manifest_pages_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
                AND page_ordinal=(v_body->>6)::integer),
            (SELECT identity_key FROM public.opportunity_manifest_rows_v3
              WHERE manifest_id=v_manifest_id AND section_key=v_section
              ORDER BY row_ordinal DESC LIMIT 1)
          );
        ELSE
          IF v_section='attempt_roster' AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(
              (SELECT header_json FROM public.opportunity_manifests_v3
                WHERE manifest_id=v_manifest_id)
            ) pair
            WHERE pair->>0='backtestCount' AND (pair->>1)::integer>0
          ) THEN
            v_next_section:='backtest_rows';
          ELSIF v_section IN ('attempt_roster','backtest_rows') AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(
              (SELECT header_json FROM public.opportunity_manifests_v3
                WHERE manifest_id=v_manifest_id)
            ) pair
            WHERE pair->>0='liveCount' AND (pair->>1)::integer>0
          ) THEN
            v_next_section:='live_rows';
          ELSIF v_section IN ('backtest_rows','live_rows') THEN
            v_next_section:='cohort_rows';
          ELSIF v_section='cohort_rows' THEN
            v_next_section:='conservation';
          ELSE
            v_next_section:=NULL;
          END IF;
          IF v_next_section IS NULL THEN
            v_payload_kind := 'manifest_root';
            v_shard := v_kind::text||':'||v_ordinal||':root';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff
            );
          ELSE
            v_payload_kind := 'manifest_page';
            v_shard := v_kind::text||':'||v_ordinal||':'||v_next_section::text||':0';
            v_body := jsonb_build_array(
              v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
              v_next_section,0,0,NULL,NULL,NULL
            );
          END IF;
        END IF;
      ELSIF v_kind IN (
        'source_identity_allowlist','publisher_verification_allowlist','instrument_roster',
        'alias_authority','taxonomy_assignment','peer_reviewer_allowlist','source_eligible'
      ) AND (
        SELECT (pair->>1)::bigint
        FROM public.opportunity_manifests_v3 m,
          LATERAL jsonb_array_elements(m.header_json) pair
        WHERE m.manifest_id=v_manifest_id AND pair->>0 IN ('rowCount','eligibleCount')
      ) > (v_body->>7)::bigint + 2000 THEN
        v_payload_kind := 'manifest_page';
        v_shard := v_kind::text||':'||v_ordinal||':rows:'||((v_body->>6)::integer+1);
        v_body := jsonb_build_array(
          v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
          'rows',(v_body->>6)::integer+1,(v_body->>7)::integer+2000,
          (SELECT page_id FROM public.opportunity_manifest_pages_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
              AND page_ordinal=(v_body->>6)::integer),
          (SELECT page_hash FROM public.opportunity_manifest_pages_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
              AND page_ordinal=(v_body->>6)::integer),
          (SELECT identity_key FROM public.opportunity_manifest_rows_v3
            WHERE manifest_id=v_manifest_id AND section_key='rows'
            ORDER BY row_ordinal DESC LIMIT 1)
        );
      ELSE
        v_payload_kind := 'manifest_root';
        v_shard := v_kind::text||':'||v_ordinal||':root';
        v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff);
      END IF;
    ELSIF v_run.status='preparing' AND v_predecessor_payload.payload_kind='manifest_root' THEN
      v_kind := (v_predecessor_payload.payload_json->5->>2)::public.opportunity_manifest_kind_v3;
      v_ordinal := (v_predecessor_payload.payload_json->5->>0)::integer;
      v_next_kind := NULL;
      IF v_run.mode='source_scan' THEN
        CASE v_kind
          WHEN 'source_identity_allowlist' THEN v_next_kind := 'publisher_verification_allowlist'; v_contract := 'source-publisher-allowlist-v3.0';
          WHEN 'publisher_verification_allowlist' THEN v_next_kind := 'instrument_roster'; v_contract := 'tw-instrument-roster-v3.0';
          WHEN 'instrument_roster' THEN v_next_kind := 'alias_authority'; v_contract := 'alias-normalization-v3.0';
          WHEN 'alias_authority' THEN v_next_kind := 'taxonomy_assignment'; v_contract := 'tw-sector-taxonomy-v3.0';
          WHEN 'taxonomy_assignment' THEN v_next_kind := 'source_eligible'; v_contract := 'source-adapter-v3.3';
          WHEN 'source_eligible' THEN
            IF v_ordinal < 10 THEN
              v_next_kind := 'source_eligible'; v_next_ordinal := v_ordinal + 1; v_contract := 'source-adapter-v3.3';
            ELSE
              v_next_kind := 'source_dataset'; v_contract := 'source-dataset-v3.3';
            END IF;
          WHEN 'source_dataset' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      ELSIF v_run.mode='enrich_rank' THEN
        CASE v_kind
          WHEN 'peer_reviewer_allowlist' THEN v_next_kind := 'peer_authority'; v_contract := 'peer-authority-v3.0';
          WHEN 'peer_authority' THEN v_next_kind := 'sector_valuation_reference'; v_contract := 'opportunity-financial-inputs-v3.0';
          WHEN 'sector_valuation_reference' THEN v_next_kind := 'candidate_financial'; v_contract := 'candidate-financial-v3.0';
          WHEN 'candidate_financial' THEN v_next_kind := 'factor_scoring_reference'; v_contract := 'opportunity-features-v3.1';
          WHEN 'factor_scoring_reference' THEN v_next_kind := 'sector_scoring_reference'; v_contract := 'sector-reference-v3.1';
          WHEN 'sector_scoring_reference' THEN
            v_next_kind := 'bias_reference'; v_contract := 'opportunity-factor-correctness-v3.11.6';
          WHEN 'bias_reference' THEN
            v_next_kind := 'technical_history_reference'; v_contract := 'opportunity-factor-correctness-v3.11.6';
          WHEN 'technical_history_reference' THEN
            v_next_kind := 'reported_pe_reference'; v_contract := 'opportunity-financial-inputs-v3.3';
          WHEN 'reported_pe_reference' THEN
            IF NOT EXISTS (
              SELECT 1 FROM public.opportunity_effective_taiwan_sessions_v3 s
              WHERE s.canonical_cutoff<=v_run.source_cutoff
            ) THEN
              RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
            END IF;
            v_next_kind := 'mover_price_reference'; v_contract := 'mover-audit-price-v3.3';
          WHEN 'mover_price_reference' THEN
            IF EXISTS (
              SELECT 1 FROM public.opportunity_effective_taiwan_sessions_v3 s
              WHERE s.canonical_cutoff<=v_run.source_cutoff
              ORDER BY s.session_id DESC OFFSET v_ordinal+1 LIMIT 1
            ) AND v_ordinal<4 THEN
              v_next_kind := 'mover_price_reference'; v_next_ordinal:=v_ordinal+1;
              v_contract := 'mover-audit-price-v3.3';
            ELSE
              v_next_kind := 'market_reference'; v_contract := 'market-context-v3.6';
            END IF;
          WHEN 'market_reference' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      ELSIF v_run.mode='label_outcomes' THEN
        IF v_kind='sector_benchmark' THEN
          IF EXISTS (
            SELECT 1
            FROM (
              SELECT DISTINCT sector.canonical_sector_key,entry.session_id
              FROM public.opportunity_run_inputs binding
              JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
              JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
              JOIN LATERAL (
                SELECT assignment.canonical_sector_key
                FROM public.stock_sector_assignments_v3 assignment
                WHERE assignment.stock_id=score.stock_id
                  AND assignment.recorded_at<=v_run.source_cutoff
                  AND assignment.source_timestamp<=v_run.source_cutoff
                  AND assignment.valid_from<=v_run.source_cutoff
                  AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                  AND assignment.status='active'
                ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
                LIMIT 1
              ) sector ON sector.canonical_sector_key<>'unknown'
              JOIN LATERAL (
                SELECT session.session_id
                FROM public.opportunity_effective_taiwan_sessions_v3 session
                WHERE session.session_id>input.trading_date
                  AND session.canonical_cutoff<=v_run.source_cutoff
                ORDER BY session.session_id LIMIT 1
              ) entry ON true
              WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
              ORDER BY sector.canonical_sector_key,entry.session_id
              OFFSET v_ordinal+1 LIMIT 1
            ) next_pair
          ) THEN
            v_next_kind:='sector_benchmark';
            v_next_ordinal:=v_ordinal+1;
            v_contract:='sector-benchmark-v3.1';
          ELSE
            v_next_kind:='outcome_input';
            v_next_ordinal:=0;
            v_contract:='source-led-eval-v3.7';
          END IF;
        ELSIF v_kind<>'outcome_input' THEN
          RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END IF;
      ELSIF v_run.mode='shadow_evaluate' THEN
        CASE v_kind
          WHEN 'evaluation_input' THEN v_next_kind := 'link_audit_sample'; v_contract := 'source-led-eval-v3.7';
          WHEN 'link_audit_sample' THEN v_next_kind := 'link_audit_resolution'; v_contract := 'source-led-eval-v3.7';
          WHEN 'link_audit_resolution' THEN v_next_kind := NULL;
          ELSE RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
        END CASE;
      END IF;
      IF v_next_kind IS NOT NULL THEN
        v_kind := v_next_kind;
        v_ordinal := v_next_ordinal;
        IF v_kind='publisher_verification_allowlist' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
            FROM public.opportunity_authority_stream_registry_v3
            WHERE family='publisher_verification'
            ORDER BY stream_key_hash,stream_key_canonical LIMIT 10001
          ) bounded_registry;
          IF v_registered_count>10000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT authority_id
                FROM public.publisher_verification_authorities_v3 authority
                WHERE authority.publisher_identity_id=(
