          IF v_registered_count>20000 OR EXISTS (
            SELECT 1
            FROM public.opportunity_authority_stream_registry_v3 registry
            CROSS JOIN LATERAL (
              SELECT count(*) retained_count FROM (
                SELECT assignment_authority_id FROM public.stock_sector_assignments_v3 authority
                WHERE authority.stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>1
