                ORDER BY authority.recorded_at DESC,authority.assignment_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='sector_assignment' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='roster_volume_exceeded'; END IF;
        ELSIF v_kind='peer_authority' THEN
          SELECT count(*) INTO v_registered_count FROM (
            SELECT stream_key_hash
