                  AND authority.customer_stock_id=(
                    convert_from(registry.stream_key_canonical,'utf8')::jsonb->>2
                  )::uuid
                ORDER BY authority.recorded_at DESC,authority.relationship_authority_id LIMIT 65
              ) bounded
            ) stream
            WHERE registry.family='peer_relationship' AND stream.retained_count>64
          ) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow'; END IF;
          v_selected_count := public.opportunity_authority_selected_stream_count_v3_internal(
            'peer_relationship',v_run.source_cutoff
          );
          IF v_selected_count>100000 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='identity_manifest_overflow';
          END IF;
        END IF;
        v_stage := CASE WHEN v_kind IN (
          'source_identity_allowlist','publisher_verification_allowlist','instrument_roster','alias_authority',
          'taxonomy_assignment','peer_reviewer_allowlist','peer_authority'
        ) THEN 'authority_manifest' ELSE 'input_manifest_pages' END;
        v_payload_kind := 'manifest_header';
        v_shard := v_kind::text||':'||v_ordinal||':header';
        v_input_text := format('["%s","%s",%s,"%s"]',requested_run_id,v_kind,v_ordinal,v_contract);
        v_bytes := substring(extensions.digest(
          decode(replace('51689af8-f3fe-5d1e-a18f-c667ddee224a','-',''),'hex')
            || convert_to(v_input_text,'utf8'),'sha1') FROM 1 FOR 16);
        v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
        v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
        v_hex := encode(v_bytes,'hex');
        v_manifest_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
          ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
        IF v_kind='sector_benchmark' THEN
          WITH benchmark_pairs AS (
            SELECT sector.canonical_sector_key,entry.session_id,
              min(input.run_id::text)::uuid AS input_run_id,
              min(entry.taiwan_session_authority_hash) AS entry_session_authority_hash
            FROM public.opportunity_run_inputs binding
            JOIN public.opportunity_runs input ON input.run_id=binding.input_run_id
            JOIN public.opportunity_score_snapshots score ON score.run_id=input.run_id
            JOIN LATERAL (
              SELECT assignment.canonical_sector_key
              FROM public.stock_sector_assignments_v3 assignment
              WHERE assignment.stock_id=score.stock_id
                AND assignment.recorded_at<=v_run.source_cutoff
                AND assignment.source_timestamp<=v_run.source_cutoff
                AND assignment.valid_from<=v_run.source_cutoff
                AND (assignment.valid_to IS NULL OR v_run.source_cutoff<assignment.valid_to)
                AND assignment.status='active'
              ORDER BY assignment.recorded_at DESC,assignment.assignment_authority_id
              LIMIT 1
            ) sector ON sector.canonical_sector_key<>'unknown'
            JOIN LATERAL (
              SELECT session.session_id,session.taiwan_session_authority_hash
              FROM public.opportunity_effective_taiwan_sessions_v3 session
              WHERE session.session_id>input.trading_date
                AND session.canonical_cutoff<=v_run.source_cutoff
              ORDER BY session.session_id LIMIT 1
            ) entry ON true
            WHERE binding.run_id=v_run.run_id AND binding.input_role='outcome_enrich'
            GROUP BY sector.canonical_sector_key,entry.session_id
            ORDER BY sector.canonical_sector_key,entry.session_id
            OFFSET v_ordinal LIMIT 1
          )
          SELECT pair.canonical_sector_key,pair.session_id,
            pair.entry_session_authority_hash,pair.input_run_id
          INTO STRICT v_canonical_sector,v_entry_session,v_entry_session_hash,
            v_benchmark_input_run_id
          FROM benchmark_pairs pair;
          SELECT manifest.manifest_hash INTO STRICT v_roster_manifest_hash
          FROM public.opportunity_run_manifest_inputs binding
          JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id
          WHERE binding.run_id=v_benchmark_input_run_id
            AND binding.input_role='instrument_roster' AND binding.ordinal=0
            AND manifest.status='complete';
          SELECT manifest.manifest_hash INTO STRICT v_taxonomy_manifest_hash
          FROM public.opportunity_run_manifest_inputs binding
          JOIN public.opportunity_manifests_v3 manifest ON manifest.manifest_id=binding.manifest_id
          WHERE binding.run_id=v_benchmark_input_run_id
            AND binding.input_role='taxonomy_assignment' AND binding.ordinal=0
            AND manifest.status='complete';
          v_body:=jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('canonicalSector',v_canonical_sector),
              jsonb_build_array('corporateActionVersion','tw-corporate-action-v3.1'),
              jsonb_build_array('entrySession',v_entry_session),
              jsonb_build_array('entrySessionAuthorityHash',v_entry_session_hash),
              jsonb_build_array('priceProviderAllowlistHash','48fa54ee9f0e3a0b888ac0dc17eda8ad5bb746106a6fe4395eb50a5865e4e44e'),
              jsonb_build_array('rosterManifestHash',v_roster_manifest_hash),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('taxonomyAssignmentManifestHash',v_taxonomy_manifest_hash),
              jsonb_build_array('tradingCalendarWindowHash',encode(extensions.digest(
                convert_to(regexp_replace(jsonb_build_array(
                  'sector-benchmark-calendar-window-v3.4',
                  coalesce((SELECT jsonb_agg(jsonb_build_array(
                    session.session_id,session.taiwan_session_authority_hash
                  ) ORDER BY session.session_id)
                  FROM (
                    SELECT session_id,taiwan_session_authority_hash
                    FROM public.opportunity_effective_taiwan_sessions_v3
                    WHERE session_id>=v_entry_session
                      AND canonical_cutoff<=v_run.source_cutoff
                    ORDER BY session_id LIMIT 250
                  ) session),'[]'::jsonb)
                )::text, ', ', ',', 'g'),'utf8'),'sha256'),'hex'))
            ));
        ELSIF v_kind='source_eligible' THEN
          v_source_key := (ARRAY[
            'bulltalk','earnings_call','instagram','investanchors','mops_material_event','podcast',
            'ptt','public_broker_research','telegram','threads','youtube'
          ]::public.source_key_v3[])[v_ordinal+1];
          SELECT count(*) INTO v_registered_count
          FROM (
            SELECT registry.revision_family_key
            FROM public.source_revision_family_registry_v3 registry
            WHERE registry.source_key=v_source_key
            ORDER BY registry.revision_family_key
            LIMIT 1000001
          ) bounded_registry;
          IF v_registered_count>1000000 THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
          END IF;
          IF EXISTS (
            SELECT 1
            FROM (
              SELECT registry.revision_family_key
              FROM public.source_revision_family_registry_v3 registry
              WHERE registry.source_key=v_source_key
              ORDER BY registry.revision_family_key
              LIMIT 1000001
            ) bounded_registry
            CROSS JOIN LATERAL (
              SELECT revision.revision_id
              FROM public.source_document_revisions_v3 revision
              WHERE revision.source_key=v_source_key
                AND revision.revision_family_key=bounded_registry.revision_family_key
              ORDER BY revision.recorded_at DESC,revision.revision_id
              OFFSET 64 LIMIT 1
            ) overflow_revision
          ) THEN
            RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
          END IF;
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('eligibleCount',(
                WITH bounded_registry AS (
                  SELECT registry.revision_family_key
                  FROM public.source_revision_family_registry_v3 registry
                  WHERE registry.source_key=v_source_key
                  ORDER BY registry.revision_family_key
                  LIMIT 1000001
                )
                SELECT count(*) FROM (
                  SELECT selected.* FROM (
                    SELECT d.*,row_number() OVER (
                      PARTITION BY d.revision_family_key
                      ORDER BY d.recorded_at DESC,d.revision_id
                    ) AS revision_rank
                    FROM bounded_registry registry
                    CROSS JOIN LATERAL (
                      SELECT revision.*
                      FROM public.source_document_revisions_v3 revision
                      WHERE revision.source_key=v_source_key
                        AND revision.revision_family_key=registry.revision_family_key
                      ORDER BY revision.recorded_at DESC,revision.revision_id
                      LIMIT 65
                    ) d
                    WHERE d.recorded_at<=v_run.source_cutoff
                      AND d.collected_at<=v_run.source_cutoff
                      AND (d.published_at IS NULL OR d.published_at<=v_run.source_cutoff)
                  ) selected WHERE selected.revision_rank=1
                ) eligible
              )),
              jsonb_build_array('registeredFamilyCount',(
                SELECT v_registered_count
              )),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('sourceKey',v_source_key)
            ));
        ELSIF v_kind='source_dataset' THEN
          v_body := jsonb_build_array(v_ordinal,v_manifest_id,v_kind,v_contract,v_run.source_cutoff,
            jsonb_build_array(
              jsonb_build_array('aliasManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='alias_authority' AND ordinal=0))),
              jsonb_build_array('instrumentRosterManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='instrument_roster' AND ordinal=0))),
              jsonb_build_array('publisherVerificationAllowlistManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='publisher_verification_allowlist' AND ordinal=0))),
              jsonb_build_array('publisherVerificationPolicyHash','d85307ccc475b54460d5d9bb415cdf4b8574bf796bde38b7fdf66543721a99ff'),
              jsonb_build_array('sourceAdapterRegistryHash','d663b2a49538c7eec6f5c91a4100d6e8a0250106c970e077a91db0ce8bd56131'),
              jsonb_build_array('sourceCutoff',v_run.source_cutoff),
              jsonb_build_array('sourceFunnelPolicyHash','ee5acd1cdde88fff9efc3b18d360624e9e7768d85f7c232b200df560205556ef'),
              jsonb_build_array('sourceIdentityAllowlistManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='source_identity_allowlist' AND ordinal=0))),
              jsonb_build_array('taxonomyAssignmentManifestHash',(SELECT manifest_hash
                FROM public.opportunity_manifests_v3 WHERE manifest_id=(
                  SELECT manifest_id FROM public.opportunity_run_manifest_inputs
                  WHERE run_id=requested_run_id AND input_role='taxonomy_assignment' AND ordinal=0))),
              jsonb_build_array('taxonomyMapHash','83f06426b8dae88f83d0610600000e529b6ad09249cee411c7ea2e89dab9a862')
            ));
        ELSIF v_kind='mover_price_reference' THEN
          SELECT s.session_id,s.taiwan_session_authority_hash INTO STRICT
            v_audited_session,v_audited_session_hash
          FROM public.opportunity_effective_taiwan_sessions_v3 s
          WHERE s.canonical_cutoff<=v_run.source_cutoff
          ORDER BY s.session_id DESC OFFSET v_ordinal LIMIT 1;
