    'opportunity-job-input-v3.3',requested_run_id,v_stage,v_shard,v_payload_hash,v_predecessor_hashes
  )::text, ', ', ',', 'g');
  v_input_hash := encode(extensions.digest(convert_to(v_input_text,'utf8'),'sha256'),'hex');
  v_bytes := substring(extensions.digest(
    decode(replace('7ad3ec9e-4db5-5e8a-b9a4-eab35ddc1a21','-',''),'hex')
      || convert_to(v_input_hash,'utf8'),'sha1') FROM 1 FOR 16);
  v_bytes := set_byte(v_bytes,6,(get_byte(v_bytes,6)&15)|80);
  v_bytes := set_byte(v_bytes,8,(get_byte(v_bytes,8)&63)|128);
  v_hex := encode(v_bytes,'hex');
  v_job_id := (substr(v_hex,1,8)||'-'||substr(v_hex,9,4)||'-'||substr(v_hex,13,4)||'-'
    ||substr(v_hex,17,4)||'-'||substr(v_hex,21,12))::uuid;
  INSERT INTO public.opportunity_run_jobs_v3(job_id,run_id,stage,shard_key,input_hash)
  VALUES(v_job_id,requested_run_id,v_stage,v_shard,v_input_hash)
  ON CONFLICT(run_id,stage,shard_key,input_hash) DO NOTHING;
  INSERT INTO public.opportunity_job_payloads_v3(job_id,run_id,payload_kind,payload_canonical,payload_json,payload_hash)
  VALUES(v_job_id,requested_run_id,v_payload_kind,convert_to(v_payload_text,'utf8'),v_payload,v_payload_hash)
  ON CONFLICT(job_id) DO NOTHING;
  RETURN v_job_id;
END
$function$

CREATE OR REPLACE FUNCTION public.enqueue_research_deep_jobs_v1(p_run_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.research_priority_runs_v1; admission_clock timestamptz; wk date; used integer; added integer:=0; item jsonb; rank integer; stock uuid; company uuid; job uuid;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(2409,6001);admission_clock:=clock_timestamp();wk:=date_trunc('week',admission_clock AT TIME ZONE 'Asia/Taipei')::date;
 SELECT * INTO r FROM public.research_priority_runs_v1 WHERE run_id=p_run_id;
 IF NOT FOUND OR r.as_of>admission_clock OR jsonb_array_length(r.research_queue)>20 THEN RAISE EXCEPTION 'research_deep_priority_run_invalid'; END IF;
 IF r.research_scope='research_observed_v1' AND NOT EXISTS(SELECT 1 FROM public.research_observed_priority_store_receipts_v1 receipt WHERE receipt.run_id=r.run_id AND receipt.stored_run_hash=encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'observed_priority_store_lineage_missing';END IF;
 IF EXISTS(SELECT 1 FROM public.research_deep_run_admissions_v1 WHERE run_id=p_run_id) THEN RETURN 0; END IF;
 IF r.created_at<(SELECT installed_at FROM public.research_deep_admission_cutover_v1) THEN RAISE EXCEPTION 'deep_legacy_zero_admission_unproven'; END IF;
 INSERT INTO public.research_deep_admission_clocks_v1(run_id,admission_at,admission_week)VALUES(p_run_id,admission_clock,wk);
 PERFORM public.reconcile_research_deep_admissions_v1();
 SELECT count(*) INTO used FROM public.research_deep_admission_charges_v1 WHERE admission_week=wk;
 FOR item,rank IN SELECT value,ordinality::integer FROM jsonb_array_elements(r.research_queue)WITH ORDINALITY LOOP
  EXIT WHEN used>=5;
  IF item->>'disposition' NOT IN('queued','stale') OR coalesce((item->>'independentRootCount')::integer,0)<1 THEN CONTINUE; END IF;
  IF EXISTS(SELECT 1 FROM public.research_deep_jobs_v1 WHERE symbol=item->>'symbol' AND status IN('queued','running')) OR EXISTS(SELECT 1 FROM public.research_deep_admission_charges_v1 WHERE issuer_key='TW:'||(item->>'symbol') AND admission_week=wk) THEN CONTINUE; END IF;
  stock:=NULL;company:=NULL;
  IF r.research_scope='formal_v1' THEN
   SELECT id INTO stock FROM public.stocks WHERE symbol=item->>'symbol' AND market='TW';
   IF stock IS NULL THEN RAISE EXCEPTION 'research_deep_stock_authority_missing'; END IF;
  ELSE
   SELECT research_company_id INTO company FROM public.research_observed_roster_members_v1 WHERE snapshot_hash=r.observed_snapshot_hash AND symbol=item->>'symbol';
   IF company IS NULL THEN RAISE EXCEPTION 'research_deep_observed_membership_missing'; END IF;
  END IF;
  INSERT INTO public.research_deep_jobs_v1(priority_run_id,stock_id,symbol,week_start,queue_rank,research_scope,research_company_id,observed_snapshot_hash,created_at)
   VALUES(p_run_id,stock,item->>'symbol',wk,rank,r.research_scope,company,r.observed_snapshot_hash,admission_clock) RETURNING job_id INTO job;
  used:=used+1;added:=added+1;
 END LOOP;
 INSERT INTO public.research_deep_run_admissions_v1(run_id,admission_at,admission_week,added_count) VALUES(p_run_id,admission_clock,wk,added);
 RETURN added;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_taiwan_data_refresh_batch_v6(p_entries jsonb, p_phase text, p_session_date date, p_queued_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_keys text[]; v_entry jsonb; v_ids jsonb:='[]'; v_id uuid;
BEGIN
  IF jsonb_typeof(p_entries) IS DISTINCT FROM 'array' OR jsonb_array_length(p_entries) NOT BETWEEN 1 AND 100
    OR p_phase IS NULL OR p_phase NOT IN ('preliminary','final') OR p_session_date IS NULL OR p_queued_at IS NULL
  THEN RAISE EXCEPTION 'invalid_taiwan_refresh_batch'; END IF;
  SELECT scope.expected_queue_keys INTO v_keys FROM public.taiwan_data_refresh_scopes_v6 scope
    WHERE scope.session_date=p_session_date AND scope.refresh_phase=p_phase FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'taiwan_refresh_scope_required'; END IF;
  FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
    IF jsonb_typeof(v_entry) IS DISTINCT FROM 'object' OR v_entry->>'queueKey' IS NULL
      OR NOT (v_entry->>'queueKey'=ANY(v_keys)) OR v_entry->>'dataset' IS NULL OR v_entry->>'exchange' IS NULL
    THEN RAISE EXCEPTION 'taiwan_refresh_batch_scope_mismatch'; END IF;
    v_id:=public.enqueue_taiwan_data_refresh_v5(v_entry->>'queueKey',v_entry->>'dataset',v_entry->>'symbol',
      v_entry->>'exchange',p_phase,p_session_date,p_queued_at);
    -- Check the row that won the unique key, including a concurrent enqueue.
    PERFORM 1 FROM public.taiwan_data_refresh_queue_v5 queue WHERE queue.job_id=v_id
      AND queue.requested_session_date=p_session_date AND queue.refresh_phase=p_phase
      AND queue.dataset IS NOT DISTINCT FROM v_entry->>'dataset' AND queue.symbol IS NOT DISTINCT FROM v_entry->>'symbol'
      AND queue.exchange IS NOT DISTINCT FROM v_entry->>'exchange' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'taiwan_refresh_batch_identity_mismatch'; END IF;
    v_ids:=v_ids||jsonb_build_array(v_id);
  END LOOP;
  RETURN jsonb_build_object('queued',jsonb_array_length(v_ids),'jobIds',v_ids);
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_taiwan_data_refresh_v5(p_queue_key text, p_dataset text, p_symbol text, p_exchange text, p_refresh_phase text, p_requested_session_date date, p_queued_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_job_id uuid;
BEGIN
  IF p_queue_key !~ '^[0-9a-f]{64}$' OR p_dataset NOT IN ('daily_price','daily_valuation','monthly_revenue','financial_statement','institutional_flow','margin_short','market_index','stock_master','trading_calendar')
    OR p_symbol IS NOT NULL AND p_symbol !~ '^\d{4}$' OR p_exchange NOT IN ('TWSE','TPEX')
    OR p_refresh_phase NOT IN ('preliminary','final') OR p_queued_at > clock_timestamp() + interval '5 minutes' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid_taiwan_data_refresh_request';
  END IF;
  INSERT INTO public.taiwan_data_refresh_queue_v5(
    queue_key,dataset,symbol,exchange,refresh_phase,requested_session_date,status,next_attempt_at,queued_at,updated_at
  ) VALUES(
    p_queue_key,p_dataset,p_symbol,p_exchange,p_refresh_phase,p_requested_session_date,'queued',p_queued_at,p_queued_at,p_queued_at
  ) ON CONFLICT(queue_key) DO UPDATE SET
    next_attempt_at = LEAST(COALESCE(public.taiwan_data_refresh_queue_v5.next_attempt_at, EXCLUDED.next_attempt_at), EXCLUDED.next_attempt_at),
    updated_at = EXCLUDED.updated_at
  WHERE public.taiwan_data_refresh_queue_v5.status <> 'terminal'
  RETURNING job_id INTO v_job_id;
  IF v_job_id IS NULL THEN
    SELECT job_id INTO v_job_id FROM public.taiwan_data_refresh_queue_v5 WHERE queue_key = p_queue_key;
  END IF;
  RETURN v_job_id;
END $function$

CREATE OR REPLACE FUNCTION public.enrich_legacy_analysis_prior_payloads_v3_16_15(p_read jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_prior jsonb;
  v_expected integer;
  v_resolved integer;
BEGIN
  v_expected:=jsonb_array_length(coalesce(p_read->'priorRevisions','[]'::jsonb));
  WITH resolved AS MATERIALIZED (
    SELECT prior.ordinality,
      prior.value || jsonb_build_object('facts',payload.payload_json) AS value
    FROM jsonb_array_elements(coalesce(p_read->'priorRevisions','[]'::jsonb))
      WITH ORDINALITY prior(value,ordinality)
    JOIN public.legacy_analysis_revision_payloads_v3_13 payload
      ON payload.revision_id=(prior.value->>'revisionId')::uuid
      AND payload.symbol=prior.value->>'symbol'
      AND payload.material_change_hash=prior.value->>'materialChangeHash'
  )
  SELECT coalesce(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb),count(*)::integer
    INTO v_prior,v_resolved FROM resolved;
  IF v_resolved<>v_expected THEN
    RAISE EXCEPTION 'analysis_prior_payload_missing';
  END IF;
  RETURN jsonb_set(p_read,'{priorRevisions}',v_prior,false);
END $function$

CREATE OR REPLACE FUNCTION public.ensure_research_publication_bundle_v2(p_revision uuid, p_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i public.research_article_input_revisions_v2;b public.candidate_dossier_bundles;v jsonb;
BEGIN
 SELECT * INTO i FROM public.research_article_input_revisions_v2 WHERE revision_id=p_revision;
 IF NOT FOUND OR i.input_hash IS DISTINCT FROM p_hash OR i.research_scope<>'research_observed_v1'
 THEN RAISE EXCEPTION 'research_publication_input_missing';END IF;
 v:=jsonb_build_object('schemaVersion','research-bundle-lineage-v2','inputRevisionId',i.revision_id,'inputHash',i.input_hash,
  'researchCompanyId',i.research_company_id,'snapshotHash',i.snapshot_hash,'publishableResearch',false,
  'researchQualified',false,'strategyApproved',false,'entryEligible',false);
 INSERT INTO public.candidate_dossier_bundles(bundle_id,revision_kind,research_input_revision_id,research_company_id,research_snapshot_hash,input_hash,symbol,payload)
 VALUES(gen_random_uuid(),'research_input_v2',i.revision_id,i.research_company_id,i.snapshot_hash,i.input_hash,i.canonical_payload->'researchIdentity'->>'symbol',v)
 ON CONFLICT(research_input_revision_id,input_hash) WHERE revision_kind='research_input_v2' DO NOTHING;
 SELECT * INTO b FROM public.candidate_dossier_bundles WHERE revision_kind='research_input_v2' AND research_input_revision_id=i.revision_id AND input_hash=i.input_hash;
 IF b.bundle_id IS NULL OR b.payload IS DISTINCT FROM v THEN RAISE EXCEPTION 'research_publication_bundle_conflict';END IF;
 RETURN b.bundle_id;
END $function$

CREATE OR REPLACE FUNCTION public.fail_legacy_producer_job_v3_11(p_run uuid, p_job uuid, p_token uuid, p_failure opportunity_legacy_producer_failure_code_v3_11)
 RETURNS TABLE(status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_now timestamptz:=date_trunc('second',clock_timestamp());v_token_hash text:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
BEGIN
  SELECT run.* INTO v_run FROM public.legacy_producer_runs_v3_11 run WHERE run.run_id=p_run AND run.status='running'
    AND run.owner_token_hash=v_token_hash AND run.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT job.* INTO v_job FROM public.legacy_producer_jobs_v3_11 job WHERE job.run_id=p_run AND job.job_id=p_job AND job.status='leased'
    AND job.owner_token_hash=v_token_hash AND job.lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF p_failure='provider_unavailable' AND v_job.attempt<5 THEN UPDATE public.legacy_producer_jobs_v3_11 SET status='retryable',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;status:='running';
  ELSE UPDATE public.legacy_producer_jobs_v3_11 SET status=CASE
      WHEN p_failure='cancelled' THEN 'cancelled'::public.opportunity_legacy_producer_job_status_v3_11
      ELSE 'failed'::public.opportunity_legacy_producer_job_status_v3_11
    END,terminal_at=v_now,failure_code=p_failure,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=p_job;
    UPDATE public.legacy_producer_runs_v3_11 SET status=CASE WHEN p_failure='cancelled' THEN 'cancelled' ELSE 'failed' END,terminal_at=v_now,failure_code=p_failure,heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=p_run;status:=CASE WHEN p_failure='cancelled' THEN 'cancelled' ELSE 'failed' END;END IF;RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.fail_opportunity_manifest_v3(job_id uuid, owner_token text, requested_manifest_id uuid, requested_failure_code opportunity_manifest_failure_code_v3)
 RETURNS TABLE(status opportunity_manifest_status_v3, failure_code opportunity_manifest_failure_code_v3, terminal_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.opportunity_run_jobs_v3%ROWTYPE; v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT * INTO v_job FROM public.opportunity_run_jobs_v3 j
  WHERE j.job_id=$1 AND j.status='leased'
    AND j.lease_expires_at >= v_now
    AND j.owner_token_hash=encode(extensions.digest(convert_to($2,'utf8'),'sha256'),'hex')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_manifests_v3 m SET status='failed',failure_code=$4,terminal_at=v_now
  WHERE m.manifest_id=$3 AND m.status='building';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure'; END IF;
  UPDATE public.opportunity_run_jobs_v3 SET status='failed',failure_code=$4::text::public.opportunity_failure_code_v3,
    terminal_at=v_now,owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
  WHERE opportunity_run_jobs_v3.job_id=$1;
  UPDATE public.opportunity_runs SET status='failed',failure_code=$4::text::public.opportunity_failure_code_v3,terminal_at=v_now
  WHERE opportunity_runs.run_id=v_job.run_id AND status IN ('preparing','running');
  RETURN QUERY SELECT 'failed'::public.opportunity_manifest_status_v3,$4,v_now;
END
$function$

CREATE OR REPLACE FUNCTION public.fence_candidate_thesis_append_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_head public.candidate_thesis_qualifications_v1;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_thesis_read_committed_required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.stock_id::text, 6101));
  SELECT * INTO v_head FROM public.candidate_thesis_qualifications_v1
    WHERE stock_id=NEW.stock_id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NEW.parent_id IS DISTINCT FROM v_head.id THEN
    RAISE EXCEPTION 'research_thesis_head_changed';
  END IF;
  IF NEW.payload->>'reviewReceiptHash' IS DISTINCT FROM NEW.review_receipt_hash
    OR NEW.payload->>'status' IS DISTINCT FROM NEW.status
    OR NEW.payload->>'articleHash' IS DISTINCT FROM NEW.article_hash
    OR (NEW.payload->>'qualifiedAt')::timestamptz IS DISTINCT FROM NEW.qualified_at
    OR (NEW.payload->>'nextReviewAt')::timestamptz IS DISTINCT FROM NEW.next_review_at
    OR jsonb_typeof(NEW.payload->'materialEventIds') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'research_thesis_payload_mismatch';
  END IF;
  IF v_head.id IS NOT NULL THEN
    IF NOT ((NEW.payload->'materialEventIds') @> (v_head.payload->'materialEventIds')) THEN
      RAISE EXCEPTION 'research_thesis_events_not_reconciled';
    END IF;
    IF NEW.status IN ('qualified','rejected','needs_evidence') THEN
      IF NEW.qualified_at <= (CASE WHEN v_head.status IN ('stale','invalidated')
        THEN v_head.next_review_at ELSE v_head.qualified_at END) THEN
        RAISE EXCEPTION 'research_thesis_review_not_newer';
      END IF;
      IF v_head.status IN ('stale','invalidated') AND NEW.article_hash=v_head.article_hash THEN
        RAISE EXCEPTION 'research_thesis_revised_article_required';
      END IF;
    ELSE
      IF NEW.qualified_at<>v_head.qualified_at OR NEW.article_hash<>v_head.article_hash
        OR NEW.next_review_at < (CASE WHEN v_head.status IN ('stale','invalidated')
          THEN v_head.next_review_at ELSE v_head.qualified_at END) THEN
        RAISE EXCEPTION 'research_thesis_event_clock_invalid';
      END IF;
    END IF;
  END IF;
  NEW.created_at := GREATEST(clock_timestamp(), coalesce(v_head.created_at + interval '1 microsecond',clock_timestamp()));
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_research_dossier_insert_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i public.research_article_input_revisions_v2;a public.research_author_results_v2;r public.research_reviewer_results_v2;
 b public.candidate_dossier_bundles;d public.candidate_research_dossiers;
BEGIN
 IF NEW.revision_kind='legacy_detail_v1' THEN
  IF NEW.bundle_id IS NOT NULL THEN
   SELECT * INTO b FROM public.candidate_dossier_bundles WHERE bundle_id=NEW.bundle_id;
   IF b.bundle_id IS NULL OR b.revision_kind IS DISTINCT FROM 'legacy_detail_v1'
    OR b.input_hash IS DISTINCT FROM NEW.input_hash THEN RAISE EXCEPTION 'research_publication_branch_mismatch';END IF;
   IF TG_TABLE_NAME='candidate_research_dossiers' THEN
    IF b.revision_id IS DISTINCT FROM NEW.detail_snapshot_id THEN RAISE EXCEPTION 'research_publication_branch_mismatch';END IF;
   ELSE
    SELECT * INTO d FROM public.candidate_research_dossiers WHERE id=NEW.dossier_id;
    IF b.revision_id IS DISTINCT FROM NEW.revision_id OR d.id IS NULL OR d.revision_kind IS DISTINCT FROM 'legacy_detail_v1'
     OR d.detail_snapshot_id IS DISTINCT FROM NEW.revision_id OR d.bundle_id IS DISTINCT FROM NEW.bundle_id OR d.input_hash IS DISTINCT FROM NEW.input_hash
    THEN RAISE EXCEPTION 'research_publication_branch_mismatch';END IF;
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.revision_kind IS DISTINCT FROM 'research_input_v2' OR current_user<>'research_observed_rpc_owner'
 THEN RAISE EXCEPTION 'research_publication_writer_required';END IF;
 SELECT * INTO i FROM public.research_article_input_revisions_v2 WHERE revision_id=NEW.research_input_revision_id;
 SELECT * INTO a FROM public.research_author_results_v2 WHERE result_id=NEW.research_author_result_id;
 SELECT * INTO r FROM public.research_reviewer_results_v2 WHERE result_id=NEW.research_reviewer_result_id;
 SELECT * INTO b FROM public.candidate_dossier_bundles WHERE bundle_id=NEW.bundle_id;
 IF i.revision_id IS NULL OR a.result_id IS NULL OR r.result_id IS NULL OR b.bundle_id IS NULL
  OR b.revision_kind IS DISTINCT FROM 'research_input_v2' OR b.research_input_revision_id IS DISTINCT FROM i.revision_id
  OR b.research_company_id IS DISTINCT FROM i.research_company_id OR b.research_snapshot_hash IS DISTINCT FROM i.snapshot_hash
  OR b.input_hash IS DISTINCT FROM i.input_hash OR NEW.input_hash IS DISTINCT FROM i.input_hash
  OR NEW.research_company_id IS DISTINCT FROM i.research_company_id OR NEW.research_snapshot_hash IS DISTINCT FROM i.snapshot_hash
  OR NEW.source_seal_id IS DISTINCT FROM i.source_seal_id OR NEW.source_seal_id IS NULL
  OR a.payload->>'inputRevisionId' IS DISTINCT FROM i.revision_id::text OR a.payload->>'inputHash' IS DISTINCT FROM i.input_hash
  OR r.payload->>'authorResultId' IS DISTINCT FROM a.result_id::text OR r.payload->>'authorResultHash' IS DISTINCT FROM a.result_hash
  OR r.payload->>'inputRevisionId' IS DISTINCT FROM i.revision_id::text OR r.payload->>'inputHash' IS DISTINCT FROM i.input_hash
 THEN RAISE EXCEPTION 'research_publication_storage_binding';END IF;
 IF TG_TABLE_NAME='candidate_research_dossiers' THEN
  IF NEW.content IS DISTINCT FROM public.research_publication_content_v2(a.payload)
   OR NEW.source_references IS DISTINCT FROM a.payload->'validatedArticle'->'sources'
  THEN RAISE EXCEPTION 'research_publication_content_binding';END IF;
 ELSE
  SELECT * INTO d FROM public.candidate_research_dossiers WHERE id=NEW.dossier_id;
  IF d.id IS NULL OR d.revision_kind IS DISTINCT FROM 'research_input_v2' OR d.bundle_id IS DISTINCT FROM NEW.bundle_id
   OR d.research_input_revision_id IS DISTINCT FROM i.revision_id OR d.research_author_result_id IS DISTINCT FROM a.result_id
   OR d.research_reviewer_result_id IS DISTINCT FROM r.result_id OR d.source_seal_id IS DISTINCT FROM NEW.source_seal_id
  THEN RAISE EXCEPTION 'research_publication_receipt_binding';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_research_paper_book_append_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_head public.research_paper_book_revisions_v1;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.book_id,6102));
  SELECT * INTO v_head FROM public.research_paper_book_revisions_v1 WHERE book_id=NEW.book_id
    ORDER BY available_at DESC,revision_hash DESC LIMIT 1;
  IF NEW.parent_hash IS DISTINCT FROM v_head.revision_hash THEN RAISE EXCEPTION 'research_paper_book_head_changed'; END IF;
  IF v_head.revision_hash IS NOT NULL AND NEW.state->>'inceptionAt' IS DISTINCT FROM v_head.state->>'inceptionAt'
    THEN RAISE EXCEPTION 'research_paper_book_inception_changed'; END IF;
  IF v_head.state->>'activationAt' IS NOT NULL
    AND NEW.state->>'activationAt' IS DISTINCT FROM v_head.state->>'activationAt'
    THEN RAISE EXCEPTION 'research_paper_book_activation_changed'; END IF;
  IF v_head.state->>'inceptionAt' IS NOT NULL AND v_head.state->>'activationAt' IS NULL
    AND (NEW.state->>'activationAt')::timestamptz IS DISTINCT FROM
      greatest((v_head.state->>'inceptionAt')::timestamptz,v_head.available_at)
    THEN RAISE EXCEPTION 'research_paper_book_activation_invalid'; END IF;
  IF NEW.available_at>clock_timestamp() OR (v_head.revision_hash IS NOT NULL AND NEW.available_at<=v_head.available_at)
    THEN RAISE EXCEPTION 'research_paper_book_revision_time_invalid'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_research_publication_lineage_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i public.research_article_input_revisions_v2; b public.candidate_dossier_bundles; j public.research_deep_jobs_v1; c public.candidate_dossier_submission_receipts;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.revision_kind='research_input_v2' THEN RAISE EXCEPTION 'research_publication_v2_inert';END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.revision_kind IS DISTINCT FROM NEW.revision_kind THEN RAISE EXCEPTION 'research_publication_branch_immutable';END IF;
  IF OLD.revision_kind='research_input_v2' THEN
   IF TG_TABLE_NAME<>'candidate_dossier_outbox_v5' OR current_user<>'research_observed_rpc_owner'
    OR (to_jsonb(OLD)-ARRAY['status','attempts','lease_owner','lease_expires_at','receipt_id','last_submission_hash','updated_at'])
      IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','attempts','lease_owner','lease_expires_at','receipt_id','last_submission_hash','updated_at'])
   THEN RAISE EXCEPTION 'research_publication_transition_writer';END IF;
   SELECT * INTO j FROM public.research_deep_jobs_v1 WHERE job_id=OLD.deep_job_id;
   IF j.job_id IS NULL OR j.research_scope IS DISTINCT FROM 'research_observed_v1'
    OR j.status IS DISTINCT FROM 'running' OR j.attempts IS DISTINCT FROM OLD.deep_attempt
    OR j.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'research_publication_transition_job';END IF;
   IF OLD.status='queued' AND OLD.attempts=0 AND NEW.status='running' AND NEW.attempts=1
    AND NEW.lease_owner IS NOT DISTINCT FROM j.lease_owner AND NEW.lease_owner IS NOT NULL
    AND NEW.lease_expires_at IS NOT NULL AND NEW.lease_expires_at>clock_timestamp() AND NEW.lease_expires_at<=j.lease_expires_at
    AND NEW.receipt_id IS NULL AND NEW.last_submission_hash IS NULL THEN RETURN NEW;END IF;
   IF OLD.status='running' AND OLD.attempts=1 AND NEW.status='accepted' AND NEW.attempts=1
    AND OLD.lease_owner IS NOT DISTINCT FROM j.lease_owner AND OLD.lease_expires_at>clock_timestamp()
    AND NEW.lease_owner IS NULL AND NEW.lease_expires_at IS NULL AND NEW.receipt_id IS NOT NULL THEN
    SELECT * INTO c FROM public.candidate_dossier_submission_receipts WHERE submission_id=NEW.receipt_id;
    IF c.status='accepted' AND c.revision_kind='research_input_v2' AND c.bundle_id=OLD.bundle_id
     AND c.research_input_revision_id=OLD.research_input_revision_id AND c.input_hash=OLD.input_hash
     AND c.research_company_id=OLD.research_company_id AND c.research_snapshot_hash=OLD.research_snapshot_hash
     AND c.submission_hash=NEW.last_submission_hash THEN RETURN NEW;END IF;
   END IF;
   RAISE EXCEPTION 'research_publication_transition_invalid';
  END IF;
  -- Preserve v1 delivery transitions, but never rebind to a v2 bundle.
  IF EXISTS(SELECT FROM public.candidate_dossier_bundles WHERE bundle_id=NEW.bundle_id AND revision_kind<>'legacy_detail_v1')
  THEN RAISE EXCEPTION 'research_publication_branch_mismatch';END IF;
  RETURN NEW;
 END IF;
 IF NEW.revision_kind='legacy_detail_v1' THEN
  -- Outbox cannot disguise a v2 bundle as v1, even before a future writer exists.
  IF TG_TABLE_NAME='candidate_dossier_outbox_v5' AND EXISTS(
   SELECT FROM public.candidate_dossier_bundles WHERE bundle_id=NEW.bundle_id AND revision_kind<>'legacy_detail_v1')
  THEN RAISE EXCEPTION 'research_publication_branch_mismatch';END IF;
  RETURN NEW;
 END IF;
 IF NEW.revision_kind IS DISTINCT FROM 'research_input_v2' THEN RAISE EXCEPTION 'research_publication_branch_invalid';END IF;
 IF (TG_TABLE_NAME='candidate_dossier_bundles' AND current_user<>'research_input_preparation_owner_v2')
  OR (TG_TABLE_NAME='candidate_dossier_outbox_v5' AND current_user<>'research_observed_rpc_owner')
 THEN RAISE EXCEPTION 'research_publication_writer_required';END IF;
 SELECT * INTO i FROM public.research_article_input_revisions_v2 WHERE revision_id=NEW.research_input_revision_id;
 IF NOT FOUND OR i.research_scope<>'research_observed_v1' OR NEW.research_company_id IS DISTINCT FROM i.research_company_id
  OR NEW.research_snapshot_hash IS DISTINCT FROM i.snapshot_hash OR NEW.input_hash IS DISTINCT FROM i.input_hash
 THEN RAISE EXCEPTION 'research_publication_input_binding';END IF;
 IF TG_TABLE_NAME='candidate_dossier_bundles' THEN
  IF NEW.symbol IS DISTINCT FROM i.canonical_payload->'researchIdentity'->>'symbol'
   OR NEW.payload IS DISTINCT FROM jsonb_build_object('schemaVersion','research-bundle-lineage-v2',
    'inputRevisionId',i.revision_id,'inputHash',i.input_hash,'researchCompanyId',i.research_company_id,
    'snapshotHash',i.snapshot_hash,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false)
  THEN RAISE EXCEPTION 'research_publication_bundle_payload';END IF;
 ELSE
  SELECT * INTO b FROM public.candidate_dossier_bundles WHERE bundle_id=NEW.bundle_id;
  IF NOT FOUND OR b.revision_kind IS DISTINCT FROM 'research_input_v2'
   OR b.research_input_revision_id IS DISTINCT FROM NEW.research_input_revision_id
   OR b.research_company_id IS DISTINCT FROM NEW.research_company_id OR b.research_snapshot_hash IS DISTINCT FROM NEW.research_snapshot_hash
   OR b.input_hash IS DISTINCT FROM NEW.input_hash OR NEW.deep_job_id IS DISTINCT FROM i.job_id OR NEW.deep_attempt IS DISTINCT FROM i.attempt
   OR NEW.publication_kind IS DISTINCT FROM 'deep' OR NEW.status IS DISTINCT FROM 'queued'
   OR NEW.attempts IS DISTINCT FROM 0 OR NEW.receipt_id IS NOT NULL OR NEW.lease_owner IS NOT NULL OR NEW.lease_expires_at IS NOT NULL
   OR NEW.last_submission_hash IS NOT NULL OR NEW.last_error IS NOT NULL OR NEW.next_attempt_at IS NOT NULL
  THEN RAISE EXCEPTION 'research_publication_outbox_binding';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_research_strategy_record_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_parent public.research_strategy_records_v1;
BEGIN
  IF NEW.available_at>clock_timestamp() THEN RAISE EXCEPTION 'research_strategy_future_record'; END IF;
  IF NEW.kind='proposal' THEN
    PERFORM pg_advisory_xact_lock(2409,6003);
    IF EXISTS(SELECT 1 FROM public.research_strategy_records_v1 r WHERE r.kind='proposal'
      AND date_trunc('week',r.available_at AT TIME ZONE 'Asia/Taipei')=
        date_trunc('week',NEW.available_at AT TIME ZONE 'Asia/Taipei')
      AND r.record_hash<>NEW.record_hash) THEN RAISE EXCEPTION 'research_strategy_weekly_hypothesis_cap'; END IF;
  ELSE
    SELECT * INTO v_parent FROM public.research_strategy_records_v1 WHERE record_hash=NEW.parent_hash;
    IF NOT FOUND OR v_parent.proposal_hash<>NEW.proposal_hash OR v_parent.available_at>NEW.available_at
      OR v_parent.kind<>(CASE NEW.kind WHEN 'assessment' THEN 'proposal' WHEN 'validation' THEN 'assessment' ELSE 'validation' END)
      THEN RAISE EXCEPTION 'research_strategy_parent_binding_invalid'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.finish_research_model_v1(p_reservation uuid, p_owner text, p_outcome text, p_result_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_prior public.research_model_completions_v1;
BEGIN
  PERFORM pg_advisory_xact_lock(2409,6002);
  SELECT * INTO v_prior FROM public.research_model_completions_v1 WHERE reservation_id=p_reservation;
  IF FOUND THEN
    IF v_prior.owner<>p_owner OR v_prior.outcome<>p_outcome OR v_prior.result_hash<>p_result_hash
      THEN RAISE EXCEPTION 'research_model_completion_replay_mismatch'; END IF;
    RETURN true;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.research_model_reservations_v1
    WHERE reservation_id=p_reservation AND owner=p_owner AND lease_expires_at>clock_timestamp())
    THEN RAISE EXCEPTION 'research_model_lease_lost'; END IF;
  INSERT INTO public.research_model_completions_v1(reservation_id,owner,outcome,result_hash)
    VALUES(p_reservation,p_owner,p_outcome,p_result_hash);
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.freeze_legacy_provider_acquisition_v3_16_21(p_run_id uuid, p_job_id uuid, p_owner_token uuid, p_provider text, p_request_key text, p_stage text, p_source_cutoff timestamp with time zone, p_fetched_at timestamp with time zone, p_response_sha256 text, p_response_bytes integer, p_normalized_payload jsonb, p_normalized_payload_sha256 text, p_terminal_status text, p_evidence_root text, p_action_eligible boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_started_at timestamptz;
  v_producer_sha text;
  v_payload_sha text;
  v_evidence_root text;
  v_selected public.legacy_provider_acquisition_revisions_v3_16_21%ROWTYPE;
  v_inserted boolean:=false;
BEGIN
  IF p_provider!~'^[a-z0-9_]{2,40}$' OR p_request_key!~'^[0-9a-f]{64}$'
    OR p_stage!~'^[a-z_]{2,40}$' OR p_response_sha256!~'^[0-9a-f]{64}$'
    OR p_normalized_payload_sha256!~'^[0-9a-f]{64}$' OR p_evidence_root!~'^[0-9a-f]{64}$'
    OR p_response_bytes NOT BETWEEN 0 AND 67108864 OR jsonb_typeof(p_normalized_payload)<>'object'
    OR p_terminal_status NOT IN ('complete','provider_failed','auth_failed','missing_endpoint')
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';END IF;

  SELECT run.started_at,run.producer_commit_sha INTO v_started_at,v_producer_sha
  FROM public.legacy_producer_runs_v3_11 run
  JOIN public.legacy_producer_jobs_v3_11 job ON job.run_id=run.run_id
  WHERE run.run_id=p_run_id AND job.job_id=p_job_id
    AND run.owner_token_hash=encode(extensions.digest(convert_to(p_owner_token::text,'utf8'),'sha256'),'hex')
    AND job.owner_token_hash=encode(extensions.digest(convert_to(p_owner_token::text,'utf8'),'sha256'),'hex')
    AND job.status='leased' AND job.lease_expires_at>=v_now
    AND run.source_cutoff=p_source_cutoff AND run.status='running' AND run.lease_expires_at>=v_now;
  IF v_started_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';
  END IF;
  IF p_fetched_at<v_started_at OR p_fetched_at>v_now+interval '5 seconds' THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='provider_acquisition_time_invalid';
  END IF;

  v_payload_sha:=encode(extensions.digest(convert_to(public.legacy_canonical_json_v3_13(p_normalized_payload),'utf8'),'sha256'),'hex');
  IF v_payload_sha<>p_normalized_payload_sha256 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='provider_acquisition_payload_hash';
  END IF;
  v_evidence_root:=encode(extensions.digest(convert_to(public.legacy_canonical_json_v3_13(jsonb_build_array(
    'provider-acquisition-revision-v3.16.21',p_provider,p_request_key,p_run_id::text,p_stage,
    to_char(p_source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    to_char(p_fetched_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    p_response_sha256,p_response_bytes,p_normalized_payload_sha256,p_terminal_status,
    p_terminal_status='complete' AND p_action_eligible)),'utf8'),'sha256'),'hex');
  IF v_evidence_root<>p_evidence_root THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='provider_acquisition_evidence_root';
  END IF;

  INSERT INTO public.legacy_provider_acquisition_revisions_v3_16_21(
    provider,request_key,run_id,stage,source_cutoff,fetched_at,response_sha256,response_bytes,
    normalized_payload_sha256,normalized_payload,terminal_status,evidence_root,action_eligible,recorded_at)
  VALUES(p_provider,p_request_key,p_run_id,p_stage,p_source_cutoff,p_fetched_at,p_response_sha256,p_response_bytes,
    p_normalized_payload_sha256,p_normalized_payload,p_terminal_status,p_evidence_root,
    p_terminal_status='complete' AND p_action_eligible,v_now)
  ON CONFLICT(provider,request_key,source_cutoff) DO NOTHING
  RETURNING * INTO v_selected;
  v_inserted:=v_selected.acquisition_id IS NOT NULL;
  IF NOT v_inserted THEN
    SELECT row.* INTO STRICT v_selected FROM public.legacy_provider_acquisition_revisions_v3_16_21 row
    WHERE row.provider=p_provider AND row.request_key=p_request_key AND row.source_cutoff=p_source_cutoff;
  END IF;

  IF v_selected.evidence_root<>p_evidence_root THEN
    INSERT INTO public.legacy_provider_acquisition_conflicts_v3_16_21(provider,request_key,source_cutoff,
      selected_evidence_root,attempted_evidence_root,attempted_response_sha256,
      attempted_normalized_payload_sha256,producer_commit_sha,recorded_at)
    VALUES(p_provider,p_request_key,p_source_cutoff,v_selected.evidence_root,p_evidence_root,p_response_sha256,
      p_normalized_payload_sha256,v_producer_sha,v_now);
    RETURN jsonb_build_object('disposition','conflict','envelope',NULL);
  END IF;
  RETURN jsonb_build_object('disposition',CASE WHEN v_inserted THEN 'appended' ELSE 'reused' END,
    'envelope',public.read_legacy_provider_acquisition_v3_16_21(p_provider,p_request_key,p_source_cutoff));
END $function$

CREATE OR REPLACE FUNCTION public.get_link_audit_assignment_v3(requested_sample_manifest_id uuid, requested_sample_id text, requested_role internal_principal_role_v3, caller_principal uuid, nonce text, request_timestamp timestamp with time zone)
 RETURNS TABLE(disposition link_audit_assignment_disposition_v3, sample_manifest_id uuid, sample_id text, review_source_key source_key_v3, evidence_ref text, review_context text, review_mention_start_offset integer, review_mention_end_offset integer, normalized_token text, link_mode opportunity_link_mode_v3, engine_outcome opportunity_mention_outcome_v3, engine_reason opportunity_mention_reason_v3, engine_canonical_symbol text, review_evidence_hash text, assigned_label_role link_audit_label_role_v3, own_canonical_symbol text, own_no_link boolean, reviewer_one_canonical_symbol text, reviewer_one_no_link boolean, reviewer_two_canonical_symbol text, reviewer_two_no_link boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz:=clock_timestamp(); v_sample public.opportunity_link_audit_samples%ROWTYPE;
  v_one public.opportunity_link_audit_labels%ROWTYPE; v_two public.opportunity_link_audit_labels%ROWTYPE;
  v_own public.opportunity_link_audit_labels%ROWTYPE;
  v_adjudication public.opportunity_link_audit_labels%ROWTYPE;
  v_disposition public.link_audit_assignment_disposition_v3;
  v_role public.link_audit_label_role_v3;
BEGIN
  IF $3 NOT IN ('link_reviewer','link_adjudicator') THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_requested_role'; END IF;
  IF $5 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now-$6)))>300 THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($4,$3,v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  SELECT * INTO v_sample FROM public.opportunity_link_audit_samples s WHERE s.sample_manifest_id=$1 AND s.sample_id=$2 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable'; END IF;
  IF v_sample.review_evidence_hash<>encode(extensions.digest(convert_to(
    jsonb_build_array(
      'link-audit-review-evidence-v3.0',v_sample.run_id,v_sample.claim_id,
      v_sample.mention_ordinal,jsonb_build_array(
        v_sample.connector,v_sample.evidence_ref,v_sample.review_context,
        v_sample.review_mention_start_offset,v_sample.review_mention_end_offset,
        v_sample.normalized_token,v_sample.link_mode,v_sample.engine_outcome,
        v_sample.engine_reason,v_sample.engine_canonical_symbol
      )
    )::text,'utf8'
  ),'sha256'),'hex') THEN
    RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at) VALUES($4,$5,$6,v_now);
  SELECT * INTO v_one FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='reviewer_1';
  SELECT * INTO v_two FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='reviewer_2';
  SELECT * INTO v_adjudication FROM public.opportunity_link_audit_labels l
    WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.label_role='adjudicator';
  SELECT * INTO v_own FROM public.opportunity_link_audit_labels l WHERE l.sample_manifest_id=$1 AND l.sample_id=$2 AND l.reviewer_principal_id=$4;
  IF $3='link_reviewer' THEN
    IF v_own.label_role='adjudicator' THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_already_other_branch'; END IF;
    IF v_own.label_role IN ('reviewer_1','reviewer_2') THEN v_role:=v_own.label_role;v_disposition:='reviewer_existing_label';
    ELSIF v_one.label_role IS NULL THEN v_role:='reviewer_1';v_disposition:='reviewer_open_slot';
    ELSIF v_two.label_role IS NULL THEN v_role:='reviewer_2';v_disposition:='reviewer_open_slot';
    ELSE v_role:=NULL;v_disposition:='reviewer_slots_full'; END IF;
  ELSE
    IF v_own.label_role IN ('reviewer_1','reviewer_2') THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_not_distinct'; END IF;
    IF v_adjudication.label_role='adjudicator' AND
      v_adjudication.reviewer_principal_id<>$4
    THEN v_role:=NULL;v_disposition:='adjudication_completed';
    ELSIF v_adjudication.label_role='adjudicator' THEN
      v_role:='adjudicator';v_own:=v_adjudication;
      v_disposition:='adjudicator_existing_label';
    ELSIF v_one.label_role IS NULL OR v_two.label_role IS NULL THEN v_disposition:='adjudication_pending';
    ELSIF (v_one.canonical_symbol,v_one.no_link) IS NOT DISTINCT FROM (v_two.canonical_symbol,v_two.no_link) THEN v_disposition:='adjudication_not_required';
    ELSE v_role:='adjudicator';v_disposition:='adjudicator_open'; END IF;
  END IF;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,
    input_hash,disposition,recorded_at
  ) VALUES(
    'get_link_audit_assignment_v3',$4,'link_label',$1,
    encode(extensions.digest(convert_to(
      jsonb_build_array($1,$2,$3,$6)::text,'utf8'
    ),'sha256'),'hex'),
    v_disposition::text::public.opportunity_rpc_audit_disposition_v3,v_now
  );
  RETURN QUERY SELECT v_disposition,$1,$2,
    v_sample.connector::public.source_key_v3,v_sample.evidence_ref,v_sample.review_context,
    v_sample.review_mention_start_offset,v_sample.review_mention_end_offset,v_sample.normalized_token,
    v_sample.link_mode,v_sample.engine_outcome,v_sample.engine_reason,v_sample.engine_canonical_symbol,
    v_sample.review_evidence_hash,v_role,
    CASE WHEN v_disposition IN ('reviewer_existing_label','adjudicator_existing_label')
      THEN v_own.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('reviewer_existing_label','adjudicator_existing_label')
      THEN v_own.no_link ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_one.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_one.no_link ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_two.canonical_symbol ELSE NULL END,
    CASE WHEN v_disposition IN ('adjudicator_open','adjudicator_existing_label')
      THEN v_two.no_link ELSE NULL END;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';
END
$function$

CREATE OR REPLACE FUNCTION public.guard_legacy_radar_projection_insert_v3_13()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_latest public.legacy_radar_projections_v3_11%ROWTYPE;
  v_latest_correctness jsonb;
  v_new_correctness jsonb;
  v_latest_evaluated_at timestamptz;
  v_new_evaluated_at timestamptz;
  v_latest_published_at timestamptz;
  v_new_published_at timestamptz;
  v_expected_window text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW."window"::text,0));
  SELECT projection.* INTO v_latest
  FROM public.legacy_radar_projections_v3_11 projection
  WHERE projection."window"=NEW."window"
  ORDER BY projection.as_of DESC,projection.created_at DESC,projection.projection_id ASC LIMIT 1;

  IF v_latest.projection_id IS NULL THEN RETURN NEW;END IF;
  IF NEW.as_of<v_latest.as_of THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='non_monotonic_projection';
  END IF;
  IF NEW.as_of>v_latest.as_of OR NEW.payload_sha256=v_latest.payload_sha256 THEN
    RETURN NEW;
  END IF;

  v_latest_correctness:=v_latest.payload_json->'sourceLedCorrectness';
  v_new_correctness:=NEW.payload_json->'sourceLedCorrectness';
  v_expected_window:=CASE WHEN NEW."window"::text='three_day' THEN 'hot' ELSE NEW."window"::text END;

  IF jsonb_typeof(v_latest_correctness) IS DISTINCT FROM 'object'
    OR jsonb_typeof(v_new_correctness) IS DISTINCT FROM 'object'
    OR coalesce(v_new_correctness->>'window','')<>v_expected_window
    OR coalesce(v_new_correctness->>'asOf','')!~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?Z$'
    OR (v_new_correctness->>'asOf')::timestamptz<>NEW.as_of
    OR coalesce(v_latest_correctness->>'evaluatedAt','')!~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?Z$'
    OR coalesce(v_new_correctness->>'evaluatedAt','')!~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?Z$'
    OR coalesce(v_latest_correctness->>'publishedAt','')!~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?Z$'
    OR coalesce(v_new_correctness->>'publishedAt','')!~
      '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?Z$'
    OR coalesce(v_new_correctness#>>'{producerIdentity,commitSha}','')<>NEW.producer_commit_sha
    OR coalesce(NEW.payload_json#>>'{releaseIdentity,producerCommitSha}','')<>NEW.producer_commit_sha
    OR coalesce(v_new_correctness#>>'{producerIdentity,workerSha256}','')<>NEW.worker_sha256
  THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='projection_release_identity_invalid';
  END IF;

  v_latest_evaluated_at:=(v_latest_correctness->>'evaluatedAt')::timestamptz;
  v_new_evaluated_at:=(v_new_correctness->>'evaluatedAt')::timestamptz;
  v_latest_published_at:=(v_latest_correctness->>'publishedAt')::timestamptz;
  v_new_published_at:=(v_new_correctness->>'publishedAt')::timestamptz;
  IF v_new_evaluated_at<=v_latest_evaluated_at
    OR v_new_published_at<v_new_evaluated_at
    OR v_new_published_at<=v_latest_published_at
  THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='projection_evaluation_time_conflict';
  END IF;
  IF NEW.producer_commit_sha=v_latest.producer_commit_sha THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='projection_same_producer_nondeterminism';
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN SQLSTATE 'PT409' THEN RAISE;
  WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='projection_release_identity_invalid';
END $function$

CREATE OR REPLACE FUNCTION public.handoff_research_deep_model_v1(p_job_id uuid, p_owner text, p_attempt integer, p_article_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_job public.research_deep_jobs_v1; v_reservation uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(2409,6002);
  SELECT * INTO v_job FROM public.research_deep_jobs_v1 WHERE job_id=p_job_id AND research_scope='formal_v1' FOR UPDATE;
  IF NOT FOUND OR v_job.status<>'running' OR v_job.lease_owner IS DISTINCT FROM p_owner
    OR v_job.attempts<>p_attempt OR v_job.lease_expires_at<=clock_timestamp()
    OR p_article_hash IS NULL OR p_article_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'research_deep_handoff_fence_lost'; END IF;
  SELECT reservation_id INTO v_reservation FROM public.research_model_reservations_v1
    WHERE role='company_research' AND owner=p_owner AND work_key='deep:'||p_job_id||':'||p_attempt::text;
  IF v_reservation IS NULL THEN RAISE EXCEPTION 'research_deep_model_reservation_missing'; END IF;
  RETURN public.finish_research_model_v1(v_reservation,p_owner,'completed',p_article_hash);
END $function$

CREATE OR REPLACE FUNCTION public.heartbeat_legacy_producer_job_v3_11(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz:=date_trunc('second',clock_timestamp());
BEGIN
  IF p_lease<>120 THEN RETURN false; END IF;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11
  WHERE run_id=p_run AND status='running' AND owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11
  WHERE run_id=p_run AND job_id=p_job AND status='leased' AND owner_token_hash=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex')
    AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  UPDATE public.legacy_producer_jobs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run AND job_id=p_job;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.insider_expected_document_v1(p_id uuid, p_index integer, p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE s public.insider_snapshots_v1; parsed jsonb; d jsonb; row_hash text; body text; metadata jsonb;
BEGIN
 SELECT * INTO STRICT s FROM public.insider_snapshots_v1 WHERE id=p_id;
 parsed:=public.insider_row_v1(p_row,s.dataset); IF parsed IS NULL THEN RETURN NULL; END IF;
 d:=public.insider_dataset_v1(s.dataset); row_hash:=encode(extensions.digest(convert_to(p_row::text,'UTF8'),'sha256'),'hex');
 body:='Official insider disclosure; symbol='||(parsed->>'symbol')||'; kind='||(d->>'kind')||'; current_shares='||coalesce(parsed->>'currentShares','unknown')||'; trust_shares='||coalesce(parsed->>'trustShares','unknown')||'; declared_shares='||coalesce(parsed->>'declaredShares','unknown')||'; confirmed_shares=unknown; snapshot='||s.id||'; raw_index='||p_index||'; row_sha256='||row_hash||'. Full private raw retained; not confirmed trading.';
 IF octet_length(body)>500 THEN RAISE EXCEPTION 'insider_projection_content_bound'; END IF;
 metadata:=jsonb_build_object('connector','official_insider_snapshot_v1','dataset',d->>'url','market',d->>'market','snapshot_id',s.id,'raw_index',p_index,'row_sha256',row_hash,'response_sha256',s.raw_sha256,'observed_at',s.observed_at,'attempted_at',s.attempted_at,'parser_identity',s.parser_identity,'rights_identity',s.rights_identity,'issue_date',parsed->'outputDate','publication_precision',parsed->'publicationPrecision','source_report_period',parsed->'sourcePeriod','insider_evidence',parsed||jsonb_build_object('kind',CASE WHEN d->>'kind'='holding' THEN 'holding_snapshot' ELSE 'transfer_declaration' END),'delta_holding',NULL,'transfer_shares',NULL,'raw_retention','private_snapshot','content_representation','bounded_summary_linked_full_private_raw');
 RETURN jsonb_build_object('documentUrl',(d->>'url')||'#si-insider-snapshot-'||s.id||'-'||p_index||'-'||row_hash,'title','Official insider disclosure '||(parsed->>'symbol'),'summary',body,'contentText',body,'publishedAt',NULL,'symbols',jsonb_build_array(parsed->>'symbol'),'metadata',metadata);
END $function$

CREATE OR REPLACE FUNCTION public.insider_row_v1(p_row jsonb, p_dataset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d jsonb:=public.insider_dataset_v1(p_dataset); holding boolean; otc boolean;
 sk text; nk text; rk text; dk text; required text[]; k text; v text; nums jsonb:='{}';
 output_date text; source_period text; report_period text; symbol text; person text; company text; role_text text; dt date;
BEGIN
 IF d IS NULL OR jsonb_typeof(p_row) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'insider_schema_invalid_row'; END IF;
 holding:=d->>'kind'='holding'; otc:=d->>'market'='TPEX' AND NOT holding;
 sk:=CASE WHEN otc THEN 'SecuritiesCompanyCode' ELSE '公司代號' END;
 nk:=CASE WHEN otc THEN 'CompanyName' ELSE '公司名稱' END;
 rk:=CASE WHEN holding THEN '職稱' WHEN otc THEN '申請人身分' ELSE '申報人身分' END;
 dk:=CASE WHEN otc THEN 'Date' ELSE '出表日期' END;
 required:=ARRAY[sk,nk,rk,'姓名',dk] || CASE WHEN holding THEN ARRAY['資料年月','目前持股'] ELSE ARRAY['預定轉讓方式及股數-轉讓股數','目前持有股數-自有持股','目前持有股數-保留運用決定權信託股數','預定轉讓方式及股數-轉讓方式','有效轉讓期間'] END;
 FOREACH k IN ARRAY required LOOP
  IF jsonb_typeof(p_row->k) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'insider_schema_required_field'; END IF;
  IF octet_length(p_row->>k)>512 THEN RAISE EXCEPTION 'insider_projection_field_unsupported'; END IF;
 END LOOP;
 v:=public.insider_trim_v1(p_row->>dk);
 IF v<>'' THEN
  IF v !~ '^[0-9]{7}$' THEN RAISE EXCEPTION 'insider_schema_invalid_date'; END IF;
  dt:=make_date(substring(v,1,3)::integer+1911,substring(v,4,2)::integer,substring(v,6,2)::integer);
  output_date:=to_char(dt,'YYYY-MM-DD');
 END IF;
 FOREACH k IN ARRAY CASE WHEN holding THEN ARRAY['目前持股'] ELSE ARRAY['目前持有股數-自有持股','目前持有股數-保留運用決定權信託股數','預定轉讓方式及股數-轉讓股數'] END LOOP
  v:=replace(public.insider_trim_v1(p_row->>k),',','');
  IF v<>'' AND (v !~ '^[0-9]+$') THEN RAISE EXCEPTION 'insider_schema_invalid_shares'; END IF;
  IF v<>'' AND v::numeric>9007199254740991 THEN RAISE EXCEPTION 'insider_schema_invalid_shares'; END IF;
  nums:=nums || jsonb_build_object(k,CASE WHEN v='' THEN NULL ELSE v::bigint END);
 END LOOP;
 source_period:=public.insider_trim_v1(p_row->>'資料年月');
 IF holding THEN
  IF source_period IS NULL OR source_period !~ '^[0-9]{5}$' OR substring(source_period,4,2)::integer NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'insider_schema_invalid_period'; END IF;
  report_period:=(substring(source_period,1,3)::integer+1911)::text || '-' || substring(source_period,4,2);
 ELSE report_period:=coalesce(nullif(public.insider_trim_v1(p_row->>'有效轉讓期間'),''),output_date,'unknown_period'); END IF;
 symbol:=public.insider_trim_v1(p_row->>sk); person:=public.insider_trim_v1(p_row->>'姓名'); company:=public.insider_trim_v1(p_row->>nk); role_text:=public.insider_trim_v1(p_row->>rk);
 IF symbol !~ '^[1-9][0-9]{3}$' OR person='' OR company='' OR role_text='' THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('symbol',symbol,'person',person,'companyName',company,'role',role_text,
  'reportPeriod',report_period,'sourcePeriod',nullif(source_period,''),'outputDate',output_date,
  'currentShares',nums->CASE WHEN holding THEN '目前持股' ELSE '目前持有股數-自有持股' END,
  'trustShares',nums->'目前持有股數-保留運用決定權信託股數','declaredShares',nums->'預定轉讓方式及股數-轉讓股數',
  'transferMethod',CASE WHEN holding THEN NULL ELSE nullif(public.insider_trim_v1(p_row->>'預定轉讓方式及股數-轉讓方式'),'') END,
  'confirmedShares',NULL,'publishedAt',NULL,'publicationPrecision',CASE WHEN output_date IS NULL THEN 'unknown' ELSE 'date' END);
END $function$

CREATE OR REPLACE FUNCTION public.insider_snapshot_assert_v1(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE s public.insider_snapshots_v1; rows jsonb;
BEGIN
 SELECT * INTO s FROM public.insider_snapshots_v1 WHERE id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'insider_snapshot_missing'; END IF;
 IF s.parser_identity<>'insider-db-projection-v1' OR s.rights_identity<>'official-insider-private-research-retain-v1' THEN RAISE EXCEPTION 'insider_snapshot_parser_or_rights_changed'; END IF;
 IF encode(extensions.digest(s.raw,'sha256'),'hex')<>s.raw_sha256 THEN RAISE EXCEPTION 'insider_snapshot_corrupt'; END IF;
 rows:=convert_from(s.raw,'UTF8')::jsonb;
 IF jsonb_typeof(rows) IS DISTINCT FROM 'array' OR jsonb_array_length(rows)<>s.row_count THEN RAISE EXCEPTION 'insider_snapshot_corrupt'; END IF;
 RETURN rows;
END $function$

CREATE OR REPLACE FUNCTION public.insider_snapshot_projection_bound_v1(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rows jsonb; doc jsonb; i integer; page_bytes bigint:=2;
BEGIN
 rows:=public.insider_snapshot_assert_v1(p_id);
 IF jsonb_array_length(rows)=0 THEN RETURN; END IF;
 FOR i IN 0..jsonb_array_length(rows)-1 LOOP
  IF i%500=0 THEN page_bytes:=2; END IF;
  doc:=public.insider_expected_document_v1(p_id,i,rows->i);
  IF doc IS NOT NULL THEN page_bytes:=page_bytes+octet_length(doc::text)+2; END IF;
  IF page_bytes>4194304-16384 THEN RAISE EXCEPTION 'insider_projection_transport_bound'; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.insider_snapshot_run_v1(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb; d integer; token uuid; tokens uuid[]:='{}'; bytes_used bigint; records_used bigint; pending bigint;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  THEN RAISE EXCEPTION 'insider_write_read_committed_required'; END IF;
 IF p_run IS NULL THEN RAISE EXCEPTION 'insider_run_required'; END IF;
 PERFORM pg_advisory_xact_lock(2410,8001);
 IF NOT EXISTS(SELECT 1 FROM public.insider_acquisition_runs_v1 WHERE id=p_run) THEN
  IF (SELECT count(*) FROM public.insider_acquisition_runs_v1)>=128 THEN RAISE EXCEPTION 'insider_run_capacity'; END IF;
  FOR d IN 0..4 LOOP
   PERFORM pg_advisory_xact_lock(2411,d);
   SELECT a.id INTO token FROM public.insider_acquisitions_v1 a JOIN public.insider_snapshot_progress_v1 p ON p.snapshot_id=a.snapshot_id WHERE a.dataset=d AND NOT p.complete;
   IF token IS NULL THEN SELECT a.id INTO token FROM public.insider_acquisitions_v1 a WHERE a.dataset=d AND a.snapshot_id IS NULL; END IF;
   IF token IS NULL THEN INSERT INTO public.insider_acquisitions_v1(dataset) VALUES(d) RETURNING id INTO token; END IF;
   tokens:=array_append(tokens,token);
  END LOOP;
  SELECT coalesce(sum(octet_length(raw)),0),count(*) INTO bytes_used,records_used FROM public.insider_snapshots_v1;
  SELECT count(*) INTO pending FROM public.insider_acquisitions_v1 WHERE snapshot_id IS NULL;
  IF bytes_used+pending*12582912>134217728 OR records_used+pending>32 THEN RAISE EXCEPTION 'insider_acquisition_reserved_capacity'; END IF;
  -- Exception above rolls back proposed tokens too. All five subscriptions precede fetch.
  INSERT INTO public.insider_acquisition_runs_v1(id) VALUES(p_run);
  INSERT INTO public.insider_run_members_v1(run_id,dataset,acquisition_token,snapshot_id)
   SELECT p_run,a.dataset,a.id,a.snapshot_id FROM public.insider_acquisitions_v1 a WHERE a.id=ANY(tokens);
  IF NOT EXISTS(SELECT 1 FROM public.insider_run_members_v1 WHERE run_id=p_run AND snapshot_id IS NULL) THEN
   UPDATE public.insider_acquisition_runs_v1 SET frozen_at=clock_timestamp() WHERE id=p_run;
  END IF;
 END IF;
 SELECT jsonb_build_object('runId',p_run,'frozen',r.frozen_at IS NOT NULL,'members',coalesce((
  SELECT jsonb_agg(CASE WHEN m.snapshot_id IS NULL THEN jsonb_build_object('dataset',m.dataset,'snapshotId',NULL,'acquisitionToken',m.acquisition_token,'complete',false)
   ELSE jsonb_build_object('dataset',m.dataset,'snapshotId',m.snapshot_id,'acquisitionToken',m.acquisition_token,'complete',p.complete,'offset',p.offset_rows,'generation',p.generation,'totalRows',s.row_count,'observedAt',s.observed_at,'attemptedAt',s.attempted_at,'hash',s.raw_sha256) END ORDER BY m.dataset)
  FROM public.insider_run_members_v1 m LEFT JOIN public.insider_snapshot_progress_v1 p ON p.snapshot_id=m.snapshot_id LEFT JOIN public.insider_snapshots_v1 s ON s.id=m.snapshot_id WHERE m.run_id=p_run),'[]'::jsonb)) INTO result FROM public.insider_acquisition_runs_v1 r WHERE r.id=p_run;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.legacy_canonical_json_v3_13(value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE kind text:=jsonb_typeof(value);result text:='';member record;first boolean:=true;
  number_text text;
BEGIN
  IF kind='object' THEN
    result:='{';
    FOR member IN SELECT key,item FROM jsonb_each(value) entry(key,item) ORDER BY key COLLATE "C" LOOP
      IF NOT first THEN result:=result||',';END IF;first:=false;
      result:=result||to_jsonb(member.key)::text||':'||public.legacy_canonical_json_v3_13(member.item);
    END LOOP;
    RETURN result||'}';
  ELSIF kind='array' THEN
    result:='[';
    FOR member IN SELECT item FROM jsonb_array_elements(value) WITH ORDINALITY entry(item,ordinal) ORDER BY ordinal LOOP
      IF NOT first THEN result:=result||',';END IF;first:=false;
      result:=result||public.legacy_canonical_json_v3_13(member.item);
    END LOOP;
    RETURN result||']';
  ELSIF kind='number' THEN
    number_text:=value#>>'{}';
    IF number_text~'[.]' AND number_text!~'[eE]' THEN
      number_text:=regexp_replace(regexp_replace(number_text,'0+$','','g'),'[.]$','','g');
    END IF;
    IF number_text IN ('-0','-0.0') THEN number_text:='0';END IF;
    RETURN number_text;
  END IF;
  RETURN value::text;
END $function$

CREATE OR REPLACE FUNCTION public.legacy_valid_decision_envelope_strict_v3_13(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE authority text;readiness text;action text;kind text;technical_state text;
  summary jsonb;plan jsonb;range_value jsonb;threshold jsonb;current_price numeric;base_value numeric;base_raw numeric;
  low_value numeric;high_value numeric;upside numeric;discount numeric;entry_low numeric;
  entry_high numeric;invalidation numeric;reward_risk numeric;expected_reward_risk numeric;
  raw_upside numeric;raw_discount numeric;raw_reward_risk numeric;has_geometry boolean;has_no_geometry boolean;
  as_of_value text;
BEGIN
  IF jsonb_typeof(value)<>'object' OR value->>'version'<>'decision-envelope-v3.13.0'
    OR jsonb_typeof(value->'decisionRevisionId') IS DISTINCT FROM 'string'
    OR (value->>'decisionRevisionId')!~'^decision-v3[.]13:[0-9a-f]{64}$'
    OR jsonb_typeof(value->'reason') IS DISTINCT FROM 'string'
    OR length(value->>'reason')=0 OR value->>'reason'<>btrim(value->>'reason')
    OR jsonb_typeof(value->'whyNow') IS DISTINCT FROM 'string'
    OR length(value->>'whyNow')=0 OR value->>'whyNow'<>btrim(value->>'whyNow')
    OR jsonb_typeof(value->'blockers') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(value->'blockers') blocker(item)
      WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}')=0 OR item#>>'{}'<>btrim(item#>>'{}'))
    OR (SELECT count(DISTINCT item) FROM jsonb_array_elements(value->'blockers') blocker(item))
      <>jsonb_array_length(value->'blockers')
  THEN RETURN false;END IF;
  authority:=value->>'recommendationAuthority';readiness:=value->>'valuationReadiness';action:=value->>'userAction';
  IF authority NOT IN ('formal','conditional_research','none')
    OR readiness NOT IN ('complete','relative_only','missing','stale','conflict')
    OR action NOT IN ('buy','accumulate','research_starter','wait_breakout','wait_reclaim','avoid_chase','avoid','unavailable')
    OR (authority='formal' AND readiness<>'complete')
    OR (authority='conditional_research' AND readiness<>'relative_only')
    OR (authority='none' AND readiness NOT IN ('missing','stale','conflict'))
  THEN RETURN false;END IF;
  summary:=value->'valuationSummary';
  IF jsonb_typeof(summary)<>'object' OR jsonb_typeof(summary->'sourceRefs') IS DISTINCT FROM 'array'
    OR jsonb_typeof(summary->'blockers') IS DISTINCT FROM 'array' OR summary->'blockers'<>value->'blockers'
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(summary->'sourceRefs') source_ref(item)
      WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}')=0 OR item#>>'{}'<>btrim(item#>>'{}'))
    OR (SELECT count(DISTINCT item) FROM jsonb_array_elements(summary->'sourceRefs') source_ref(item))
      <>jsonb_array_length(summary->'sourceRefs')
  THEN RETURN false;END IF;
  kind:=summary->>'kind';
  IF (authority='formal' AND kind<>'formal_range')
    OR (authority='conditional_research' AND kind<>'relative_reference_band')
    OR (authority='none' AND kind<>'unavailable') THEN RETURN false;END IF;
  IF authority='none' THEN
    IF summary->'formalRange' IS DISTINCT FROM 'null'::jsonb OR summary->'relativeBand' IS DISTINCT FROM 'null'::jsonb
      OR summary->'baseUpsidePct' IS DISTINCT FROM 'null'::jsonb OR summary->'relativeDiscountPct' IS DISTINCT FROM 'null'::jsonb
      OR summary->'method' IS DISTINCT FROM 'null'::jsonb OR summary->'asOf' IS DISTINCT FROM 'null'::jsonb
      OR summary->'thresholdAuthority' IS DISTINCT FROM 'null'::jsonb
      OR jsonb_array_length(summary->'sourceRefs')<>0
      OR (summary->'currentPrice' IS DISTINCT FROM 'null'::jsonb AND (
        jsonb_typeof(summary->'currentPrice') IS DISTINCT FROM 'number' OR (summary->>'currentPrice')::numeric<=0))
      OR value->'entryPlan' IS DISTINCT FROM 'null'::jsonb
      OR (readiness IN ('missing','stale') AND action<>'unavailable')
      OR (action='avoid' AND readiness<>'conflict')
      OR action NOT IN ('avoid','unavailable') THEN RETURN false;END IF;
    RETURN action<>'unavailable' OR jsonb_array_length(value->'blockers')>0;
  END IF;
  IF jsonb_typeof(summary->'currentPrice') IS DISTINCT FROM 'number'
    OR (summary->>'currentPrice')::numeric<=0 OR jsonb_typeof(summary->'method') IS DISTINCT FROM 'string'
    OR length(summary->>'method')=0 OR summary->>'method'<>btrim(summary->>'method')
    OR jsonb_typeof(summary->'asOf') IS DISTINCT FROM 'string'
    OR jsonb_array_length(summary->'sourceRefs')=0 THEN RETURN false;END IF;
  as_of_value:=summary->>'asOf';
  IF as_of_value~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    PERFORM as_of_value::date;
  ELSIF NOT public.legacy_valid_rfc3339_v3_13(as_of_value) THEN RETURN false;END IF;
  current_price:=(summary->>'currentPrice')::numeric;
  threshold:=summary->'thresholdAuthority';
  range_value:=CASE WHEN authority='formal' THEN summary->'formalRange' ELSE summary->'relativeBand' END;
  IF jsonb_typeof(range_value)<>'object' THEN RETURN false;END IF;
  IF authority='formal' THEN
    IF jsonb_typeof(range_value->'bear') IS DISTINCT FROM 'number'
      OR jsonb_typeof(range_value->'base') IS DISTINCT FROM 'number'
      OR jsonb_typeof(range_value->'bull') IS DISTINCT FROM 'number'
      OR jsonb_typeof(summary->'baseUpsidePct') IS DISTINCT FROM 'number'
      OR summary->'relativeBand' IS DISTINCT FROM 'null'::jsonb
      OR summary->'relativeDiscountPct' IS DISTINCT FROM 'null'::jsonb
      OR jsonb_typeof(threshold) IS DISTINCT FROM 'object' OR threshold->>'kind'<>'formal'
      OR jsonb_typeof(threshold->'baseTargetRaw') IS DISTINCT FROM 'number' THEN RETURN false;END IF;
    low_value:=(range_value->>'bear')::numeric;base_value:=(range_value->>'base')::numeric;
    high_value:=(range_value->>'bull')::numeric;upside:=(summary->>'baseUpsidePct')::numeric;
    base_raw:=(threshold->>'baseTargetRaw')::numeric;raw_upside:=100*(base_raw/current_price-1);
    IF low_value<=0 OR low_value>base_value OR base_value>high_value
      OR base_raw<=0 OR round(base_raw,2)<>base_value OR upside<>round(raw_upside,1) THEN RETURN false;END IF;
  ELSE
    IF jsonb_typeof(range_value->'low') IS DISTINCT FROM 'number'
      OR jsonb_typeof(range_value->'base') IS DISTINCT FROM 'number'
      OR jsonb_typeof(range_value->'high') IS DISTINCT FROM 'number'
      OR jsonb_typeof(summary->'relativeDiscountPct') IS DISTINCT FROM 'number'
      OR summary->'formalRange' IS DISTINCT FROM 'null'::jsonb
      OR summary->'baseUpsidePct' IS DISTINCT FROM 'null'::jsonb
      OR jsonb_typeof(threshold) IS DISTINCT FROM 'object' OR threshold->>'kind'<>'relative'
      OR jsonb_typeof(threshold->'currentMultiple') IS DISTINCT FROM 'number'
      OR jsonb_typeof(threshold->'referenceMultiple') IS DISTINCT FROM 'number'
      OR jsonb_typeof(threshold->'historySessions') IS DISTINCT FROM 'number'
      OR jsonb_typeof(threshold->'sectorPeers') IS DISTINCT FROM 'number'
      OR threshold->>'algorithm'<>'official-relative-pe-evidence-v1'
      OR coalesce(threshold->>'evidenceRoot','')!~'^[0-9a-f]{64}$'
      OR coalesce(threshold->>'currentObservationRoot','')!~'^[0-9a-f]{64}$'
      OR coalesce(threshold->>'historyMembershipRoot','')!~'^[0-9a-f]{64}$'
      OR coalesce(threshold->>'sectorMembershipRoot','')!~'^[0-9a-f]{64}$' THEN RETURN false;END IF;
    low_value:=(range_value->>'low')::numeric;base_value:=(range_value->>'base')::numeric;
    high_value:=(range_value->>'high')::numeric;discount:=(summary->>'relativeDiscountPct')::numeric;
    IF low_value<=0 OR low_value>base_value OR base_value>high_value
      OR (threshold->>'currentMultiple')::numeric<=0 OR (threshold->>'referenceMultiple')::numeric<=0
      OR (threshold->>'historySessions')::numeric<>trunc((threshold->>'historySessions')::numeric)
      OR (threshold->>'historySessions')::numeric<>252
      OR (threshold->>'sectorPeers')::numeric<>trunc((threshold->>'sectorPeers')::numeric)
      OR (threshold->>'sectorPeers')::numeric<8
      OR round(current_price/(threshold->>'currentMultiple')::numeric
        *(threshold->>'referenceMultiple')::numeric,2)<>base_value THEN RETURN false;END IF;
    raw_discount:=100*(1-(threshold->>'currentMultiple')::numeric/(threshold->>'referenceMultiple')::numeric);
    IF discount<>round(raw_discount,1) THEN RETURN false;END IF;
  END IF;
  plan:=value->'entryPlan';
  IF plan IS DISTINCT FROM 'null'::jsonb THEN
    IF jsonb_typeof(plan)<>'object' OR jsonb_typeof(plan->'technicalState') IS DISTINCT FROM 'string'
      OR length(plan->>'technicalState')=0 OR plan->>'technicalState'<>btrim(plan->>'technicalState')
      OR (SELECT count(*) FROM jsonb_object_keys(plan))<>5
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(plan) key
        WHERE key NOT IN ('technicalState','trigger','entryZone','invalidation','rewardRisk'))
      THEN RETURN false;END IF;
    technical_state:=plan->>'technicalState';
    has_geometry:=jsonb_typeof(plan->'entryZone')='array' AND jsonb_array_length(plan->'entryZone')=2
      AND jsonb_typeof(plan#>'{entryZone,0}')='number' AND jsonb_typeof(plan#>'{entryZone,1}')='number'
      AND jsonb_typeof(plan->'invalidation')='number';
    has_no_geometry:=plan->'entryZone'='null'::jsonb AND plan->'invalidation'='null'::jsonb;
    IF NOT has_geometry AND NOT has_no_geometry THEN RETURN false;END IF;
    IF has_geometry THEN
      entry_low:=(plan#>>'{entryZone,0}')::numeric;entry_high:=(plan#>>'{entryZone,1}')::numeric;
      invalidation:=(plan->>'invalidation')::numeric;
      IF entry_low<=0 OR entry_low>entry_high OR invalidation<=0 OR invalidation>=entry_low THEN RETURN false;END IF;
    ELSE entry_low:=NULL;entry_high:=NULL;invalidation:=NULL;END IF;
    IF (technical_state IN ('below_support','reclaim_required') AND (NOT has_no_geometry
        OR plan#>>'{trigger,kind}' IS DISTINCT FROM 'reclaim'))
      OR (technical_state='breakout_pending' AND (NOT has_geometry
        OR plan#>>'{trigger,kind}' IS DISTINCT FROM 'breakout'))
      OR (technical_state='extended' AND (NOT has_no_geometry
        OR plan#>>'{trigger,kind}' IS DISTINCT FROM 'pullback'))
      OR (technical_state='invalidated' AND (NOT has_no_geometry OR plan->'trigger' IS DISTINCT FROM 'null'::jsonb))
      OR (technical_state IN ('at_support','breakout_confirmed') AND (NOT has_geometry
        OR plan->'trigger' IS DISTINCT FROM 'null'::jsonb))
      OR technical_state NOT IN ('below_support','reclaim_required','breakout_pending','extended','invalidated',
        'at_support','breakout_confirmed') THEN RETURN false;END IF;
    IF technical_state IN ('below_support','reclaim_required','breakout_pending','extended') AND (
      jsonb_typeof(plan->'trigger') IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(plan->'trigger')) NOT IN (2,3)
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(plan->'trigger') key
        WHERE key NOT IN ('kind','threshold','volumeRatioMinimum'))
      OR jsonb_typeof(plan#>'{trigger,threshold}') IS DISTINCT FROM 'number'
      OR (plan#>>'{trigger,threshold}')::numeric<=0
      OR (plan#>'{trigger,volumeRatioMinimum}' IS NOT NULL
        AND plan#>'{trigger,volumeRatioMinimum}' IS DISTINCT FROM 'null'::jsonb
        AND (jsonb_typeof(plan#>'{trigger,volumeRatioMinimum}') IS DISTINCT FROM 'number'
          OR (plan#>>'{trigger,volumeRatioMinimum}')::numeric<=0))) THEN RETURN false;END IF;
    IF has_geometry AND authority='formal' THEN
      IF jsonb_typeof(plan->'rewardRisk') IS DISTINCT FROM 'number' THEN RETURN false;END IF;
      reward_risk:=(plan->>'rewardRisk')::numeric;
      raw_reward_risk:=(base_raw-(entry_low+entry_high)/2)/(((entry_low+entry_high)/2)-invalidation);
      expected_reward_risk:=round(raw_reward_risk,2);
      IF reward_risk<>expected_reward_risk THEN RETURN false;END IF;
    ELSIF plan->'rewardRisk' IS DISTINCT FROM 'null'::jsonb THEN RETURN false;END IF;
  ELSIF action IN ('buy','accumulate','research_starter','wait_breakout','wait_reclaim','avoid_chase') THEN
    RETURN false;
  END IF;
  IF (action='buy' AND (authority<>'formal' OR NOT has_geometry OR technical_state<>'breakout_confirmed' OR raw_upside<15
      OR raw_reward_risk<2 OR jsonb_array_length(value->'blockers')<>0))
    OR (action='accumulate' AND (authority<>'formal' OR NOT has_geometry OR technical_state<>'at_support' OR raw_upside<15
      OR raw_reward_risk<2 OR jsonb_array_length(value->'blockers')<>0))
    OR (action='research_starter' AND (authority<>'conditional_research'
      OR NOT has_geometry OR technical_state NOT IN ('at_support','breakout_confirmed') OR raw_discount<15
      OR jsonb_array_length(value->'blockers')<>0))
    OR (action='wait_breakout' AND (NOT has_geometry OR technical_state<>'breakout_pending' OR plan->'trigger'='null'::jsonb
      OR jsonb_array_length(value->'blockers')<>0))
    OR (action='wait_reclaim' AND (NOT has_no_geometry OR technical_state NOT IN ('below_support','reclaim_required') OR plan->'trigger'='null'::jsonb
      OR jsonb_array_length(value->'blockers')<>0))
    OR (action='avoid_chase' AND (NOT has_no_geometry OR technical_state<>'extended' OR plan->'trigger'='null'::jsonb
      OR jsonb_array_length(value->'blockers')<>0))
    OR (action='avoid' AND authority='formal' AND (plan IS NOT DISTINCT FROM 'null'::jsonb OR NOT (
      raw_upside<15 OR (raw_reward_risk IS NOT NULL AND raw_reward_risk<2)
      OR technical_state='invalidated' OR value->>'reason'='bias_observe_only')))
    OR (action='avoid' AND authority='conditional_research' AND (plan IS NOT DISTINCT FROM 'null'::jsonb OR NOT (
      raw_discount<15 OR technical_state='invalidated' OR value->>'reason'='bias_observe_only')))
    OR (action='unavailable' AND jsonb_array_length(value->'blockers')=0)
  THEN RETURN false;END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.legacy_valid_decision_envelope_v3_14(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE adapted jsonb;action text;threshold jsonb;unlock jsonb;summary jsonb;plan jsonb;
  actual_margin numeric;actual_reward_risk numeric;recomputed_margin numeric;recomputed_reward_risk numeric;
  required_margin numeric;required_reward_risk numeric;target_value numeric;entry_midpoint numeric;stop_value numeric;
  margin_passed boolean;reward_risk_passed boolean;
BEGIN
  IF jsonb_typeof(value)<>'object' OR value->>'version'<>'decision-envelope-v3.14.0'
    OR coalesce(value->>'decisionRevisionId','')!~'^decision-v3[.]14:[0-9a-f]{64}$'
    OR coalesce(value->>'userAction','') NOT IN ('buy','accumulate','research_starter','wait_value','wait_market',
      'wait_breakout','wait_reclaim','avoid_chase','avoid','unavailable')
  THEN RETURN false;END IF;
  action:=value->>'userAction';threshold:=value->'thresholdAuthority';unlock:=value->'nextUnlock';
  IF NOT (value ? 'thresholdAuthority') THEN RETURN false;END IF;
  IF action IN ('buy','accumulate','research_starter','wait_value','wait_market') THEN
    IF jsonb_typeof(threshold) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
  ELSIF action='unavailable' THEN
    IF jsonb_typeof(threshold) IS DISTINCT FROM 'object'
      AND threshold IS DISTINCT FROM 'null'::jsonb THEN RETURN false;END IF;
  ELSIF threshold IS DISTINCT FROM 'null'::jsonb THEN RETURN false;END IF;
  IF jsonb_typeof(threshold)='object' THEN
    IF jsonb_typeof(threshold)<>'object'
      OR action NOT IN ('buy','accumulate','research_starter','wait_value','wait_market','unavailable')
      OR NOT (threshold ?& ARRAY['actualMarginPct','actualRewardRisk','evidenceRoot','marketRegime',
        'requiredMarginPct','requiredRewardRisk']::text[])
      OR (SELECT count(*) FROM jsonb_object_keys(threshold))<>6
      OR coalesce(threshold->>'marketRegime','') NOT IN ('risk_on','selective_or_defensive')
      OR jsonb_typeof(threshold->'requiredMarginPct') IS DISTINCT FROM 'number'
      OR (threshold->>'requiredMarginPct')::numeric NOT IN (15,20)
      OR jsonb_typeof(threshold->'requiredRewardRisk') IS DISTINCT FROM 'number'
      OR (threshold->>'requiredRewardRisk')::numeric NOT IN (2,2.5)
      OR jsonb_typeof(threshold->'actualMarginPct') IS DISTINCT FROM 'number'
      OR jsonb_typeof(threshold->'actualRewardRisk') IS DISTINCT FROM 'number'
      OR coalesce(threshold->>'evidenceRoot','')!~'^[0-9a-f]{64}$'
      OR (threshold->>'marketRegime'='risk_on'
        AND ((threshold->>'requiredMarginPct')::numeric IS DISTINCT FROM 15
          OR (threshold->>'requiredRewardRisk')::numeric IS DISTINCT FROM 2))
      OR (threshold->>'marketRegime'='selective_or_defensive'
        AND ((threshold->>'requiredMarginPct')::numeric IS DISTINCT FROM 20
          OR (threshold->>'requiredRewardRisk')::numeric IS DISTINCT FROM 2.5))
    THEN RETURN false;END IF;
  END IF;
  IF action='wait_value' THEN
    IF jsonb_typeof(unlock)<>'object' OR unlock->>'kind'<>'max_entry'
      OR jsonb_typeof(unlock->'price')<>'number' OR (unlock->>'price')::numeric<=0
      OR jsonb_typeof(unlock->'requiredMarginPct')<>'number'
      OR jsonb_typeof(unlock->'requiredRewardRisk')<>'number'
    THEN RETURN false;END IF;
  ELSIF unlock IS DISTINCT FROM 'null'::jsonb THEN RETURN false;END IF;
  IF action='wait_market' AND NOT (value->'blockers' ? 'market_regime_gate') THEN RETURN false;END IF;
  adapted:=jsonb_set(jsonb_set(value,'{version}',to_jsonb('decision-envelope-v3.13.0'::text)),
    '{decisionRevisionId}',to_jsonb('decision-v3.13:'||substring(value->>'decisionRevisionId' from 16)));
  IF action IN ('wait_value','wait_market') THEN
    adapted:=jsonb_set(adapted,'{userAction}',to_jsonb('unavailable'::text));
  END IF;
  IF NOT public.legacy_valid_decision_envelope_strict_v3_13(adapted) THEN RETURN false;END IF;
  IF jsonb_typeof(threshold)='object' THEN
    summary:=value->'valuationSummary';plan:=value->'entryPlan';
    IF jsonb_typeof(summary)<>'object' OR jsonb_typeof(plan)<>'object'
      OR jsonb_array_length(plan->'entryZone')<>2 THEN RETURN false;END IF;
    required_margin:=(threshold->>'requiredMarginPct')::numeric;
    required_reward_risk:=(threshold->>'requiredRewardRisk')::numeric;
    actual_margin:=(threshold->>'actualMarginPct')::numeric;
    actual_reward_risk:=(threshold->>'actualRewardRisk')::numeric;
    entry_midpoint:=((plan#>>'{entryZone,0}')::numeric+(plan#>>'{entryZone,1}')::numeric)/2;
    stop_value:=(plan->>'invalidation')::numeric;
    IF value->>'recommendationAuthority'='formal' THEN
      target_value:=(summary#>>'{thresholdAuthority,baseTargetRaw}')::numeric;
      recomputed_margin:=100*(target_value/(summary->>'currentPrice')::numeric-1);
    ELSIF value->>'recommendationAuthority'='conditional_research' THEN
      target_value:=(summary->>'currentPrice')::numeric
        /(summary#>>'{thresholdAuthority,currentMultiple}')::numeric
        *(summary#>>'{thresholdAuthority,referenceMultiple}')::numeric;
      recomputed_margin:=100*(1-(summary#>>'{thresholdAuthority,currentMultiple}')::numeric
        /(summary#>>'{thresholdAuthority,referenceMultiple}')::numeric);
    ELSE RETURN false;END IF;
    IF entry_midpoint<=stop_value THEN RETURN false;END IF;
    recomputed_reward_risk:=(target_value-entry_midpoint)/(entry_midpoint-stop_value);
    IF abs(actual_margin-recomputed_margin)>0.000000001*greatest(1,abs(actual_margin),abs(recomputed_margin))
      OR abs(actual_reward_risk-recomputed_reward_risk)>0.000000001
        *greatest(1,abs(actual_reward_risk),abs(recomputed_reward_risk)) THEN RETURN false;END IF;
    margin_passed:=actual_margin>=required_margin
      -0.000000000000003552713678800501*greatest(1,abs(actual_margin),abs(required_margin));
    reward_risk_passed:=actual_reward_risk>=required_reward_risk
      -0.000000000000003552713678800501*greatest(1,abs(actual_reward_risk),abs(required_reward_risk));
    IF action IN ('buy','accumulate','research_starter','wait_market')
      AND NOT (margin_passed AND reward_risk_passed) THEN RETURN false;END IF;
    IF action='wait_market' AND (jsonb_array_length(value->'blockers')<>1
      OR value#>>'{blockers,0}'<>'market_regime_gate') THEN RETURN false;END IF;
    IF action='wait_value' AND (margin_passed=reward_risk_passed OR jsonb_array_length(value->'blockers')<>1
      OR value#>>'{blockers,0}'<>'entry_price_above_required_value_gate'
      OR (unlock->>'requiredMarginPct')::numeric<>required_margin
      OR (unlock->>'requiredRewardRisk')::numeric<>required_reward_risk) THEN RETURN false;END IF;
    IF action='unavailable' AND margin_passed AND reward_risk_passed
      AND value->>'reason'<>'insufficient_cited_decision_brief' THEN RETURN false;END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.legacy_valid_https_url_v3_13(value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE port_text text;
BEGIN
  IF value<>btrim(value) OR value!~'^https://[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?(?::[0-9]{1,5})?(?:[/?#][^[:space:]\\]*)?$'
    OR position(E'\\\\' in value)>0 THEN RETURN false;END IF;
  port_text:=substring(value from '^https://[^/:?#]+:([0-9]+)');
  RETURN port_text IS NULL OR port_text::integer BETWEEN 1 AND 65535;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.legacy_valid_rfc3339_v3_13(value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE parsed timestamptz;offset_hour integer;offset_minute integer;
  hour_value integer;minute_value integer;second_value integer;
BEGIN
  IF value!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    THEN RETURN false;END IF;
  hour_value:=substring(value from 'T([0-9]{2}):')::integer;
  minute_value:=substring(value from 'T[0-9]{2}:([0-9]{2}):')::integer;
  second_value:=substring(value from 'T[0-9]{2}:[0-9]{2}:([0-9]{2})')::integer;
  IF hour_value>23 OR minute_value>59 OR second_value>59 THEN RETURN false;END IF;
  IF right(value,1)<>'Z' THEN
    offset_hour:=substring(value from '[+-]([0-9]{2}):[0-9]{2}$')::integer;
    offset_minute:=substring(value from '[+-][0-9]{2}:([0-9]{2})$')::integer;
    IF offset_hour>14 OR offset_minute>59 OR (offset_hour=14 AND offset_minute<>0) THEN RETURN false;END IF;
  END IF;
  parsed:=value::timestamptz;
  RETURN parsed IS NOT NULL;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.opportunity_levenshtein_v3_internal(left_value text, right_value text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  left_length integer:=char_length(left_value);
  right_length integer:=char_length(right_value);
  previous_row integer[];
  current_row integer[];
  left_index integer;
  right_index integer;
  substitution_cost integer;
BEGIN
  IF left_length>40 OR right_length>40 THEN
    RETURN 41;
  END IF;
  previous_row:=ARRAY(
    SELECT value FROM generate_series(0,right_length) value ORDER BY value
  );
  FOR left_index IN 1..left_length LOOP
    current_row:=ARRAY[left_index];
    FOR right_index IN 1..right_length LOOP
      substitution_cost:=CASE
        WHEN substr(left_value,left_index,1)=substr(right_value,right_index,1)
        THEN 0 ELSE 1 END;
      current_row:=array_append(current_row,least(
        current_row[right_index]+1,
        previous_row[right_index+1]+1,
        previous_row[right_index]+substitution_cost
      ));
    END LOOP;
    previous_row:=current_row;
  END LOOP;
  RETURN previous_row[right_length+1];
END
$function$

CREATE OR REPLACE FUNCTION public.persist_taiwan_data_canonical_result_v5(p_job_id uuid, p_owner text, p_result jsonb, p_persisted_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_dataset text; v_symbol text; v_exchange text; v_session date; v_provider text; v_tier text;
  v_records jsonb; v_hash text; v_id uuid; v_stock_id uuid; v_row jsonb;
  v_open numeric; v_high numeric; v_low numeric; v_close numeric; v_volume numeric; v_pe numeric; v_pb numeric; v_revenue numeric;
  v_source_url text; v_pe_text text; v_pb_text text; v_pe_index integer; v_pb_index integer;
  v_row_symbol text; v_period_text text; v_period date; v_typed_rows integer := 0;
BEGIN
  IF jsonb_typeof(p_result)<>'object' OR p_result->>'schema'<>'taiwan-data-provider-result-v1'
    OR p_result->>'terminal'<>'complete' OR jsonb_typeof(p_result->'canonical')<>'object'
    OR p_result->'canonical'->>'schema'<>'taiwan-data-canonical-v1'
    OR jsonb_typeof(p_result->'canonical'->'records')<>'array'
    OR jsonb_array_length(p_result->'canonical'->'records') NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_taiwan_canonical_result';
  END IF;
  SELECT dataset,symbol,exchange,requested_session_date INTO v_dataset,v_symbol,v_exchange,v_session
  FROM public.taiwan_data_refresh_queue_v5 WHERE job_id=p_job_id AND status='running' AND lease_owner=p_owner AND lease_expires_at>=p_persisted_at FOR UPDATE;
  IF v_dataset IS NULL OR p_result->>'dataset' IS DISTINCT FROM v_dataset OR p_result->>'symbol' IS DISTINCT FROM v_symbol
    OR p_result->>'exchange' IS DISTINCT FROM v_exchange OR (p_result->'canonical'->>'expectedSessionDate')::date IS DISTINCT FROM v_session THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='taiwan_canonical_identity_mismatch';
  END IF;
  v_provider:=p_result->>'selectedProvider'; v_tier:=p_result->>'selectedAuthorityTier'; v_records:=p_result->'canonical'->'records';
  IF v_provider NOT IN ('twse','tpex','finmind') OR v_tier NOT IN ('official_primary','finmind_fallback')
    OR (v_provider='finmind') <> (v_tier='finmind_fallback') THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='taiwan_canonical_provenance_invalid'; END IF;
  SELECT attempt->>'sourceUrl' INTO v_source_url FROM jsonb_array_elements(p_result->'attempts') attempt
  WHERE attempt->>'provider'=v_provider AND attempt->>'authorityTier'=v_tier LIMIT 1;
  IF (v_provider='finmind' AND v_source_url !~ '^https://api\.finmindtrade\.com/api/v4/data(?:\?|$)')
    OR (v_provider='twse' AND v_source_url !~ '^https://(www\.twse\.com\.tw|openapi\.twse\.com\.tw|mopsov\.twse\.com\.tw)/')
    OR (v_provider='tpex' AND v_source_url !~ '^https://www\.tpex\.org\.tw/') THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='taiwan_canonical_source_url_invalid';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(v_records::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.taiwan_data_canonical_results_v5(job_id,dataset,symbol,exchange,requested_session_date,provider,authority_tier,canonical_schema,record_count,records,records_sha256,persisted_at)
  VALUES(p_job_id,v_dataset,v_symbol,v_exchange,v_session,v_provider,v_tier,'taiwan-data-canonical-v1',jsonb_array_length(v_records),v_records,v_hash,p_persisted_at)
  ON CONFLICT(job_id) DO NOTHING RETURNING canonical_result_id INTO v_id;
  IF v_id IS NULL THEN SELECT canonical_result_id INTO v_id FROM public.taiwan_data_canonical_results_v5 WHERE job_id=p_job_id AND records_sha256=v_hash; END IF;
  IF v_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='taiwan_canonical_conflict'; END IF;
  -- Aggregate valuation/revenue responses are fetched once per exchange. Each
  -- canonical row is mapped to its own stock before a typed upsert; no loop of
  -- candidate-specific official requests is permitted.
  IF v_dataset IN ('daily_valuation','monthly_revenue') AND v_symbol IS NULL THEN
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_records) value LOOP
      v_row_symbol:=COALESCE(v_row->>'stock_id',v_row->>'data_id',v_row->>'公司代號',v_row->>'證券代號',v_row->>'股票代號',v_row->'values'->>0);
      IF v_row_symbol !~ '^\d{4}$' THEN CONTINUE; END IF;
      SELECT id INTO v_stock_id FROM public.stocks WHERE symbol=v_row_symbol AND market='TW';
      IF v_stock_id IS NULL THEN CONTINUE; END IF;
      IF v_dataset='daily_valuation' THEN
        v_pe_text:=COALESCE(v_row->>'PER',v_row->>'pe_ratio',v_row->>'本益比');
        v_pb_text:=COALESCE(v_row->>'PBR',v_row->>'pb_ratio',v_row->>'股價淨值比');
        IF jsonb_typeof(v_row->'fields')='array' THEN
          SELECT ordinal-1 INTO v_pe_index FROM jsonb_array_elements_text(v_row->'fields') WITH ORDINALITY item(name,ordinal) WHERE name='本益比' LIMIT 1;
          SELECT ordinal-1 INTO v_pb_index FROM jsonb_array_elements_text(v_row->'fields') WITH ORDINALITY item(name,ordinal) WHERE name='股價淨值比' LIMIT 1;
          v_pe_text:=COALESCE(v_pe_text,v_row->'values'->>v_pe_index); v_pb_text:=COALESCE(v_pb_text,v_row->'values'->>v_pb_index);
        END IF;
        v_pe:=NULLIF(regexp_replace(COALESCE(v_pe_text,''),'[^0-9.\-]','','g'),'')::numeric;
        v_pb:=NULLIF(regexp_replace(COALESCE(v_pb_text,''),'[^0-9.\-]','','g'),'')::numeric;
        IF v_pe IS NULL AND v_pb IS NULL THEN CONTINUE; END IF;
        INSERT INTO public.official_multiple_history(stock_id,month_end,close,pe_ratio,pb_ratio,source_url,as_of,available_at,provenance)
        VALUES(v_stock_id,v_session,NULL,v_pe,v_pb,v_source_url,(v_session::text||'T13:30:00+08:00')::timestamptz,p_persisted_at,jsonb_build_object('canonical_result_id',v_id,'provider',v_provider,'authorityTier',v_tier,'valuation_parser_version','taiwan-data-v5'))
        ON CONFLICT(stock_id,month_end) DO UPDATE SET pe_ratio=EXCLUDED.pe_ratio,pb_ratio=EXCLUDED.pb_ratio,source_url=EXCLUDED.source_url,as_of=EXCLUDED.as_of,available_at=EXCLUDED.available_at,provenance=EXCLUDED.provenance;
        v_typed_rows:=v_typed_rows+1;
      ELSE
        v_period_text:=COALESCE(v_row->>'revenue_month',v_row->>'date',v_row->>'資料年月');
        v_period:=CASE
          WHEN v_period_text ~ '^\d{4}-\d{2}' THEN (substring(v_period_text,1,7)||'-01')::date
          WHEN v_period_text ~ '^\d{3}/\d{2}$' THEN ((substring(v_period_text,1,3)::integer+1911)::text||'-'||substring(v_period_text,5,2)||'-01')::date
          WHEN v_period_text ~ '^\d{5}$' THEN ((substring(v_period_text,1,3)::integer+1911)::text||'-'||substring(v_period_text,4,2)||'-01')::date
          ELSE NULL END;
        v_revenue:=NULLIF(regexp_replace(COALESCE(v_row->>'revenue',v_row->>'monthly_revenue',v_row->>'當月營收',v_row->>'營業收入-當月營收',''),'[^0-9.\-]','','g'),'')::numeric;
        IF v_period IS NULL OR v_revenue IS NULL OR v_revenue<0 THEN CONTINUE; END IF;
        INSERT INTO public.revenue_signals(stock_id,as_of_date,monthly_revenue,yoy_growth,mom_growth,source_url)
        VALUES(v_stock_id,v_period,v_revenue,NULL,NULL,v_source_url)
        ON CONFLICT(stock_id,as_of_date) DO UPDATE SET monthly_revenue=EXCLUDED.monthly_revenue,source_url=EXCLUDED.source_url;
        v_typed_rows:=v_typed_rows+1;
      END IF;
    END LOOP;
    IF v_typed_rows=0 AND v_dataset='daily_valuation' THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='aggregate_valuation_no_typed_rows'; END IF;
    IF v_typed_rows=0 AND v_dataset='monthly_revenue' THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='aggregate_revenue_no_typed_rows'; END IF;
    RETURN v_id;
  END IF;
  -- These are the three canonical planes consumed by candidate research. The
  -- generic ledger above is audit lineage; success is not promoted until this
  -- same transaction writes the typed research tables.
  IF v_dataset IN ('daily_price','daily_valuation','monthly_revenue') THEN
    SELECT id INTO v_stock_id FROM public.stocks WHERE symbol=v_symbol AND market='TW';
    IF v_stock_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='taiwan_canonical_stock_missing'; END IF;
    SELECT value INTO v_row FROM jsonb_array_elements(v_records) value
      WHERE COALESCE(value->>'stock_id',value->>'data_id',value->>'公司代號',value->'values'->>0,v_symbol)=v_symbol LIMIT 1;
    v_row:=COALESCE(v_row,v_records->0);
  END IF;
  IF v_dataset='daily_price' THEN
    v_open:=NULLIF(regexp_replace(COALESCE(v_row->>'open',v_row->>'Open',v_row->'values'->>3,''),'[^0-9.\-]','','g'),'')::numeric;
    v_high:=NULLIF(regexp_replace(COALESCE(v_row->>'max',v_row->>'high',v_row->>'High',v_row->'values'->>4,''),'[^0-9.\-]','','g'),'')::numeric;
    v_low:=NULLIF(regexp_replace(COALESCE(v_row->>'min',v_row->>'low',v_row->>'Low',v_row->'values'->>5,''),'[^0-9.\-]','','g'),'')::numeric;
    v_close:=NULLIF(regexp_replace(COALESCE(v_row->>'close',v_row->>'Close',v_row->'values'->>6,''),'[^0-9.\-]','','g'),'')::numeric;
    v_volume:=NULLIF(regexp_replace(COALESCE(v_row->>'Trading_Volume',v_row->>'volume',v_row->>'Volume',v_row->'values'->>1,''),'[^0-9.\-]','','g'),'')::numeric;
    IF v_provider='tpex' AND v_volume IS NOT NULL AND jsonb_typeof(v_row->'fields')='array' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_row->'fields') item(name)
      WHERE regexp_replace(item.name,'\s','','g')='成交張數'
    ) THEN v_volume:=v_volume*1000; END IF;
    IF v_open IS NULL OR v_high IS NULL OR v_low IS NULL OR v_close IS NULL OR v_open<=0 OR v_high<GREATEST(v_open,v_close) OR v_low>LEAST(v_open,v_close) THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='daily_price_canonical_values_invalid';
    END IF;
    INSERT INTO public.official_price_history(stock_id,session_date,open,high,low,close,volume,source_url,as_of,available_at,provenance)
    VALUES(v_stock_id,v_session,v_open,v_high,v_low,v_close,v_volume,v_source_url,(v_session::text||'T13:30:00+08:00')::timestamptz,p_persisted_at,
      jsonb_build_object('canonical_result_id',v_id,'provider',v_provider,'authorityTier',v_tier))
    ON CONFLICT(stock_id,session_date) DO UPDATE SET open=EXCLUDED.open,high=EXCLUDED.high,low=EXCLUDED.low,close=EXCLUDED.close,volume=EXCLUDED.volume,source_url=EXCLUDED.source_url,as_of=EXCLUDED.as_of,available_at=EXCLUDED.available_at,provenance=EXCLUDED.provenance;
  ELSIF v_dataset='daily_valuation' THEN
    v_pe_text:=COALESCE(v_row->>'PER',v_row->>'pe_ratio',v_row->>'本益比');
    v_pb_text:=COALESCE(v_row->>'PBR',v_row->>'pb_ratio',v_row->>'股價淨值比');
    IF jsonb_typeof(v_row->'fields')='array' THEN
      SELECT ordinal-1 INTO v_pe_index FROM jsonb_array_elements_text(v_row->'fields') WITH ORDINALITY item(name,ordinal) WHERE name='本益比' LIMIT 1;
      SELECT ordinal-1 INTO v_pb_index FROM jsonb_array_elements_text(v_row->'fields') WITH ORDINALITY item(name,ordinal) WHERE name='股價淨值比' LIMIT 1;
      v_pe_text:=COALESCE(v_pe_text,v_row->'values'->>v_pe_index);
      v_pb_text:=COALESCE(v_pb_text,v_row->'values'->>v_pb_index);
    END IF;
    v_pe:=NULLIF(regexp_replace(COALESCE(v_pe_text,''),'[^0-9.\-]','','g'),'')::numeric;
    v_pb:=NULLIF(regexp_replace(COALESCE(v_pb_text,''),'[^0-9.\-]','','g'),'')::numeric;
    IF v_pe IS NULL AND v_pb IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='daily_valuation_canonical_values_invalid'; END IF;
    INSERT INTO public.official_multiple_history(stock_id,month_end,close,pe_ratio,pb_ratio,source_url,as_of,available_at,provenance)
    VALUES(v_stock_id,v_session,NULL,v_pe,v_pb,v_source_url,(v_session::text||'T13:30:00+08:00')::timestamptz,p_persisted_at,
      jsonb_build_object('canonical_result_id',v_id,'provider',v_provider,'authorityTier',v_tier,'valuation_parser_version','taiwan-data-v5'))
    ON CONFLICT(stock_id,month_end) DO UPDATE SET pe_ratio=EXCLUDED.pe_ratio,pb_ratio=EXCLUDED.pb_ratio,source_url=EXCLUDED.source_url,as_of=EXCLUDED.as_of,available_at=EXCLUDED.available_at,provenance=EXCLUDED.provenance;
  ELSIF v_dataset='monthly_revenue' THEN
    v_revenue:=NULLIF(regexp_replace(COALESCE(v_row->>'revenue',v_row->>'monthly_revenue',v_row->>'當月營收',v_row->>'營業收入-當月營收',''),'[^0-9.\-]','','g'),'')::numeric;
    IF v_revenue IS NULL OR v_revenue<0 THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='monthly_revenue_canonical_values_invalid'; END IF;
    INSERT INTO public.revenue_signals(stock_id,as_of_date,monthly_revenue,yoy_growth,mom_growth,source_url)
    VALUES(v_stock_id,v_session,v_revenue,NULL,NULL,v_source_url)
    ON CONFLICT(stock_id,as_of_date) DO UPDATE SET monthly_revenue=EXCLUDED.monthly_revenue,source_url=EXCLUDED.source_url;
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.prepare_research_input_v2(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE j public.research_deep_jobs_v1; r public.research_model_reservations_v1;
 pri public.research_priority_runs_v1; snap public.research_observed_roster_snapshots_v1;
 old public.research_input_preparations_v2; saved public.research_input_preparations_v2;
 rh text; n timestamptz; docs jsonb; seal jsonb; material jsonb;
 used_count bigint; used_bytes bigint; charged_bytes integer; seal_manifest jsonb; seal_hash text; new_seal boolean:=false;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'input_preparation_read_committed_required'; END IF;
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR octet_length(p_request::text)>8192
  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_request) key) IS DISTINCT FROM ARRAY['attempt','bundleId','jobId','owner','reservationId','scope','snapshotHash','sourceDocumentIds']
  OR p_request->>'scope' IS DISTINCT FROM 'research_observed_v1' OR p_request->'bundleId' IS DISTINCT FROM 'null'::jsonb
  OR jsonb_typeof(p_request->'owner') IS DISTINCT FROM 'string' OR p_request->>'owner' !~ '^[A-Za-z0-9:_-]{3,120}$'
  OR jsonb_typeof(p_request->'attempt') IS DISTINCT FROM 'number' OR p_request->>'attempt' !~ '^[1-3]$'
  OR jsonb_typeof(p_request->'sourceDocumentIds') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'input_preparation_shape'; END IF;
 IF jsonb_array_length(p_request->'sourceDocumentIds')>30 OR EXISTS(SELECT FROM jsonb_array_elements(p_request->'sourceDocumentIds') x WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$')
  OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_request->'sourceDocumentIds') x)<>jsonb_array_length(p_request->'sourceDocumentIds')
  OR jsonb_typeof(p_request->'jobId') IS DISTINCT FROM 'string' OR p_request->>'jobId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR jsonb_typeof(p_request->'reservationId') IS DISTINCT FROM 'string' OR p_request->>'reservationId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR jsonb_typeof(p_request->'snapshotHash') IS DISTINCT FROM 'string' OR p_request->>'snapshotHash' !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'input_preparation_shape'; END IF;
 -- One order: stable source fence, then existing global deep-job/model slot.
 PERFORM pg_advisory_xact_lock(610091002::bigint);
 PERFORM pg_advisory_xact_lock(2409,6002);
 SELECT * INTO j FROM public.research_deep_jobs_v1 WHERE job_id=(p_request->>'jobId')::uuid FOR SHARE;
 SELECT * INTO r FROM public.research_model_reservations_v1 WHERE reservation_id=(p_request->>'reservationId')::uuid FOR SHARE;
 n:=clock_timestamp();
 IF j.job_id IS NULL OR r.reservation_id IS NULL OR j.research_scope IS DISTINCT FROM 'research_observed_v1'
  OR j.status IS DISTINCT FROM 'running' OR j.attempts IS DISTINCT FROM (p_request->>'attempt')::integer
  OR j.lease_owner IS DISTINCT FROM p_request->>'owner' OR j.observed_snapshot_hash IS DISTINCT FROM p_request->>'snapshotHash'
  OR j.lease_expires_at IS NULL OR NOT isfinite(j.lease_expires_at) OR j.lease_expires_at<=n
  OR r.role IS DISTINCT FROM 'company_research' OR r.owner IS DISTINCT FROM j.lease_owner
  OR r.work_key IS DISTINCT FROM 'deep:'||j.job_id||':'||j.attempts
  OR r.started_at IS NULL OR NOT isfinite(r.started_at) OR r.started_at>n
  OR r.lease_expires_at IS NULL OR NOT isfinite(r.lease_expires_at) OR r.lease_expires_at<=n
  OR r.lease_expires_at>r.started_at+interval '30 minutes'
  OR NOT EXISTS(SELECT FROM public.research_deep_job_attempts_v1 a WHERE a.job_id=j.job_id AND a.attempt=j.attempts AND a.owner=j.lease_owner AND a.lease_expires_at=j.lease_expires_at AND a.claimed_at<=n)
  OR EXISTS(SELECT FROM public.research_model_completions_v1 c WHERE c.reservation_id=r.reservation_id)
 THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
 SELECT * INTO pri FROM public.research_priority_runs_v1 WHERE run_id=j.priority_run_id;
 SELECT * INTO snap FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=j.observed_snapshot_hash;
 IF pri.run_id IS NULL OR pri.research_scope IS DISTINCT FROM j.research_scope OR pri.observed_snapshot_hash IS DISTINCT FROM j.observed_snapshot_hash
  OR pri.as_of IS NULL OR NOT isfinite(pri.as_of) OR pri.as_of>n OR snap.snapshot_hash IS NULL OR snap.received_at IS NULL OR NOT isfinite(snap.received_at) OR snap.latest_observed_at IS NULL OR NOT isfinite(snap.latest_observed_at) OR snap.received_at>pri.as_of OR snap.latest_observed_at>pri.as_of
  OR NOT EXISTS(SELECT FROM public.research_observed_priority_store_receipts_v1 s WHERE s.run_id=pri.run_id AND s.stored_run_hash=encode(sha256(convert_to(to_jsonb(pri)::text,'UTF8')),'hex'))
  OR NOT EXISTS(SELECT FROM public.research_observed_roster_members_v1 m JOIN public.research_observed_companies_v1 c USING(research_company_id) WHERE m.snapshot_hash=snap.snapshot_hash AND m.research_company_id=j.research_company_id AND m.symbol=j.symbol AND c.symbol=j.symbol)
 THEN RAISE EXCEPTION 'input_preparation_lineage'; END IF;
 rh:=encode(sha256(convert_to(public.research_observed_canonical_json_v1(p_request),'UTF8')),'hex');
 SELECT * INTO old FROM public.research_input_preparations_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id AND request_hash=rh;
 IF FOUND THEN
  IF old.request IS DISTINCT FROM p_request THEN RAISE EXCEPTION 'input_preparation_replay_mismatch'; END IF;
  IF old.source_seal_id IS NOT NULL THEN PERFORM public.assert_research_source_seal_v2(old.source_seal_id); END IF;
  IF clock_timestamp()>=least(j.lease_expires_at,r.lease_expires_at) THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
  RETURN to_jsonb(old)||jsonb_build_object('replay',true,'dispatchReady',false);
 END IF;
 -- Original-unit history is permanent: expiry, invalidation and takeover never refund it.
 SELECT count(*),coalesce(sum(logical_bytes),0) INTO used_count,used_bytes FROM (SELECT logical_bytes FROM public.research_input_preparations_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id
  UNION ALL SELECT logical_bytes FROM public.research_article_input_revisions_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id) history;
 IF used_count>=4 THEN RAISE EXCEPTION 'input_preparation_count_bound'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'rowHash',encode(sha256(convert_to(to_jsonb(d)::text,'UTF8')),'hex')) ORDER BY d.id),'[]') INTO docs FROM public.source_raw_documents d WHERE p_request->'sourceDocumentIds' @> jsonb_build_array(d.id::text);
 IF jsonb_array_length(docs)<>jsonb_array_length(p_request->'sourceDocumentIds') THEN RAISE EXCEPTION 'input_preparation_source_missing'; END IF;
 IF jsonb_array_length(docs)>0 THEN
  -- Exact existing-seal lookup under the shared source fence; full receipt is charged only when new.
  SELECT jsonb_agg(jsonb_build_object('id',d.id::text,'rowHash',encode(sha256(convert_to(to_jsonb(d)::text,'UTF8')),'hex'),
   'root',public.research_source_root_v2(to_jsonb(d)),'publishedAt',to_jsonb(d)->'published_at',
   'observedAt',to_jsonb(d)->'collected_at','rights',d.metadata->>'rights_boundary') ORDER BY d.id) INTO seal_manifest
   FROM public.source_raw_documents d WHERE p_request->'sourceDocumentIds' @> jsonb_build_array(d.id::text);
  seal_hash:=encode(sha256(convert_to(jsonb_build_object('documents',seal_manifest,'cutoff',n)::text,'UTF8')),'hex');
  new_seal:=NOT EXISTS(SELECT FROM public.research_source_seals_v2 WHERE request_hash=seal_hash);
  seal:=public.seal_research_sources_v2(docs,n);
  IF seal->>'request_hash' IS DISTINCT FROM seal_hash THEN RAISE EXCEPTION 'input_preparation_seal_projection_changed'; END IF;
 END IF;
 -- Freeze DB-derived manifests; full original rows remain behind the private source seal.
 -- No supplied model output, financial facts, calculator or role identity is accepted here.
 material:=jsonb_build_object('schemaVersion','research-input-preparation-v2','researchCompanyId',j.research_company_id,'symbol',j.symbol,
  'scope',j.research_scope,'snapshotHash',snap.snapshot_hash,'mappingDigest',snap.mapping_digest,'stockId',j.stock_id,
  'priorityRunId',pri.run_id,'priorityInputHash',pri.input_hash,'discoveryCutoff',pri.as_of,'originalModelCutoff',NULL,'researchCutoff',n,
  'originalJob',jsonb_build_object('jobId',j.job_id,'attempt',j.attempts,'owner',j.lease_owner,'leaseExpiresAt',j.lease_expires_at),
  'originalReservation',jsonb_build_object('reservationId',r.reservation_id,'startedAt',r.started_at,'leaseExpiresAt',r.lease_expires_at),
  'sourceManifest',coalesce(seal->'documents','[]'),'sourceSelectionComplete',false,'financial',NULL,'calculator',NULL,
  'status','draft_incomplete','gaps',jsonb_build_array('financial_input_revision_missing','trusted_calculator_not_bound','original_model_not_selected','trusted_execution_authority_unavailable')||CASE WHEN jsonb_array_length(docs)=0 THEN jsonb_build_array('sources_not_selected') ELSE '[]'::jsonb END,
  'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false);
 charged_bytes:=public.research_input_preparation_bytes_v2(p_request,material,CASE WHEN new_seal THEN seal ELSE 'null'::jsonb END);
 IF used_bytes+charged_bytes>524288 THEN RAISE EXCEPTION 'input_preparation_byte_bound'; END IF;
 IF clock_timestamp()>=least(j.lease_expires_at,r.lease_expires_at) THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
 INSERT INTO public.research_input_preparations_v2(job_id,attempt,reservation_id,request_hash,request,input_hash,payload,logical_bytes,source_seal_id,admitted_at)
 VALUES(j.job_id,j.attempts,r.reservation_id,rh,p_request,encode(sha256(convert_to(public.research_observed_canonical_json_v1(material),'UTF8')),'hex'),material,charged_bytes,(seal->>'seal_id')::uuid,n) RETURNING * INTO saved;
 RETURN to_jsonb(saved)||jsonb_build_object('replay',false,'dispatchReady',false);
END $function$

CREATE OR REPLACE FUNCTION public.prepare_retention_archive_manifest_v1(p_root_kind text, p_root_id uuid, p_planned_snapshot_at timestamp with time zone, p_schema_hash text, p_closure_hash text, p_relation_counts jsonb, p_rows jsonb, p_created_by_principal text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_eligibility JSONB; v_manifest UUID; v_row JSONB; v_ordinal INTEGER:=0; v_requested_rows JSONB;
  v_computed_closure_hash TEXT; v_computed_relation_counts JSONB;
BEGIN
  IF p_schema_hash !~ '^[0-9a-f]{64}$' OR p_closure_hash !~ '^[0-9a-f]{64}$'
    OR jsonb_typeof(p_relation_counts)<>'object' OR jsonb_typeof(p_rows)<>'array'
    OR length(trim(coalesce(p_created_by_principal,'')))=0 THEN
    RAISE EXCEPTION 'retention_manifest_input_invalid';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_rows) row_spec
    WHERE coalesce(row_spec->>'relation','') !~ '^public[.][a-z][a-z0-9_]*$'
      OR coalesce(row_spec->>'key','') !~ '^[0-9a-fA-F-]{36}$'
      OR coalesce(row_spec->>'rowHash','') !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'retention_manifest_row_invalid';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('relation',row_spec->>'relation','key',row_spec->>'key')
    ORDER BY row_spec->>'relation',row_spec->>'key'),'[]'::jsonb)
    INTO v_requested_rows FROM jsonb_array_elements(p_rows) row_spec;
  SELECT encode(digest(convert_to(coalesce(string_agg(
      (row_spec->>'relation')||'|'||(row_spec->>'key')||'|'||(row_spec->>'rowHash')||E'\n',''
      ORDER BY row_spec->>'relation',row_spec->>'key'),''),'UTF8'),'sha256'),'hex')
    INTO v_computed_closure_hash FROM jsonb_array_elements(p_rows) row_spec;
  SELECT coalesce(jsonb_object_agg(relation_name,row_count),'{}'::jsonb)
    INTO v_computed_relation_counts FROM (
      SELECT row_spec->>'relation' relation_name,count(*) row_count
      FROM jsonb_array_elements(p_rows) row_spec GROUP BY row_spec->>'relation'
    ) counts;
  IF v_computed_closure_hash IS DISTINCT FROM p_closure_hash
    OR v_computed_relation_counts IS DISTINCT FROM p_relation_counts THEN
    RAISE EXCEPTION 'retention_manifest_summary_mismatch';
  END IF;
  v_eligibility:=public.retention_archive_eligibility_v1(p_root_kind,p_root_id,p_planned_snapshot_at);
  IF NOT coalesce((v_eligibility->>'eligible')::BOOLEAN,FALSE) THEN
    RAISE EXCEPTION 'retention_root_not_eligible:%',v_eligibility->'blockers';
  END IF;
  IF v_eligibility->'rows' IS DISTINCT FROM v_requested_rows THEN RAISE EXCEPTION 'retention_closure_changed'; END IF;
  INSERT INTO public.retention_archive_manifests_v1(
    root_kind,root_id,policy_version,cutoff_at,planned_snapshot_at,schema_hash,closure_hash,
    expected_row_count,expected_relation_counts,created_by_principal
  ) VALUES (
    p_root_kind,p_root_id,v_eligibility->>'policyVersion',(v_eligibility->>'cutoffAt')::TIMESTAMPTZ,
    p_planned_snapshot_at,p_schema_hash,p_closure_hash,jsonb_array_length(p_rows),p_relation_counts,p_created_by_principal
  ) RETURNING manifest_id INTO v_manifest;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    INSERT INTO public.retention_archive_manifest_rows_v1(manifest_id,relation_name,row_key,row_hash,ordinal)
    VALUES(v_manifest,v_row->>'relation',v_row->>'key',v_row->>'rowHash',v_ordinal);
    v_ordinal:=v_ordinal+1;
  END LOOP;
  RETURN v_manifest;
END;
$function$

CREATE OR REPLACE FUNCTION public.preserve_first_recommended_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.first_recommended_at IS NOT NULL THEN
    NEW.first_recommended_at = OLD.first_recommended_at;
  ELSIF NEW.first_recommended_at IS NULL THEN
    NEW.first_recommended_at = NOW();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_published_candidate_detail_revision_v4()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.candidate_dossier_bundles WHERE revision_id = OLD.id)
     OR EXISTS (SELECT 1 FROM public.candidate_daily_stage_snapshots WHERE detail_revision_id = OLD.id) THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'published_candidate_detail_revisions_are_append_only';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_radar_public_snapshots(p_home_payload jsonb, p_home_hash text, p_home_etag text, p_daily_payload jsonb, p_daily_hash text, p_daily_etag text, p_schema_version text, p_content_as_of timestamp with time zone, p_pipeline_run_id uuid, p_ruleset_version text, p_model_version text, p_published_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE home_id UUID; daily_id UUID; v_phase text; v_cutoff timestamptz; v_pct numeric;
BEGIN
  v_phase:=COALESCE(NULLIF(p_home_payload->>'snapshotPhase',''),'final');
  IF v_phase NOT IN ('preliminary','final') THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_snapshot_phase'; END IF;
  v_cutoff:=COALESCE(NULLIF(p_home_payload->>'dataCutoffAt','')::timestamptz,p_content_as_of);
  v_pct:=COALESCE(NULLIF(p_home_payload->>'datasetCompletenessPct','')::numeric,100);
  IF v_pct NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_dataset_completeness_pct'; END IF;
  INSERT INTO public.radar_public_snapshots(window_key,schema_version,payload_json,payload_hash,etag,content_as_of,pipeline_run_id,ruleset_version,model_version,status,published_at,publication_phase,data_cutoff_at,dataset_completeness_pct)
  VALUES('home',p_schema_version,p_home_payload,p_home_hash,p_home_etag,p_content_as_of,p_pipeline_run_id,p_ruleset_version,p_model_version,'valid',p_published_at,v_phase,v_cutoff,v_pct)
  RETURNING id INTO home_id;
  INSERT INTO public.radar_public_snapshots(window_key,schema_version,payload_json,payload_hash,etag,content_as_of,pipeline_run_id,ruleset_version,model_version,status,published_at,publication_phase,data_cutoff_at,dataset_completeness_pct)
  VALUES('daily',p_schema_version,p_daily_payload,p_daily_hash,p_daily_etag,p_content_as_of,p_pipeline_run_id,p_ruleset_version,p_model_version,'valid',p_published_at,v_phase,v_cutoff,v_pct)
  RETURNING id INTO daily_id;
  INSERT INTO public.radar_publication_state(window_key,status,last_attempt_at,last_success_snapshot_id,terminal_reason,updated_at)
  VALUES('home','valid',p_published_at,home_id,NULL,p_published_at),('daily','valid',p_published_at,daily_id,NULL,p_published_at)
  ON CONFLICT(window_key) DO UPDATE SET status=EXCLUDED.status,last_attempt_at=EXCLUDED.last_attempt_at,last_success_snapshot_id=EXCLUDED.last_success_snapshot_id,terminal_reason=NULL,updated_at=EXCLUDED.updated_at;
  RETURN jsonb_build_object('homeId',home_id,'dailyId',daily_id,'publicationPhase',v_phase,'dataCutoffAt',v_cutoff,'datasetCompletenessPct',v_pct);
END $function$

CREATE OR REPLACE FUNCTION public.publish_research_article_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_author_principal text, p_reviewer_principal text, p_author_result_id uuid, p_author_result_hash text, p_reviewer_result_id uuid, p_reviewer_result_hash text, p_content_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior jsonb;ctx jsonb;i public.research_article_input_revisions_v2;j public.research_deep_jobs_v1;
 a public.research_author_assignments_v2;ra public.research_reviewer_assignments_v2;
 ar public.research_author_results_v2;rr public.research_reviewer_results_v2;
 o public.candidate_dossier_outbox_v5;b uuid;d uuid;c uuid;content jsonb;rh text;sh text;expiry timestamptz;
BEGIN
 -- Historical replay is checked before any live claim/source assertion.
 prior:=public.read_completed_research_publication_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,
  p_author_result_id,p_author_result_hash,p_reviewer_result_id,p_reviewer_result_hash);
 IF prior IS NOT NULL THEN
  IF p_content_hash IS DISTINCT FROM prior->'receipt'->>'contentHash' THEN RAISE EXCEPTION 'research_publication_replay_content';END IF;
  RETURN prior;
 END IF;
 -- The completed reader already holds source→global→original job locks.
 ctx:=public.read_research_reviewer_result_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_author_result_id,p_author_result_hash);
 SELECT * INTO i FROM public.research_article_input_revisions_v2 WHERE revision_id=p_revision_id;
 SELECT * INTO j FROM public.research_deep_jobs_v1 WHERE job_id=i.job_id FOR UPDATE;
 SELECT * INTO a FROM public.research_author_assignments_v2 WHERE input_revision_id=i.revision_id;
 SELECT * INTO ar FROM public.research_author_results_v2 WHERE result_id=p_author_result_id;
 SELECT * INTO rr FROM public.research_reviewer_results_v2 WHERE result_id=p_reviewer_result_id;
 SELECT * INTO ra FROM public.research_reviewer_assignments_v2 WHERE assignment_id=rr.assignment_id;
 IF i.source_seal_id IS NULL OR j.status IS DISTINCT FROM 'running' OR j.attempts IS DISTINCT FROM i.attempt
  OR j.lease_owner IS DISTINCT FROM a.work_owner OR j.lease_expires_at IS DISTINCT FROM a.original_job_deadline
  OR ctx->'reviewResult'->>'result_id' IS DISTINCT FROM rr.result_id::text
  OR ctx->'reviewResult'->>'result_hash' IS DISTINCT FROM rr.result_hash
  OR rr.payload->'rawReview'->>'decision' IS DISTINCT FROM 'accepted'
 THEN RAISE EXCEPTION 'research_publication_live_fence';END IF;
 PERFORM public.assert_research_source_seal_v2(i.source_seal_id);
 PERFORM public.assert_research_editorial_review_v2(rr.payload->'packet',rr.payload->'rawReview');
 IF rr.payload->>'packetHash' IS DISTINCT FROM public.research_complete_hash_v2(rr.payload->'packet')
  OR rr.payload->'packet'->>'articleHash' IS DISTINCT FROM ar.payload->'validatedArticle'->>'articleHash'
  OR rr.payload->'packet'->'article' IS DISTINCT FROM ar.payload->'rawArticle'
  OR rr.payload->'packet'->'tables' IS DISTINCT FROM ar.payload->'validatedArticle'->'tables'
  OR rr.payload->'packet'->'valuations' IS DISTINCT FROM ar.payload->'validatedArticle'->'valuations'
 THEN RAISE EXCEPTION 'research_publication_packet_conflict';END IF;
 content:=public.research_publication_content_v2(ar.payload);
 IF p_content_hash IS NULL OR p_content_hash !~ '^[a-f0-9]{64}$' OR public.research_complete_hash_v2(content) IS DISTINCT FROM p_content_hash
 THEN RAISE EXCEPTION 'research_publication_content_hash';END IF;
 expiry:=least(j.lease_expires_at,ra.reservation_expires_at,a.reservation_expires_at);
 IF clock_timestamp()>=expiry THEN RAISE EXCEPTION 'research_publication_expired';END IF;
 b:=public.ensure_research_publication_bundle_v2(i.revision_id,i.input_hash);
 INSERT INTO public.candidate_dossier_outbox_v5(bundle_id,revision_kind,research_input_revision_id,research_company_id,research_snapshot_hash,input_hash,publication_kind,deep_job_id,deep_attempt)
 VALUES(b,'research_input_v2',i.revision_id,i.research_company_id,i.snapshot_hash,i.input_hash,'deep',j.job_id,i.attempt)
 ON CONFLICT(research_input_revision_id,input_hash,publication_kind) WHERE revision_kind='research_input_v2' DO NOTHING;
 SELECT * INTO o FROM public.candidate_dossier_outbox_v5 WHERE revision_kind='research_input_v2'
  AND research_input_revision_id=i.revision_id AND input_hash=i.input_hash AND publication_kind='deep' FOR UPDATE;
 IF o.bundle_id IS DISTINCT FROM b OR o.deep_job_id IS DISTINCT FROM j.job_id OR o.deep_attempt IS DISTINCT FROM i.attempt
  OR o.status IS DISTINCT FROM 'queued' OR o.attempts IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'research_publication_outbox_conflict';END IF;
 PERFORM 1 FROM public.candidate_dossier_bundles WHERE bundle_id=b FOR UPDATE;
 UPDATE public.candidate_dossier_outbox_v5 SET status='running',attempts=1,lease_owner=a.work_owner,lease_expires_at=expiry,updated_at=clock_timestamp() WHERE job_id=o.job_id;
 rh:=public.research_complete_hash_v2(jsonb_build_object('domain','research-publication-request-v2','input',p_request,
  'inputRevisionId',p_revision_id,'inputHash',p_input_hash,'authorResultId',p_author_result_id,'authorResultHash',p_author_result_hash,
  'reviewerResultId',p_reviewer_result_id,'reviewerResultHash',p_reviewer_result_hash));
 sh:=public.research_complete_hash_v2(jsonb_build_object('domain','research-publication-v2','requestHash',rh,
  'researchCompanyId',i.research_company_id,'snapshotHash',i.snapshot_hash,'bundleId',b,'contentHash',p_content_hash));
 INSERT INTO public.candidate_research_dossiers(narrative_kind,content,validation_status,bundle_hash,detail_payload_hash,bundle_id,input_hash,
  claims,source_references,claim_fact_map,published_at,revision_kind,research_input_revision_id,research_company_id,research_snapshot_hash,
  research_author_result_id,research_reviewer_result_id,source_seal_id)
 VALUES('codex_enriched',content,'valid',i.input_hash,i.input_hash,b,i.input_hash,'[]',ar.payload->'validatedArticle'->'sources','{}',clock_timestamp(),
  'research_input_v2',i.revision_id,i.research_company_id,i.snapshot_hash,ar.result_id,rr.result_id,i.source_seal_id) RETURNING id INTO d;
 INSERT INTO public.candidate_dossier_submission_receipts(bundle_id,input_hash,dossier_id,submission_hash,status,revision_kind,
  research_input_revision_id,research_company_id,research_snapshot_hash,research_author_result_id,research_reviewer_result_id,source_seal_id,research_request_hash)
 VALUES(b,i.input_hash,d,sh,'accepted','research_input_v2',i.revision_id,i.research_company_id,i.snapshot_hash,ar.result_id,rr.result_id,i.source_seal_id,rh) RETURNING submission_id INTO c;
 IF clock_timestamp()>=expiry THEN RAISE EXCEPTION 'research_publication_expired';END IF;
 UPDATE public.candidate_dossier_outbox_v5 SET status='accepted',lease_owner=NULL,lease_expires_at=NULL,receipt_id=c,last_submission_hash=sh,updated_at=clock_timestamp() WHERE job_id=o.job_id;
 UPDATE public.research_deep_jobs_v1 SET status='completed',lease_owner=NULL,lease_expires_at=NULL,receipt_id=c,completion_owner=a.work_owner,
  completion_outbox_owner=a.work_owner,completion_outbox_job_id=o.job_id,completion_reviewer_result_id=rr.result_id,
  completion_article_hash=ar.payload->'validatedArticle'->>'articleHash',completion_submission_hash=sh,terminal_reason=NULL,finished_at=clock_timestamp()
 WHERE job_id=j.job_id;
 IF clock_timestamp()>=expiry THEN RAISE EXCEPTION 'research_publication_expired';END IF;
 prior:=public.read_completed_research_publication_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,
  p_author_result_id,p_author_result_hash,p_reviewer_result_id,p_reviewer_result_hash);
 IF prior IS NULL THEN RAISE EXCEPTION 'research_publication_receipt_missing';END IF;
 RETURN jsonb_set(prior,'{idempotentReplay}','false');
END $function$

CREATE OR REPLACE FUNCTION public.purge_internal_nonces_v3(cutoff timestamp with time zone, caller_principal uuid)
 RETURNS TABLE(deleted integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz := clock_timestamp(); v_deleted integer;
BEGIN
  IF $1 > v_now - interval '24 hours' THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_authority_request';
  END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($2,'opportunity_runner',v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  DELETE FROM public.internal_principal_nonces_v3 n WHERE n.recorded_at < $1;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,input_hash,disposition,recorded_at
  ) VALUES(
    'purge_internal_nonces_v3',$2,'nonce_purge',NULL,
    encode(extensions.digest(convert_to(jsonb_build_array($1)::text,'utf8'),'sha256'),'hex'),'purged',v_now
  );
  RETURN QUERY SELECT v_deleted;
END
$function$

CREATE OR REPLACE FUNCTION public.read_insider_snapshot_page_v1(p_run uuid, p_dataset integer, p_snapshot uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.insider_snapshots_v1; p public.insider_snapshot_progress_v1; rows jsonb; docs jsonb:='[]'; doc jsonb; i integer; stop_at integer;
BEGIN
 IF p_run IS NULL OR p_dataset IS NULL OR p_snapshot IS NULL OR NOT EXISTS(SELECT 1 FROM public.insider_acquisition_runs_v1 r JOIN public.insider_run_members_v1 m ON m.run_id=r.id WHERE r.id=p_run AND r.frozen_at IS NOT NULL AND m.dataset=p_dataset AND m.snapshot_id=p_snapshot) THEN RAISE EXCEPTION 'insider_frozen_run_binding_required'; END IF;
 SELECT * INTO STRICT s FROM public.insider_snapshots_v1 WHERE id=p_snapshot AND dataset=p_dataset;
 SELECT * INTO STRICT p FROM public.insider_snapshot_progress_v1 WHERE snapshot_id=p_snapshot;
 rows:=public.insider_snapshot_assert_v1(p_snapshot); stop_at:=least(p.offset_rows+500,s.row_count);
 IF NOT p.complete AND stop_at>p.offset_rows THEN FOR i IN p.offset_rows..stop_at-1 LOOP
  doc:=public.insider_expected_document_v1(p_snapshot,i,rows->i); IF doc IS NOT NULL THEN docs:=docs||jsonb_build_array(doc); END IF;
 END LOOP; END IF;
 RETURN jsonb_build_object('runId',p_run,'dataset',p_dataset,'snapshotId',p_snapshot,'offset',p.offset_rows,'generation',p.generation,'nextOffset',stop_at,'totalRows',s.row_count,'complete',p.complete,'documents',docs,'excludedRows',stop_at-p.offset_rows-jsonb_array_length(docs),'observedAt',s.observed_at,'attemptedAt',s.attempted_at,'hash',s.raw_sha256);
END $function$

CREATE OR REPLACE FUNCTION public.read_legacy_candidate_fact_plane_v3_11(p_source_cutoff timestamp with time zone, p_candidate_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_bounded_candidates jsonb;v_bounded_result jsonb;v_result jsonb;v_bytes integer;
BEGIN
  IF jsonb_typeof(p_candidate_result)<>'object'
    OR jsonb_typeof(coalesce(p_candidate_result->'candidates','[]'::jsonb))<>'array'
    OR jsonb_array_length(coalesce(p_candidate_result->'candidates','[]'::jsonb))>60
  THEN RAISE EXCEPTION 'bound_violation';END IF;

  SELECT coalesce(jsonb_agg(candidate.value ORDER BY candidate.ordinality),'[]'::jsonb)
  INTO v_bounded_candidates
  FROM (
    SELECT candidate.value,candidate.ordinality
    FROM jsonb_array_elements(coalesce(p_candidate_result->'candidates','[]'::jsonb))
      WITH ORDINALITY candidate(value,ordinality)
    WHERE coalesce((candidate.value->>'deepSelected')::boolean,false)
    ORDER BY candidate.ordinality
    LIMIT 10
  ) candidate;

  v_bounded_result:=jsonb_set(p_candidate_result,'{candidates}',v_bounded_candidates,true);
  v_result:=public.read_legacy_candidate_fact_plane_v3_16_11_internal(
    p_source_cutoff,v_bounded_result
  );
  -- Preserve every visible source/shallow candidate. Only authority-heavy fact
  -- arrays are bounded; omitted deep candidates remain explicitly unavailable.
  v_result:=jsonb_set(v_result,'{candidateResult}',p_candidate_result,true);
  v_bytes:=octet_length(convert_to(v_result::text,'utf8'));
  IF jsonb_array_length(v_bounded_candidates)>10 OR v_bytes>3145728
  THEN RAISE EXCEPTION 'bound_violation';END IF;
  RETURN v_result;
END
$function$

CREATE OR REPLACE FUNCTION public.read_legacy_discovery_authority_v3_11(uuid, text, text)
 RETURNS SETOF legacy_discovery_authority_page_v3_11
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_kind public.opportunity_legacy_authority_page_kind_v3_11;
  v_size integer;v_count integer;v_pages integer;v_page integer;v_rows jsonb;v_all jsonb;v_page_bytes bytea;v_header jsonb;v_header_bytes bytea;
BEGIN
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 r WHERE r.run_id=$1 AND r.producer_commit_sha=$2 AND r.scheduler_config_sha256=$3 AND r.status='running';
  IF NOT FOUND THEN RETURN;END IF;
  PERFORM public.opportunity_authority_selected_stream_count_v3_internal('instrument_roster',v_run.source_cutoff);
  PERFORM public.opportunity_authority_selected_stream_count_v3_internal('stock_alias',v_run.source_cutoff);
  PERFORM public.opportunity_authority_selected_stream_count_v3_internal('sector_assignment',v_run.source_cutoff);
  PERFORM public.opportunity_authority_selected_stream_count_v3_internal('discovery_identity',v_run.source_cutoff);
  v_header:=jsonb_build_object('schema','legacy-discovery-authority-v1','runId',v_run.run_id,'scheduledOccurrenceId',v_run.scheduled_occurrence_id,'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  v_header_bytes:=convert_to(v_header::text,'utf8');
  FOREACH v_kind IN ARRAY ARRAY['roster','alias','taxonomy','selected_revision']::public.opportunity_legacy_authority_page_kind_v3_11[] LOOP
    v_size:=CASE WHEN v_kind='selected_revision' THEN 200 ELSE 500 END;
    IF v_kind='roster' THEN
      WITH heads AS MATERIALIZED (
        SELECT DISTINCT ON(stock_id) instrument.* FROM public.stock_instruments_v3 instrument
        WHERE instrument.source_timestamp<=v_run.source_cutoff AND instrument.recorded_at<=v_run.source_cutoff
          AND instrument.valid_from<=v_run.source_cutoff
        ORDER BY stock_id,recorded_at DESC,instrument_authority_id
      )
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,symbol,exchange,instrument_type,listing_status,official_legal_name,official_short_name) ORDER BY symbol,stock_id),'[]'::jsonb)
      INTO v_all FROM heads WHERE instrument_type='common_stock' AND listing_status='active'
        AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSIF v_kind='alias' THEN
      WITH heads AS MATERIALIZED (
        SELECT DISTINCT ON(stock_id,normalized_alias,source) alias.* FROM public.stock_aliases_v3 alias
        WHERE alias.source_timestamp<=v_run.source_cutoff AND alias.approved_at<=v_run.source_cutoff
          AND alias.recorded_at<=v_run.source_cutoff AND alias.valid_from<=v_run.source_cutoff
        ORDER BY stock_id,normalized_alias,source,recorded_at DESC,alias_authority_id
      )
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,normalized_alias,source) ORDER BY normalized_alias,stock_id),'[]'::jsonb)
      INTO v_all FROM heads WHERE status='active' AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSIF v_kind='taxonomy' THEN
      WITH heads AS MATERIALIZED (
        SELECT DISTINCT ON(stock_id,market) assignment.* FROM public.stock_sector_assignments_v3 assignment
        WHERE assignment.source_timestamp<=v_run.source_cutoff AND assignment.recorded_at<=v_run.source_cutoff
          AND assignment.valid_from<=v_run.source_cutoff
        ORDER BY stock_id,market,recorded_at DESC,assignment_authority_id
      )
      SELECT coalesce(jsonb_agg(jsonb_build_array(stock_id,market,official_industry_code,canonical_sector_key) ORDER BY stock_id,canonical_sector_key),'[]'::jsonb)
      INTO v_all FROM heads WHERE status='active' AND (valid_to IS NULL OR valid_to>v_run.source_cutoff);
    ELSE
      WITH authority_heads AS MATERIALIZED (
        SELECT DISTINCT ON(authority.source_identity_id) authority.*
        FROM public.source_identity_authorities_v3 authority
        WHERE authority.approved_at<=v_run.source_cutoff AND authority.recorded_at<=v_run.source_cutoff
          AND authority.valid_from<=v_run.source_cutoff
        ORDER BY authority.source_identity_id,authority.recorded_at DESC,authority.authority_id
      ), family_heads AS (
        SELECT d.*,row_number() OVER(PARTITION BY d.source_key,d.revision_family_key ORDER BY d.recorded_at DESC,d.revision_id) AS family_rank
        FROM public.source_document_revisions_v3 d
        JOIN public.source_revision_family_registry_v3 registry ON registry.source_key=d.source_key AND registry.revision_family_key=d.revision_family_key
          AND registry.approved_source_identity_id=d.approved_source_identity_id AND registry.stable_connector_document_id=d.stable_connector_document_id
        JOIN authority_heads authority ON authority.authority_id=d.source_identity_authority_id
          AND authority.source_identity_id=d.approved_source_identity_id AND authority.source_key=d.source_key
        WHERE d.collected_at<=v_run.source_cutoff AND d.recorded_at<=v_run.source_cutoff
          AND (d.recorded_at,d.revision_id)>coalesce((
            SELECT ROW(cursor.source_document_high_water_at,cursor.source_document_high_water_revision_id)
            FROM public.legacy_producer_runs_v3_11 prior
            JOIN public.legacy_source_sync_cursors_v3_19 cursor ON cursor.source_run_id=prior.run_id
            WHERE prior.status='success' AND prior.source_cutoff<v_run.source_cutoff
            ORDER BY prior.source_cutoff DESC,prior.terminal_at DESC,prior.run_id DESC LIMIT 1
          ),ROW('-infinity'::timestamptz,'00000000-0000-0000-0000-000000000000'::uuid))
          AND authority.status='active' AND (authority.valid_to IS NULL OR authority.valid_to>v_run.source_cutoff)
      ), connector_bound AS (
        SELECT f.*,row_number() OVER(PARTITION BY f.source_key ORDER BY f.collected_at DESC,f.revision_family_key,f.revision_id) AS connector_rank
        FROM family_heads f WHERE f.family_rank=1 AND f.acquisition_status='complete'
          AND (f.published_at IS NULL OR f.published_at<=f.collected_at)
      )
      SELECT coalesce(jsonb_agg(jsonb_build_array(source_key,revision_id,revision_family_key,approved_source_identity_id,stable_connector_document_id,published_at,collected_at,
        raw_field_payload_algorithm_version,ingestion_content_revision_sha256,canonical_content_algorithm_version,ingestion_canonical_content_hash_v3)
      ORDER BY source_key,collected_at DESC,revision_family_key,revision_id),'[]'::jsonb) INTO v_all FROM connector_bound WHERE connector_rank<=2000;
      IF EXISTS(
        WITH authority_heads AS MATERIALIZED (
          SELECT DISTINCT ON(authority.source_identity_id) authority.*
          FROM public.source_identity_authorities_v3 authority
          WHERE authority.approved_at<=v_run.source_cutoff AND authority.recorded_at<=v_run.source_cutoff
            AND authority.valid_from<=v_run.source_cutoff
          ORDER BY authority.source_identity_id,authority.recorded_at DESC,authority.authority_id
        ), family_heads AS (
          SELECT d.source_key,d.revision_family_key,d.collected_at,d.recorded_at,d.revision_id,d.acquisition_status,d.published_at,
            row_number() OVER(PARTITION BY d.source_key,d.revision_family_key ORDER BY d.recorded_at DESC,d.revision_id) family_rank
          FROM public.source_document_revisions_v3 d
          JOIN authority_heads authority ON authority.authority_id=d.source_identity_authority_id
          WHERE d.collected_at<=v_run.source_cutoff AND d.recorded_at<=v_run.source_cutoff
          AND (d.recorded_at,d.revision_id)>coalesce((
            SELECT ROW(cursor.source_document_high_water_at,cursor.source_document_high_water_revision_id)
            FROM public.legacy_producer_runs_v3_11 prior
            JOIN public.legacy_source_sync_cursors_v3_19 cursor ON cursor.source_run_id=prior.run_id
            WHERE prior.status='success' AND prior.source_cutoff<v_run.source_cutoff
            ORDER BY prior.source_cutoff DESC,prior.terminal_at DESC,prior.run_id DESC LIMIT 1
          ),ROW('-infinity'::timestamptz,'00000000-0000-0000-0000-000000000000'::uuid))
            AND authority.status='active' AND (authority.valid_to IS NULL OR authority.valid_to>v_run.source_cutoff)
        ), connector_bound AS (
          SELECT row_number() OVER(PARTITION BY source_key ORDER BY collected_at DESC,revision_family_key,revision_id) connector_rank
          FROM family_heads WHERE family_rank=1 AND acquisition_status='complete'
            AND (published_at IS NULL OR published_at<=collected_at)
        ) SELECT 1 FROM connector_bound WHERE connector_rank>2000
      ) THEN RAISE EXCEPTION 'bound_violation';END IF;
    END IF;
    v_count:=jsonb_array_length(v_all);v_pages:=greatest(1,ceil(v_count::numeric/v_size)::integer);
    FOR v_page IN 0..v_pages-1 LOOP
      SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(v_all) WITH ORDINALITY item(value,ordinal) WHERE ordinal>v_page*v_size AND ordinal<=(v_page+1)*v_size;
      v_page_bytes:=convert_to(v_rows::text,'utf8');
      RETURN NEXT ROW(v_kind,v_page,v_page*v_size,jsonb_array_length(v_rows),v_page_bytes,v_rows,encode(extensions.digest(v_page_bytes,'sha256'),'hex'),v_count,v_pages,
        encode(extensions.digest(convert_to(v_all::text,'utf8'),'sha256'),'hex'),v_header_bytes,v_header,encode(extensions.digest(v_header_bytes,'sha256'),'hex'))::public.legacy_discovery_authority_page_v3_11;
    END LOOP;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.read_research_article_input_revision_v2(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent jsonb; saved public.research_article_input_revisions_v2;
BEGIN
 parent:=public.research_complete_parent_v2(p_request);
 SELECT * INTO saved FROM public.research_article_input_revisions_v2 WHERE preparation_id=(p_request->>'preparationId')::uuid;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','absent','preparation',parent,'dispatchReady',false);END IF;
 IF saved.canonical_request IS DISTINCT FROM p_request OR saved.request_hash IS DISTINCT FROM public.research_complete_hash_v2(p_request) THEN RAISE EXCEPTION 'complete_replay_conflict';END IF;
 IF clock_timestamp()>=least((parent->'payload'->'originalJob'->>'leaseExpiresAt')::timestamptz,(parent->'payload'->'originalReservation'->>'leaseExpiresAt')::timestamptz) THEN RAISE EXCEPTION 'complete_lease_lost';END IF;
 RETURN to_jsonb(saved)||jsonb_build_object('status','sealed','replay',true,'dispatchReady',false);
END $function$

CREATE OR REPLACE FUNCTION public.read_research_author_packet_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_principal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a jsonb; revision jsonb; payload jsonb; seal public.research_source_seals_v2;
 item jsonb; doc jsonb; m jsonb; descriptor jsonb; sources jsonb:='[]'; result jsonb;
 observed timestamptz; collected timestamptz; cutoff timestamptz; symbol text;
BEGIN
 a:=public.read_research_author_assignment_v2(p_request,p_revision_id,p_input_hash,p_principal);
 IF a IS NULL THEN RAISE EXCEPTION 'research_author_packet_assignment_missing'; END IF;
 revision:=public.research_author_assignment_context_v2(p_request,p_revision_id,p_input_hash,p_principal);
 payload:=revision->'canonical_payload';symbol:=payload->'researchIdentity'->>'symbol';
 cutoff:=(payload->'clocks'->>'researchCutoff')::timestamptz;
 IF cutoff IS NULL OR NOT isfinite(cutoff) OR cutoff>clock_timestamp()
  OR jsonb_typeof(payload->'sources'->'manifest') IS DISTINCT FROM 'array'
  OR jsonb_array_length(payload->'sources'->'manifest')>30 THEN
  RAISE EXCEPTION 'research_author_packet_source_shape'; END IF;
 IF jsonb_array_length(payload->'sources'->'manifest')>0 THEN
  SELECT * INTO seal FROM public.research_source_seals_v2
   WHERE seal_id=(payload->'sources'->>'sealId')::uuid;
  IF seal.seal_id IS NULL OR seal.received_at IS NULL OR NOT isfinite(seal.received_at)
   OR seal.received_at>cutoff OR seal.documents IS DISTINCT FROM payload->'sources'->'manifest'
   THEN RAISE EXCEPTION 'research_author_packet_seal_clock'; END IF;
 END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(payload->'sources'->'manifest') x ORDER BY x->>'id' LOOP
  SELECT to_jsonb(d) INTO doc FROM public.source_raw_documents d WHERE id=(item->>'id')::uuid;
  IF doc IS NULL OR encode(sha256(convert_to(doc::text,'UTF8')),'hex') IS DISTINCT FROM item->>'rowHash'
   THEN RAISE EXCEPTION 'research_author_packet_source_changed'; END IF;
  m:=doc->'metadata';
  IF m->>'rights_boundary' IS DISTINCT FROM 'public_citation' OR m->>'visibility' IS DISTINCT FROM 'public'
   OR m->>'subject_scope' IS NULL OR m->>'subject_scope' NOT IN ('company_mentions','industry_context')
   OR jsonb_typeof(doc->'symbols') IS DISTINCT FROM 'array'
   OR jsonb_array_length(doc->'symbols')>50
   OR EXISTS(SELECT FROM jsonb_array_elements(doc->'symbols') x
    WHERE jsonb_typeof(x)<>'string' OR (x#>>'{}')!~'^[0-9]{4}$')
   OR (m->>'subject_scope'='company_mentions' AND NOT(doc->'symbols' @> jsonb_build_array(symbol)))
   OR (m->>'subject_scope'='industry_context' AND doc->'symbols'<>'[]'::jsonb)
   OR NULLIF(m->>'retracted_at','') IS NOT NULL OR m->>'withdrawn'='true'
   OR m->>'claim_status' IS NULL OR m->>'claim_status' NOT IN ('rumor','reported','confirmed')
   THEN RAISE EXCEPTION 'research_author_packet_source_rights_or_scope'; END IF;
  IF jsonb_typeof(doc->'title') IS DISTINCT FROM 'string' OR octet_length(doc->>'title') NOT BETWEEN 1 AND 512
   OR jsonb_typeof(doc->'summary') IS DISTINCT FROM 'string' OR octet_length(doc->>'summary') NOT BETWEEN 1 AND 4096
   OR jsonb_typeof(m->'catalyst') IS DISTINCT FROM 'string' OR octet_length(m->>'catalyst') NOT BETWEEN 1 AND 2048
   OR jsonb_typeof(m->'risk') IS DISTINCT FROM 'string' OR octet_length(m->>'risk') NOT BETWEEN 1 AND 2048
   OR jsonb_typeof(doc->'platform') IS DISTINCT FROM 'string' OR octet_length(doc->>'platform') NOT BETWEEN 1 AND 80
   OR jsonb_typeof(m->'canonical_url') IS DISTINCT FROM 'string' OR octet_length(m->>'canonical_url') NOT BETWEEN 1 AND 800
   OR jsonb_typeof(m->'first_observed_at') IS DISTINCT FROM 'string' OR octet_length(m->>'first_observed_at') NOT BETWEEN 1 AND 100
   THEN RAISE EXCEPTION 'research_author_packet_content_bound'; END IF;
  observed:=(m->>'first_observed_at')::timestamptz;collected:=(doc->>'collected_at')::timestamptz;
  IF observed IS NULL OR collected IS NULL OR NOT isfinite(observed) OR NOT isfinite(collected)
   OR observed>collected OR collected>seal.received_at
   OR (doc->>'published_at')::timestamptz>observed
   OR ((doc->>'published_at') IS NOT NULL AND NOT isfinite((doc->>'published_at')::timestamptz))
   THEN RAISE EXCEPTION 'research_author_packet_source_clock'; END IF;
  descriptor:=jsonb_build_object('id',item->'id','rowHash',item->'rowHash','url',m->'canonical_url',
   'observedAt',m->'first_observed_at','admittedAt',seal.received_at,
   'publication',jsonb_build_object('precision','unknown','raw',NULL,'timezone',NULL,'instant',NULL),
   'scope',m->'subject_scope','symbols',doc->'symbols','rights','public_summary_only','retracted',false,'superseded',false);
  sources:=sources||jsonb_build_array(jsonb_build_object('descriptor',descriptor,
   'title',doc->'title','summary',doc->'summary','catalyst',m->'catalyst','risk',m->'risk',
   'platform',doc->'platform','sourceClaimStatus',m->'claim_status','collectedAt',doc->'collected_at',
   'unverifiedPublicationClaim',doc->'published_at','untrustedEvidence',true));
  IF octet_length(sources::text)>307200 THEN RAISE EXCEPTION 'research_author_packet_sources_bound'; END IF;
 END LOOP;
 -- Original source -> deep locks still held. No renewal on read or replay.
 IF public.read_research_author_assignment_v2(p_request,p_revision_id,p_input_hash,p_principal) IS DISTINCT FROM a
  THEN RAISE EXCEPTION 'research_author_packet_assignment_changed'; END IF;
 result:=jsonb_build_object('assignment',a-'controller_principal'-'canonical_request',
  'inputRevisionId',p_revision_id,'inputHash',p_input_hash,'sourceSealReceivedAt',seal.received_at,'sources',sources);
 IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'research_author_packet_response_bound'; END IF;
 IF clock_timestamp()>=least((a->>'original_job_deadline')::timestamptz,(a->>'reservation_expires_at')::timestamptz)
  THEN RAISE EXCEPTION 'research_author_packet_expired'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.read_research_author_result_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_principal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a jsonb; saved public.research_author_results_v2;
BEGIN
 a:=public.read_research_author_assignment_v2(p_request,p_revision_id,p_input_hash,p_principal);
 IF a IS NULL THEN RAISE EXCEPTION 'research_author_result_assignment_missing'; END IF;
 SELECT * INTO saved FROM public.research_author_results_v2 WHERE assignment_id=(a->>'assignment_id')::uuid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF clock_timestamp()>=least((a->>'original_job_deadline')::timestamptz,(a->>'reservation_expires_at')::timestamptz)
 THEN RAISE EXCEPTION 'research_author_result_expired'; END IF;
 RETURN to_jsonb(saved)-'invocation_id';
END $function$

CREATE OR REPLACE FUNCTION public.read_research_company_publication_v2(p_company uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.candidate_research_dossiers;c public.candidate_dossier_submission_receipts;
 i public.research_article_input_revisions_v2;a public.research_author_assignments_v2;
 ra public.research_reviewer_assignments_v2;ar public.research_author_results_v2;
 rr public.research_reviewer_results_v2;company public.research_observed_companies_v1;v jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR p_company IS NULL
 THEN RAISE EXCEPTION 'research_publication_view_request';END IF;
 -- Acquire the original order BEFORE selecting the latest version. A withdrawal
 -- must never make the reader silently select an older positive article.
 PERFORM pg_advisory_xact_lock(610091002::bigint);PERFORM pg_advisory_xact_lock(2409,6002);
 SELECT * INTO company FROM public.research_observed_companies_v1 WHERE research_company_id=p_company;
 IF company.research_company_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO d FROM public.candidate_research_dossiers WHERE research_company_id=p_company
  AND revision_kind='research_input_v2' AND validation_status='valid'
  ORDER BY published_at DESC,id DESC LIMIT 1;
 IF d.id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO c FROM public.candidate_dossier_submission_receipts WHERE dossier_id=d.id;
 SELECT * INTO i FROM public.research_article_input_revisions_v2 WHERE revision_id=d.research_input_revision_id;
 SELECT * INTO ar FROM public.research_author_results_v2 WHERE result_id=d.research_author_result_id;
 SELECT * INTO rr FROM public.research_reviewer_results_v2 WHERE result_id=d.research_reviewer_result_id;
 SELECT * INTO a FROM public.research_author_assignments_v2 WHERE assignment_id=ar.assignment_id;
 SELECT * INTO ra FROM public.research_reviewer_assignments_v2 WHERE assignment_id=rr.assignment_id;
 IF c.submission_id IS NULL OR c.status IS DISTINCT FROM 'accepted' OR i.revision_id IS NULL
  OR d.published_at IS NULL OR NOT isfinite(d.published_at)
  OR i.research_company_id IS DISTINCT FROM p_company OR c.research_company_id IS DISTINCT FROM p_company
  OR ar.result_id IS NULL OR rr.result_id IS NULL OR a.assignment_id IS NULL OR ra.assignment_id IS NULL
 THEN RAISE EXCEPTION 'research_publication_view_lineage';END IF;
 v:=public.read_completed_research_publication_v2(i.canonical_request,i.revision_id,i.input_hash,
  a.controller_principal,ra.reviewer_principal,ar.result_id,ar.result_hash,rr.result_id,rr.result_hash);
 IF v IS NULL OR v->'receipt'->>'dossierId' IS DISTINCT FROM d.id::text
  OR v->'receipt'->>'submissionId' IS DISTINCT FROM c.submission_id::text
  OR v->'content'->'deepResearch'->'article'->>'researchCompanyId' IS DISTINCT FROM p_company::text
  OR v->'content'->'deepResearch'->'article'->>'symbol' IS DISTINCT FROM company.symbol
 THEN RAISE EXCEPTION 'research_publication_view_lineage';END IF;
 RETURN jsonb_build_object('schemaVersion','research-company-publication-v2',
  'researchCompanyId',p_company,'symbol',company.symbol,'publishedAt',d.published_at,'publication',v);
END $function$

CREATE OR REPLACE FUNCTION public.read_research_observed_claim_v2(p_owner text, p_snapshot_hash text, p_job_id uuid DEFAULT NULL::uuid, p_attempt integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.research_deep_jobs_v1;r public.research_priority_runs_v1;s public.research_observed_roster_snapshots_v1;a public.research_deep_job_attempts_v1;m public.research_model_reservations_v1;done public.research_model_completions_v1;n timestamptz:=clock_timestamp();
BEGIN
 IF p_owner IS NULL OR p_owner !~ '^[A-Za-z0-9:_-]{3,120}$' OR p_snapshot_hash IS NULL OR p_snapshot_hash !~ '^[a-f0-9]{64}$' OR (p_job_id IS NULL)<>(p_attempt IS NULL) OR p_attempt NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'observed_claim_identity_invalid';END IF;
 IF (SELECT count(*)FROM public.research_deep_jobs_v1 WHERE research_scope='research_observed_v1'AND observed_snapshot_hash=p_snapshot_hash AND lease_owner=p_owner AND status='running'AND lease_expires_at>n AND(p_job_id IS NULL OR(job_id=p_job_id AND attempts=p_attempt)))>1 THEN RAISE EXCEPTION 'observed_claim_ambiguous';END IF;
 SELECT *INTO j FROM public.research_deep_jobs_v1 WHERE research_scope='research_observed_v1'AND observed_snapshot_hash=p_snapshot_hash AND lease_owner=p_owner AND status='running'AND lease_expires_at>n AND(p_job_id IS NULL OR(job_id=p_job_id AND attempts=p_attempt));IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT *INTO r FROM public.research_priority_runs_v1 WHERE run_id=j.priority_run_id AND research_scope=j.research_scope AND observed_snapshot_hash=j.observed_snapshot_hash;
 IF NOT FOUND THEN RAISE EXCEPTION 'observed_claim_run_changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.research_observed_priority_store_receipts_v1 receipt WHERE receipt.run_id=r.run_id AND receipt.stored_run_hash=encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex'))THEN RAISE EXCEPTION 'observed_claim_store_lineage_missing';END IF;
 SELECT *INTO s FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=j.observed_snapshot_hash;
 IF NOT FOUND OR s.received_at>r.as_of OR s.latest_observed_at>r.as_of OR r.as_of>n OR NOT EXISTS(SELECT 1 FROM public.research_observed_roster_members_v1 WHERE snapshot_hash=j.observed_snapshot_hash AND research_company_id=j.research_company_id AND symbol=j.symbol) OR NOT EXISTS(SELECT 1 FROM public.research_deep_admission_charges_v1 WHERE job_id=j.job_id AND issuer_key='TW:'||j.symbol) THEN RAISE EXCEPTION 'observed_claim_membership_changed';END IF;
 IF j.stock_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.stocks WHERE id=j.stock_id AND symbol=j.symbol AND market='TW')THEN RAISE EXCEPTION 'observed_claim_mapping_changed';END IF;
 SELECT *INTO a FROM public.research_deep_job_attempts_v1 WHERE job_id=j.job_id AND attempt=j.attempts AND owner=p_owner;
 IF NOT FOUND OR a.lease_expires_at<>j.lease_expires_at THEN RAISE EXCEPTION 'observed_claim_attempt_changed';END IF;
 SELECT *INTO m FROM public.research_model_reservations_v1 WHERE role='company_research'AND owner=p_owner AND work_key='deep:'||j.job_id||':'||j.attempts;
 IF NOT FOUND OR a.claimed_at<m.started_at OR a.claimed_at>n OR j.lease_expires_at<>m.lease_expires_at THEN RAISE EXCEPTION 'observed_claim_reservation_changed';END IF;
 SELECT *INTO done FROM public.research_model_completions_v1 WHERE reservation_id=m.reservation_id;
 IF FOUND AND(done.owner<>p_owner OR done.finished_at<m.started_at OR done.finished_at>=m.lease_expires_at OR done.finished_at>n)THEN RAISE EXCEPTION 'observed_claim_completion_changed';END IF;
 IF done.reservation_id IS NULL AND m.lease_expires_at<=n THEN RAISE EXCEPTION 'observed_claim_expired';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.research_deep_jobs_v1 x WHERE x.job_id=j.job_id AND to_jsonb(x)=to_jsonb(j)) THEN RAISE EXCEPTION 'observed_claim_changed_during_read';END IF;
 RETURN jsonb_build_object('schemaVersion','research-deep-claim-context-v2','observedAt',n,'job',jsonb_build_object('jobId',j.job_id,'symbol',j.symbol,'priorityRunId',j.priority_run_id,'attempt',j.attempts,'owner',j.lease_owner,'leaseExpiresAt',j.lease_expires_at),'modelReservation',jsonb_build_object('reservationId',m.reservation_id,'role',m.role,'owner',m.owner,'workKey',m.work_key,'startedAt',m.started_at,'leaseExpiresAt',m.lease_expires_at),'modelCompletion',CASE WHEN done.reservation_id IS NULL THEN NULL ELSE jsonb_build_object('outcome',done.outcome,'resultHash',done.result_hash,'completedAt',done.finished_at)END,'researchIdentity',jsonb_build_object('scope','research_observed_v1','researchCompanyId',j.research_company_id,'snapshotHash',j.observed_snapshot_hash,'mappingDigest',s.mapping_digest,'stockId',j.stock_id,'priorityInputHash',r.input_hash,'snapshotReceivedAt',s.received_at,'snapshotObservedAt',s.latest_observed_at,'priorityAsOf',r.as_of));
END $function$

CREATE OR REPLACE FUNCTION public.read_research_observed_roster_v1(p_snapshot_hash text, p_as_of timestamp with time zone, p_offset integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.research_observed_roster_snapshots_v1; members jsonb;
BEGIN
 IF p_offset IS NULL OR p_limit IS NULL OR p_offset<0 OR p_offset>5000 OR p_limit<1 OR p_limit>500 OR p_as_of IS NULL OR p_as_of>clock_timestamp() THEN RAISE EXCEPTION 'observed_roster_read_invalid'; END IF;
 SELECT * INTO r FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=p_snapshot_hash AND received_at<=p_as_of AND latest_observed_at<=p_as_of;
 IF NOT FOUND THEN RAISE EXCEPTION 'observed_snapshot_missing_or_future'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.symbol),'[]') INTO members FROM (
  SELECT x.research_company_id,x.symbol,x.exchange,x.isin,x.observed_name AS name,x.observed_sector AS sector,x.cfi,x.observed_at FROM public.research_observed_roster_members_v1 x WHERE snapshot_hash=p_snapshot_hash ORDER BY symbol LIMIT p_limit OFFSET p_offset)m;
 RETURN jsonb_build_object('snapshotHash',r.snapshot_hash,'mappingDigest',r.mapping_digest,'classifierHash',r.classifier_hash,'classificationHash',r.classification_hash,'schemaVersion',r.schema_version,'receivedAt',r.received_at,'latestObservedAt',r.latest_observed_at,'includedCount',r.included_count,'members',members);
END $function$

CREATE OR REPLACE FUNCTION public.read_research_reviewer_context_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_author_principal text, p_reviewer_principal text, p_result_id uuid, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE h jsonb; a jsonb; saved public.research_reviewer_assignments_v2; r public.research_model_reservations_v1; n timestamptz;
BEGIN
 IF p_reviewer_principal IS NULL OR p_reviewer_principal !~ '^[a-f0-9]{64}$'
  OR p_author_principal IS NULL OR p_author_principal !~ '^[a-f0-9]{64}$'
  OR p_reviewer_principal=p_author_principal THEN RAISE EXCEPTION 'research_reviewer_principal_invalid'; END IF;
 -- p_author_principal is server configuration-derived, never the stored fallback.
 h:=public.read_research_author_handoff_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_result_id,p_result_hash);
 IF h->'completion' IS NULL OR h->'completion'='null'::jsonb THEN RAISE EXCEPTION 'research_reviewer_author_handoff_missing'; END IF;
 a:=h->'assignment';
 SELECT * INTO saved FROM public.research_reviewer_assignments_v2 WHERE job_id=(a->>'job_id')::uuid AND attempt=(a->>'attempt')::integer;
 IF NOT FOUND THEN RETURN jsonb_build_object('authorContext',h,'reviewerAssignment',NULL); END IF;
 SELECT * INTO r FROM public.research_model_reservations_v1 WHERE reservation_id=saved.reservation_id;n:=clock_timestamp();
 IF saved.author_assignment_id::text IS DISTINCT FROM a->>'assignment_id' OR saved.author_result_id IS DISTINCT FROM p_result_id
  OR saved.author_result_hash IS DISTINCT FROM p_result_hash OR saved.input_revision_id IS DISTINCT FROM p_revision_id
  OR saved.input_hash IS DISTINCT FROM p_input_hash OR saved.reviewer_principal IS DISTINCT FROM p_reviewer_principal
  OR saved.work_owner IS DISTINCT FROM a->>'work_owner'
  OR saved.original_job_deadline IS DISTINCT FROM (a->>'original_job_deadline')::timestamptz
  OR r.reservation_id IS NULL OR r.role IS DISTINCT FROM 'counter_review' OR r.owner IS DISTINCT FROM saved.work_owner
  OR r.work_key IS DISTINCT FROM 'deep-review-v2:'||saved.job_id||':'||saved.attempt||':'||saved.author_result_id
  OR r.started_at IS DISTINCT FROM saved.reservation_started_at OR r.lease_expires_at IS DISTINCT FROM saved.reservation_expires_at
  OR NOT isfinite(r.started_at) OR NOT isfinite(r.lease_expires_at)
  OR r.lease_expires_at>r.started_at+interval '30 minutes' OR r.started_at>saved.assigned_at
  OR saved.assigned_at>n OR saved.reservation_started_at<(h->'completion'->>'finished_at')::timestamptz
  OR EXISTS(SELECT FROM public.research_model_completions_v1 WHERE reservation_id=r.reservation_id)
  OR n>=least(saved.original_job_deadline,saved.reservation_expires_at)
 THEN RAISE EXCEPTION 'research_reviewer_assignment_fence_lost'; END IF;
 IF clock_timestamp()>=least(saved.original_job_deadline,saved.reservation_expires_at) THEN RAISE EXCEPTION 'research_reviewer_assignment_expired'; END IF;
 RETURN jsonb_build_object('authorContext',h,'reviewerAssignment',to_jsonb(saved));
END $function$

CREATE OR REPLACE FUNCTION public.read_research_reviewer_result_context_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_author_principal text, p_reviewer_principal text, p_result_id uuid, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE h jsonb; a jsonb; ra public.research_reviewer_assignments_v2; r public.research_model_reservations_v1;
 saved public.research_reviewer_results_v2;c public.research_model_completions_v1;n timestamptz;
BEGIN
 IF p_reviewer_principal IS NULL OR p_reviewer_principal !~ '^[a-f0-9]{64}$' OR p_reviewer_principal=p_author_principal THEN RAISE EXCEPTION 'research_reviewer_result_principal'; END IF;
 h:=public.read_research_author_handoff_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_result_id,p_result_hash);
 IF h->'completion'='null'::jsonb THEN RAISE EXCEPTION 'research_reviewer_result_author_incomplete'; END IF;
 a:=h->'assignment';
 SELECT * INTO ra FROM public.research_reviewer_assignments_v2 WHERE job_id=(a->>'job_id')::uuid AND attempt=(a->>'attempt')::integer;
 SELECT * INTO r FROM public.research_model_reservations_v1 WHERE reservation_id=ra.reservation_id;n:=clock_timestamp();
 IF ra.assignment_id IS NULL OR ra.author_assignment_id::text IS DISTINCT FROM a->>'assignment_id'
  OR ra.author_result_id IS DISTINCT FROM p_result_id OR ra.author_result_hash IS DISTINCT FROM p_result_hash
  OR ra.input_revision_id IS DISTINCT FROM p_revision_id OR ra.input_hash IS DISTINCT FROM p_input_hash
  OR ra.reviewer_principal IS DISTINCT FROM p_reviewer_principal OR ra.work_owner IS DISTINCT FROM a->>'work_owner'
  OR ra.original_job_deadline IS DISTINCT FROM (a->>'original_job_deadline')::timestamptz
  OR r.reservation_id IS NULL OR r.role IS DISTINCT FROM 'counter_review' OR r.owner IS DISTINCT FROM ra.work_owner
  OR r.work_key IS DISTINCT FROM 'deep-review-v2:'||ra.job_id||':'||ra.attempt||':'||ra.author_result_id
  OR r.started_at IS DISTINCT FROM ra.reservation_started_at OR r.lease_expires_at IS DISTINCT FROM ra.reservation_expires_at
  OR NOT isfinite(r.started_at) OR NOT isfinite(r.lease_expires_at) OR r.lease_expires_at>r.started_at+interval '30 minutes'
  OR ra.assigned_at<r.started_at OR ra.assigned_at>n OR ra.reservation_started_at<(h->'completion'->>'finished_at')::timestamptz
  OR n>=least(ra.original_job_deadline,ra.reservation_expires_at)
 THEN RAISE EXCEPTION 'research_reviewer_result_original_fence'; END IF;
 SELECT * INTO saved FROM public.research_reviewer_results_v2 WHERE assignment_id=ra.assignment_id;
 SELECT * INTO c FROM public.research_model_completions_v1 WHERE reservation_id=ra.reservation_id;
 IF saved.result_id IS NULL THEN
  IF c.reservation_id IS NOT NULL THEN RAISE EXCEPTION 'research_reviewer_result_completion_without_result'; END IF;
  PERFORM public.read_research_reviewer_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_result_id,p_result_hash);
 ELSE
  IF saved.result_hash IS DISTINCT FROM public.research_complete_hash_v2(saved.payload)
   OR saved.logical_bytes IS DISTINCT FROM octet_length(convert_to(public.research_complete_canonical_v2(saved.payload),'UTF8'))
   OR saved.payload->>'assignmentId' IS DISTINCT FROM ra.assignment_id::text
   OR saved.payload->'observation'->>'invocationId' IS DISTINCT FROM saved.invocation_id
   OR saved.received_at<ra.assigned_at OR saved.received_at>n
   OR c.reservation_id IS NULL OR c.owner IS DISTINCT FROM ra.work_owner OR c.outcome IS DISTINCT FROM 'completed'
   OR c.result_hash IS DISTINCT FROM saved.result_hash OR c.finished_at IS NULL OR NOT isfinite(c.finished_at)
   OR c.finished_at<saved.received_at OR c.finished_at>n OR c.finished_at>=least(ra.original_job_deadline,ra.reservation_expires_at)
   OR NOT EXISTS(SELECT FROM public.research_execution_invocations_v2 i WHERE i.invocation_id=saved.invocation_id
    AND i.role='reviewer' AND i.result_id=saved.result_id AND i.payload_hash=saved.result_hash)
  THEN RAISE EXCEPTION 'research_reviewer_result_completion_conflict'; END IF;
 END IF;
 IF clock_timestamp()>=least(ra.original_job_deadline,ra.reservation_expires_at) THEN RAISE EXCEPTION 'research_reviewer_result_expired'; END IF;
 RETURN jsonb_build_object('authorContext',h,'reviewerAssignment',to_jsonb(ra),'reviewResult',CASE WHEN saved.result_id IS NULL THEN NULL ELSE to_jsonb(saved)-'invocation_id' END,
  'reviewCompletion',CASE WHEN c.reservation_id IS NULL THEN NULL ELSE to_jsonb(c) END);
END $function$

CREATE OR REPLACE FUNCTION public.read_research_reviewer_result_sources_v2(p_request jsonb, p_revision_id uuid, p_input_hash text, p_author_principal text, p_reviewer_principal text, p_result_id uuid, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context jsonb; revision jsonb; payload jsonb; seal public.research_source_seals_v2;
 item jsonb; doc jsonb; m jsonb; descriptor jsonb; sources jsonb:='[]'; result jsonb;
 observed timestamptz; collected timestamptz; cutoff timestamptz; symbol text;
BEGIN
 context:=public.read_research_reviewer_result_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_result_id,p_result_hash);
 IF context->'reviewerAssignment'='null'::jsonb THEN RAISE EXCEPTION 'research_reviewer_assignment_missing'; END IF;
 revision:=context->'authorContext'->'revision';
 payload:=revision->'canonical_payload';symbol:=payload->'researchIdentity'->>'symbol';
 cutoff:=(payload->'clocks'->>'researchCutoff')::timestamptz;
 IF cutoff IS NULL OR NOT isfinite(cutoff) OR cutoff>clock_timestamp()
  OR jsonb_typeof(payload->'sources'->'manifest') IS DISTINCT FROM 'array'
  OR jsonb_array_length(payload->'sources'->'manifest')>30 THEN
  RAISE EXCEPTION 'research_author_packet_source_shape'; END IF;
 IF jsonb_array_length(payload->'sources'->'manifest')>0 THEN
  SELECT * INTO seal FROM public.research_source_seals_v2
   WHERE seal_id=(payload->'sources'->>'sealId')::uuid;
  IF seal.seal_id IS NULL OR seal.received_at IS NULL OR NOT isfinite(seal.received_at)
   OR seal.received_at>cutoff OR seal.documents IS DISTINCT FROM payload->'sources'->'manifest'
   THEN RAISE EXCEPTION 'research_author_packet_seal_clock'; END IF;
 END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(payload->'sources'->'manifest') x ORDER BY x->>'id' LOOP
  SELECT to_jsonb(d) INTO doc FROM public.source_raw_documents d WHERE id=(item->>'id')::uuid;
  IF doc IS NULL OR encode(sha256(convert_to(doc::text,'UTF8')),'hex') IS DISTINCT FROM item->>'rowHash'
   THEN RAISE EXCEPTION 'research_author_packet_source_changed'; END IF;
  m:=doc->'metadata';
  IF m->>'rights_boundary' IS DISTINCT FROM 'public_citation' OR m->>'visibility' IS DISTINCT FROM 'public'
   OR m->>'subject_scope' IS NULL OR m->>'subject_scope' NOT IN ('company_mentions','industry_context')
   OR jsonb_typeof(doc->'symbols') IS DISTINCT FROM 'array'
   OR jsonb_array_length(doc->'symbols')>50
   OR EXISTS(SELECT FROM jsonb_array_elements(doc->'symbols') x
    WHERE jsonb_typeof(x)<>'string' OR (x#>>'{}')!~'^[0-9]{4}$')
   OR (m->>'subject_scope'='company_mentions' AND NOT(doc->'symbols' @> jsonb_build_array(symbol)))
   OR (m->>'subject_scope'='industry_context' AND doc->'symbols'<>'[]'::jsonb)
   OR NULLIF(m->>'retracted_at','') IS NOT NULL OR m->>'withdrawn'='true'
   OR m->>'claim_status' IS NULL OR m->>'claim_status' NOT IN ('rumor','reported','confirmed')
   THEN RAISE EXCEPTION 'research_author_packet_source_rights_or_scope'; END IF;
  IF jsonb_typeof(doc->'title') IS DISTINCT FROM 'string' OR octet_length(doc->>'title') NOT BETWEEN 1 AND 512
   OR jsonb_typeof(doc->'summary') IS DISTINCT FROM 'string' OR octet_length(doc->>'summary') NOT BETWEEN 1 AND 4096
   OR jsonb_typeof(m->'catalyst') IS DISTINCT FROM 'string' OR octet_length(m->>'catalyst') NOT BETWEEN 1 AND 2048
   OR jsonb_typeof(m->'risk') IS DISTINCT FROM 'string' OR octet_length(m->>'risk') NOT BETWEEN 1 AND 2048
   OR jsonb_typeof(doc->'platform') IS DISTINCT FROM 'string' OR octet_length(doc->>'platform') NOT BETWEEN 1 AND 80
   OR jsonb_typeof(m->'canonical_url') IS DISTINCT FROM 'string' OR octet_length(m->>'canonical_url') NOT BETWEEN 1 AND 800
   OR jsonb_typeof(m->'first_observed_at') IS DISTINCT FROM 'string' OR octet_length(m->>'first_observed_at') NOT BETWEEN 1 AND 100
   THEN RAISE EXCEPTION 'research_author_packet_content_bound'; END IF;
  observed:=(m->>'first_observed_at')::timestamptz;collected:=(doc->>'collected_at')::timestamptz;
  IF observed IS NULL OR collected IS NULL OR NOT isfinite(observed) OR NOT isfinite(collected)
   OR observed>collected OR collected>seal.received_at
   OR (doc->>'published_at')::timestamptz>observed
   OR ((doc->>'published_at') IS NOT NULL AND NOT isfinite((doc->>'published_at')::timestamptz))
   THEN RAISE EXCEPTION 'research_author_packet_source_clock'; END IF;
  descriptor:=jsonb_build_object('id',item->'id','rowHash',item->'rowHash','url',m->'canonical_url',
   'observedAt',m->'first_observed_at','admittedAt',seal.received_at,
   'publication',jsonb_build_object('precision','unknown','raw',NULL,'timezone',NULL,'instant',NULL),
   'scope',m->'subject_scope','symbols',doc->'symbols','rights','public_summary_only','retracted',false,'superseded',false);
  sources:=sources||jsonb_build_array(jsonb_build_object('descriptor',descriptor,
   'title',doc->'title','summary',doc->'summary','catalyst',m->'catalyst','risk',m->'risk',
   'platform',doc->'platform','sourceClaimStatus',m->'claim_status','collectedAt',doc->'collected_at',
   'unverifiedPublicationClaim',doc->'published_at','untrustedEvidence',true));
  IF octet_length(sources::text)>307200 THEN RAISE EXCEPTION 'research_author_packet_sources_bound'; END IF;
 END LOOP;

 IF public.read_research_reviewer_result_context_v2(p_request,p_revision_id,p_input_hash,p_author_principal,p_reviewer_principal,p_result_id,p_result_hash) IS DISTINCT FROM context
 THEN RAISE EXCEPTION 'research_reviewer_context_changed'; END IF;
 result:=jsonb_build_object('sourceSealReceivedAt',seal.received_at,'sources',sources);
 IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'research_reviewer_sources_bound'; END IF;
 IF clock_timestamp()>=least((context->'reviewerAssignment'->>'original_job_deadline')::timestamptz,(context->'reviewerAssignment'->>'reservation_expires_at')::timestamptz)
 THEN RAISE EXCEPTION 'research_reviewer_assignment_expired'; END IF;
 RETURN result;
END $function$

