CREATE OR REPLACE FUNCTION public.read_taiwan_data_candidate_universe_v5(p_limit integer DEFAULT 5000)
 RETURNS TABLE(symbol text, exchange text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_cutoff timestamptz:=statement_timestamp(); v_after text:=''; v_count integer:=0; v_page_count integer; v_row record;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20000 THEN RAISE EXCEPTION 'invalid_taiwan_candidate_limit'; END IF;
  LOOP
    v_page_count:=0;
    FOR v_row IN SELECT * FROM public.read_taiwan_data_candidate_universe_v6(v_cutoff,v_after,least(500,p_limit-v_count)) LOOP
      symbol:=v_row.symbol; exchange:=v_row.exchange; v_after:=v_row.symbol;
      v_count:=v_count+1; v_page_count:=v_page_count+1; RETURN NEXT;
    END LOOP;
    EXIT WHEN v_page_count=0 OR v_count>=p_limit;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.reap_expired_research_deep_jobs_v2()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(2409,6002);n:=clock_timestamp();
 INSERT INTO public.research_model_completions_v1(reservation_id,owner,outcome,result_hash)
 SELECT r.reservation_id,r.owner,'failed',encode(sha256(convert_to('deep_lease_expired','UTF8')),'hex')FROM public.research_model_reservations_v1 r JOIN public.research_deep_jobs_v1 j ON r.role='company_research'AND r.work_key='deep:'||j.job_id||':'||j.attempts WHERE j.status='running'AND j.lease_expires_at<=n ON CONFLICT(reservation_id)DO NOTHING;
 UPDATE public.research_deep_jobs_v1 SET status=CASE WHEN attempts>=3 THEN 'failed'ELSE 'queued'END,terminal_reason=CASE WHEN attempts>=3 THEN 'lease_expired_max_attempts'ELSE terminal_reason END,lease_owner=NULL,lease_expires_at=NULL,finished_at=CASE WHEN attempts>=3 THEN n ELSE NULL END WHERE status='running'AND lease_expires_at<=n;
END $function$

CREATE OR REPLACE FUNCTION public.reap_legacy_expired_producer_run_v3_20(p_commit text, p_worker_sha256 text, p_config_sha256 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=date_trunc('second',clock_timestamp());
  v_count integer;v_run uuid;v_leased_job uuid;v_job uuid;
  v_stage text;v_job_kind text;v_input_hash text;v_hash text;
BEGIN
  IF p_commit !~ '^[0-9a-f]{40}$' OR p_worker_sha256 !~ '^[0-9a-f]{64}$'
    OR p_config_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected';
  END IF;
  SELECT count(*),(array_agg(run.run_id ORDER BY run.run_id))[1]
    INTO v_count,v_run
  FROM public.legacy_producer_runs_v3_11 run
  WHERE run.status='running' AND run.producer_commit_sha=p_commit
    AND run.worker_sha256=p_worker_sha256 AND run.scheduler_config_sha256=p_config_sha256
    AND run.lease_expires_at<v_now;
  IF v_count=0 THEN RETURN NULL; END IF;
  IF v_count<>1 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='lease_expired_identity_ambiguous';
  END IF;

  SELECT job.job_id INTO v_leased_job
  FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.run_id=v_run AND job.status='leased' AND job.lease_expires_at<v_now
  ORDER BY job.job_id FOR UPDATE;
  IF v_leased_job IS NOT NULL THEN
    RETURN public.terminalize_legacy_expired_producer_run_v3_20(
      v_run,v_leased_job,p_commit,p_worker_sha256,p_config_sha256);
  END IF;

  -- Do not reclaim a run that has a newer job heartbeat even when the outer
  -- run row is stale.  A mismatched lease remains fail-closed for operator
  -- investigation rather than becoming a cancellation primitive.
  IF EXISTS(SELECT 1 FROM public.legacy_producer_jobs_v3_11 job
    WHERE job.run_id=v_run AND job.status='leased' AND job.lease_expires_at>=v_now) THEN
    RETURN NULL;
  END IF;

  SELECT job.job_id,job.stage::text,job.job_kind::text,job.input_hash
    INTO v_job,v_stage,v_job_kind,v_input_hash
  FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.run_id=v_run AND job.status IN ('queued','retryable')
  ORDER BY job.stage_ordinal,job.shard_ordinal NULLS FIRST,job.execution_ordinal,job.job_id
  LIMIT 1 FOR UPDATE;
  IF v_job IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='lease_expired_unclaimed_job_missing';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(
    'lease-expired-unclaimed-v3.20:'||v_run::text||':'||v_job::text||':'||p_commit,'utf8'),'sha256'),'hex');
  PERFORM public.append_legacy_expired_producer_diagnostic_v3_20(
    v_run,v_job,v_stage,v_job_kind,v_input_hash,p_commit,v_hash,v_now);
  UPDATE public.legacy_producer_jobs_v3_11 SET status='failed',terminal_at=v_now,
    failure_code='lease_expired',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
    WHERE run_id=v_run AND job_id=v_job AND status IN ('queued','retryable');
  UPDATE public.legacy_producer_jobs_v3_11 SET status='cancelled',terminal_at=v_now,
    failure_code='cancelled',owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
    WHERE run_id=v_run AND status IN ('queued','retryable');
  UPDATE public.legacy_producer_runs_v3_11 SET status='failed',terminal_at=v_now,
    failure_code='lease_expired',heartbeat_at=v_now,lease_expires_at=v_now
    WHERE run_id=v_run AND status='running';
  RETURN 'failed_recoverable';
END $function$

CREATE OR REPLACE FUNCTION public.reap_legacy_producer_jobs_v3_11(p_limit integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_count integer:=0;v_row record;v_attempt smallint;
BEGIN
  IF p_limit<1 OR p_limit>1000 THEN RAISE EXCEPTION 'invalid reap limit'; END IF;
  FOR v_row IN SELECT run_id,job_id FROM public.legacy_producer_jobs_v3_11 WHERE status='leased' AND lease_expires_at<clock_timestamp() ORDER BY lease_expires_at LIMIT p_limit LOOP
    PERFORM 1 FROM public.legacy_producer_runs_v3_11 WHERE run_id=v_row.run_id FOR UPDATE;
    SELECT attempt INTO v_attempt FROM public.legacy_producer_jobs_v3_11 WHERE run_id=v_row.run_id AND job_id=v_row.job_id AND status='leased' AND lease_expires_at<clock_timestamp() FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE;END IF;
    UPDATE public.legacy_producer_jobs_v3_11 SET status=CASE
        WHEN v_attempt<5 THEN 'retryable'::public.opportunity_legacy_producer_job_status_v3_11
        ELSE 'failed'::public.opportunity_legacy_producer_job_status_v3_11
      END,failure_code=CASE WHEN v_attempt<5 THEN NULL ELSE 'job_attempts_exhausted'::public.opportunity_legacy_producer_failure_code_v3_11 END,
      terminal_at=CASE WHEN v_attempt<5 THEN NULL ELSE date_trunc('second',clock_timestamp()) END,owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL WHERE job_id=v_row.job_id;
    IF v_attempt>=5 THEN UPDATE public.legacy_producer_runs_v3_11 SET status='failed',failure_code='job_attempts_exhausted',terminal_at=date_trunc('second',clock_timestamp()) WHERE run_id=v_row.run_id;END IF;v_count:=v_count+1;
  END LOOP;RETURN v_count;
END $function$

CREATE OR REPLACE FUNCTION public.reap_opportunity_jobs_v3(caller_principal uuid)
 RETURNS TABLE(requeued integer, failed integer, runs_failed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_requeued integer := 0;
  v_failed integer := 0;
  v_runs_failed integer := 0;
  v_orphaned integer := 0;
  v_reap_at timestamptz := clock_timestamp();
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal($1,'opportunity_runner',v_reap_at) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable';
  END IF;
  DELETE FROM public.opportunity_job_staging_v3 s
  USING public.opportunity_run_jobs_v3 j,public.opportunity_runs r
  WHERE s.job_id=j.job_id
    AND s.attempt=j.attempt
    AND j.run_id=r.run_id
    AND j.status='leased'
    AND j.lease_expires_at<v_reap_at
    AND r.status IN ('preparing','running');
  WITH updated AS (
    UPDATE public.opportunity_run_jobs_v3
    SET status=CASE WHEN attempt < 5 THEN 'retryable'::public.opportunity_job_status_v3 ELSE 'failed'::public.opportunity_job_status_v3 END,
      failure_code=CASE WHEN attempt < 5 THEN NULL ELSE 'job_attempts_exhausted'::public.opportunity_failure_code_v3 END,
      terminal_at=CASE WHEN attempt < 5 THEN NULL ELSE v_reap_at END,
      owner_token_hash=NULL,lease_expires_at=NULL,heartbeat_at=NULL
    WHERE status='leased' AND lease_expires_at < v_reap_at
    RETURNING status,run_id
  )
  SELECT count(*) FILTER (WHERE status='retryable'),count(*) FILTER (WHERE status='failed')
  INTO v_requeued,v_failed FROM updated;
  WITH failed_runs AS (
    UPDATE public.opportunity_runs r SET status='failed',failure_code='job_attempts_exhausted',terminal_at=v_reap_at
    WHERE r.status IN ('preparing','running') AND EXISTS (
      SELECT 1 FROM public.opportunity_run_jobs_v3 j WHERE j.run_id=r.run_id AND j.status='failed'
    ) RETURNING 1
  ) SELECT count(*) INTO v_runs_failed FROM failed_runs;
  WITH orphaned_runs AS (
    UPDATE public.opportunity_runs r
    SET status='failed',failure_code='orphaned_run',terminal_at=v_reap_at
    WHERE r.status IN ('preparing','running')
      AND (
        EXISTS (
          SELECT 1
          FROM public.opportunity_run_jobs_v3 j
          LEFT JOIN public.opportunity_job_payloads_v3 p ON p.job_id=j.job_id
          WHERE j.run_id=r.run_id AND p.job_id IS NULL
        )
        OR NOT EXISTS (
          SELECT 1
          FROM public.opportunity_run_jobs_v3 j
          WHERE j.run_id=r.run_id AND j.status IN ('queued','retryable','leased')
        )
      )
    RETURNING 1
  )
  SELECT count(*) INTO v_orphaned FROM orphaned_runs;
  v_runs_failed := v_runs_failed + v_orphaned;
  RETURN QUERY SELECT v_requeued,v_failed,v_runs_failed;
END
$function$

CREATE OR REPLACE FUNCTION public.reconcile_research_deep_admissions_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j public.research_deep_jobs_v1; wk date;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(2409,6001);
 FOR j IN SELECT jobs.* FROM public.research_deep_jobs_v1 jobs LEFT JOIN public.research_deep_admission_charges_v1 c USING(job_id) WHERE c.job_id IS NULL ORDER BY jobs.created_at,jobs.job_id LOOP
  IF j.created_at IS NULL OR j.created_at>clock_timestamp() OR j.symbol !~ '^[0-9]{4}$' THEN RAISE EXCEPTION 'deep_legacy_admission_ambiguous'; END IF;
  wk:=date_trunc('week',j.created_at AT TIME ZONE 'Asia/Taipei')::date;
  INSERT INTO public.research_deep_admission_charges_v1(job_id,issuer_key,admission_at,admission_week) VALUES(j.job_id,'TW:'||j.symbol,j.created_at,wk);
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.record_candidate_dossier_submission_v4(p_bundle_id uuid, p_revision_id uuid, p_input_hash text, p_submission_hash text, p_content jsonb, p_claims jsonb, p_source_references jsonb, p_claim_fact_map jsonb, p_validation_status text, p_rejection_reasons jsonb)
 RETURNS TABLE(submission_id uuid, dossier_id uuid, status text, rejection_reasons jsonb, idempotent_replay boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_dossier_id uuid;
  v_submission_id uuid;
BEGIN
  IF p_input_hash !~ '^[0-9a-f]{64}$' OR p_submission_hash !~ '^[0-9a-f]{64}$'
    OR p_validation_status NOT IN ('valid','rejected')
    OR jsonb_typeof(p_claims) <> 'array' OR jsonb_typeof(p_source_references) <> 'array'
    OR jsonb_typeof(p_claim_fact_map) <> 'object' OR jsonb_typeof(p_rejection_reasons) <> 'array' THEN
    RAISE EXCEPTION 'invalid_candidate_dossier_persistence_input';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.candidate_dossier_bundles bundle
    WHERE bundle.bundle_id = p_bundle_id AND bundle.revision_id = p_revision_id
      AND bundle.published_revision_id = p_revision_id AND bundle.input_hash = p_input_hash
  ) OR NOT EXISTS (
    SELECT 1 FROM public.candidate_daily_stage_snapshots stage WHERE stage.detail_revision_id = p_revision_id
  ) THEN
    RAISE EXCEPTION 'candidate_dossier_revision_not_published';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_submission_hash, 0));
  RETURN QUERY
  SELECT receipt.submission_id, receipt.dossier_id, receipt.status, receipt.rejection_reasons, TRUE
  FROM public.candidate_dossier_submission_receipts receipt
  WHERE receipt.submission_hash = p_submission_hash;
  IF FOUND THEN RETURN; END IF;

  INSERT INTO public.candidate_research_dossiers (
    detail_snapshot_id,narrative_kind,bundle_id,input_hash,content,claims,source_references,
    claim_fact_map,validation_status,rejection_reasons,bundle_hash,detail_payload_hash,published_at
  ) VALUES (
    p_revision_id,'codex_enriched',p_bundle_id,p_input_hash,p_content,p_claims,p_source_references,
    p_claim_fact_map,p_validation_status,p_rejection_reasons,p_input_hash,p_input_hash,
    CASE WHEN p_validation_status = 'valid' THEN clock_timestamp() ELSE NULL END
  ) RETURNING id INTO v_dossier_id;

  INSERT INTO public.candidate_dossier_submission_receipts (
    bundle_id,revision_id,input_hash,dossier_id,submission_hash,status,rejection_reasons
  ) VALUES (
    p_bundle_id,p_revision_id,p_input_hash,v_dossier_id,p_submission_hash,
    CASE WHEN p_validation_status = 'valid' THEN 'accepted' ELSE 'rejected' END,p_rejection_reasons
  ) RETURNING candidate_dossier_submission_receipts.submission_id INTO v_submission_id;

  RETURN QUERY SELECT v_submission_id, v_dossier_id,
    CASE WHEN p_validation_status = 'valid' THEN 'accepted' ELSE 'rejected' END,
    p_rejection_reasons, FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_candidate_dossier_submission_v6(p_job_id uuid, p_owner text, p_bundle_id uuid, p_revision_id uuid, p_input_hash text, p_submission_hash text, p_content jsonb, p_claims jsonb, p_source_references jsonb, p_claim_fact_map jsonb, p_validation_status text, p_rejection_reasons jsonb)
 RETURNS TABLE(submission_id uuid, dossier_id uuid, status text, rejection_reasons jsonb, idempotent_replay boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_job public.candidate_dossier_outbox_v5%ROWTYPE;
  v_receipt RECORD;
BEGIN
  SELECT * INTO v_job FROM public.candidate_dossier_outbox_v5
  WHERE job_id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.publication_kind<>'ordinary' OR p_content ? 'deepResearch' OR v_job.bundle_id <> p_bundle_id OR v_job.revision_id <> p_revision_id
    OR v_job.input_hash <> p_input_hash THEN
    RAISE EXCEPTION 'candidate_dossier_job_identity_mismatch';
  END IF;
  IF v_job.status IN ('accepted', 'rejected') AND v_job.last_submission_hash = p_submission_hash THEN
    RETURN QUERY SELECT receipt.submission_id, receipt.dossier_id, receipt.status,
      receipt.rejection_reasons, TRUE
    FROM public.candidate_dossier_submission_receipts receipt
    WHERE receipt.submission_hash = p_submission_hash AND receipt.revision_id = p_revision_id
      AND receipt.bundle_id = p_bundle_id AND receipt.status = v_job.status;
    IF FOUND THEN RETURN; END IF;
  END IF;
  IF v_job.status <> 'running' OR v_job.lease_owner <> p_owner
    OR v_job.lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'candidate_dossier_lease_lost';
  END IF;
  SELECT * INTO v_receipt FROM public.record_candidate_dossier_submission_v4(
    p_bundle_id, p_revision_id, p_input_hash, p_submission_hash, p_content,
    p_claims, p_source_references, p_claim_fact_map, p_validation_status, p_rejection_reasons
  );
  IF NOT FOUND THEN RAISE EXCEPTION 'candidate_dossier_receipt_missing'; END IF;
  UPDATE public.candidate_dossier_outbox_v5
  SET status = v_receipt.status, lease_owner = NULL, lease_expires_at = NULL,
    receipt_id = CASE WHEN v_receipt.status = 'accepted' THEN v_receipt.submission_id ELSE NULL END,
    last_submission_hash = p_submission_hash,
    last_error = CASE WHEN v_receipt.status = 'rejected' THEN v_receipt.rejection_reasons::TEXT ELSE NULL END,
    updated_at = clock_timestamp()
  WHERE job_id = p_job_id;
  RETURN QUERY SELECT v_receipt.submission_id, v_receipt.dossier_id,
    v_receipt.status, v_receipt.rejection_reasons, v_receipt.idempotent_replay;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_candidate_financial_document_receipt_v6(p_stock_id uuid, p_acquisition_job_id uuid, p_source_url text, p_exchange text, p_period_end date, p_published_at timestamp with time zone, p_content_type text, p_document_sha256 text, p_object_key text, p_byte_length integer, p_metadata jsonb)
 RETURNS TABLE(receipt_id uuid, receipt_status text, idempotent_replay boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_host text; v_document_id uuid; v_receipt public.candidate_financial_document_receipts_v6%ROWTYPE;
BEGIN
  IF p_source_url !~ '^https://[^/@:]+/' OR p_document_sha256 !~ '^[0-9a-f]{64}$'
    OR p_object_key <> 'issuer/'||p_stock_id::text||'/'||p_period_end::text||'/'||p_document_sha256
    OR p_byte_length NOT BETWEEN 1 AND 52428800
    OR p_exchange NOT IN ('TWSE','TPEX') OR p_content_type NOT IN ('application/pdf','text/html','application/xhtml+xml','application/xml','text/xml')
    OR jsonb_typeof(COALESCE(p_metadata,'{}'::jsonb))<>'object'
  THEN RAISE EXCEPTION 'invalid_candidate_financial_document_receipt'; END IF;
  v_host:=lower(substring(p_source_url from '^https://([^/]+)'));
  IF v_host NOT IN ('mops.twse.com.tw','mopsov.twse.com.tw','www.twse.com.tw','www.tpex.org.tw')
    AND NOT EXISTS (SELECT 1 FROM public.candidate_issuer_document_domains_v6 domain WHERE domain.stock_id=p_stock_id AND domain.host=v_host)
  THEN RAISE EXCEPTION 'issuer_document_domain_not_approved'; END IF;
  IF p_acquisition_job_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.candidate_financial_acquisition_jobs_v4 job
    WHERE job.job_id=p_acquisition_job_id AND job.stock_id=p_stock_id
  ) THEN RAISE EXCEPTION 'candidate_financial_document_job_mismatch'; END IF;
  SELECT * INTO v_receipt FROM public.candidate_financial_document_receipts_v6
  WHERE stock_id=p_stock_id AND document_sha256=p_document_sha256 FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.source_url<>p_source_url OR v_receipt.period_end<>p_period_end OR v_receipt.object_key<>p_object_key
    THEN RAISE EXCEPTION 'candidate_financial_document_hash_collision'; END IF;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.receipt_status,true; RETURN;
  END IF;
  INSERT INTO public.candidate_issuer_ir_document_queue_v4(
    stock_id,queue_key,listing_source_url,document_url,title,published_at,mime_type,document_sha256,
    acquisition_status,terminal_reason,metadata,collected_at
  ) VALUES (
    p_stock_id,encode(extensions.digest(convert_to(p_stock_id::text||':'||p_document_sha256,'utf8'),'sha256'),'hex'),
    p_source_url,p_source_url,'Uploaded verified issuer document',p_published_at,p_content_type,p_document_sha256,
    'fetched','complete',p_metadata,clock_timestamp()
  ) RETURNING document_id INTO v_document_id;
  INSERT INTO public.candidate_financial_document_receipts_v6(
    stock_id,acquisition_job_id,issuer_document_id,source_url,exchange,period_end,published_at,content_type,
    document_sha256,object_key,byte_length
  ) VALUES (p_stock_id,p_acquisition_job_id,v_document_id,p_source_url,p_exchange,p_period_end,p_published_at,
    p_content_type,p_document_sha256,p_object_key,p_byte_length)
  RETURNING candidate_financial_document_receipts_v6.receipt_id,candidate_financial_document_receipts_v6.receipt_status
  INTO receipt_id,receipt_status;
  idempotent_replay:=false; RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.record_candidate_financial_fallback_v6(p_job_id uuid, p_owner text, p_caller_principal uuid, p_facts jsonb, p_source_sha256 text, p_response_bytes integer, p_collected_at timestamp with time zone, p_primary_reason financial_acquisition_terminal_reason_v4, p_primary_error text)
 RETURNS TABLE(written_facts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_job public.candidate_financial_acquisition_jobs_v4%ROWTYPE; v_fact jsonb; v_fact_id uuid; v_written integer:=0;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal(p_caller_principal,'opportunity_runner',clock_timestamp())
  THEN RAISE EXCEPTION 'principal_role_unavailable'; END IF;
  IF jsonb_typeof(COALESCE(p_facts,'null'::jsonb))<>'array' OR jsonb_array_length(p_facts)<1
    OR COALESCE(p_source_sha256,'') !~ '^[0-9a-f]{64}$' OR p_response_bytes NOT BETWEEN 0 AND 67108864
    OR p_collected_at IS NULL OR p_collected_at>clock_timestamp() OR p_primary_reason IS NULL
    OR p_primary_reason IN ('complete','empty_official_response') OR char_length(COALESCE(p_primary_error,'')) NOT BETWEEN 1 AND 500
  THEN RAISE EXCEPTION 'invalid_candidate_financial_fallback'; END IF;
  SELECT * INTO v_job FROM public.candidate_financial_acquisition_jobs_v4
  WHERE job_id=p_job_id AND endpoint_key IN ('mops_inline','tpex_general_income','tpex_broker_income','tpex_general_balance','tpex_broker_balance')
    AND status='running' AND lease_owner=p_owner FOR UPDATE;
  IF NOT FOUND OR v_job.lease_expires_at<clock_timestamp() THEN RAISE EXCEPTION 'candidate_financial_job_lease_lost'; END IF;
  FOR v_fact IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
    IF (v_fact #>> '{input,provider}')<>'finmind' OR (v_fact #>> '{input,authority_tier}')<>'finmind_mirror'
      OR (v_fact #>> '{input,stock_id}')::uuid IS DISTINCT FROM v_job.stock_id
      OR (v_fact #>> '{input,period_end}')::date IS DISTINCT FROM v_job.period_end
      OR (v_fact #>> '{input,collected_at}')::timestamptz IS DISTINCT FROM p_collected_at
      OR COALESCE(v_fact #>> '{input,source_ref}','') !~ '^finmind:'
    THEN RAISE EXCEPTION 'candidate_financial_fallback_provenance_invalid'; END IF;
    SELECT fact.fact_id INTO v_fact_id FROM public.opportunity_financial_facts_v3 fact
    WHERE fact.stock_id=v_job.stock_id AND fact.source_ref=v_fact #>> '{input,source_ref}'
      AND fact.collected_at<=(v_fact #>> '{input,collected_at}')::timestamptz
    ORDER BY fact.recorded_at,fact.fact_id LIMIT 1;
    IF v_fact_id IS NULL THEN
      SELECT appended.fact_id INTO v_fact_id FROM public.append_financial_fact_v3(
        jsonb_populate_record(NULL::public.financial_fact_input_v3,v_fact->'input'),p_caller_principal
      ) appended LIMIT 1;
    END IF;
    IF v_fact_id IS NULL THEN RAISE EXCEPTION 'candidate_financial_fact_append_empty'; END IF;
    IF COALESCE((v_fact #>> '{validation,schema_valid}')::boolean,FALSE) IS NOT TRUE
      OR COALESCE((v_fact #>> '{validation,unit_valid}')::boolean,FALSE) IS NOT TRUE
      OR COALESCE((v_fact #>> '{validation,point_in_time_valid}')::boolean,FALSE) IS NOT TRUE
      OR COALESCE((v_fact #>> '{validation,consistency_valid}')::boolean,FALSE) IS NOT TRUE
      OR COALESCE(v_fact #>> '{validation,upstream_provider}','') !~ '^[A-Za-z0-9_.:-]{1,120}$'
    THEN RAISE EXCEPTION 'candidate_financial_fallback_validation_missing'; END IF;
    IF NOT public.validate_finmind_financial_fact_v6(
      v_fact_id,TRUE,TRUE,TRUE,TRUE,v_fact #>> '{validation,upstream_provider}'
    ) THEN RAISE EXCEPTION 'candidate_financial_fallback_validation_failed'; END IF;
    INSERT INTO public.candidate_financial_fact_provenance_v4(
      fact_id,acquisition_job_id,source_url,source_sha256,locator,extracted_at
    ) VALUES(v_fact_id,p_job_id,'https://api.finmindtrade.com/api/v4/data',p_source_sha256,
      COALESCE(v_fact->'locator','{}'::jsonb),p_collected_at) ON CONFLICT DO NOTHING;
    v_written:=v_written+1;
  END LOOP;
  -- The mirror satisfied this company/period/method work item. Retain MOPS
  -- failure history and close it instead of repeatedly paying FinMind to
  -- produce identical facts on every retry.
  UPDATE public.candidate_financial_acquisition_jobs_v4 SET
    status='terminal',attempts=LEAST(attempts+1,20),consecutive_failures=LEAST(mops_consecutive_failures+1,5),
    mops_attempts=LEAST(mops_attempts+1,20),mops_consecutive_failures=LEAST(mops_consecutive_failures+1,5),
    finmind_attempts=LEAST(finmind_attempts+1,20),finmind_consecutive_failures=0,
    lease_owner=NULL,lease_expires_at=NULL,terminal_reason='complete',terminal_detail='primary:'||p_primary_error,
    response_sha256=p_source_sha256,response_bytes=p_response_bytes,collected_at=p_collected_at,next_attempt_at=NULL,updated_at=p_collected_at
  WHERE job_id=p_job_id;
  INSERT INTO public.candidate_financial_acquisition_cursors_v4(
    stock_id,endpoint_key,cursor_value,last_successful_period_end,last_terminal_reason,last_collected_at,updated_at
  ) VALUES(v_job.stock_id,v_job.endpoint_key,jsonb_build_object(
      'cursor_key',v_job.cursor_key,'job_id',p_job_id,'provider','finmind','mops_terminal_reason',p_primary_reason::text,
      'mops_consecutive_failures',LEAST(v_job.mops_consecutive_failures+1,5)
    ),v_job.period_end,'complete',p_collected_at,p_collected_at)
  ON CONFLICT(stock_id,endpoint_key) DO UPDATE SET cursor_value=EXCLUDED.cursor_value,last_successful_period_end=GREATEST(
      public.candidate_financial_acquisition_cursors_v4.last_successful_period_end,EXCLUDED.last_successful_period_end),
    last_terminal_reason=EXCLUDED.last_terminal_reason,last_collected_at=EXCLUDED.last_collected_at,updated_at=EXCLUDED.updated_at;
  RETURN QUERY SELECT v_written;
END $function$

CREATE OR REPLACE FUNCTION public.record_retention_archive_restore_v1(p_manifest_id uuid, p_restore_environment_id text, p_restored_row_count integer, p_restored_closure_hash text, p_restored_schema_hash text, p_verified_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "stockinsider.retention_rpc_transition" TO 'allowed'
AS $function$
DECLARE v_manifest public.retention_archive_manifests_v1%ROWTYPE;
BEGIN
  SELECT * INTO v_manifest FROM public.retention_archive_manifests_v1 WHERE manifest_id=p_manifest_id FOR UPDATE;
  IF v_manifest.status<>'exported' THEN RAISE EXCEPTION 'retention_manifest_not_exported'; END IF;
  IF length(trim(coalesce(p_restore_environment_id,'')))=0 OR p_restore_environment_id='source'
    OR p_restored_row_count<>v_manifest.expected_row_count
    OR p_restored_closure_hash IS DISTINCT FROM v_manifest.closure_hash
    OR p_restored_schema_hash IS DISTINCT FROM v_manifest.schema_hash THEN
    RAISE EXCEPTION 'retention_restore_verification_mismatch';
  END IF;
  UPDATE public.retention_archive_manifests_v1 SET status='verified',restore_environment_id=p_restore_environment_id,
    restored_row_count=p_restored_row_count,restored_closure_hash=p_restored_closure_hash,
    restored_schema_hash=p_restored_schema_hash,restore_verified_at=p_verified_at
  WHERE manifest_id=p_manifest_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_taiwan_data_publication_metadata_v5(p_session_date date, p_publication_phase text, p_data_cutoff_at timestamp with time zone, p_dataset_completeness jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_merged jsonb; v_progress jsonb; v_total integer; v_complete integer; v_pct numeric; v_cutoff timestamptz;
BEGIN
  IF p_session_date IS NULL OR p_publication_phase IS NULL OR p_publication_phase NOT IN ('preliminary','final')
    OR jsonb_typeof(p_dataset_completeness) IS DISTINCT FROM 'object' OR p_data_cutoff_at IS NULL
    OR p_data_cutoff_at>clock_timestamp()+interval '5 minutes'
  THEN RAISE EXCEPTION 'invalid_taiwan_publication_metadata'; END IF;
  -- Match registration's lock so scope growth cannot race publication's count.
  PERFORM 1 FROM public.taiwan_data_refresh_scopes_v6 scope
    WHERE scope.session_date=p_session_date AND scope.refresh_phase=p_publication_phase FOR SHARE;
  INSERT INTO public.taiwan_data_publication_metadata_v5(session_date,publication_phase,data_cutoff_at,
    dataset_completeness,dataset_completeness_pct,shadow_eligible)
    VALUES(p_session_date,p_publication_phase,p_data_cutoff_at,'{}',0,false)
    ON CONFLICT(session_date,publication_phase) DO NOTHING;
  SELECT metadata.dataset_completeness||p_dataset_completeness,greatest(metadata.data_cutoff_at,p_data_cutoff_at)
    INTO v_merged,v_cutoff FROM public.taiwan_data_publication_metadata_v5 metadata
    WHERE metadata.session_date=p_session_date AND metadata.publication_phase=p_publication_phase FOR UPDATE;
  v_progress:=public.read_taiwan_data_refresh_progress_v6(p_session_date,p_publication_phase);
  v_total:=(v_progress->>'expected')::integer; v_complete:=(v_progress->>'completed')::integer;
  -- Never round an incomplete scope up to 100 (the scope can contain 20,000 keys).
  v_pct:=CASE WHEN v_total=0 THEN 0 WHEN v_complete=v_total THEN 100 ELSE least(99.99,round(100.0*v_complete/v_total,2)) END;
  v_merged:=v_merged||jsonb_build_object('_refresh_scope_v6',v_progress);
  UPDATE public.taiwan_data_publication_metadata_v5 SET data_cutoff_at=v_cutoff,dataset_completeness=v_merged,
    dataset_completeness_pct=v_pct,shadow_eligible=false,recorded_at=clock_timestamp()
    WHERE session_date=p_session_date AND publication_phase=p_publication_phase;
  RETURN jsonb_build_object('publicationPhase',p_publication_phase,'dataCutoffAt',v_cutoff,
    'datasetCompletenessPct',v_pct,'shadowEligible',false,'refreshProgress',v_progress);
END $function$

CREATE OR REPLACE FUNCTION public.register_private_artifact_receipt_v1(p_artifact_hash text, p_byte_length bigint, p_media_type text, p_purpose text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(artifact_hash text, idempotent_replay boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE backend uuid; existing public.private_artifact_receipts_v1%ROWTYPE;
BEGIN
  backend:=public.assert_stockinsider_backend_request_v1(true);
  IF p_artifact_hash !~ '^[0-9a-f]{64}$' OR p_byte_length NOT BETWEEN 1 AND 67108864
    OR char_length(COALESCE(p_media_type,'')) NOT BETWEEN 3 AND 200
    OR p_purpose NOT IN ('financial_document','diagnostic_attachment') THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='private_artifact_receipt_invalid';
  END IF;
  SELECT * INTO existing FROM public.private_artifact_receipts_v1 WHERE private_artifact_receipts_v1.artifact_hash=p_artifact_hash;
  IF FOUND THEN
    IF existing.byte_length<>p_byte_length OR existing.media_type<>p_media_type OR existing.purpose<>p_purpose THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='private_artifact_receipt_conflict';
    END IF;
    RETURN QUERY SELECT p_artifact_hash,true; RETURN;
  END IF;
  INSERT INTO public.private_artifact_receipts_v1(artifact_hash,byte_length,media_type,purpose,created_by_backend_id,metadata)
    VALUES(p_artifact_hash,p_byte_length,p_media_type,p_purpose,backend,COALESCE(p_metadata,'{}'::jsonb));
  RETURN QUERY SELECT p_artifact_hash,false;
END
$function$

CREATE OR REPLACE FUNCTION public.register_taiwan_data_refresh_scope_v6(p_session_date date, p_phase text, p_queue_keys text[], p_cutoff timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_keys text[]; v_cutoff timestamptz; v_publication_cutoff timestamptz;
BEGIN
  IF p_session_date IS NULL OR p_phase IS NULL OR p_phase NOT IN ('preliminary','final') OR p_cutoff IS NULL
    OR p_cutoff>clock_timestamp()+interval '5 minutes' OR p_queue_keys IS NULL OR cardinality(p_queue_keys)>20000
    OR EXISTS(SELECT 1 FROM unnest(p_queue_keys) item WHERE item IS NULL OR item!~'^[0-9a-f]{64}$')
  THEN RAISE EXCEPTION 'invalid_taiwan_refresh_scope'; END IF;
  INSERT INTO public.taiwan_data_refresh_scopes_v6(session_date,refresh_phase,expected_queue_keys,cutoff_at)
    VALUES(p_session_date,p_phase,'{}',p_cutoff) ON CONFLICT(session_date,refresh_phase) DO NOTHING;
  SELECT scope.expected_queue_keys,scope.cutoff_at INTO v_keys,v_cutoff
    FROM public.taiwan_data_refresh_scopes_v6 scope
    WHERE scope.session_date=p_session_date AND scope.refresh_phase=p_phase FOR UPDATE;
  SELECT ARRAY(SELECT DISTINCT item FROM unnest(v_keys||p_queue_keys) item ORDER BY item) INTO v_keys;
  IF cardinality(v_keys)>20000 THEN RAISE EXCEPTION 'taiwan_refresh_scope_overflow'; END IF;
  UPDATE public.taiwan_data_refresh_scopes_v6 SET expected_queue_keys=v_keys,
    cutoff_at=greatest(v_cutoff,p_cutoff),updated_at=clock_timestamp()
    WHERE session_date=p_session_date AND refresh_phase=p_phase;
  -- A growing scope immediately invalidates an earlier 100% publication, even
  -- if enqueueing stops before another worker records a completed batch.
  SELECT metadata.data_cutoff_at INTO v_publication_cutoff FROM public.taiwan_data_publication_metadata_v5 metadata
    WHERE metadata.session_date=p_session_date AND metadata.publication_phase=p_phase;
  IF FOUND THEN PERFORM public.record_taiwan_data_publication_metadata_v5(
    p_session_date,p_phase,greatest(v_publication_cutoff,p_cutoff),'{}'::jsonb); END IF;
  RETURN jsonb_build_object('expected',cardinality(v_keys),'cutoffAt',greatest(v_cutoff,p_cutoff));
END $function$

CREATE OR REPLACE FUNCTION public.register_taiwan_data_refresh_scope_v7(p_session_date date, p_phase text, p_queue_keys text[], p_cutoff timestamp with time zone, p_contract_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_keys text[]; v_cutoff timestamptz; v_contract text; v_publication_cutoff timestamptz;
BEGIN
  IF p_session_date IS NULL OR p_phase IS NULL OR p_phase NOT IN ('preliminary','final') OR p_cutoff IS NULL
    OR p_cutoff>clock_timestamp()+interval '5 minutes' OR p_queue_keys IS NULL OR cardinality(p_queue_keys)>20000
    OR p_contract_version IS NULL OR p_contract_version !~ '^taiwan-data-provider-v[0-9]+$'
    OR EXISTS(SELECT 1 FROM unnest(p_queue_keys) item WHERE item IS NULL OR item!~'^[0-9a-f]{64}$')
  THEN RAISE EXCEPTION 'invalid_taiwan_refresh_scope'; END IF;
  INSERT INTO public.taiwan_data_refresh_scopes_v6(
    session_date,refresh_phase,expected_queue_keys,cutoff_at,contract_version
  ) VALUES(p_session_date,p_phase,'{}',p_cutoff,p_contract_version)
  ON CONFLICT(session_date,refresh_phase) DO NOTHING;
  SELECT scope.expected_queue_keys,scope.cutoff_at,scope.contract_version INTO v_keys,v_cutoff,v_contract
    FROM public.taiwan_data_refresh_scopes_v6 scope
    WHERE scope.session_date=p_session_date AND scope.refresh_phase=p_phase FOR UPDATE;
  IF v_contract IS DISTINCT FROM p_contract_version THEN
    SELECT ARRAY(SELECT DISTINCT item FROM unnest(p_queue_keys) item ORDER BY item) INTO v_keys;
    v_cutoff:=p_cutoff;
  ELSE
    SELECT ARRAY(SELECT DISTINCT item FROM unnest(v_keys||p_queue_keys) item ORDER BY item) INTO v_keys;
    v_cutoff:=greatest(v_cutoff,p_cutoff);
  END IF;
  IF cardinality(v_keys)>20000 THEN RAISE EXCEPTION 'taiwan_refresh_scope_overflow'; END IF;
  UPDATE public.taiwan_data_refresh_scopes_v6 SET expected_queue_keys=v_keys,cutoff_at=v_cutoff,
    contract_version=p_contract_version,updated_at=clock_timestamp()
    WHERE session_date=p_session_date AND refresh_phase=p_phase;
  SELECT metadata.data_cutoff_at INTO v_publication_cutoff FROM public.taiwan_data_publication_metadata_v5 metadata
    WHERE metadata.session_date=p_session_date AND metadata.publication_phase=p_phase;
  IF FOUND THEN PERFORM public.record_taiwan_data_publication_metadata_v5(
    p_session_date,p_phase,greatest(v_publication_cutoff,p_cutoff),'{}'::jsonb); END IF;
  RETURN jsonb_build_object('expected',cardinality(v_keys),'cutoffAt',v_cutoff,'contractVersion',p_contract_version);
END $function$

