CREATE OR REPLACE FUNCTION public.reserve_research_model_v1(p_role text, p_owner text, p_work_key text)
 RETURNS SETOF research_model_reservations_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_now timestamptz; v_day date; v_prior public.research_model_reservations_v1;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
  IF p_role NOT IN ('discovery','company_research','counter_review','technical','strategy_research','independent_test')
    OR length(trim(p_owner)) NOT BETWEEN 3 AND 120 OR length(p_work_key) NOT BETWEEN 3 AND 200
    OR p_owner IS NULL OR p_work_key IS NULL THEN RAISE EXCEPTION 'research_model_reservation_invalid'; END IF;
  PERFORM pg_advisory_xact_lock(2409,6002);
  v_now:=clock_timestamp();
  v_day:=(v_now AT TIME ZONE 'Asia/Taipei')::date;
  SELECT * INTO v_prior FROM public.research_model_reservations_v1 WHERE role=p_role AND work_key=p_work_key;
  IF FOUND THEN
    IF v_prior.owner<>p_owner OR v_prior.lease_expires_at<=v_now
      OR EXISTS(SELECT 1 FROM public.research_model_completions_v1 WHERE reservation_id=v_prior.reservation_id)
      THEN RAISE EXCEPTION 'research_model_reservation_replay_closed'; END IF;
    RETURN NEXT v_prior; RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM public.research_model_reservations_v1 r WHERE r.lease_expires_at>v_now
      AND NOT EXISTS(SELECT 1 FROM public.research_model_completions_v1 c WHERE c.reservation_id=r.reservation_id))
    OR (SELECT COALESCE(sum(reserved_seconds),0) FROM public.research_model_reservations_v1 WHERE taipei_day=v_day)+1800>7200
    OR NOT public.research_model_lease_fits_day_v1(v_now)
    THEN RETURN; END IF;
  RETURN QUERY INSERT INTO public.research_model_reservations_v1(role,owner,work_key,taipei_day,started_at,lease_expires_at)
    VALUES(p_role,p_owner,p_work_key,v_day,v_now,v_now+interval '30 minutes') RETURNING *;
END $function$

CREATE OR REPLACE FUNCTION public.resolve_legacy_scheduled_occurrence_v3_11(p_owner_label text, p_config_hash text)
 RETURNS legacy_scheduled_occurrence_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz:=date_trunc('second',clock_timestamp());v_local timestamp;v_date date;
  v_cutoff timestamptz;v_material_recorded_at timestamptz;v_material_cutoff timestamptz;
  v_id text;v_base_id text;v_session_hash text;v_occurrence_kind text:='scheduled';
  v_failed_terminal timestamptz;v_recovery_cutoff timestamptz;
BEGIN
  IF p_owner_label<>'com.stockinsider.auth-source-worker'
    OR p_config_hash<>'1ead338d6a56194a51c64ac2adbf36551a410c327ce08ba18f9224e34471c3c2'
  THEN RETURN NULL;END IF;
  v_local:=v_now AT TIME ZONE 'Asia/Taipei';v_date:=v_local::date;
  IF extract(isodow FROM v_date)>5 OR v_local::time<time '18:20:00' THEN v_date:=v_date-1;END IF;
  WHILE extract(isodow FROM v_date)>5 LOOP v_date:=v_date-1;END LOOP;
  v_cutoff:=(v_date+time '18:20:00') AT TIME ZONE 'Asia/Taipei';
  SELECT max(recorded_at) INTO v_material_recorded_at FROM(
    SELECT max(recorded_at) recorded_at FROM public.stock_instruments_v3
      WHERE instrument_type='common_stock' AND listing_status='active'
    UNION ALL SELECT max(recorded_at) FROM public.stock_aliases_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.stock_sector_assignments_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.source_identity_authorities_v3 WHERE status='active'
    UNION ALL SELECT max(recorded_at) FROM public.source_document_revisions_v3 WHERE acquisition_status='complete'
  ) material;
  v_material_cutoff:=date_trunc('second',v_material_recorded_at)+interval '1 second';
  IF v_material_recorded_at>v_cutoff AND v_material_cutoff<=v_now THEN
    v_cutoff:=v_material_cutoff;v_occurrence_kind:='material-authority-refresh';
  END IF;
  v_base_id:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
    'legacy-producer-scheduled-occurrence-v2',p_owner_label,v_date,'18:20:00','Asia/Taipei',
    v_occurrence_kind,to_char(v_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),p_config_hash
  )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');

  -- Only the typed, immutable calendar-dependency diagnostic opens recovery.
  -- Requiring calendar authority recorded between cutoff and terminal proves
  -- that advancing to the database-owned terminal boundary can add authority.
  v_failed_terminal:=public.resolve_legacy_calendar_recovery_cutoff_v3_16_11_internal(v_base_id);
  IF v_failed_terminal IS NOT NULL THEN
    v_recovery_cutoff:=date_trunc('second',v_failed_terminal);
    IF v_recovery_cutoff>v_cutoff AND v_recovery_cutoff<=v_now THEN
      v_cutoff:=v_recovery_cutoff;v_occurrence_kind:='calendar-dependency-recovery';
      v_id:=encode(extensions.digest(convert_to(regexp_replace(jsonb_build_array(
        'legacy-producer-calendar-dependency-recovery-v1',p_owner_label,v_base_id,
        to_char(v_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),p_config_hash
      )::text,', ', ',', 'g'),'utf8'),'sha256'),'hex');
    END IF;
  END IF;
  v_id:=coalesce(v_id,v_base_id);
  SELECT session.taiwan_session_authority_hash INTO v_session_hash
  FROM public.opportunity_effective_taiwan_sessions_v3 session
  WHERE session.session_id=v_date AND session.canonical_cutoff<=v_cutoff;
  RETURN ROW(v_id,v_cutoff,CASE WHEN v_session_hash IS NULL THEN NULL ELSE v_date END,v_session_hash)
    ::public.legacy_scheduled_occurrence_v3_11;
END $function$

CREATE OR REPLACE FUNCTION public.resolve_legacy_trading_session_window_v3_13(p_market tw_market_v3, p_oldest date, p_newest date, p_cutoff timestamp with time zone)
 RETURNS SETOF tw_trading_sessions_v3
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_sessions date[];v_stream_count integer;
BEGIN
  IF p_oldest IS NULL OR p_newest IS NULL OR p_oldest>p_newest THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_calendar_window';
  END IF;
  SELECT array_agg(session_id ORDER BY session_id DESC),count(*)
    INTO v_sessions,v_stream_count FROM(
      SELECT DISTINCT raw.session_id FROM public.tw_trading_sessions_v3 raw
      WHERE raw.market=p_market AND raw.session_id BETWEEN p_oldest AND p_newest
      ORDER BY raw.session_id DESC LIMIT 513
    ) bounded;
  IF v_stream_count>512 THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation';
  END IF;
  RETURN QUERY
  SELECT selected.* FROM unnest(coalesce(v_sessions,'{}'::date[])) WITH ORDINALITY stream(session_id,ordinal)
  CROSS JOIN LATERAL public.resolve_legacy_trading_session_authority_v3_13(
    stream.session_id,p_market,p_cutoff) selected
  ORDER BY stream.ordinal;
END $function$

CREATE OR REPLACE FUNCTION public.retention_archive_current_row_hash_v1(p_relation text, p_row_key text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_hash TEXT;
BEGIN
  IF p_row_key !~ '^[0-9a-fA-F-]{36}$' THEN RETURN NULL; END IF;
  CASE p_relation
    WHEN 'public.candidate_research_runs' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.candidate_research_runs row_value WHERE id=p_row_key::UUID;
    WHEN 'public.candidate_research_run_items' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.candidate_research_run_items row_value WHERE id=p_row_key::UUID;
    WHEN 'public.connector_runs' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.connector_runs row_value WHERE id=p_row_key::UUID;
    WHEN 'public.source_audits' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.source_audits row_value WHERE id=p_row_key::UUID;
    WHEN 'public.source_run_ledger' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.source_run_ledger row_value WHERE id=p_row_key::UUID;
    WHEN 'public.worker_job_runs' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.worker_job_runs row_value WHERE id=p_row_key::UUID;
    WHEN 'public.worker_logs' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.worker_logs row_value WHERE id=p_row_key::UUID;
    WHEN 'public.runtime_artifacts' THEN
      SELECT encode(digest(convert_to(to_jsonb(row_value)::TEXT,'UTF8'),'sha256'),'hex') INTO v_hash
        FROM public.runtime_artifacts row_value WHERE id=p_row_key::UUID;
    ELSE RAISE EXCEPTION 'retention_relation_not_allowlisted';
  END CASE;
  RETURN v_hash;
END;
$function$

CREATE OR REPLACE FUNCTION public.retention_archive_deletion_readiness_v1(p_manifest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_manifest public.retention_archive_manifests_v1%ROWTYPE; v_eligibility JSONB; v_blockers JSONB:='[]'::jsonb;
BEGIN
  SELECT * INTO v_manifest FROM public.retention_archive_manifests_v1 WHERE manifest_id=p_manifest_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ready',FALSE,'blockers',jsonb_build_array(jsonb_build_object('code','manifest_not_found'))); END IF;
  IF v_manifest.status<>'verified' THEN v_blockers:=v_blockers||'[{"code":"restore_not_verified"}]'::jsonb; END IF;
  v_eligibility:=public.retention_archive_eligibility_v1(v_manifest.root_kind,v_manifest.root_id,clock_timestamp());
  IF NOT coalesce((v_eligibility->>'eligible')::BOOLEAN,FALSE) THEN
    v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','eligibility_changed','detail',v_eligibility->'blockers'));
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.retention_archive_active_pins_v1() pin
    JOIN public.retention_archive_manifest_rows_v1 archived
      ON archived.manifest_id=p_manifest_id AND archived.relation_name=pin.relation_name AND archived.row_key=pin.row_key
  ) THEN v_blockers:=v_blockers||'[{"code":"pin_added_after_export"}]'::jsonb; END IF;
  IF EXISTS (
    SELECT 1 FROM public.retention_archive_manifest_rows_v1 archived
    WHERE archived.manifest_id=p_manifest_id
      AND public.retention_archive_current_row_hash_v1(archived.relation_name,archived.row_key)
        IS DISTINCT FROM archived.row_hash
  ) THEN v_blockers:=v_blockers||'[{"code":"row_changed_or_missing_after_export"}]'::jsonb; END IF;
  RETURN jsonb_build_object('ready',jsonb_array_length(v_blockers)=0,'manifestId',p_manifest_id,
    'blockers',v_blockers,'deleteRpcAvailable',FALSE,'requiresSeparateReviewedDeletionExecutor',TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.retention_archive_eligibility_v1(p_root_kind text, p_root_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_days INTEGER;
  v_cutoff TIMESTAMPTZ;
  v_rows JSONB := '[]'::jsonb;
  v_terminal BOOLEAN := FALSE;
  v_blockers JSONB := '[]'::jsonb;
  v_relation TEXT;
BEGIN
  SELECT retention_days INTO v_days FROM public.retention_archive_policies_v1
  WHERE root_kind=p_root_kind AND enabled;
  IF v_days IS NULL THEN RAISE EXCEPTION 'retention_policy_disabled_or_unknown'; END IF;
  v_cutoff:=p_now-make_interval(days=>v_days);

  IF p_root_kind='candidate_research_run' THEN
    v_relation:='public.candidate_research_runs';
    SELECT run.status='success' AND run.finished_at IS NOT NULL AND run.finished_at<v_cutoff
      AND NOT EXISTS (
        SELECT 1 FROM public.candidate_research_run_items item
        WHERE item.run_id=run.id AND item.status IS DISTINCT FROM 'success'
      ) INTO v_terminal
    FROM public.candidate_research_runs run WHERE run.id=p_root_id;
    SELECT coalesce(jsonb_agg(row_spec ORDER BY relation_name,row_key),'[]'::jsonb) INTO v_rows FROM (
      SELECT 'public.candidate_research_runs' relation_name,run.id::TEXT row_key,
        jsonb_build_object('relation','public.candidate_research_runs','key',run.id::TEXT) row_spec
      FROM public.candidate_research_runs run WHERE run.id=p_root_id
      UNION ALL
      SELECT 'public.candidate_research_run_items',item.id::TEXT,
        jsonb_build_object('relation','public.candidate_research_run_items','key',item.id::TEXT)
      FROM public.candidate_research_run_items item WHERE item.run_id=p_root_id
    ) closure;
  ELSIF p_root_kind='connector_run' THEN
    v_relation:='public.connector_runs';
    SELECT run.status IN ('success','skipped') AND run.finished_at IS NOT NULL AND run.finished_at<v_cutoff
      AND NOT coalesce(run.metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
      AND NOT coalesce(run.metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
      AND NOT EXISTS (
        SELECT 1 FROM public.source_audits audit
        WHERE audit.connector_run_id=run.id AND (
          audit.status IS DISTINCT FROM 'success'
          OR coalesce(audit.metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
          OR coalesce(audit.metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
          OR coalesce(audit.metadata,'{}'::jsonb) @> '{"security_event":true}'::jsonb
        )
      ) INTO v_terminal
    FROM public.connector_runs run WHERE run.id=p_root_id;
    SELECT coalesce(jsonb_agg(row_spec ORDER BY relation_name,row_key),'[]'::jsonb) INTO v_rows FROM (
      SELECT 'public.connector_runs' relation_name,run.id::TEXT row_key,
        jsonb_build_object('relation','public.connector_runs','key',run.id::TEXT) row_spec
      FROM public.connector_runs run WHERE run.id=p_root_id
      UNION ALL
      SELECT 'public.source_audits',audit.id::TEXT,
        jsonb_build_object('relation','public.source_audits','key',audit.id::TEXT)
      FROM public.source_audits audit WHERE audit.connector_run_id=p_root_id
    ) closure;
  ELSIF p_root_kind='source_run_ledger' THEN
    v_relation:='public.source_run_ledger';
    SELECT terminal_reason IN ('successful_empty','duplicate_only') AND attempted_at<v_cutoff INTO v_terminal
    FROM public.source_run_ledger WHERE id=p_root_id;
    SELECT coalesce(jsonb_agg(jsonb_build_object('relation','public.source_run_ledger','key',id::TEXT)),'[]'::jsonb)
      INTO v_rows FROM public.source_run_ledger WHERE id=p_root_id;
  ELSIF p_root_kind='worker_job_run' THEN
    v_relation:='public.worker_job_runs';
    SELECT status='success' AND finished_at IS NOT NULL AND finished_at<v_cutoff
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"security_event":true}'::jsonb
      INTO v_terminal
    FROM public.worker_job_runs WHERE id=p_root_id;
    SELECT coalesce(jsonb_agg(jsonb_build_object('relation','public.worker_job_runs','key',id::TEXT)),'[]'::jsonb)
      INTO v_rows FROM public.worker_job_runs WHERE id=p_root_id;
  ELSIF p_root_kind='source_audit' THEN
    v_relation:='public.source_audits';
    SELECT status='success' AND created_at<v_cutoff
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"security_event":true}'::jsonb
      INTO v_terminal FROM public.source_audits WHERE id=p_root_id;
    SELECT coalesce(jsonb_agg(jsonb_build_object('relation','public.source_audits','key',id::TEXT)),'[]'::jsonb)
      INTO v_rows FROM public.source_audits WHERE id=p_root_id;
  ELSIF p_root_kind='worker_log' THEN
    v_relation:='public.worker_logs';
    SELECT lower(level) NOT IN ('warn','warning','error','critical','security','audit')
      AND created_at<v_cutoff
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
      INTO v_terminal FROM public.worker_logs WHERE id=p_root_id;
    SELECT coalesce(jsonb_agg(jsonb_build_object('relation','public.worker_logs','key',id::TEXT)),'[]'::jsonb)
      INTO v_rows FROM public.worker_logs WHERE id=p_root_id;
  ELSIF p_root_kind='runtime_artifact' THEN
    v_relation:='public.runtime_artifacts';
    SELECT created_at<v_cutoff AND artifact_key !~* '(latest|release|recovery)'
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"pinned":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"unresolved":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"recovery_required":true}'::jsonb
      AND NOT coalesce(metadata,'{}'::jsonb) @> '{"security_event":true}'::jsonb
      INTO v_terminal FROM public.runtime_artifacts WHERE id=p_root_id;
    SELECT coalesce(jsonb_agg(jsonb_build_object('relation','public.runtime_artifacts','key',id::TEXT)),'[]'::jsonb)
      INTO v_rows FROM public.runtime_artifacts WHERE id=p_root_id;
  END IF;

  IF jsonb_array_length(v_rows)=0 THEN v_blockers:=v_blockers||'[{"code":"root_not_found"}]'::jsonb; END IF;
  IF NOT coalesce(v_terminal,FALSE) THEN v_blockers:=v_blockers||'[{"code":"not_terminal_or_retention_not_elapsed"}]'::jsonb; END IF;
  IF EXISTS (
    SELECT 1 FROM public.retention_archive_active_pins_v1() pin
    JOIN jsonb_array_elements(v_rows) row_spec
      ON pin.relation_name=row_spec->>'relation' AND pin.row_key=row_spec->>'key'
  ) THEN v_blockers:=v_blockers||'[{"code":"active_pin"}]'::jsonb; END IF;

  RETURN jsonb_build_object(
    'eligible',jsonb_array_length(v_blockers)=0,'rootKind',p_root_kind,'rootId',p_root_id,
    'rootRelation',v_relation,'cutoffAt',v_cutoff,'rows',v_rows,'blockers',v_blockers,
    'policyVersion','retention-v1'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.retry_candidate_financial_document_runtime(p_receipt_id uuid, p_request_id uuid, p_caller_principal uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_receipt public.candidate_financial_document_receipts_v6%ROWTYPE; v_reasons jsonb;
BEGIN
  IF NOT public.internal_principal_role_is_exact_v3_internal(p_caller_principal,'opportunity_runner',clock_timestamp())
    THEN RAISE EXCEPTION 'principal_role_unavailable'; END IF;
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'retry_request_id_required'; END IF;
  SELECT * INTO v_receipt FROM public.candidate_financial_document_receipts_v6 WHERE receipt_id=p_receipt_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retry_receipt_missing'; END IF;
  IF EXISTS(SELECT 1 FROM public.candidate_financial_document_retry_audit WHERE request_id=p_request_id AND receipt_id=p_receipt_id)
    THEN RETURN FALSE; END IF;
  v_reasons := v_receipt.missing_requirements || v_receipt.rejection_reasons;
  IF v_receipt.parser_status<>'complete' OR v_receipt.added_fact_count<>0 OR v_receipt.duplicate_fact_count<>0
    OR jsonb_array_length(v_reasons)=0
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_reasons) reason
      WHERE reason ~ '^candidate_financial_local_parser_(socket_unavailable|not_configured|timeout|spawn_failed|failed)(:|$)')
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_reasons) reason
      WHERE reason !~ '^candidate_financial_local_parser_(socket_unavailable|not_configured|timeout|spawn_failed|failed)(:|$)'
        AND reason<>'no_verified_financial_facts_extracted')
    THEN RAISE EXCEPTION 'receipt_not_runtime_retryable'; END IF;
  IF (SELECT count(*) FROM public.candidate_financial_document_retry_audit WHERE receipt_id=p_receipt_id)>=3
    THEN RAISE EXCEPTION 'receipt_runtime_retry_limit'; END IF;
  INSERT INTO public.candidate_financial_document_retry_audit(request_id,receipt_id,prior_receipt,caller_principal)
    VALUES(p_request_id,p_receipt_id,to_jsonb(v_receipt),p_caller_principal);
  UPDATE public.candidate_financial_document_receipts_v6 SET receipt_status='accepted',parser_status='queued',
    parser_owner=NULL,parser_lease_expires_at=NULL,completed_at=NULL,missing_requirements='[]'::jsonb,rejection_reasons='[]'::jsonb
    WHERE receipt_id=p_receipt_id;
  RETURN TRUE;
END; $function$

CREATE OR REPLACE FUNCTION public.revoke_provider_credential_cas_v1(p_provider text, p_expected_generation bigint, p_owner_user_id_hash text, p_request_kind text, p_confirmation_code_hash text, p_request_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prior public.provider_credentials_encrypted_v1%ROWTYPE; now_at timestamptz:=clock_timestamp();
BEGIN
  PERFORM public.assert_stockinsider_backend_request_v1(false);
  IF p_provider<>'threads' OR p_expected_generation<1 OR p_owner_user_id_hash !~ '^[0-9a-f]{64}$'
    OR p_request_kind NOT IN ('deauthorize','data_deletion') OR p_confirmation_code_hash !~ '^[0-9a-f]{64}$'
    OR p_request_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='provider_revocation_payload_invalid';
  END IF;
  IF EXISTS(SELECT 1 FROM public.threads_data_deletion_requests WHERE request_digest=p_request_digest) THEN
    RETURN jsonb_build_object('status','completed','replayed',true);
  END IF;
  SELECT * INTO prior FROM public.provider_credentials_encrypted_v1 WHERE provider=p_provider FOR UPDATE;
  IF NOT FOUND OR prior.generation<>p_expected_generation OR prior.status<>'valid'
    OR prior.owner_user_id_hash IS DISTINCT FROM p_owner_user_id_hash THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='provider_credential_revocation_conflict';
  END IF;
  UPDATE public.provider_credentials_encrypted_v1 SET generation=generation+1,status='revoked',iv=NULL,tag=NULL,
    ciphertext=NULL,token_sha256=NULL,expires_at=NULL,refreshed_at=NULL,revoked_at=now_at,updated_at=now_at
    WHERE provider=p_provider;
  UPDATE public.source_credentials_registry SET status='invalid',credential_ref=NULL,
    error_message='threads_user_revoked_authorization',
    metadata=(COALESCE(metadata,'{}'::jsonb)-'token_hash'-'last_refreshed_at'-'expires_at'-'non_self_public_search_canary')
      ||jsonb_build_object('credential_generation',p_expected_generation+1,'revoked_at',now_at,
        'revocation_kind',p_request_kind,'storage','contabo_envelope_v1'),updated_at=now_at
    WHERE platform=p_provider;
  UPDATE public.source_connector_registry SET lifecycle='blocked_auth',updated_at=now_at WHERE connector=p_provider;
  INSERT INTO public.threads_data_deletion_requests(confirmation_code_hash,threads_user_id_hash,request_digest,
    request_kind,status,requested_at,completed_at,metadata)
  VALUES(p_confirmation_code_hash,p_owner_user_id_hash,p_request_digest,p_request_kind,'completed',now_at,now_at,
    jsonb_build_object('credential_deleted',true,'credential_owner_matched',true,'storage','contabo_envelope_v1'));
  RETURN jsonb_build_object('status','completed','credential_deleted',true,'generation',p_expected_generation+1);
END
$function$

CREATE OR REPLACE FUNCTION public.schedule_legacy_source_shard_successor_v3_19(p_run uuid, p_completed_source_job uuid, p_successor_job uuid, p_source_result_hash text, p_first_ordinal integer, p_first_revision uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payload jsonb;v_payload_bytes bytea;v_payload_hash text;v_successor uuid;
  v_execution_ordinal integer;v_uuid_hash text;v_existing public.legacy_producer_jobs_v3_11%ROWTYPE;
  v_barrier_status public.opportunity_legacy_producer_job_status_v3_11;
BEGIN
  IF p_source_result_hash !~ '^[0-9a-f]{64}$' OR p_first_ordinal<0 OR p_first_revision IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_input_invalid';
  END IF;
  PERFORM 1 FROM public.legacy_producer_jobs_v3_11 job
  JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=job.job_id
  WHERE job.run_id=p_run AND job.job_id=p_completed_source_job
    AND job.stage='source_sync' AND job.status='succeeded' AND result.result_hash=p_source_result_hash;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_predecessor_conflict';
  END IF;
  SELECT job.status,job.execution_ordinal+1 INTO v_barrier_status,v_execution_ordinal
  FROM public.legacy_producer_jobs_v3_11 job
  WHERE job.job_id=p_successor_job AND job.run_id=p_run
    AND job.stage='mention_claim_extraction' AND job.job_kind='stage_barrier'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_conflict';
  END IF;
  v_uuid_hash:=encode(extensions.digest(convert_to(
    'legacy-v319-source-shard:'||p_run::text||':'||p_first_ordinal::text||':'||p_first_revision::text,'utf8'),'sha256'),'hex');
  v_successor:=(substr(v_uuid_hash,1,8)||'-'||substr(v_uuid_hash,9,4)||'-'||substr(v_uuid_hash,13,4)||'-'||
    substr(v_uuid_hash,17,4)||'-'||substr(v_uuid_hash,21,12))::uuid;
  v_payload:=jsonb_build_array('e6d9c09b8b552f5d9eaf389b76d2d90daa2d89578433d2a1ad63286888b3b743',
    p_source_result_hash,'mention_claim_extraction','revision_shard',p_first_ordinal,p_first_revision);
  v_payload_bytes:=convert_to(v_payload::text,'utf8');
  v_payload_hash:=encode(extensions.digest(v_payload_bytes,'sha256'),'hex');
  SELECT * INTO v_existing FROM public.legacy_producer_jobs_v3_11 job WHERE job.job_id=v_successor;
  IF v_existing.job_id IS NOT NULL THEN
    IF v_existing.run_id<>p_run OR v_existing.stage<>'mention_claim_extraction'
      OR v_existing.job_kind<>'revision_shard' OR v_existing.shard_ordinal<>p_first_ordinal
      OR v_existing.execution_ordinal<>v_execution_ordinal OR v_existing.revision_id<>p_first_revision
      OR v_existing.input_hash<>v_payload_hash OR v_barrier_status<>'cancelled'
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_identity_conflict';
    END IF;
    RETURN jsonb_build_object('jobId',v_successor,'stage','mention_claim_extraction');
  END IF;
  IF v_barrier_status<>'queued' THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_transition_conflict';
  END IF;
  UPDATE public.legacy_producer_jobs_v3_11 job
  SET status='cancelled',terminal_at=date_trunc('second',clock_timestamp()),failure_code='cancelled',
    owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
  WHERE job.job_id=p_successor_job AND job.status='queued';
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v319_same_run_successor_transition_conflict';
  END IF;
  IF v_existing.job_id IS NULL THEN
    INSERT INTO public.legacy_producer_jobs_v3_11(
      job_id,run_id,stage,job_kind,stage_ordinal,shard_ordinal,execution_ordinal,revision_id,
      predecessor_job_id,input_hash,payload_hash,status,attempt,max_attempts,owner_token_hash,leased_at,
      heartbeat_at,lease_expires_at,terminal_at,failure_code,recorded_at
    ) VALUES(
      v_successor,p_run,'mention_claim_extraction','revision_shard',1,p_first_ordinal,v_execution_ordinal,
      p_first_revision,p_completed_source_job,v_payload_hash,v_payload_hash,'queued',0,5,NULL,NULL,NULL,NULL,NULL,NULL,
      date_trunc('second',clock_timestamp())
    );
    INSERT INTO public.legacy_producer_job_payloads_v3_11(
      job_id,payload_canonical,payload_json,payload_hash,recorded_at
    ) VALUES(v_successor,v_payload_bytes,v_payload,v_payload_hash,date_trunc('second',clock_timestamp()));
  END IF;
  RETURN jsonb_build_object('jobId',v_successor,'stage','mention_claim_extraction');
END $function$

CREATE OR REPLACE FUNCTION public.seal_research_article_input_revision_v2(p_request jsonb, p_calculation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent jsonb; existing jsonb; m jsonb; p jsonb; f jsonb; projection jsonb; calc jsonb; material jsonb; known timestamptz; n timestamptz; rh text; ih text; charge integer; used_count bigint;used_bytes bigint;saved public.research_article_input_revisions_v2;gaps jsonb;
BEGIN
 existing:=public.read_research_article_input_revision_v2(p_request);IF existing->>'status'='sealed' THEN RETURN existing;END IF;
 parent:=existing->'preparation';p:=parent->'payload';m:=public.research_complete_mapping_v2(p->>'symbol');
 IF p_calculation IS NULL OR octet_length(p_calculation::text)>262144 THEN RAISE EXCEPTION 'complete_calculation_bound';END IF;
 known:=(p_calculation->>'artifactReadKnownAt')::timestamptz;
 PERFORM public.research_complete_schema_check_v2(p_calculation,m->'schema',known);
 IF p_calculation->>'sourceClosureHash' IS DISTINCT FROM m->>'sourceClosureHash' OR p_calculation->>'artifactInventoryHash' IS DISTINCT FROM m->>'inventoryHash' THEN RAISE EXCEPTION 'complete_calculation_mapping';END IF;
 f:=p_calculation->'financialMaterial';projection:=f->'projection';calc:=f->'calculation';
 IF octet_length(projection::text)>160000 THEN RAISE EXCEPTION 'complete_projection_bound';END IF;
 -- After bounded computation/validation, repeat all original fences under the same locks.
 parent:=public.research_complete_parent_v2(p_request);n:=clock_timestamp();
 IF NOT isfinite(known) OR known>n OR known<(m->>'modelCutoff')::timestamptz OR (parent->>'admitted_at')::timestamptz>n OR (parent->>'admitted_at')::timestamptz<n-interval '120 seconds' THEN RAISE EXCEPTION 'complete_freshness';END IF;
 gaps:=jsonb_build_array(jsonb_build_object('namespace','source','reason','source_coverage_incomplete'),jsonb_build_object('namespace','financial','reason','financial_source_live_rights_unverified'),jsonb_build_object('namespace','execution','reason','trusted_role_execution_unavailable'));
 SELECT gaps||jsonb_agg(jsonb_build_object('namespace','financial','reason',reason) ORDER BY ord) INTO gaps FROM jsonb_array_elements_text(projection->'gaps') WITH ORDINALITY a(reason,ord);
 IF jsonb_array_length(p->'sourceManifest')=0 THEN gaps:=gaps||jsonb_build_array(jsonb_build_object('namespace','source','reason','sources_not_selected'));END IF;
 material:=jsonb_build_object('schemaVersion','research-article-input-v2','assemblyStatus','complete','evidenceStatus','incomplete','producerAttribution','internal_controller_asserted',
 'preparation',jsonb_build_object('id',parent->'preparation_id','inputHash',parent->'input_hash'),
 'researchIdentity',jsonb_build_object('researchCompanyId',p->'researchCompanyId','symbol',p->'symbol','scope',p->'scope','snapshotHash',p->'snapshotHash','mappingDigest',p->'mappingDigest','stockId',p->'stockId'),
 'priority',jsonb_build_object('runId',p->'priorityRunId','inputHash',p->'priorityInputHash','discoveryCutoff',p->'discoveryCutoff'),
 'originalJob',p->'originalJob','originalReservation',p->'originalReservation','sources',jsonb_build_object('sealId',parent->'source_seal_id','manifest',p->'sourceManifest','coverage','incomplete'),
 'financial',jsonb_build_object('artifactInventory',m->'inventory','material',f),
 'hashes',jsonb_build_object('preparationInputHash',parent->'input_hash','artifactInventoryHash',public.research_complete_hash_v2(m->'inventory'),'modelHistoricalCanonicalHash',m->'historicalHash',
 'sourceManifestHash',public.research_complete_hash_v2(projection->'sourceManifest'),'projectionHash',public.research_complete_hash_v2(projection),'scenarioInputHash',public.research_complete_hash_v2(projection->'projected'->'scenarios'),'resultHash',public.research_complete_hash_v2(calc),'sourceClosureHash',m->'sourceClosureHash'),
 'clocks',jsonb_build_object('originalModelCutoff',m->'modelCutoff','originalPreparationAdmittedAt',parent->'admitted_at','artifactReadKnownAt',p_calculation->'artifactReadKnownAt','financialAdmittedAt',n,'researchCutoff',n),
 'gaps',gaps,'capabilities',jsonb_build_object('financialVerified',false,'dispatchReady',false,'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false,'historicalPITEligible',false));
 charge:=octet_length(convert_to(public.research_complete_canonical_v2(p_request),'UTF8'))+octet_length(convert_to(public.research_complete_canonical_v2(material),'UTF8'));
 SELECT count(*),coalesce(sum(logical_bytes),0) INTO used_count,used_bytes FROM (
 SELECT logical_bytes FROM public.research_input_preparations_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid
 UNION ALL SELECT logical_bytes FROM public.research_article_input_revisions_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid) history;
 IF used_count>=4 THEN RAISE EXCEPTION 'complete_count_bound';END IF;IF used_bytes+charge>524288 THEN RAISE EXCEPTION 'complete_byte_bound';END IF;
 IF clock_timestamp()>=least((p->'originalJob'->>'leaseExpiresAt')::timestamptz,(p->'originalReservation'->>'leaseExpiresAt')::timestamptz) THEN RAISE EXCEPTION 'complete_lease_lost';END IF;
 rh:=public.research_complete_hash_v2(p_request);ih:=public.research_complete_hash_v2(material);
 INSERT INTO public.research_article_input_revisions_v2(preparation_id,job_id,attempt,reservation_id,research_company_id,research_scope,snapshot_hash,request_hash,canonical_request,input_hash,canonical_payload,logical_bytes,admitted_at,research_cutoff,source_seal_id)
 VALUES((parent->>'preparation_id')::uuid,(parent->>'job_id')::uuid,(parent->>'attempt')::int,(parent->>'reservation_id')::uuid,(p->>'researchCompanyId')::uuid,'research_observed_v1',p->>'snapshotHash',rh,p_request,ih,material,charge,n,n,(parent->>'source_seal_id')::uuid) RETURNING * INTO saved;
 RETURN to_jsonb(saved)||jsonb_build_object('status','sealed','replay',false,'dispatchReady',false);
END $function$

CREATE OR REPLACE FUNCTION public.seal_research_sources_v2(p_documents jsonb, p_cutoff timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb; doc jsonb; root text; docs jsonb:='[]'; row_hash text; req text; result public.research_source_seals_v2;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'source_fence_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(610091002::bigint);
 IF p_cutoff IS NULL OR NOT isfinite(p_cutoff) OR p_cutoff>clock_timestamp()
  OR p_documents IS NULL OR jsonb_typeof(p_documents)<>'array' THEN RAISE EXCEPTION 'source_seal_shape'; END IF;
 IF jsonb_array_length(p_documents) NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'source_seal_shape'; END IF;
 IF (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_documents) x)<>jsonb_array_length(p_documents) THEN RAISE EXCEPTION 'source_seal_duplicate'; END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(p_documents) x ORDER BY x->>'id' LOOP
  IF jsonb_typeof(item)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>2
   OR jsonb_typeof(item->'id')<>'string' OR jsonb_typeof(item->'rowHash')<>'string'
   OR NOT(item ? 'id' AND item ? 'rowHash') OR COALESCE(item->>'rowHash','')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'source_seal_shape'; END IF;
  SELECT to_jsonb(s) INTO doc FROM public.source_raw_documents s WHERE s.id=(item->>'id')::uuid;
  IF doc IS NULL THEN RAISE EXCEPTION 'source_seal_missing'; END IF;
  -- Reposts cannot launder an older ancestor's revoked rights. Until the full
  -- immutable ancestor closure is implemented, admit originals only; never
  -- infer ancestor permission from the child's public-citation flag.
  IF NULLIF(doc->'metadata'->>'parent_source_url','') IS NOT NULL
   AND doc->'metadata'->>'parent_source_url' IS DISTINCT FROM COALESCE(NULLIF(doc->'metadata'->>'canonical_url',''),split_part(doc->>'document_url','#si-revision-',1)) THEN RAISE EXCEPTION 'source_seal_unsupported_parent_lineage'; END IF;
  IF octet_length(doc::text)>4194304 THEN RAISE EXCEPTION 'source_seal_document_bound'; END IF;
  row_hash:=encode(sha256(convert_to(doc::text,'UTF8')),'hex'); root:=public.research_source_root_v2(doc);
  IF row_hash<>item->>'rowHash' THEN RAISE EXCEPTION 'source_seal_hash_changed'; END IF;
  IF root IS NULL OR root='' OR octet_length(root)>4096 OR (doc->>'collected_at')::timestamptz IS NULL
   OR NOT isfinite((doc->>'collected_at')::timestamptz) OR (doc->>'collected_at')::timestamptz>p_cutoff
   OR (doc->>'published_at')::timestamptz>p_cutoff THEN RAISE EXCEPTION 'source_seal_clock'; END IF;
  IF COALESCE(doc->'metadata'->>'rights_boundary','') NOT IN ('public_citation','bounded_summary_only')
   OR NULLIF(doc->'metadata'->>'retracted_at','') IS NOT NULL OR doc->'metadata'->>'claim_status'='denied' THEN RAISE EXCEPTION 'source_seal_rights_or_withdrawn'; END IF;
  IF EXISTS(SELECT FROM public.source_raw_documents s WHERE public.research_source_root_v2(to_jsonb(s))=root
   AND s.id<>(doc->>'id')::uuid AND (s.collected_at>=(doc->>'collected_at')::timestamptz
    OR NULLIF(s.metadata->>'retracted_at','') IS NOT NULL OR s.metadata->>'claim_status'='denied')) THEN RAISE EXCEPTION 'source_seal_root_changed'; END IF;
  docs:=docs||jsonb_build_array(jsonb_build_object('id',doc->>'id','rowHash',row_hash,'root',root,
   'publishedAt',doc->'published_at','observedAt',doc->'collected_at','rights',doc->'metadata'->>'rights_boundary'));
 END LOOP;
 req:=encode(sha256(convert_to(jsonb_build_object('documents',docs,'cutoff',p_cutoff)::text,'UTF8')),'hex');
 SELECT * INTO result FROM public.research_source_seals_v2 WHERE request_hash=req;
 IF FOUND THEN
  IF EXISTS(SELECT FROM public.research_source_seal_invalidations_v2 WHERE seal_id=result.seal_id) THEN RAISE EXCEPTION 'source_seal_invalidated'; END IF;
 ELSE
  INSERT INTO public.research_source_seals_v2(request_hash,cutoff,documents) VALUES(req,p_cutoff,docs) RETURNING * INTO result;
 END IF;
 RETURN to_jsonb(result)||jsonb_build_object('publicationAuthorized',false,'historicalPITEligible',false);
END $function$

CREATE OR REPLACE FUNCTION public.seed_financial_document_job_link_v9()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_required jsonb;
BEGIN
  IF NEW.acquisition_job_id IS NOT NULL THEN
    SELECT job.required_fact_keys INTO v_required FROM public.candidate_financial_acquisition_jobs_v4 job
      WHERE job.job_id=NEW.acquisition_job_id AND job.stock_id=NEW.stock_id AND job.period_end=NEW.period_end;
