      VALUES(NEW.receipt_id,NEW.acquisition_job_id,v_required) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.seed_v320_kol_source_authorities()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_rows jsonb := $identity$[
    {"id":"712771ff-b763-5045-8f8c-dd6466d6e6c0","platform":"telegram","entityType":"channel","displayName":"股癌","sourceIdentityKey":"v320:telegram:gooaye","profileUrl":"https://t.me/Gooaye","sourceKey":"telegram","sourceClass":"community","distributionIdentity":"telegram:gooaye"},
    {"id":"09d40273-9595-5a1c-8a0c-ee1624745473","platform":"telegram","entityType":"channel","displayName":"定錨投筆","sourceIdentityKey":"v320:telegram:investanchors","profileUrl":"https://t.me/investanchors","sourceKey":"telegram","sourceClass":"community","distributionIdentity":"telegram:investanchors"},
    {"id":"8cddda0f-0143-5df3-98d0-31a525e765fa","platform":"telegram","entityType":"channel","displayName":"John 林睿閔","sourceIdentityKey":"v320:telegram:johnstock888","profileUrl":"https://t.me/johnstock888","sourceKey":"telegram","sourceClass":"community","distributionIdentity":"telegram:johnstock888"},
    {"id":"c6067995-32ee-5886-a56f-067eccac29e4","platform":"investanchors","entityType":"site","displayName":"定錨投筆","sourceIdentityKey":"v320:investanchors:investanchors","profileUrl":"https://investanchors.com","sourceKey":"investanchors","sourceClass":"curated_thesis","distributionIdentity":"investanchors:investanchors"}
  ]$identity$::jsonb;
  v_expected integer := 4;
  v_source_reviewer_principal_id uuid := 'a11d4e67-7d0a-4c44-8a9d-1d5c3b875002'::uuid;
  v_source_reviewer_binding_id uuid := '2ef0a7f8-862c-51a7-837e-f606ff43b59a'::uuid;
  v_source_reviewer_configuration_hash text := 'aa07af55ed6f178ecf811bb6ca8081217a738dffb98b3746055669db0d145356';
BEGIN
  IF jsonb_array_length(v_rows) <> v_expected THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_authority_seed_fixture_conflict';
  END IF;
  IF EXISTS (
    WITH requested AS (SELECT * FROM jsonb_to_recordset(v_rows) AS x(
      id uuid,platform text,"entityType" text,"displayName" text,"sourceIdentityKey" text,"profileUrl" text,
      "sourceKey" text,"sourceClass" text,"distributionIdentity" text))
    SELECT 1 FROM requested r JOIN public.source_entities entity
      ON entity.source_key=r."sourceIdentityKey" OR entity.id=r.id
    WHERE entity.id<>r.id OR entity.source_key<>r."sourceIdentityKey" OR entity.platform<>r.platform
      OR entity.entity_type<>r."entityType" OR entity.display_name<>r."displayName"
      OR entity.profile_url IS DISTINCT FROM r."profileUrl" OR entity.status<>'active'
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_authority_identity_conflict';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.internal_principal_role_bindings_v3 binding
    WHERE binding.binding_id=v_source_reviewer_binding_id
      AND (binding.principal_id<>v_source_reviewer_principal_id OR binding.role<>'source_reviewer'
        OR binding.status<>'active' OR binding.configuration_hash<>v_source_reviewer_configuration_hash)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_reviewer_binding_conflict';
  END IF;
  INSERT INTO public.internal_principal_role_bindings_v3(
    binding_id,principal_id,role,valid_from,valid_to,status,configuration_hash,recorded_at
  )
  SELECT v_source_reviewer_binding_id,v_source_reviewer_principal_id,'source_reviewer',
    clock_timestamp()-interval '1 second',NULL,'active',v_source_reviewer_configuration_hash,clock_timestamp()
  WHERE NOT EXISTS (
    SELECT 1 FROM public.internal_principal_role_bindings_v3 binding
    WHERE binding.binding_id=v_source_reviewer_binding_id
  );
  IF NOT EXISTS (
    SELECT 1 FROM public.internal_principal_role_bindings_v3 binding
    WHERE binding.binding_id=v_source_reviewer_binding_id
      AND binding.principal_id=v_source_reviewer_principal_id AND binding.role='source_reviewer'
      AND binding.status='active' AND binding.valid_to IS NULL
      AND binding.configuration_hash=v_source_reviewer_configuration_hash
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_reviewer_binding_postcondition_failed';
  END IF;
  INSERT INTO public.source_entities(
    id,platform,entity_type,display_name,source_key,profile_url,status,metadata,created_at,updated_at
  )
  SELECT id,platform,"entityType","displayName","sourceIdentityKey","profileUrl",'active',
    jsonb_build_object('authority','approved-source-roster-v3.20','migration','v320-kol-source-authority'),
    clock_timestamp(),clock_timestamp()
  FROM jsonb_to_recordset(v_rows) AS x(
    id uuid,platform text,"entityType" text,"displayName" text,"sourceIdentityKey" text,"profileUrl" text,
    "sourceKey" text,"sourceClass" text,"distributionIdentity" text)
  ON CONFLICT(source_key) DO NOTHING;
  IF (WITH requested AS (SELECT * FROM jsonb_to_recordset(v_rows) AS x(
      id uuid,platform text,"entityType" text,"displayName" text,"sourceIdentityKey" text,"profileUrl" text,
      "sourceKey" text,"sourceClass" text,"distributionIdentity" text))
    SELECT count(*) FROM requested r JOIN public.source_entities entity
      ON entity.id=r.id AND entity.source_key=r."sourceIdentityKey" AND entity.platform=r.platform
        AND entity.entity_type=r."entityType" AND entity.display_name=r."displayName"
        AND entity.profile_url IS NOT DISTINCT FROM r."profileUrl" AND entity.status='active') <> v_expected THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_authority_identity_postcondition_failed';
  END IF;
  PERFORM appended.authority_id
  FROM (
    WITH requested AS (SELECT * FROM jsonb_to_recordset(v_rows) AS x(
      id uuid,platform text,"entityType" text,"displayName" text,"sourceIdentityKey" text,"profileUrl" text,
      "sourceKey" text,"sourceClass" text,"distributionIdentity" text))
    SELECT r.* FROM requested r WHERE NOT EXISTS (
      SELECT 1 FROM public.source_identity_authorities_v3 authority
      WHERE authority.source_identity_id=r.id AND authority.source_key::text=r."sourceKey"
        AND authority.distribution_identity=r."distributionIdentity" AND authority.status='active'
    )
  ) missing
  CROSS JOIN LATERAL public.append_source_identity_authority_v3(ROW(
    missing.id,missing."sourceKey"::public.source_key_v3,missing."sourceClass"::public.source_class_v3,
    missing."distributionIdentity",'1970-01-01T00:00:00Z'::timestamptz,NULL,'active'::public.authority_status_v3
  )::public.source_identity_authority_input_v3,v_source_reviewer_principal_id) appended;
  IF (WITH requested AS (SELECT * FROM jsonb_to_recordset(v_rows) AS x(
      id uuid,platform text,"entityType" text,"displayName" text,"sourceIdentityKey" text,"profileUrl" text,
      "sourceKey" text,"sourceClass" text,"distributionIdentity" text))
    SELECT count(*) FROM requested r JOIN public.source_identity_authorities_v3 authority
      ON authority.source_identity_id=r.id AND authority.source_key::text=r."sourceKey"
        AND authority.distribution_identity=r."distributionIdentity" AND authority.status='active') <> v_expected THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='v320_kol_source_authority_postcondition_failed';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.store_observed_research_priority_v1(p_snapshot_hash text, p_as_of timestamp with time zone, p_input_hash text, p_attempts jsonb, p_rows jsonb, p_queue jsonb, p_scope_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE snap public.research_observed_roster_snapshots_v1; id uuid; member record; row jsonb; first_at timestamptz; added integer; captures integer:=0; existing public.research_priority_runs_v1; heads jsonb:='[]'; page jsonb; source_offset integer:=0; actual_first timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 PERFORM pg_advisory_xact_lock(2409,6001);
 SELECT * INTO snap FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=p_snapshot_hash AND received_at<=p_as_of AND latest_observed_at<=p_as_of;
 IF NOT FOUND OR p_as_of IS NULL OR NOT isfinite(p_as_of) OR p_as_of>clock_timestamp() OR p_input_hash IS NULL OR octet_length(coalesce(p_rows::text,''))+octet_length(coalesce(p_attempts::text,''))+octet_length(coalesce(p_scope_receipt::text,''))>16000000 OR p_input_hash !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows)<>snap.included_count OR jsonb_typeof(p_queue) IS DISTINCT FROM 'array' OR jsonb_array_length(p_queue)>20 OR jsonb_typeof(p_attempts) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'observed_priority_input_invalid'; END IF;
 IF p_scope_receipt IS DISTINCT FROM (public.read_research_observed_roster_v1(p_snapshot_hash,p_as_of,0,1)-'members') THEN RAISE EXCEPTION 'observed_priority_receipt_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)r LEFT JOIN public.research_observed_roster_members_v1 m ON m.snapshot_hash=p_snapshot_hash AND m.symbol=r->>'symbol' WHERE m.symbol IS NULL) OR (SELECT count(DISTINCT r->>'symbol')FROM jsonb_array_elements(p_rows)r)<>snap.included_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_queue)q WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)r WHERE r @> q)) THEN RAISE EXCEPTION 'observed_priority_accounting_invalid'; END IF;
 SELECT * INTO existing FROM public.research_priority_runs_v1 WHERE policy_version='research-priority-v1' AND input_hash=p_input_hash;
 IF FOUND THEN
  IF existing.research_scope<>'research_observed_v1' OR existing.observed_snapshot_hash<>p_snapshot_hash OR existing.as_of<>p_as_of OR existing.rows<>p_rows OR existing.research_queue<>p_queue OR existing.source_attempts<>p_attempts OR existing.scope_receipt<>p_scope_receipt THEN RAISE EXCEPTION 'observed_priority_replay_mismatch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.research_observed_priority_store_receipts_v1 receipt WHERE receipt.run_id=existing.run_id AND receipt.stored_run_hash=encode(sha256(convert_to(to_jsonb(existing)::text,'UTF8')),'hex'))THEN RAISE EXCEPTION 'observed_priority_store_lineage_missing';END IF;
  RETURN jsonb_build_object('runId',existing.run_id,'newDeepResearchJobs',0,'firstDiscoveryCaptures',0,'idempotentReplay',true);
 END IF;
 -- Verify claimed root identities against actual bounded database source heads.
 LOOP
  SELECT coalesce(jsonb_agg(value),'[]') INTO page FROM public.research_source_heads_page_v1(p_as_of,source_offset,500)value;
  heads:=heads||page;IF jsonb_array_length(heads)>20000 THEN RAISE EXCEPTION 'observed_source_head_bound'; END IF;
  EXIT WHEN jsonb_array_length(page)<500;source_offset:=source_offset+500;
 END LOOP;
 FOR row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  IF jsonb_typeof(row->'rootIds') IS DISTINCT FROM 'array' OR jsonb_typeof(row->'independentRootCount') IS DISTINCT FROM 'number' OR row->>'independentRootCount' !~ '^[0-9]+$' OR (row->>'independentRootCount')::integer<>jsonb_array_length(row->'rootIds') OR (SELECT count(DISTINCT value)FROM jsonb_array_elements(row->'rootIds'))<>jsonb_array_length(row->'rootIds') THEN RAISE EXCEPTION 'observed_priority_root_count_invalid'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(row->'rootIds')root WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(heads)h WHERE h->'symbols' @> jsonb_build_array(row->'symbol') AND coalesce(h#>>'{metadata,subject_scope}','company_mentions')='company_mentions' AND coalesce(h#>>'{metadata,parent_source_url}',h#>>'{metadata,canonical_url}',split_part(h->>'document_url','#si-revision-',1))=root AND coalesce(h->>'content_semantics','')<>'metadata_only' AND coalesce(h#>>'{metadata,content_form}','')<>'chapter_titles' AND h#>>'{metadata,retracted_at}' IS NULL AND coalesce(h#>>'{metadata,claim_status}','')<>'denied')) THEN RAISE EXCEPTION 'observed_priority_source_binding_invalid'; END IF;
  SELECT min((h#>>'{metadata,first_observed_at}')::timestamptz) INTO actual_first FROM jsonb_array_elements(heads)h WHERE h->'symbols' @> jsonb_build_array(row->'symbol') AND coalesce(h#>>'{metadata,subject_scope}','company_mentions')='company_mentions' AND coalesce(h->>'content_semantics','')<>'metadata_only' AND coalesce(h#>>'{metadata,content_form}','')<>'chapter_titles';
  IF (row->'hasDiscoveryEvidence' IS DISTINCT FROM to_jsonb(actual_first IS NOT NULL)) OR (row->>'firstSeenAt')::timestamptz IS DISTINCT FROM actual_first THEN RAISE EXCEPTION 'observed_first_observation_binding_invalid'; END IF;
 END LOOP;
 INSERT INTO public.research_priority_runs_v1(as_of,policy_version,input_hash,expected_count,accounted_count,source_attempts,rows,research_queue,research_scope,observed_snapshot_hash,scope_receipt)
  VALUES(p_as_of,'research-priority-v1',p_input_hash,snap.included_count,snap.included_count,p_attempts,p_rows,p_queue,'research_observed_v1',p_snapshot_hash,p_scope_receipt) RETURNING run_id INTO id;
 INSERT INTO public.research_observed_priority_store_receipts_v1(run_id,stored_run_hash)SELECT run_id,encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')FROM public.research_priority_runs_v1 r WHERE run_id=id;
 FOR member IN SELECT * FROM public.research_observed_roster_members_v1 WHERE snapshot_hash=p_snapshot_hash LOOP
  SELECT value INTO row FROM jsonb_array_elements(p_rows) WHERE value->>'symbol'=member.symbol;
  IF coalesce((row->>'hasDiscoveryEvidence')::boolean,false) THEN
   first_at:=(row->>'firstSeenAt')::timestamptz;
   IF first_at IS NULL OR first_at>p_as_of THEN RAISE EXCEPTION 'observed_discovery_clock_invalid'; END IF;
   INSERT INTO public.research_observed_first_discoveries_v1(research_company_id,symbol,run_id,first_seen_at,snapshot,observed_snapshot_hash)
    VALUES(member.research_company_id,member.symbol,id,first_at,jsonb_build_object('price',NULL,'priceStatus','missing_at_discovery','pricePhase','unknown','relative5d',NULL,'relative20d',NULL,'relative60d',NULL,'factors',row->'factors','scope','research_observed_v1'),p_snapshot_hash)ON CONFLICT(research_company_id)DO NOTHING;
   IF FOUND THEN captures:=captures+1; END IF;
   INSERT INTO public.research_observed_discovery_lineage_v1(research_company_id,snapshot_hash,run_id)VALUES(member.research_company_id,p_snapshot_hash,id)ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
 added:=public.enqueue_research_deep_jobs_v1(id);
 RETURN jsonb_build_object('runId',id,'newDeepResearchJobs',added,'firstDiscoveryCaptures',captures,'idempotentReplay',false);
END $function$

CREATE OR REPLACE FUNCTION public.submit_link_audit_label_v3(requested_sample_manifest_id uuid, requested_sample_id text, requested_role internal_principal_role_v3, requested_label_role link_audit_label_role_v3, canonical_symbol_or_null text, no_link boolean, caller_principal uuid, nonce text, request_timestamp timestamp with time zone)
 RETURNS TABLE(sample_manifest_id uuid, sample_id text, label_role link_audit_label_role_v3, label_hash text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz:=clock_timestamp(); v_hash text;
  v_sample public.opportunity_link_audit_samples%ROWTYPE;
  v_one public.opportunity_link_audit_labels%ROWTYPE;
  v_two public.opportunity_link_audit_labels%ROWTYPE;
  v_own public.opportunity_link_audit_labels%ROWTYPE;
  v_assigned_role public.link_audit_label_role_v3;
BEGIN
  IF (($3='link_reviewer' AND $4 NOT IN ('reviewer_1','reviewer_2')) OR ($3='link_adjudicator' AND $4<>'adjudicator'))
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_label_role'; END IF;
  IF (($6 AND $5 IS NOT NULL) OR (NOT $6 AND ($5 IS NULL OR $5 !~ '^[0-9]{4}$')))
  THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_label_value'; END IF;
  IF $8 !~ '^[0-9a-f]{16,64}$' OR abs(extract(epoch FROM (v_now-$9)))>300 THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected'; END IF;
  IF NOT public.internal_principal_role_is_exact_v3_internal($7,$3,v_now)
  THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='principal_role_unavailable'; END IF;
  SELECT * INTO v_sample
  FROM public.opportunity_link_audit_samples sample
  WHERE sample.sample_manifest_id=$1 AND sample.sample_id=$2
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='assignment_unavailable';
  END IF;
  INSERT INTO public.internal_principal_nonces_v3(principal_id,nonce,request_timestamp,recorded_at) VALUES($7,$8,$9,v_now);
  SELECT * INTO v_one FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.label_role='reviewer_1';
  SELECT * INTO v_two FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.label_role='reviewer_2';
  SELECT * INTO v_own FROM public.opportunity_link_audit_labels label
  WHERE label.sample_manifest_id=$1 AND label.sample_id=$2
    AND label.reviewer_principal_id=$7;
  IF $3='link_reviewer' AND v_own.label_role='adjudicator' THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_already_other_branch';
  ELSIF $3='link_adjudicator' AND v_own.label_role IN ('reviewer_1','reviewer_2') THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='principal_not_distinct';
  END IF;
  IF v_own.label_role IS NOT NULL THEN
    IF v_own.label_role<>$4 THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    ELSIF v_own.canonical_symbol IS DISTINCT FROM $5
      OR v_own.no_link IS DISTINCT FROM $6
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_conflict';
    END IF;
    INSERT INTO public.opportunity_rpc_audit_v3(
      function_name,caller_principal_id,subject_kind,subject_id,
      input_hash,disposition,recorded_at
    ) VALUES(
      'submit_link_audit_label_v3',$7,'link_label',$1,
      encode(extensions.digest(convert_to(jsonb_build_array(
        $1,$2,$3,$4,$5,$6,$9
      )::text,'utf8'),'sha256'),'hex'),
      'idempotent',v_now
    );
    RETURN QUERY SELECT $1,$2,v_own.label_role,v_own.label_hash,v_own.submitted_at;
    RETURN;
  END IF;
  IF $3='link_reviewer' THEN
    v_assigned_role:=CASE
      WHEN v_one.label_role IS NULL THEN 'reviewer_1'::public.link_audit_label_role_v3
      WHEN v_two.label_role IS NULL THEN 'reviewer_2'::public.link_audit_label_role_v3
      ELSE NULL END;
    IF v_assigned_role IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_unavailable';
    END IF;
    IF $4<>v_assigned_role THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    END IF;
  ELSE
    IF v_one.label_role IS NULL OR v_two.label_role IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='reviewer_pair_incomplete';
    END IF;
    IF (v_one.canonical_symbol,v_one.no_link)
      IS NOT DISTINCT FROM (v_two.canonical_symbol,v_two.no_link)
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='adjudication_not_required';
    END IF;
    IF $4<>'adjudicator' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_not_assigned';
    END IF;
  END IF;
  IF NOT $6 AND NOT EXISTS (
    SELECT 1
    FROM public.opportunity_run_manifest_inputs binding
    JOIN public.opportunity_manifests_v3 manifest
      ON manifest.manifest_id=binding.manifest_id
      AND manifest.manifest_kind='instrument_roster'
      AND manifest.status='complete'
    JOIN public.opportunity_manifest_rows_v3 row
      ON row.manifest_id=manifest.manifest_id
      AND row.section_key='rows'
      AND row.payload_json->>2=$5
      AND row.payload_json->>4='common_stock'
      AND row.payload_json->>5='active'
    WHERE binding.run_id=v_sample.run_id
      AND binding.input_role='instrument_roster'
      AND binding.ordinal=0
  ) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_symbol_unavailable';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_array('link-audit-label-v3.0',$1,$2,$4,$5,$6,$7,v_now)::text,'utf8'),'sha256'),'hex');
  INSERT INTO public.opportunity_link_audit_labels(sample_manifest_id,sample_id,label_role,canonical_symbol,no_link,
    reviewer_principal_id,submitted_at,label_hash,recorded_at)
  VALUES($1,$2,$4,$5,$6,$7,v_now,v_hash,v_now);
  INSERT INTO public.opportunity_rpc_audit_v3(
    function_name,caller_principal_id,subject_kind,subject_id,
    input_hash,disposition,recorded_at
  ) VALUES(
    'submit_link_audit_label_v3',$7,'link_label',$1,
    encode(extensions.digest(convert_to(jsonb_build_array(
      $1,$2,$3,$4,$5,$6,$9
    )::text,'utf8'),'sha256'),'hex'),
    'submitted',v_now
  );
  RETURN QUERY SELECT $1,$2,$4,v_hash,v_now;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='label_slot_unavailable';
END
$function$

CREATE OR REPLACE FUNCTION public.terminalize_legacy_expired_producer_run_v3_20(p_run uuid, p_job uuid, p_commit text, p_worker_sha256 text, p_config_sha256 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_now timestamptz:=date_trunc('second',clock_timestamp()); v_hash text;
BEGIN
  IF p_commit !~ '^[0-9a-f]{40}$' OR p_worker_sha256 !~ '^[0-9a-f]{64}$'
    OR p_config_sha256 !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='authentication_rejected'; END IF;
  PERFORM 1 FROM public.legacy_producer_runs_v3_11 run
    JOIN public.legacy_producer_jobs_v3_11 job ON job.run_id=run.run_id
    WHERE run.run_id=p_run AND job.job_id=p_job AND run.status='running' AND job.status='leased'
      AND run.producer_commit_sha=p_commit AND run.worker_sha256=p_worker_sha256
      AND run.scheduler_config_sha256=p_config_sha256
      AND run.lease_expires_at<v_now AND job.lease_expires_at<v_now
    FOR UPDATE OF run,job;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_hash:=encode(extensions.digest(convert_to('lease-expired-v3.20:'||p_run::text||':'||p_job::text||':'||p_commit,'utf8'),'sha256'),'hex');
  PERFORM public.append_legacy_expired_producer_diagnostic_v3_20(
    p_run,p_job,(SELECT stage::text FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job),
    (SELECT job_kind::text FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job),
    (SELECT input_hash FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job),p_commit,v_hash,v_now);
  UPDATE public.legacy_producer_jobs_v3_11 SET status='failed',terminal_at=v_now,failure_code='lease_expired',
    owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
    WHERE run_id=p_run AND job_id=p_job AND status='leased';
  UPDATE public.legacy_producer_jobs_v3_11 SET status='cancelled',terminal_at=v_now,failure_code='cancelled',
    owner_token_hash=NULL,leased_at=NULL,heartbeat_at=NULL,lease_expires_at=NULL
    WHERE run_id=p_run AND status IN ('queued','retryable');
  UPDATE public.legacy_producer_runs_v3_11 SET status='failed',terminal_at=v_now,failure_code='lease_expired',
    heartbeat_at=v_now,lease_expires_at=v_now WHERE run_id=p_run AND status='running';
  RETURN 'failed_recoverable';
END $function$

CREATE OR REPLACE FUNCTION public.validate_opportunity_manifest_lifecycle_v3()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_manifest_id uuid;
  v_status public.opportunity_manifest_status_v3;
BEGIN
  IF TG_TABLE_NAME='opportunity_manifests_v3' THEN
    IF TG_OP='DELETE' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF OLD.status<>'building' THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF NEW.manifest_id<>OLD.manifest_id
      OR NEW.manifest_kind<>OLD.manifest_kind
      OR NEW.contract_version<>OLD.contract_version
      OR NEW.source_cutoff IS DISTINCT FROM OLD.source_cutoff
      OR NEW.header_canonical<>OLD.header_canonical
      OR NEW.header_json<>OLD.header_json
      OR NEW.created_at<>OLD.created_at
      OR NEW.recorded_at<>OLD.recorded_at
    THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
    END IF;
    IF NEW.status='complete' AND (
      NEW.root_canonical IS NULL
      OR encode(extensions.digest(NEW.root_canonical,'sha256'),'hex')<>NEW.manifest_hash
    ) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME='opportunity_manifest_pages_v3' THEN
    v_manifest_id:=CASE WHEN TG_OP='DELETE' THEN OLD.manifest_id ELSE NEW.manifest_id END;
  ELSE
    v_manifest_id:=CASE WHEN TG_OP='DELETE' THEN OLD.manifest_id ELSE NEW.manifest_id END;
  END IF;
  SELECT status INTO STRICT v_status
  FROM public.opportunity_manifests_v3 WHERE manifest_id=v_manifest_id;
  RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure';
END
$function$

CREATE OR REPLACE FUNCTION public.validate_opportunity_manifest_page_rows_v3()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_page public.opportunity_manifest_pages_v3%ROWTYPE;
  v_manifest public.opportunity_manifests_v3%ROWTYPE;
  v_count bigint; v_min bigint; v_max bigint; v_first text; v_last text;
  v_expected_symbol text; v_expected_session date; v_expected_terminal text;
  v_status text; v_valid_to timestamptz; v_row public.opportunity_manifest_rows_v3%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME='opportunity_manifest_rows_v3' THEN
    v_row:=NEW;
    SELECT * INTO STRICT v_page
    FROM public.opportunity_manifest_pages_v3 WHERE page_id=NEW.page_id;
    IF NEW.row_ordinal<>v_page.first_row_ordinal+v_page.row_count-1 THEN
      RETURN NEW;
    END IF;
  ELSE
    v_page:=NEW;
  END IF;
  SELECT * INTO STRICT v_manifest
  FROM public.opportunity_manifests_v3 WHERE manifest_id=v_page.manifest_id;
  IF v_page.page_canonical<>convert_to(regexp_replace(v_page.page_json::text,', ', ',', 'g'),'utf8')
    OR encode(extensions.digest(v_page.page_canonical,'sha256'),'hex')<>v_page.page_hash
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
  SELECT count(*),min(row_ordinal),max(row_ordinal),
    (array_agg(identity_key ORDER BY row_ordinal))[1],
    (array_agg(identity_key ORDER BY row_ordinal DESC))[1]
  INTO v_count,v_min,v_max,v_first,v_last
  FROM public.opportunity_manifest_rows_v3 WHERE page_id=v_page.page_id;
  IF v_count<>v_page.row_count OR v_min<>v_page.first_row_ordinal
    OR v_max<>v_page.first_row_ordinal+v_page.row_count-1
    OR v_max-v_min+1<>v_count OR v_first<>v_page.first_identity
    OR v_last<>v_page.last_identity
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='conservation_failure'; END IF;
  FOR v_row IN
    SELECT * FROM public.opportunity_manifest_rows_v3
    WHERE page_id=v_page.page_id ORDER BY row_ordinal
  LOOP
    IF v_row.payload_canonical<>convert_to(
        regexp_replace(v_row.payload_json::text,', ', ',', 'g'),'utf8')
      OR encode(extensions.digest(v_row.payload_canonical,'sha256'),'hex')<>v_row.payload_hash
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='manifest_hash_mismatch'; END IF;
    v_expected_symbol:=NULL; v_expected_session:=NULL; v_expected_terminal:=NULL;
    IF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='entry_rows' THEN
      v_expected_symbol:=v_row.payload_json->>0;
      SELECT (pair->>1)::date INTO v_expected_session
      FROM jsonb_array_elements(v_manifest.header_json) pair
      WHERE pair->>0='entrySession';
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='evaluation_rows' THEN
      v_expected_session:=(v_row.payload_json->>0)::date;
      v_expected_symbol:=v_row.payload_json->>3;
    ELSIF v_manifest.manifest_kind='sector_benchmark' AND v_row.section_key='session_conservation' THEN
      v_expected_session:=(v_row.payload_json->>0)::date;
    END IF;
    v_status:=CASE v_manifest.manifest_kind
      WHEN 'source_identity_allowlist' THEN v_row.payload_json->>7
      WHEN 'publisher_verification_allowlist' THEN v_row.payload_json->>10
      WHEN 'instrument_roster' THEN v_row.payload_json->>5
      WHEN 'alias_authority' THEN v_row.payload_json->>9
      WHEN 'taxonomy_assignment' THEN v_row.payload_json->>10
      WHEN 'peer_reviewer_allowlist' THEN v_row.payload_json->>5
      ELSE NULL END;
    v_valid_to:=CASE v_manifest.manifest_kind
      WHEN 'source_identity_allowlist' THEN (v_row.payload_json->>6)::timestamptz
      WHEN 'publisher_verification_allowlist' THEN (v_row.payload_json->>7)::timestamptz
      WHEN 'instrument_roster' THEN (v_row.payload_json->>10)::timestamptz
      WHEN 'alias_authority' THEN (v_row.payload_json->>8)::timestamptz
      WHEN 'taxonomy_assignment' THEN (v_row.payload_json->>8)::timestamptz
      WHEN 'peer_reviewer_allowlist' THEN (v_row.payload_json->>4)::timestamptz
      ELSE NULL END;
    IF v_status IS NOT NULL THEN
      v_expected_terminal:=CASE
        WHEN v_status='active'
          AND (v_valid_to IS NULL OR v_manifest.source_cutoff<v_valid_to)
        THEN 'effective_active' ELSE 'revoked_or_expired' END;
    END IF;
    IF v_row.lookup_symbol IS DISTINCT FROM v_expected_symbol
      OR v_row.lookup_session IS DISTINCT FROM v_expected_session
      OR v_row.terminal_code IS DISTINCT FROM v_expected_terminal
    THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='data_integrity_failure',
      DETAIL=format(
        'kind=%s section=%s ordinal=%s terminal=%s expected=%s symbol=%s expectedSymbol=%s session=%s expectedSession=%s',
        v_manifest.manifest_kind,v_row.section_key,v_row.row_ordinal,v_row.terminal_code,
        v_expected_terminal,v_row.lookup_symbol,v_expected_symbol,
        v_row.lookup_session,v_expected_session
      ); END IF;
  END LOOP;
  IF octet_length(v_page.page_canonical)
      +coalesce((SELECT sum(octet_length(payload_canonical))
        FROM public.opportunity_manifest_rows_v3 WHERE page_id=v_page.page_id),0)>3145728
  THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='bound_violation'; END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.validate_research_deep_scope_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.research_priority_runs_v1; c public.research_observed_companies_v1; s public.stocks; admission_clock timestamptz;
BEGIN
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
    THEN RAISE EXCEPTION 'research_admission_read_committed_required'; END IF;
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(2409,6001);admission_clock:=clock_timestamp();
  IF current_user='research_observed_rpc_owner' THEN
   SELECT admission_at INTO admission_clock FROM public.research_deep_admission_clocks_v1 WHERE run_id=NEW.priority_run_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'deep_scoped_admission_clock_missing';END IF;
  END IF;
  NEW.created_at:=admission_clock;NEW.week_start:=date_trunc('week',admission_clock AT TIME ZONE 'Asia/Taipei')::date;
 END IF;
 SELECT * INTO r FROM public.research_priority_runs_v1 WHERE run_id=NEW.priority_run_id;
 IF r.research_scope IS DISTINCT FROM NEW.research_scope OR r.observed_snapshot_hash IS DISTINCT FROM NEW.observed_snapshot_hash THEN RAISE EXCEPTION 'deep_scope_run_binding_invalid'; END IF;
 IF NEW.research_scope='research_observed_v1' THEN
  IF current_user<>'research_observed_rpc_owner' THEN RAISE EXCEPTION 'observed_job_requires_scoped_rpc'; END IF;
  SELECT * INTO c FROM public.research_observed_companies_v1 WHERE research_company_id=NEW.research_company_id;
  IF NOT FOUND OR c.symbol<>NEW.symbol THEN RAISE EXCEPTION 'deep_scope_company_invalid'; END IF;
 END IF;
 IF NEW.stock_id IS NOT NULL THEN
  SELECT * INTO s FROM public.stocks WHERE id=NEW.stock_id;
  IF NOT FOUND OR s.market<>'TW' OR s.symbol<>NEW.symbol THEN RAISE EXCEPTION 'deep_scope_stock_mapping_invalid'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND (OLD.research_scope,OLD.research_company_id,OLD.observed_snapshot_hash,OLD.stock_id,OLD.symbol,OLD.priority_run_id,OLD.week_start,OLD.created_at) IS DISTINCT FROM (NEW.research_scope,NEW.research_company_id,NEW.observed_snapshot_hash,NEW.stock_id,NEW.symbol,NEW.priority_run_id,NEW.week_start,NEW.created_at) THEN RAISE EXCEPTION 'deep_scope_lineage_immutable'; END IF;
 RETURN NEW;
END $function$
